{
  "name": "p15-test-uuroiv",
  "version": "1.0.0",
  "description": "Express API with PostgreSQL connection pooling and parameterised queries",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node --experimental-vm-modules node_modules/.bin/jest --forceExit"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "pg": "^8.12.0"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  }
}

/**
 * db.js — PostgreSQL connection pool
 *
 * Creates a single shared Pool instance for the whole process.
 * Configuration is read exclusively from environment variables so that no
 * credentials ever live in source code.
 *
 * Required environment variables (set via .env for local dev, never committed):
 *   DB_HOST     – hostname of the PostgreSQL server  (default: localhost)
 *   DB_PORT     – port                               (default: 5432)
 *   DB_NAME     – database name
 *   DB_USER     – role / username
 *   DB_PASSWORD – password
 *
 * Alternatively you may set DATABASE_URL as a connection string and the pg
 * library will parse it automatically.
 *
 * Pool-sizing knobs (all optional, sensible defaults shown):
 *   DB_POOL_MAX         – maximum simultaneous clients  (default: 10)
 *   DB_POOL_MIN         – minimum idle clients          (default: 2)
 *   DB_IDLE_TIMEOUT_MS  – ms before idle client closed  (default: 30000)
 *   DB_CONN_TIMEOUT_MS  – ms to wait for a free client  (default: 5000)
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Build pool configuration from individual env vars.
// If DATABASE_URL is present the pg driver uses it directly; the individual
// vars below act as a typed, documented alternative.
// ---------------------------------------------------------------------------
const poolConfig = {
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME,
  user:     process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max:              parseInt(process.env.DB_POOL_MAX        || '10',    10),
  min:              parseInt(process.env.DB_POOL_MIN        || '2',     10),
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS || '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT_MS || '5000', 10),

  // Re-use SSL settings from DATABASE_URL when present, otherwise respect
  // DB_SSL env var ('true' / 'false').
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : undefined,
};

// Allow a raw connection string to override the individual vars.
const pool = process.env.DATABASE_URL
  ? new Pool({
      connectionString: process.env.DATABASE_URL,
      max:              poolConfig.max,
      min:              poolConfig.min,
      idleTimeoutMillis: poolConfig.idleTimeoutMillis,
      connectionTimeoutMillis: poolConfig.connectionTimeoutMillis,
    })
  : new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Lifecycle events
// ---------------------------------------------------------------------------

/** Emitted every time a new physical connection is opened. */
pool.on('connect', (client) => {
  console.log('[db] New client connected to pool ' +
    `(total=${pool.totalCount}, idle=${pool.idleCount}, waiting=${pool.waitingCount})`);
});

/** Emitted when a client is removed from the pool due to an error. */
pool.on('remove', () => {
  console.log('[db] Client removed from pool ' +
    `(total=${pool.totalCount}, idle=${pool.idleCount})`);
});

/**
 * Emitted when a background client encounters an error (e.g. the server
 * closes a long-idle connection).  Without this handler the error would be
 * an unhandledRejection and crash the process.
 */
pool.on('error', (err) => {
  console.error('[db] Unexpected error on idle pool client:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool cleanly.  Call this from your SIGTERM / SIGINT handler so
 * in-flight queries can finish before the process exits.
 */
async function closePool() {
  await pool.end();
  console.log('[db] Pool has ended – all clients released.');
}

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Security guarantees
 * ───────────────────
 * • Every query uses the pg driver's parameterised-query protocol ($1, $2 …).
 *   Parameters are transmitted to PostgreSQL out-of-band from the SQL text,
 *   so the driver never interpolates them into the statement string.  This
 *   makes SQL injection structurally impossible for these queries.
 *
 * • Input validation is applied *before* the query reaches the driver as a
 *   second, defence-in-depth layer.  Invalid inputs are rejected with a
 *   typed QueryValidationError rather than silently coerced.
 *
 * • LIKE wildcard characters (%, _) inside searchUsers() search terms are
 *   escaped so that a user cannot craft a term that turns into a full-table
 *   scan or leaks data via wildcard abuse.
 *
 * Performance
 * ───────────
 * • The module uses the shared pg Pool (connection pooling) from db.js, so
 *   no connection is opened per-request.
 *
 * • Every query is wrapped by the internal `timedQuery` helper which records
 *   wall-clock duration and emits a structured log line (plus a WARN when the
 *   query exceeds SLOW_QUERY_THRESHOLD_MS).
 *
 * Exported API
 * ────────────
 *   getUserById(id)                    → single user row or null
 *   getAllUsers(limit, offset)          → { users, total, limit, offset }
 *   searchUsers(query, limit, offset)  → { users, total, limit, offset, query }
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Queries slower than this threshold emit a WARN log entry. */
const SLOW_QUERY_THRESHOLD_MS = 200;

/** Hard ceiling on the number of rows any single query may return. */
const MAX_LIMIT = 100;

/** Default page size when the caller does not supply one. */
const DEFAULT_LIMIT = 20;

// ---------------------------------------------------------------------------
// Custom error type
// ---------------------------------------------------------------------------

/**
 * Thrown when caller-supplied arguments fail validation.
 * Distinguishing it from generic Error lets the route handler return 400
 * without catching unrelated runtime errors.
 */
class QueryValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'QueryValidationError';
  }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Execute a parameterised SQL query via the shared pool and emit timing logs.
 *
 * @param {string}   label   – human-readable name shown in log lines
 * @param {string}   text    – SQL statement with $1/$2/… placeholders
 * @param {Array}    values  – parameter values (never interpolated into SQL)
 * @returns {Promise<pg.QueryResult>}
 */
async function timedQuery(label, text, values) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query({ text, values });
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    const level = durationMs > SLOW_QUERY_THRESHOLD_MS ? 'WARN' : 'INFO';

    console.log(
      `[query] ${level} label="${label}" ` +
      `rows=${result.rowCount} ` +
      `duration=${durationMs.toFixed(2)}ms` +
      (level === 'WARN' ? ' — slow query detected' : '')
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    // Log the error but NOT the parameter values (they might contain PII).
    console.error(
      `[query] ERROR label="${label}" ` +
      `duration=${durationMs.toFixed(2)}ms ` +
      `error="${err.message}"`
    );
    throw err; // re-throw so callers can handle / convert to HTTP responses
  }
}

/**
 * Validate and normalise pagination parameters shared by getAllUsers and
 * searchUsers.
 *
 * @param {*} rawLimit   – value from caller (may be undefined / string / number)
 * @param {*} rawOffset  – value from caller
 * @returns {{ limit: number, offset: number }}
 * @throws {QueryValidationError}
 */
function normalisePagination(rawLimit, rawOffset) {
  const limit  = rawLimit  === undefined ? DEFAULT_LIMIT : Number(rawLimit);
  const offset = rawOffset === undefined ? 0             : Number(rawOffset);

  if (!Number.isInteger(limit)  || limit  < 1) {
    throw new QueryValidationError(
      `limit must be a positive integer (received: ${rawLimit})`
    );
  }
  if (!Number.isInteger(offset) || offset < 0) {
    throw new QueryValidationError(
      `offset must be a non-negative integer (received: ${rawOffset})`
    );
  }
  if (limit > MAX_LIMIT) {
    throw new QueryValidationError(
      `limit exceeds maximum allowed value of ${MAX_LIMIT} (received: ${limit})`
    );
  }

  return { limit, offset };
}

/**
 * Escape LIKE metacharacters (%, _) inside a search term.
 * The escaped value is still passed as a parameterised value — this only
 * prevents wildcard abuse rather than injection.
 *
 * @param {string} term
 * @returns {string}
 */
function escapeLike(term) {
  return term.replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by their primary-key ID.
 *
 * The ID is passed as a parameterised value ($1); PostgreSQL never sees it
 * as part of the SQL text.  We also validate that it is a positive integer
 * before the query is executed.
 *
 * @param {number|string} id – user ID (coerced to integer internally)
 * @returns {Promise<Object|null>} user row, or null when not found
 * @throws {QueryValidationError} for non-integer or non-positive IDs
 *
 * @example
 *   const user = await getUserById(42);
 *   // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: Date }
 */
async function getUserById(id) {
  // ── Validation ────────────────────────────────────────────────────────────
  const parsed = Number(id);
  if (!Number.isInteger(parsed) || parsed < 1) {
    throw new QueryValidationError(
      `id must be a positive integer (received: ${id})`
    );
  }

  // ── Parameterised query ───────────────────────────────────────────────────
  // $1 is bound to `parsed` by the pg driver; it is NEVER interpolated into
  // the SQL string, making injection impossible.
  const { rows } = await timedQuery(
    'getUserById',
    `SELECT id, name, email, created_at
       FROM users
      WHERE id = $1`,
    [parsed]                  // ← out-of-band parameter binding
  );

  return rows[0] ?? null;
}

/**
 * Fetch a paginated list of all users, ordered by ID (stable sort).
 *
 * Both `limit` and `offset` are validated and then passed as parameterised
 * values ($1 / $2).  LIMIT and OFFSET accept integer literals in PostgreSQL
 * so this is safe even without parameterisation, but binding them keeps the
 * approach consistent and allows the database to cache the query plan.
 *
 * @param {number} [limit=20]   – rows per page  (1 – 100)
 * @param {number} [offset=0]   – rows to skip
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number }>}
 * @throws {QueryValidationError} for invalid pagination values
 *
 * @example
 *   const page = await getAllUsers(10, 20);
 *   // { users: [...], total: 57, limit: 10, offset: 20 }
 */
async function getAllUsers(limit, offset) {
  // ── Validation ────────────────────────────────────────────────────────────
  const { limit: safeLimit, offset: safeOffset } =
    normalisePagination(limit, offset);

  // ── Parameterised query ───────────────────────────────────────────────────
  // We fetch the total count in the same round-trip using a window function
  // so the caller can build pagination metadata without a second query.
  const { rows } = await timedQuery(
    'getAllUsers',
    `SELECT id,
            name,
            email,
            created_at,
            COUNT(*) OVER() AS total_count
       FROM users
      ORDER BY id
      LIMIT  $1    -- bound to safeLimit,  never string-interpolated
      OFFSET $2`,  // bound to safeOffset, never string-interpolated
    [safeLimit, safeOffset]   // ← out-of-band parameter binding
  );

  const total = rows.length > 0 ? parseInt(rows[0].total_count, 10) : 0;
  // Strip the synthetic total_count column from each user object.
  const users = rows.map(({ total_count, ...user }) => user);

  return { users, total, limit: safeLimit, offset: safeOffset };
}

/**
 * Full-text search across user name and email columns using a LIKE pattern.
 *
 * Three-layer SQL injection prevention:
 *   1. `query` is validated as a non-empty string with a maximum length.
 *   2. LIKE metacharacters (%, _) inside the term are escaped via escapeLike().
 *   3. The final search term is bound as a parameterised value ($1) — it
 *      never appears inside the SQL text string at all.
 *
 * @param {string} query          – search term (max 200 chars)
 * @param {number} [limit=20]     – rows per page  (1 – 100)
 * @param {number} [offset=0]     – rows to skip
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number, query: string }>}
 * @throws {QueryValidationError} for blank / oversized query or invalid pagination
 *
 * @example
 *   const results = await searchUsers('alice', 5, 0);
 *   // { users: [...], total: 2, limit: 5, offset: 0, query: 'alice' }
 */
async function searchUsers(query, limit, offset) {
  // ── Validation ────────────────────────────────────────────────────────────
  if (typeof query !== 'string' || query.trim().length === 0) {
    throw new QueryValidationError('query must be a non-empty string');
  }
  if (query.length > 200) {
    throw new QueryValidationError(
      `query exceeds maximum length of 200 characters (received: ${query.length})`
    );
  }

  const { limit: safeLimit, offset: safeOffset } =
    normalisePagination(limit, offset);

  // ── Build the search term ─────────────────────────────────────────────────
  // escapeLike prevents wildcard abuse; wrapping in % makes it a
  // "contains" search.  The result is still bound as $1 (not interpolated).
  const searchTerm = `%${escapeLike(query.trim())}%`;

  // ── Parameterised query ───────────────────────────────────────────────────
  // $1 = searchTerm  (bound out-of-band — injection impossible)
  // $2 = safeLimit   (bound out-of-band)
  // $3 = safeOffset  (bound out-of-band)
  //
  // ILIKE is used for case-insensitive matching.  If the target PostgreSQL
  // version or collation does not support ILIKE, replace with:
  //   LOWER(name) LIKE LOWER($1)
  const { rows } = await timedQuery(
    'searchUsers',
    `SELECT id,
            name,
            email,
            created_at,
            COUNT(*) OVER() AS total_count
       FROM users
      WHERE name  ILIKE $1   -- $1 bound out-of-band; LIKE wildcards pre-escaped
         OR email ILIKE $1
      ORDER BY id
      LIMIT  $2
      OFFSET $3`,
    [searchTerm, safeLimit, safeOffset]  // ← out-of-band parameter binding
  );

  const total = rows.length > 0 ? parseInt(rows[0].total_count, 10) : 0;
  const users = rows.map(({ total_count, ...user }) => user);

  return {
    users,
    total,
    limit:  safeLimit,
    offset: safeOffset,
    query:  query.trim(),   // return the original (unescaped) term for the client
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,   // exported so route handlers can instanceof-check it
  // constants exported for tests / documentation
  MAX_LIMIT,
  DEFAULT_LIMIT,
  SLOW_QUERY_THRESHOLD_MS,
};

/**
 * app.js — Express application
 *
 * /health           – liveness probe
 * /users            – paginated list of all users
 * /users/search     – full-text search by name / email
 * /users/:id        – fetch a single user by ID
 *
 * The database layer lives in queries.js (parameterised queries + timing logs)
 * and db.js (shared connection pool).  app.js is responsible only for HTTP
 * concern: routing, request parsing, and translating query results / errors
 * into appropriate status codes.
 */

'use strict';

require('dotenv').config();
const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
} = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Central error handler for route callbacks.
 * Keeps each route body clean; only one place decides HTTP status codes.
 *
 * @param {Error}              err  – the thrown error
 * @param {express.Response}   res  – Express response object
 * @param {string}             ctx  – short label for log lines ("getUserById")
 */
function handleError(err, res, ctx) {
  if (err instanceof QueryValidationError) {
    // Caller supplied bad input — 400 Bad Request, message is safe to expose.
    return res.status(400).json({ error: err.message });
  }

  // Unexpected errors (DB down, network timeout, …) — 500.
  // Log full detail on the server; send only a generic message to the client
  // so internal infrastructure details are never leaked.
  console.error(`[${ctx}] Unexpected error: ${err.message}`);
  return res.status(500).json({ error: 'Internal server error' });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe — does not touch the database.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── /users/search must be registered BEFORE /users/:id so Express does not
// treat the literal string "search" as an :id parameter value.

/**
 * GET /users/search?q=alice[&limit=20&offset=0]
 *
 * Query parameters
 *   q       {string}  required — search term, max 200 chars
 *   limit   {number}  optional — rows per page, 1–100 (default 20)
 *   offset  {number}  optional — rows to skip    (default 0)
 *
 * Responses
 *   200 { users, total, limit, offset, query }
 *   400 validation error (missing/blank q, bad pagination)
 *   500 internal server error
 *
 * @example
 *   GET /users/search?q=alice&limit=5
 */
app.get('/users/search', async (req, res) => {
  const { q, limit, offset } = req.query;

  if (!q || String(q).trim().length === 0) {
    return res.status(400).json({
      error: 'Missing required query parameter: q',
    });
  }

  try {
    const result = await searchUsers(q, limit, offset);
    return res.json(result);
  } catch (err) {
    return handleError(err, res, 'searchUsers');
  }
});

/**
 * GET /users?limit=20&offset=0
 *
 * Query parameters
 *   limit   {number}  optional — rows per page, 1–100 (default 20)
 *   offset  {number}  optional — rows to skip    (default 0)
 *
 * Responses
 *   200 { users, total, limit, offset }
 *   400 validation error
 *   500 internal server error
 *
 * @example
 *   GET /users?limit=10&offset=30
 */
app.get('/users', async (req, res) => {
  const { limit, offset } = req.query;

  try {
    const result = await getAllUsers(limit, offset);
    return res.json(result);
  } catch (err) {
    return handleError(err, res, 'getAllUsers');
  }
});

/**
 * GET /users/:id
 *
 * Path parameters
 *   id  {number}  required — positive integer user ID
 *
 * Responses
 *   200 { id, name, email, created_at }
 *   400 validation error (non-integer id)
 *   404 user not found
 *   500 internal server error
 *
 * @example
 *   GET /users/42
 */
app.get('/users/:id', async (req, res) => {
  const { id } = req.params;

  try {
    const user = await getUserById(id);

    if (user === null) {
      return res.status(404).json({ error: `User with id ${id} not found` });
    }

    return res.json(user);
  } catch (err) {
    return handleError(err, res, 'getUserById');
  }
});

// ---------------------------------------------------------------------------
// Startup & graceful shutdown
// ---------------------------------------------------------------------------

// Only start listening when this file is executed directly (not required by
// tests), so test files can import `app` without binding a port.
if (require.main === module) {
  const { closePool } = require('./db');
  const PORT = parseInt(process.env.PORT || '3000', 10);

  const server = app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });

  async function shutdown(signal) {
    console.log(`[app] ${signal} received — shutting down gracefully`);
    server.close(async () => {
      await closePool();
      console.log('[app] Clean exit');
      process.exit(0);
    });
  }

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT',  () => shutdown('SIGINT'));
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * The pg pool is mocked so no real database is required.
 * Tests cover:
 *   • Happy-path results and return-shape for all three functions
 *   • Input validation (QueryValidationError) for every guard
 *   • SQL injection probe — confirms parameterised binding is used
 *   • Pagination edge cases (max limit, zero offset, defaults)
 *   • LIKE metacharacter escaping inside searchUsers
 *   • "Not found" path for getUserById
 *   • Slow-query WARN log emission
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the pg Pool BEFORE requiring any module that imports it.
// ---------------------------------------------------------------------------
const mockQuery = jest.fn();

jest.mock('pg', () => {
  const Pool = jest.fn().mockImplementation(() => ({
    query:       mockQuery,
    end:         jest.fn().mockResolvedValue(undefined),
    on:          jest.fn(),    // silence event-listener registrations
    totalCount:  0,
    idleCount:   0,
    waitingCount: 0,
  }));
  return { Pool };
});

// Also stub dotenv so it never touches the filesystem.
jest.mock('dotenv', () => ({ config: jest.fn() }));

const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
  MAX_LIMIT,
  DEFAULT_LIMIT,
  SLOW_QUERY_THRESHOLD_MS,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Build a fake pg result where each row gets a `total_count` attached. */
function mockRows(rows, total) {
  return {
    rows:      rows.map(r => ({ ...r, total_count: String(total) })),
    rowCount:  rows.length,
  };
}

/** Capture all console.log / console.error calls made during `fn()`. */
async function captureConsole(fn) {
  const logs   = [];
  const errors = [];
  const origLog   = console.log;
  const origError = console.error;
  console.log   = (...a) => logs.push(a.join(' '));
  console.error = (...a) => errors.push(a.join(' '));
  try   { await fn(); }
  finally {
    console.log   = origLog;
    console.error = origError;
  }
  return { logs, errors };
}

// ---------------------------------------------------------------------------
// Shared set-up
// ---------------------------------------------------------------------------

beforeEach(() => {
  mockQuery.mockReset();
});

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

describe('getUserById', () => {
  const fakeUser = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };

  test('returns the matching user row', async () => {
    mockQuery.mockResolvedValue({ rows: [fakeUser], rowCount: 1 });
    const user = await getUserById(1);
    expect(user).toEqual(fakeUser);
  });

  test('returns null when no rows come back', async () => {
    mockQuery.mockResolvedValue({ rows: [], rowCount: 0 });
    const user = await getUserById(99);
    expect(user).toBeNull();
  });

  test('passes id as a parameterised value, not in the SQL text', async () => {
    mockQuery.mockResolvedValue({ rows: [fakeUser], rowCount: 1 });
    await getUserById(42);

    const [callArg] = mockQuery.mock.calls[0];
    // The SQL text must NOT contain the literal id value.
    expect(callArg.text).not.toContain('42');
    // The value must appear in the values array (out-of-band).
    expect(callArg.values).toContain(42);
    // Placeholder must be present in the SQL text.
    expect(callArg.text).toContain('$1');
  });

  test('SQL injection probe — malicious string goes to values[], not SQL text', async () => {
    // Even though this value is invalid (non-integer) and will be rejected by
    // our own validator, we verify that the parameterisation layer would have
    // prevented it even if the validator were absent.
    // We test with a valid-looking but injection-carrying numeric string that
    // passes Number() conversion:  the validator catches it; if it somehow
    // slipped through, pg would bind it as $1, never concatenate it.
    mockQuery.mockResolvedValue({ rows: [fakeUser], rowCount: 1 });
    await expect(getUserById("1; DROP TABLE users--")).rejects.toBeInstanceOf(QueryValidationError);
    // mockQuery must NOT have been called — the validator fired first.
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError for id = 0', async () => {
    await expect(getUserById(0)).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for negative id', async () => {
    await expect(getUserById(-5)).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for non-numeric string', async () => {
    await expect(getUserById('abc')).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for float id', async () => {
    await expect(getUserById(3.14)).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('accepts a numeric string that represents a valid id', async () => {
    mockQuery.mockResolvedValue({ rows: [fakeUser], rowCount: 1 });
    const user = await getUserById('7');
    expect(user).toEqual(fakeUser);
    expect(mockQuery.mock.calls[0][0].values).toContain(7); // coerced to number
  });

  test('emits a timing INFO log on success', async () => {
    mockQuery.mockResolvedValue({ rows: [fakeUser], rowCount: 1 });
    const { logs } = await captureConsole(() => getUserById(1));
    expect(logs.some(l => l.includes('getUserById') && l.includes('INFO'))).toBe(true);
  });

  test('emits a WARN log when the query is slow', async () => {
    // Simulate slow query by delaying the mock resolution.
    mockQuery.mockImplementation(() =>
      new Promise(resolve =>
        setTimeout(() => resolve({ rows: [fakeUser], rowCount: 1 }),
          SLOW_QUERY_THRESHOLD_MS + 10)
      )
    );
    const { logs } = await captureConsole(() => getUserById(1));
    expect(logs.some(l => l.includes('WARN') && l.includes('slow query'))).toBe(true);
  });

  test('re-throws database errors after logging them', async () => {
    const dbError = new Error('connection refused');
    mockQuery.mockRejectedValue(dbError);
    const { errors } = await captureConsole(async () => {
      await expect(getUserById(1)).rejects.toThrow('connection refused');
    });
    expect(errors.some(e => e.includes('ERROR') && e.includes('getUserById'))).toBe(true);
  });
});

// ---------------------------------------------------------------------------
// getAllUsers
// ---------------------------------------------------------------------------

describe('getAllUsers', () => {
  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date() },
  ];

  test('returns users array with pagination metadata', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 42));
    const result = await getAllUsers(10, 0);
    expect(result.users).toHaveLength(2);
    expect(result.total).toBe(42);
    expect(result.limit).toBe(10);
    expect(result.offset).toBe(0);
  });

  test('strips total_count from individual user objects', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 2));
    const { users } = await getAllUsers(10, 0);
    users.forEach(u => expect(u).not.toHaveProperty('total_count'));
  });

  test('passes limit and offset as parameterised values', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 2));
    await getAllUsers(15, 30);
    const [callArg] = mockQuery.mock.calls[0];
    expect(callArg.values).toEqual([15, 30]);
    expect(callArg.text).toContain('$1');
    expect(callArg.text).toContain('$2');
    // Raw numbers must not be string-interpolated into the SQL.
    expect(callArg.text).not.toMatch(/LIMIT\s+15/);
    expect(callArg.text).not.toMatch(/OFFSET\s+30/);
  });

  test('uses DEFAULT_LIMIT when limit is omitted', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 2));
    const result = await getAllUsers();
    expect(result.limit).toBe(DEFAULT_LIMIT);
    expect(mockQuery.mock.calls[0][0].values[0]).toBe(DEFAULT_LIMIT);
  });

  test('uses offset 0 when offset is omitted', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 2));
    const result = await getAllUsers(5);
    expect(result.offset).toBe(0);
  });

  test('returns total 0 and empty array when no rows', async () => {
    mockQuery.mockResolvedValue({ rows: [], rowCount: 0 });
    const result = await getAllUsers();
    expect(result.users).toHaveLength(0);
    expect(result.total).toBe(0);
  });

  test('accepts limit = MAX_LIMIT', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 2));
    const result = await getAllUsers(MAX_LIMIT, 0);
    expect(result.limit).toBe(MAX_LIMIT);
  });

  test('throws QueryValidationError when limit exceeds MAX_LIMIT', async () => {
    await expect(getAllUsers(MAX_LIMIT + 1, 0)).rejects.toBeInstanceOf(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError for limit = 0', async () => {
    await expect(getAllUsers(0, 0)).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for negative limit', async () => {
    await expect(getAllUsers(-1, 0)).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for negative offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for non-numeric limit', async () => {
    await expect(getAllUsers('many', 0)).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for float limit', async () => {
    await expect(getAllUsers(2.5, 0)).rejects.toBeInstanceOf(QueryValidationError);
  });
});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() },
  ];

  test('returns matching users with pagination metadata and query echo', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 1));
    const result = await searchUsers('alice', 10, 0);
    expect(result.users).toHaveLength(1);
    expect(result.total).toBe(1);
    expect(result.limit).toBe(10);
    expect(result.offset).toBe(0);
    expect(result.query).toBe('alice');
  });

  test('strips total_count from individual user objects', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 1));
    const { users } = await searchUsers('alice', 10, 0);
    users.forEach(u => expect(u).not.toHaveProperty('total_count'));
  });

  test('wraps the search term in % wildcards', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 1));
    await searchUsers('alice', 10, 0);
    const [callArg] = mockQuery.mock.calls[0];
    expect(callArg.values[0]).toBe('%alice%');
  });

  test('passes search term as parameterised $1 value, not in SQL text', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 1));
    await searchUsers('alice', 10, 0);
    const [callArg] = mockQuery.mock.calls[0];
    expect(callArg.text).toContain('$1');
    expect(callArg.text).not.toContain('alice'); // never interpolated
    expect(callArg.values[0]).toContain('alice');
  });

  test('SQL injection probe — classic payload is bound as $1, never in SQL', async () => {
    mockQuery.mockResolvedValue(mockRows([], 0));
    const payload = "' OR '1'='1";
    await searchUsers(payload, 10, 0);
    const [callArg] = mockQuery.mock.calls[0];
    // The raw payload must not appear in the SQL text.
    expect(callArg.text).not.toContain(payload);
    // It must appear only inside the values array (out-of-band).
    expect(callArg.values[0]).toContain(payload.trim());
  });

  test('escapes % in search term to prevent wildcard abuse', async () => {
    mockQuery.mockResolvedValue(mockRows([], 0));
    await searchUsers('100%', 10, 0);
    const [callArg] = mockQuery.mock.calls[0];
    // The % inside the term must be escaped; only the surrounding % wildcards remain raw.
    expect(callArg.values[0]).toBe('%100\\%%');
  });

  test('escapes _ in search term to prevent single-char wildcard abuse', async () => {
    mockQuery.mockResolvedValue(mockRows([], 0));
    await searchUsers('a_b', 10, 0);
    const [callArg] = mockQuery.mock.calls[0];
    expect(callArg.values[0]).toBe('%a\\_b%');
  });

  test('escapes backslash in search term', async () => {
    mockQuery.mockResolvedValue(mockRows([], 0));
    await searchUsers('C:\\path', 10, 0);
    const [callArg] = mockQuery.mock.calls[0];
    expect(callArg.values[0]).toBe('%C:\\\\path%');
  });

  test('trims whitespace from query before use', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 1));
    const result = await searchUsers('  alice  ', 10, 0);
    expect(result.query).toBe('alice');
    const [callArg] = mockQuery.mock.calls[0];
    expect(callArg.values[0]).toBe('%alice%');
  });

  test('returns query field with the original (pre-escape) trimmed term', async () => {
    mockQuery.mockResolvedValue(mockRows([], 0));
    const result = await searchUsers('100%', 10, 0);
    // The client sees the original unescaped term.
    expect(result.query).toBe('100%');
  });

  test('uses DEFAULT_LIMIT when limit is omitted', async () => {
    mockQuery.mockResolvedValue(mockRows(fakeUsers, 1));
    const result = await searchUsers('alice');
    expect(result.limit).toBe(DEFAULT_LIMIT);
  });

  test('returns empty result set without error', async () => {
    mockQuery.mockResolvedValue({ rows: [], rowCount: 0 });
    const result = await searchUsers('zzznomatch');
    expect(result.users).toHaveLength(0);
    expect(result.total).toBe(0);
  });

  test('throws QueryValidationError for blank query', async () => {
    await expect(searchUsers('   ')).rejects.toBeInstanceOf(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError for empty string query', async () => {
    await expect(searchUsers('')).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for non-string query', async () => {
    await expect(searchUsers(123)).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for null query', async () => {
    await expect(searchUsers(null)).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('throws QueryValidationError for query longer than 200 chars', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toBeInstanceOf(QueryValidationError);
  });

  test('accepts query of exactly 200 chars', async () => {
    mockQuery.mockResolvedValue(mockRows([], 0));
    await expect(searchUsers('a'.repeat(200))).resolves.not.toThrow();
  });

  test('throws QueryValidationError for invalid pagination', async () => {
    await expect(searchUsers('alice', 0, 0)).rejects.toBeInstanceOf(QueryValidationError);
  });
});

// ---------------------------------------------------------------------------
// QueryValidationError identity
// ---------------------------------------------------------------------------

describe('QueryValidationError', () => {
  test('is an instance of Error', () => {
    const err = new QueryValidationError('bad input');
    expect(err).toBeInstanceOf(Error);
  });

  test('has the correct name property', () => {
    const err = new QueryValidationError('bad input');
    expect(err.name).toBe('QueryValidationError');
  });

  test('carries the supplied message', () => {
    const err = new QueryValidationError('bad input');
    expect(err.message).toBe('bad input');
  });
});

// ---------------------------------------------------------------------------
// Exported constants sanity checks
// ---------------------------------------------------------------------------

describe('exported constants', () => {
  test('MAX_LIMIT is a positive integer', () => {
    expect(Number.isInteger(MAX_LIMIT) && MAX_LIMIT > 0).toBe(true);
  });

  test('DEFAULT_LIMIT is within [1, MAX_LIMIT]', () => {
    expect(DEFAULT_LIMIT).toBeGreaterThanOrEqual(1);
    expect(DEFAULT_LIMIT).toBeLessThanOrEqual(MAX_LIMIT);
  });

  test('SLOW_QUERY_THRESHOLD_MS is a positive number', () => {
    expect(SLOW_QUERY_THRESHOLD_MS).toBeGreaterThan(0);
  });
});

