/**
 * db.js — Connection pool factory
 *
 * Wraps the `pg` Pool so the rest of the application never holds raw Client
 * references and always returns connections to the pool automatically.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials are ever hard-coded in source files.
 *
 * Usage
 * -----
 *   const { query, getClient, end } = require('./db');
 *
 *   // Single query (connection automatically returned to pool)
 *   const { rows } = await query('SELECT $1::text AS msg', ['hello']);
 *
 *   // Transaction (manual client checkout)
 *   const client = await getClient();
 *   try {
 *     await client.query('BEGIN');
 *     ...
 *     await client.query('COMMIT');
 *   } catch (err) {
 *     await client.query('ROLLBACK');
 *     throw err;
 *   } finally {
 *     client.release();
 *   }
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate required environment variable at startup, not at first query time.
// ---------------------------------------------------------------------------
if (!process.env.DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL environment variable is not set. ' +
    'Copy .env.example to .env and fill in your database connection string.'
  );
}

// ---------------------------------------------------------------------------
// Pool configuration
// All values come from environment variables so no secrets live in code.
// ---------------------------------------------------------------------------
const poolConfig = {
  connectionString: process.env.DATABASE_URL,

  // Maximum number of clients in the pool (default: 10).
  max: parseInt(process.env.DB_POOL_MAX || '10', 10),

  // How long (ms) a client may sit idle before being evicted (default: 30 s).
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT_MS || '30000', 10),

  // How long (ms) to wait for a connection before throwing (default: 2 s).
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONNECTION_TIMEOUT_MS || '2000', 10),

  // Enforce SSL in production; allow self-signed certs in non-production.
  ...(process.env.NODE_ENV === 'production'
    ? { ssl: { rejectUnauthorized: true } }
    : {}),
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event hooks — surface problems early in the server log.
// ---------------------------------------------------------------------------

/** Logs whenever a new physical connection is opened. */
pool.on('connect', (client) => {
  console.info(`[db] New client connected  (pool size: ${pool.totalCount})`);
});

/** Logs when a client is returned to the pool after use. */
pool.on('acquire', (client) => {
  console.debug(`[db] Client acquired from pool`);
});

/**
 * Catches errors emitted by idle clients (e.g. the database server closed
 * the connection unexpectedly).  Without this handler the error would be
 * an unhandled rejection that crashes the process.
 */
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle pool client:', err.message);
});

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Execute a single parameterised query and automatically release the
 * connection back to the pool.
 *
 * @param {string}  text    - Parameterised SQL string, e.g. `SELECT * FROM users WHERE id = $1`
 * @param {Array}   [params=[]] - Positional parameters that replace the $N placeholders
 * @returns {Promise<import('pg').QueryResult>}
 */
async function query(text, params = []) {
  const client = await pool.connect();
  try {
    return await client.query(text, params);
  } finally {
    client.release();
  }
}

/**
 * Check out a client from the pool for multi-statement transactions.
 * The caller **must** call `client.release()` in a finally block.
 *
 * @returns {Promise<import('pg').PoolClient>}
 */
async function getClient() {
  return pool.connect();
}

/**
 * Gracefully drain and close the pool.
 * Call this on process exit / SIGTERM so in-flight queries are not
 * interrupted and the OS file-descriptor table is not leaked.
 *
 * @returns {Promise<void>}
 */
async function end() {
  await pool.end();
  console.info('[db] Connection pool closed');
}

/**
 * Returns a snapshot of the current pool metrics — useful for health checks
 * and monitoring dashboards.
 *
 * @returns {{ total: number, idle: number, waiting: number }}
 */
function poolStats() {
  return {
    total:   pool.totalCount,
    idle:    pool.idleCount,
    waiting: pool.waitingCount,
  };
}

module.exports = { query, getClient, end, poolStats };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * -----------------
 * 1. SQL INJECTION PREVENTION
 *    Every value supplied by callers is passed as a positional parameter
 *    ($1, $2, …) and handed to the `pg` driver as the second argument to
 *    client.query().  The driver sends the SQL text and the parameters to
 *    PostgreSQL in separate protocol messages so the database itself parses
 *    and binds them — user-supplied strings can NEVER be interpolated into
 *    the query text.
 *
 *    For the searchUsers() function the search term is wrapped in a LIKE
 *    pattern server-side (not by the caller), and the LIKE special characters
 *    `%` and `_` inside the *term* are escaped before the parameter is bound,
 *    preventing wildcard injection.
 *
 *    Numeric parameters (id, limit, offset) are coerced and range-checked in
 *    JavaScript before they reach the database, so crafted strings like
 *    "1; DROP TABLE users" are rejected with a TypeError long before the
 *    database sees them.
 *
 * 2. CONNECTION POOLING
 *    All functions delegate to `db.query()` which borrows a client from the
 *    shared Pool in db.js and returns it immediately after the query
 *    completes.  No function holds a connection open while doing other work.
 *
 * 3. QUERY TIMING LOGS
 *    Every call is wrapped by `timedQuery()` which records wall-clock
 *    duration (via `process.hrtime.bigint()`) and logs it along with the
 *    function name, the sanitised SQL template, and the row count returned.
 *    Parameter values are intentionally NOT logged to avoid leaking PII.
 *
 * 4. INPUT VALIDATION
 *    Helper functions `toPositiveInt` and `toSafeString` validate and
 *    normalise each argument so bad input produces a clear error message
 *    rather than a database error or silent mis-behaviour.
 */

'use strict';

const { query } = require('./db');

// ---------------------------------------------------------------------------
// Tuneable constants
// ---------------------------------------------------------------------------

/** Hard upper bound on rows returned by getAllUsers / searchUsers. */
const MAX_LIMIT = 200;

/** Default page size when `limit` is omitted. */
const DEFAULT_LIMIT = 20;

/** Maximum length accepted for the search query string. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Escapes the LIKE special characters `%` and `_` within `str` so that a
 * user-supplied term is treated as a literal substring and cannot expand into
 * an unrestricted wildcard.
 *
 * @param {string} str
 * @returns {string}
 */
function escapeLikePattern(str) {
  // Replace `\` first (must come before the others), then `%`, then `_`.
  return str.replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
}

/**
 * Coerce `value` to a positive integer and clamp it inside [min, max].
 * Throws a TypeError with a descriptive message if coercion fails.
 *
 * @param {*}      value
 * @param {string} name  - The parameter name (for error messages).
 * @param {number} min
 * @param {number} max
 * @returns {number}
 */
function toPositiveInt(value, name, min = 1, max = Number.MAX_SAFE_INTEGER) {
  const n = Number(value);

  if (!Number.isFinite(n) || !Number.isInteger(n)) {
    throw new TypeError(
      `Invalid parameter "${name}": expected an integer, received "${value}".`
    );
  }

  if (n < min || n > max) {
    throw new RangeError(
      `Invalid parameter "${name}": value ${n} is outside the allowed range [${min}, ${max}].`
    );
  }

  return n;
}

/**
 * Validate and trim a string parameter.
 * Throws a TypeError if the value is not a non-empty string after trimming.
 *
 * @param {*}      value
 * @param {string} name   - The parameter name (for error messages).
 * @param {number} [maxLength=MAX_SEARCH_LENGTH]
 * @returns {string}
 */
function toSafeString(value, name, maxLength = MAX_SEARCH_LENGTH) {
  if (typeof value !== 'string') {
    throw new TypeError(
      `Invalid parameter "${name}": expected a string, received ${typeof value}.`
    );
  }

  const trimmed = value.trim();

  if (trimmed.length === 0) {
    throw new TypeError(
      `Invalid parameter "${name}": value must not be blank.`
    );
  }

  if (trimmed.length > maxLength) {
    throw new RangeError(
      `Invalid parameter "${name}": value exceeds maximum length of ${maxLength} characters.`
    );
  }

  return trimmed;
}

/**
 * Thin timing wrapper.
 *
 * Runs `fn`, measures its wall-clock duration with nanosecond resolution,
 * and logs a structured line to stdout.  Parameter *values* are deliberately
 * excluded from the log so PII (email addresses, names, etc.) never appears
 * in log files.
 *
 * @template T
 * @param {string}             label  - Human-readable label for the log line.
 * @param {string}             sql    - The SQL template string (no values).
 * @param {() => Promise<T>}   fn     - Async function that runs the query.
 * @returns {Promise<T>}
 */
async function timedQuery(label, sql, fn) {
  const start = process.hrtime.bigint();
  let rowCount = 0;
  let status = 'ok';

  try {
    const result = await fn();
    // `result` may be a pg QueryResult or our own shaped object.
    rowCount = Array.isArray(result) ? result.length
             : Array.isArray(result?.rows) ? result.rows.length
             : result != null ? 1
             : 0;
    return result;
  } catch (err) {
    status = 'error';
    throw err;
  } finally {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.info(
      JSON.stringify({
        level: 'info',
        event: 'query',
        label,
        sql,
        rows: rowCount,
        durationMs: parseFloat(durationMs.toFixed(3)),
        status,
        ts: new Date().toISOString(),
      })
    );
  }
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by their numeric primary key.
 *
 * @param {number|string} id  - The user's ID (coerced to a positive integer).
 * @returns {Promise<object|null>}  The user row, or null if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: Date }
 */
async function getUserById(id) {
  // Validate: must be a finite integer ≥ 1.
  const safeId = toPositiveInt(id, 'id', 1);

  const SQL = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `.trim();

  return timedQuery('getUserById', SQL, async () => {
    const { rows } = await query(SQL, [safeId]);
    return rows[0] ?? null;
  });
}

/**
 * Return a paginated list of all users, ordered by ascending ID.
 *
 * @param {number|string} [limit=DEFAULT_LIMIT]  - Rows per page (1 – MAX_LIMIT).
 * @param {number|string} [offset=0]             - Zero-based row offset.
 * @returns {Promise<{ rows: object[], total: number, limit: number, offset: number }>}
 *
 * @example
 *   const page = await getAllUsers(10, 0);
 *   // { rows: [...], total: 84, limit: 10, offset: 0 }
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
  // Validate limit: 1 → MAX_LIMIT.
  const safeLimit  = toPositiveInt(limit,  'limit',  1, MAX_LIMIT);
  // Validate offset: 0 → MAX_SAFE_INTEGER.
  const safeOffset = toPositiveInt(offset, 'offset', 0);

  // A single round-trip returns both the page and the total count thanks to
  // the window function.  This avoids issuing two separate queries and the
  // TOCTOU inconsistency that would produce.
  const SQL = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `.trim();

  return timedQuery('getAllUsers', SQL, async () => {
    const { rows } = await query(SQL, [safeLimit, safeOffset]);

    // Extract the total from the window function column and remove it from
    // each individual row to keep the API shape clean.
    const total = rows.length > 0 ? parseInt(rows[0].total_count, 10) : 0;
    const cleanRows = rows.map(({ total_count, ...rest }) => rest);

    return {
      rows:   cleanRows,
      total,
      limit:  safeLimit,
      offset: safeOffset,
    };
  });
}

/**
 * Search users by a partial match on `name` or `email`.
 *
 * The search is case-insensitive (ILIKE) and the caller's term is
 * sandwiched between `%` wildcards so it acts as a substring search.
 * The LIKE special characters `%` and `_` within the term are escaped
 * server-side (in escapeLikePattern) so callers cannot manipulate the
 * wildcard pattern.
 *
 * @param {string}        searchTerm            - Substring to search for (1 – MAX_SEARCH_LENGTH chars).
 * @param {number|string} [limit=DEFAULT_LIMIT] - Rows per page (1 – MAX_LIMIT).
 * @param {number|string} [offset=0]            - Zero-based row offset.
 * @returns {Promise<{ rows: object[], total: number, limit: number, offset: number, query: string }>}
 *
 * @example
 *   const results = await searchUsers('alice', 5, 0);
 *   // { rows: [...], total: 2, limit: 5, offset: 0, query: 'alice' }
 */
async function searchUsers(searchTerm, limit = DEFAULT_LIMIT, offset = 0) {
  // Validate the search term (trims whitespace, checks length).
  const safeTerm   = toSafeString(searchTerm, 'query');
  const safeLimit  = toPositiveInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = toPositiveInt(offset, 'offset', 0);

  // Escape LIKE metacharacters inside the term, then wrap it with `%`.
  // The resulting pattern is sent as a bound parameter — never interpolated.
  const likePattern = `%${escapeLikePattern(safeTerm)}%`;

  // ILIKE is PostgreSQL-specific case-insensitive LIKE.
  // The ESCAPE clause tells Postgres that `\` is the escape character used
  // by escapeLikePattern() above.
  const SQL = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR
      email ILIKE $1 ESCAPE '\\'
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `.trim();

  return timedQuery('searchUsers', SQL, async () => {
    const { rows } = await query(SQL, [likePattern, safeLimit, safeOffset]);

    const total = rows.length > 0 ? parseInt(rows[0].total_count, 10) : 0;
    const cleanRows = rows.map(({ total_count, ...rest }) => rest);

    return {
      rows:   cleanRows,
      total,
      limit:  safeLimit,
      offset: safeOffset,
      query:  safeTerm,   // Echo back the validated (trimmed) term.
    };
  });
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Expose the helpers so they can be unit-tested independently.
  _escapeLikePattern: escapeLikePattern,
  _toPositiveInt:     toPositiveInt,
  _toSafeString:      toSafeString,
};

/**
 * app.js — Express application
 *
 * /health          — Liveness probe (no DB required)
 * /health/db       — Readiness probe (verifies database connectivity)
 * GET /users       — Paginated list of all users
 * GET /users/:id   — Single user by ID
 * GET /users/search?q=…&limit=…&offset=… — Substring search
 */

'use strict';

require('dotenv').config();           // Load .env before importing db.js

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');
const { end: closePool, poolStats }             = require('./db');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Utility: wrap an async route handler so any thrown error is forwarded to
// Express's error middleware rather than causing an unhandled rejection.
// ---------------------------------------------------------------------------
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Health routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Basic liveness check — does not touch the database.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /health/db
 * Readiness check — verifies the pool can reach the database.
 * Also surfaces current pool metrics for monitoring dashboards.
 */
app.get('/health/db', asyncHandler(async (req, res) => {
  const { query } = require('./db');
  await query('SELECT 1');
  res.json({
    status: 'ok',
    pool:   poolStats(),
    timestamp: new Date().toISOString(),
  });
}));

// ---------------------------------------------------------------------------
// /users routes
//
// Route order matters: the static segment `/users/search` must be registered
// BEFORE the dynamic segment `/users/:id`, otherwise Express would try to
// look up a user with id = "search".
// ---------------------------------------------------------------------------

/**
 * GET /users/search?q=alice&limit=10&offset=0
 *
 * Query parameters
 *   q       {string}  required  Substring to search in name or email
 *   limit   {number}  optional  Page size, default 20, max 200
 *   offset  {number}  optional  Zero-based row offset, default 0
 *
 * Response 200
 *   { data: [...], meta: { total, limit, offset, query } }
 *
 * Response 400 — missing or invalid `q`
 * Response 422 — invalid limit / offset values
 */
app.get('/users/search', asyncHandler(async (req, res) => {
  const { q, limit, offset } = req.query;

  if (q === undefined || q === null) {
    return res.status(400).json({
      error:   'Missing required query parameter: q',
      example: '/users/search?q=alice&limit=10&offset=0',
    });
  }

  const result = await searchUsers(
    q,
    limit  !== undefined ? limit  : undefined,
    offset !== undefined ? offset : undefined
  );

  res.json({
    data: result.rows,
    meta: {
      total:  result.total,
      limit:  result.limit,
      offset: result.offset,
      query:  result.query,
    },
  });
}));

/**
 * GET /users/:id
 *
 * Path parameter
 *   id  {positive integer}  The user's numeric primary key
 *
 * Response 200  — { data: { id, name, email, created_at } }
 * Response 404  — user not found
 * Response 422  — id is not a positive integer
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await getUserById(req.params.id);

  if (user === null) {
    return res.status(404).json({
      error: `User with id "${req.params.id}" not found.`,
    });
  }

  res.json({ data: user });
}));

/**
 * GET /users?limit=20&offset=0
 *
 * Query parameters
 *   limit   {number}  optional  Page size, default 20, max 200
 *   offset  {number}  optional  Zero-based row offset, default 0
 *
 * Response 200
 *   { data: [...], meta: { total, limit, offset } }
 */
app.get('/users', asyncHandler(async (req, res) => {
  const { limit, offset } = req.query;

  const result = await getAllUsers(
    limit  !== undefined ? limit  : undefined,
    offset !== undefined ? offset : undefined
  );

  res.json({
    data: result.rows,
    meta: {
      total:  result.total,
      limit:  result.limit,
      offset: result.offset,
    },
  });
}));

// ---------------------------------------------------------------------------
// Error-handling middleware
// Must have four parameters so Express recognises it as an error handler.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // TypeError / RangeError from our validators → 422 Unprocessable Entity
  if (err instanceof TypeError || err instanceof RangeError) {
    return res.status(422).json({ error: err.message });
  }

  // Log unexpected errors WITHOUT including the raw error message in the
  // client response (it might contain database internals).
  console.error('[app] Unhandled error:', err);
  res.status(500).json({ error: 'An internal server error occurred.' });
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------
async function shutdown(signal) {
  console.info(`[app] Received ${signal} — draining connection pool…`);
  await closePool();
  console.info('[app] Shutdown complete.');
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = parseInt(process.env.PORT || '3000', 10);
  app.listen(PORT, () => {
    console.info(`[app] Server listening on port ${PORT}  (NODE_ENV=${process.env.NODE_ENV || 'development'})`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * These tests run entirely in-process with no live database.
 * The `./db` module is replaced by a mock so every scenario can be
 * exercised deterministically and quickly.
 *
 * Run with:  node queries.test.js
 */

'use strict';

// ---------------------------------------------------------------------------
// Minimal test harness (no external dependencies)
// ---------------------------------------------------------------------------
let passed = 0;
let failed = 0;
const errors = [];

function assert(condition, message) {
  if (!condition) {
    throw new Error(`Assertion failed: ${message}`);
  }
}

function assertEqual(actual, expected, message) {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) {
    throw new Error(`${message}\n  expected: ${e}\n  received: ${a}`);
  }
}

async function test(description, fn) {
  try {
    await fn();
    console.log(`  ✓  ${description}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${description}`);
    console.error(`     ${err.message}`);
    errors.push({ description, error: err });
    failed++;
  }
}

// ---------------------------------------------------------------------------
// Mock the `./db` module before requiring `./queries`
// ---------------------------------------------------------------------------

// We intercept require() for './db' by inserting a fake into the module cache.
const Module = require('module');
const path   = require('path');

// Build the key that Node uses for the cache entry.
const dbModuleKey = path.resolve(__dirname, 'db.js');

// Mutable state so individual tests can control what the DB returns.
let mockRows       = [];
let mockShouldThrow = false;
let mockError       = null;
let capturedParams  = [];    // Records each (sql, params) pair for inspection.

Module._cache[dbModuleKey] = {
  id:       dbModuleKey,
  filename: dbModuleKey,
  loaded:   true,
  exports: {
    query: async (sql, params = []) => {
      capturedParams.push({ sql, params });
      if (mockShouldThrow) throw mockError || new Error('mock DB error');
      return { rows: mockRows, rowCount: mockRows.length };
    },
    getClient: async () => { throw new Error('not implemented in mock'); },
    end:       async () => {},
    poolStats: () => ({ total: 3, idle: 2, waiting: 0 }),
  },
};

// Now safe to require queries — it will pick up the mock above.
const {
  getUserById,
  getAllUsers,
  searchUsers,
  _escapeLikePattern,
  _toPositiveInt,
  _toSafeString,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helper: reset mock state before each test
// ---------------------------------------------------------------------------
function resetMock(rows = [], shouldThrow = false, error = null) {
  mockRows        = rows;
  mockShouldThrow = shouldThrow;
  mockError       = error;
  capturedParams  = [];
}

// ============================================================
// Suite 1: _escapeLikePattern()
// ============================================================
console.log('\n── escapeLikePattern ──────────────────────────────────');

await test('leaves plain strings unchanged', () => {
  assertEqual(_escapeLikePattern('alice'), 'alice', 'plain string');
});

await test('escapes % characters', () => {
  assertEqual(_escapeLikePattern('100%'), '100\\%', 'percent sign');
});

await test('escapes _ characters', () => {
  assertEqual(_escapeLikePattern('a_b'), 'a\\_b', 'underscore');
});

await test('escapes multiple special characters', () => {
  assertEqual(_escapeLikePattern('%_100_%'), '\\%\\_100\\_\\%', 'multiple specials');
});

await test('escapes backslash first (no double-escaping)', () => {
  assertEqual(_escapeLikePattern('a\\b'), 'a\\\\b', 'backslash');
});

// ============================================================
// Suite 2: _toPositiveInt()
// ============================================================
console.log('\n── toPositiveInt ──────────────────────────────────────');

await test('accepts a valid positive integer', () => {
  assertEqual(_toPositiveInt(5, 'id', 1), 5, 'valid int');
});

await test('accepts a numeric string', () => {
  assertEqual(_toPositiveInt('42', 'id', 1), 42, 'string "42"');
});

await test('accepts the minimum boundary value', () => {
  assertEqual(_toPositiveInt(1, 'id', 1, 100), 1, 'min boundary');
});

await test('accepts the maximum boundary value', () => {
  assertEqual(_toPositiveInt(100, 'id', 1, 100), 100, 'max boundary');
});

await test('accepts 0 when min=0 (offset)', () => {
  assertEqual(_toPositiveInt(0, 'offset', 0), 0, 'zero offset');
});

await test('rejects a float', () => {
  let threw = false;
  try { _toPositiveInt(1.5, 'id', 1); } catch { threw = true; }
  assert(threw, 'should throw for float');
});

await test('rejects a non-numeric string', () => {
  let threw = false;
  try { _toPositiveInt('abc', 'id', 1); } catch { threw = true; }
  assert(threw, 'should throw for non-numeric string');
});

await test('rejects a value below min', () => {
  let threw = false;
  try { _toPositiveInt(0, 'id', 1); } catch { threw = true; }
  assert(threw, 'should throw below min');
});

await test('rejects a value above max', () => {
  let threw = false;
  try { _toPositiveInt(300, 'limit', 1, 200); } catch { threw = true; }
  assert(threw, 'should throw above max');
});

await test('rejects SQL-injection strings', () => {
  let threw = false;
  try { _toPositiveInt("1; DROP TABLE users", 'id', 1); } catch { threw = true; }
  assert(threw, 'SQL injection string rejected');
});

// ============================================================
// Suite 3: _toSafeString()
// ============================================================
console.log('\n── toSafeString ───────────────────────────────────────');

await test('returns the trimmed string', () => {
  assertEqual(_toSafeString('  alice  ', 'query'), 'alice', 'trimmed');
});

await test('accepts the maximum allowed length', () => {
  const s = 'a'.repeat(200);
  assertEqual(_toSafeString(s, 'query', 200).length, 200, 'max length');
});

await test('rejects blank strings', () => {
  let threw = false;
  try { _toSafeString('   ', 'query'); } catch { threw = true; }
  assert(threw, 'blank string rejected');
});

await test('rejects non-string input', () => {
  let threw = false;
  try { _toSafeString(99, 'query'); } catch { threw = true; }
  assert(threw, 'non-string rejected');
});

await test('rejects strings exceeding maxLength', () => {
  let threw = false;
  try { _toSafeString('a'.repeat(201), 'query', 200); } catch { threw = true; }
  assert(threw, 'too-long string rejected');
});

// ============================================================
// Suite 4: getUserById()
// ============================================================
console.log('\n── getUserById ────────────────────────────────────────');

await test('returns the user row when found', async () => {
  const fakeUser = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };
  resetMock([fakeUser]);

  const result = await getUserById(1);

  assertEqual(result, fakeUser, 'returned user should match');
  assert(capturedParams.length === 1, 'exactly one query issued');
  assertEqual(capturedParams[0].params, [1], 'parameter is the id');
});

await test('returns null when user is not found', async () => {
  resetMock([]);
  const result = await getUserById(99);
  assert(result === null, 'should return null for no rows');
});

await test('passes id as a bound parameter (not interpolated)', async () => {
  resetMock([]);
  await getUserById(7);
  const { sql, params } = capturedParams[0];
  assert(!sql.includes('7'), 'id must not be interpolated into SQL text');
  assertEqual(params, [7], 'id sent as bound parameter');
});

await test('accepts a numeric-string id (coercion)', async () => {
  resetMock([{ id: 3, name: 'Carol', email: 'carol@example.com', created_at: new Date() }]);
  const result = await getUserById('3');
  assertEqual(capturedParams[0].params, [3], 'string coerced to integer');
  assert(result !== null, 'should find user');
});

await test('rejects a non-numeric id', async () => {
  resetMock([]);
  let threw = false;
  try { await getUserById('notanid'); } catch { threw = true; }
  assert(threw, 'non-numeric id should throw');
  assertEqual(capturedParams.length, 0, 'no query issued for invalid input');
});

await test('rejects a zero id', async () => {
  resetMock([]);
  let threw = false;
  try { await getUserById(0); } catch { threw = true; }
  assert(threw, 'id=0 should throw');
});

await test('rejects a negative id', async () => {
  resetMock([]);
  let threw = false;
  try { await getUserById(-5); } catch { threw = true; }
  assert(threw, 'negative id should throw');
});

await test('rejects SQL-injection id string', async () => {
  resetMock([]);
  let threw = false;
  try { await getUserById("1 OR 1=1"); } catch { threw = true; }
  assert(threw, 'SQL injection string rejected before DB call');
  assertEqual(capturedParams.length, 0, 'no query issued');
});

await test('propagates database errors', async () => {
  resetMock([], true, new Error('connection refused'));
  let threw = false;
  try { await getUserById(1); } catch (err) {
    threw = true;
    assert(err.message === 'connection refused', 'error message preserved');
  }
  assert(threw, 'DB error should propagate');
});

// ============================================================
// Suite 5: getAllUsers()
// ============================================================
console.log('\n── getAllUsers ─────────────────────────────────────────');

await test('returns shaped result with rows, total, limit, offset', async () => {
  const fakeRows = [
    { id: 1, name: 'Alice', email: 'a@a.com', created_at: new Date(), total_count: '2' },
    { id: 2, name: 'Bob',   email: 'b@b.com', created_at: new Date(), total_count: '2' },
  ];
  resetMock(fakeRows);

  const result = await getAllUsers(20, 0);

  assertEqual(result.total,  2,  'total extracted from window fn');
  assertEqual(result.limit,  20, 'limit echoed');
  assertEqual(result.offset, 0,  'offset echoed');
  assertEqual(result.rows.length, 2, 'two rows');
  assert(!('total_count' in result.rows[0]), 'total_count stripped from rows');
});

await test('passes limit and offset as bound parameters', async () => {
  resetMock([]);
  await getAllUsers(10, 30);

  const { params } = capturedParams[0];
  assertEqual(params, [10, 30], 'limit=10, offset=30 bound');
});

await test('uses default limit when omitted', async () => {
  resetMock([]);
  await getAllUsers();
  const { params } = capturedParams[0];
  assert(params[0] === 20, 'default limit is 20');
  assert(params[1] === 0,  'default offset is 0');
});

await test('total is 0 when no rows returned', async () => {
  resetMock([]);
  const result = await getAllUsers();
  assertEqual(result.total, 0, 'total should be 0');
  assertEqual(result.rows,  [], 'rows should be empty');
});

await test('rejects limit above MAX_LIMIT (200)', async () => {
  resetMock([]);
  let threw = false;
  try { await getAllUsers(201, 0); } catch { threw = true; }
  assert(threw, 'limit > 200 should throw');
  assertEqual(capturedParams.length, 0, 'no query issued');
});

await test('rejects limit of 0', async () => {
  resetMock([]);
  let threw = false;
  try { await getAllUsers(0, 0); } catch { threw = true; }
  assert(threw, 'limit=0 should throw');
});

await test('rejects negative offset', async () => {
  resetMock([]);
  let threw = false;
  try { await getAllUsers(10, -1); } catch { threw = true; }
  assert(threw, 'negative offset should throw');
});

await test('rejects non-numeric limit string', async () => {
  resetMock([]);
  let threw = false;
  try { await getAllUsers('all', 0); } catch { threw = true; }
  assert(threw, 'non-numeric limit should throw');
});

// ============================================================
// Suite 6: searchUsers()
// ============================================================
console.log('\n── searchUsers ────────────────────────────────────────');

await test('returns shaped result with rows, total, limit, offset, query', async () => {
  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), total_count: '1' },
  ];
  resetMock(fakeRows);

  const result = await searchUsers('alice');

  assertEqual(result.total,  1,       'total from window fn');
  assertEqual(result.query,  'alice', 'echoes validated term');
  assertEqual(result.rows.length, 1,  'one row');
  assert(!('total_count' in result.rows[0]), 'total_count stripped');
});

await test('wraps term in % wildcards as a bound parameter', async () => {
  resetMock([]);
  await searchUsers('bob');

  const { params } = capturedParams[0];
  assertEqual(params[0], '%bob%', 'pattern is %bob%');
});

await test('escapes % in search term to prevent wildcard injection', async () => {
  resetMock([]);
  await searchUsers('100%');
  const { params } = capturedParams[0];
  assertEqual(params[0], '%100\\%%', 'percent escaped');
});

await test('escapes _ in search term', async () => {
  resetMock([]);
  await searchUsers('a_b');
  const { params } = capturedParams[0];
  assertEqual(params[0], '%a\\_b%', 'underscore escaped');
});

await test('trims whitespace from the search term', async () => {
  resetMock([]);
  await searchUsers('  alice  ');
  const result = await searchUsers('  alice  ');
  // Should echo the trimmed value.
  assertEqual(capturedParams[1].params[0], '%alice%', 'trimmed term used in pattern');
});

await test('passes limit and offset as bound parameters', async () => {
  resetMock([]);
  await searchUsers('alice', 5, 10);

  const { params } = capturedParams[0];
  assertEqual(params[1], 5,  'limit bound');
  assertEqual(params[2], 10, 'offset bound');
});

await test('rejects blank search term', async () => {
  resetMock([]);
  let threw = false;
  try { await searchUsers('   '); } catch { threw = true; }
  assert(threw, 'blank term should throw');
  assertEqual(capturedParams.length, 0, 'no query issued');
});

await test('rejects non-string search term', async () => {
  resetMock([]);
  let threw = false;
  try { await searchUsers(null); } catch { threw = true; }
  assert(threw, 'null term should throw');
});

await test('rejects term exceeding 200 characters', async () => {
  resetMock([]);
  let threw = false;
  try { await searchUsers('a'.repeat(201)); } catch { threw = true; }
  assert(threw, 'overlong term should throw');
});

await test('rejects limit above MAX_LIMIT (200)', async () => {
  resetMock([]);
  let threw = false;
  try { await searchUsers('alice', 999); } catch { threw = true; }
  assert(threw, 'limit > 200 should throw');
});

await test('does not interpolate term into SQL text', async () => {
  resetMock([]);
  const injectionAttempt = "alice' OR '1'='1";
  // The validator will accept this as a valid string and pass it through.
  // The crucial thing is it goes into params[], not the SQL string.
  await searchUsers(injectionAttempt);
  const { sql, params } = capturedParams[0];
  assert(!sql.includes("OR '1'='1"), 'injection string not in SQL text');
  assert(params[0].includes("OR '1'='1"), 'injection string is only in params array');
});

await test('propagates database errors', async () => {
  resetMock([], true, new Error('timeout'));
  let threw = false;
  try { await searchUsers('alice'); } catch (err) {
    threw = true;
    assert(err.message === 'timeout', 'error message preserved');
  }
  assert(threw, 'DB error should propagate');
});

// ============================================================
// Summary
// ============================================================
console.log(`\n${'─'.repeat(56)}`);
console.log(`Results: ${passed} passed, ${failed} failed out of ${passed + failed} tests.\n`);

if (failed > 0) {
  console.error('FAILED TESTS:');
  errors.forEach(({ description, error }) => {
    console.error(`  • ${description}`);
    console.error(`    ${error.message}`);
  });
  process.exit(1);
} else {
  console.log('All tests passed ✓');
  process.exit(0);
}

