/**
 * db.js — PostgreSQL connection pool
 *
 * Reads configuration from environment variables (set via a .env file in
 * development, or injected by your platform in production).  A single Pool
 * instance is exported so every module that imports this file shares the
 * same pool — the canonical Node-postgres pattern for connection reuse.
 *
 * Environment variables (all optional — sensible defaults shown):
 *   DB_HOST          Hostname of the PostgreSQL server      (default: localhost)
 *   DB_PORT          Port the server listens on             (default: 5432)
 *   DB_NAME          Database / catalogue name              (default: app)
 *   DB_USER          Login role                             (default: postgres)
 *   DB_PASSWORD      Password for the login role            (required in prod)
 *   DB_SSL           Set to "true" to require TLS           (default: false)
 *   DB_POOL_MAX      Maximum open connections               (default: 10)
 *   DB_POOL_IDLE_MS  How long (ms) an idle connection lives (default: 30000)
 *   DB_POOL_CONN_MS  Connection-acquisition timeout (ms)    (default: 5000)
 */

'use strict';

const { Pool } = require('pg');
require('dotenv').config();   // no-op if dotenv is absent; env vars are already set

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
const poolConfig = {
  host:               process.env.DB_HOST         || 'localhost',
  port:     parseInt( process.env.DB_PORT  || '5432', 10),
  database:           process.env.DB_NAME         || 'app',
  user:               process.env.DB_USER         || 'postgres',
  password:           process.env.DB_PASSWORD,

  // Size / lifetime knobs
  max:                parseInt( process.env.DB_POOL_MAX      || '10',    10),
  idleTimeoutMillis:  parseInt( process.env.DB_POOL_IDLE_MS  || '30000', 10),
  connectionTimeoutMillis: parseInt( process.env.DB_POOL_CONN_MS || '5000', 10),

  // TLS: opt-in via DB_SSL=true, required in most cloud environments
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Lifecycle hooks — log pool-level events so ops can see saturation /
// connection errors without digging into per-query logs.
// ---------------------------------------------------------------------------
pool.on('connect', (client) => {
  // Fired each time a *new* physical TCP connection is opened (not on
  // checkout from an already-open connection).
  if (process.env.NODE_ENV !== 'test') {
    console.log(
      `[db] New client connected — pool size: ${pool.totalCount} ` +
      `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
    );
  }
});

pool.on('acquire', (_client) => {
  // Optional — uncomment for verbose per-query connection tracing.
  // console.log(`[db] Client acquired from pool`);
});

pool.on('remove', (_client) => {
  if (process.env.NODE_ENV !== 'test') {
    console.log(
      `[db] Client removed — pool size: ${pool.totalCount} ` +
      `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
    );
  }
});

pool.on('error', (err, _client) => {
  // Unhandled errors on idle clients (e.g. the DB restarted).
  // Log and let the pool reconnect on the next query; do not crash the
  // process — that is the caller's responsibility.
  console.error('[db] Unexpected error on idle client:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown — drain the pool when the process is asked to stop so
// that in-flight queries complete and connections are closed cleanly.
// ---------------------------------------------------------------------------
const shutdown = async (signal) => {
  console.log(`[db] ${signal} received — draining connection pool…`);
  try {
    await pool.end();
    console.log('[db] Pool drained. Goodbye.');
  } catch (err) {
    console.error('[db] Error while draining pool:', err.message);
  }
};

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * -----------------
 * 1. SQL injection prevention
 *    Every user-supplied value is passed as a *parameter* ($1, $2, …), never
 *    interpolated into the SQL string.  pg sends parameters separately over
 *    the wire so the server always parses the query template before it sees
 *    any data value — structural injection is categorically impossible.
 *
 *    The one partial exception is `searchUsers`, where `ILIKE` requires a
 *    pattern string.  The pattern is still sent as a parameter; we only
 *    escape the three special LIKE metacharacters (%, _, \) *inside* the
 *    value so a caller cannot accidentally turn a literal search term into a
 *    glob.  The escaping happens in JavaScript before the value reaches the
 *    DB driver.
 *
 * 2. Connection pooling
 *    We import the shared Pool from db.js.  `pool.query()` checks out a
 *    connection, runs the query, and returns it immediately — no manual
 *    `client.connect()` / `client.release()` lifecycle to manage.
 *
 * 3. Query timing
 *    Every function records a high-resolution start time with
 *    `process.hrtime.bigint()`, runs the query, then logs the elapsed time
 *    in milliseconds before returning.  Slow queries are flagged with a
 *    WARN log at ≥ SLOW_QUERY_THRESHOLD_MS (default 200 ms).
 *
 * 4. Input validation
 *    Bounds checks are applied to pagination parameters (limit, offset) and
 *    to the search query length before any SQL is issued.  Validation errors
 *    are thrown as plain Error objects with a `statusCode` property so the
 *    Express route handler can return an appropriate HTTP status without
 *    needing to know the internals of this module.
 *
 * Exported functions
 * ------------------
 *   getUserById(id)                    → single user row or null
 *   getAllUsers(limit, offset)         → { users[], total }
 *   searchUsers(query, limit, offset)  → { users[], total }
 */

'use strict';

const pool = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Queries that take longer than this (ms) are logged as warnings. */
const SLOW_QUERY_THRESHOLD_MS = 200;

/** Hard ceiling on the number of rows a caller may request per page. */
const MAX_LIMIT = 100;

/** Maximum length of a search query string (characters). */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Executes a parameterised query against the shared pool, logs timing
 * information, and returns the raw pg Result object.
 *
 * @param {string}   label  Human-readable name used in log lines.
 * @param {string}   sql    Query template with $1/$2/… placeholders.
 * @param {Array}    params Array of parameter values.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, sql, params = []) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, params);
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    if (elapsedMs >= SLOW_QUERY_THRESHOLD_MS) {
      console.warn(
        `[queries] SLOW ${label} — ${elapsedMs.toFixed(2)} ms ` +
        `(rows: ${result.rowCount}, threshold: ${SLOW_QUERY_THRESHOLD_MS} ms)`
      );
    } else {
      console.log(
        `[queries] ${label} — ${elapsedMs.toFixed(2)} ms ` +
        `(rows: ${result.rowCount})`
      );
    }

    return result;
  } catch (err) {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.error(
      `[queries] ERROR ${label} — ${elapsedMs.toFixed(2)} ms — ${err.message}`
    );
    throw err;
  }
}

/**
 * Creates a validation Error that carries an HTTP status code so the
 * route layer can forward it without extra logic.
 *
 * @param {string} message  Human-readable description.
 * @param {number} code     HTTP status code (default 400).
 * @returns {Error}
 */
function validationError(message, code = 400) {
  const err = new Error(message);
  err.statusCode = code;
  return err;
}

/**
 * Escapes LIKE / ILIKE metacharacters (%, _, \) inside a search term so the
 * literal string is matched rather than treated as a pattern.
 *
 * The escaped value is still sent to PostgreSQL as a *parameter*, not inline
 * SQL, so this only affects pattern semantics — not injection risk.
 *
 * @param {string} raw  Untrusted search string from the caller.
 * @returns {string}    Safe ILIKE pattern: %<escaped-term>%
 */
function buildLikePattern(raw) {
  const escaped = raw
    .replace(/\\/g, '\\\\')  // must be first — escapes the escape char
    .replace(/%/g,  '\\%')
    .replace(/_/g,  '\\_');
  return `%${escaped}%`;
}

/**
 * Validates and normalises the pagination parameters shared by
 * getAllUsers and searchUsers.
 *
 * @param {*} rawLimit   Value from the caller (may be string, number, etc.)
 * @param {*} rawOffset  Value from the caller.
 * @returns {{ limit: number, offset: number }}
 */
function normalisePagination(rawLimit, rawOffset) {
  const limit  = parseInt(rawLimit,  10);
  const offset = parseInt(rawOffset, 10);

  if (!Number.isFinite(limit)  || limit  < 1) {
    throw validationError(`"limit" must be a positive integer (got: ${rawLimit})`);
  }
  if (limit > MAX_LIMIT) {
    throw validationError(`"limit" may not exceed ${MAX_LIMIT} (got: ${limit})`);
  }
  if (!Number.isFinite(offset) || offset < 0) {
    throw validationError(`"offset" must be a non-negative integer (got: ${rawOffset})`);
  }

  return { limit, offset };
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetches a single user by primary key.
 *
 * Uses a parameterised query — `id` is never interpolated into SQL text.
 * Returns `null` when no row is found so callers can distinguish "not found"
 * from a database error without catching exceptions.
 *
 * @param {number|string} id  The user's primary key.
 * @returns {Promise<Object|null>}  The user row, or null.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(id) {
  // Validate: id must coerce to a finite integer > 0
  const numericId = parseInt(id, 10);
  if (!Number.isFinite(numericId) || numericId < 1) {
    throw validationError(`"id" must be a positive integer (got: ${id})`);
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
  `;

  const result = await timedQuery('getUserById', sql, [numericId]);
  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users together with the total row count
 * (useful for building pagination UI without a separate COUNT query).
 *
 * The total is calculated with `COUNT(*) OVER()` — a single round-trip to
 * the database covers both the page slice and the total count.
 *
 * @param {number} limit   Maximum rows to return (1–100).
 * @param {number} offset  Zero-based row offset for pagination.
 * @returns {Promise<{ users: Object[], total: number }>}
 *
 * @example
 *   const { users, total } = await getAllUsers(20, 0);
 */
async function getAllUsers(limit = 20, offset = 0) {
  const { limit: safeLimit, offset: safeOffset } = normalisePagination(limit, offset);

  // COUNT(*) OVER() is a window function that attaches the total result-set
  // size to every row without a subquery or second round-trip.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await timedQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  return {
    users: result.rows.map(({ total_count, ...user }) => user),
    total: result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0,
  };
}

/**
 * Full-text search over `name` and `email` columns using `ILIKE`.
 *
 * SQL injection prevention
 * ————————————————————————
 * • The search term travels to PostgreSQL as parameter $1 — the query
 *   template is compiled before the driver sees the value.
 * • LIKE metacharacters (%, _, \) are escaped with `buildLikePattern` so
 *   callers cannot accidentally widen the pattern (e.g. searching for "%"
 *   would otherwise match every row).
 * • Column names and the ILIKE keyword are static strings in this source
 *   file — no dynamic SQL construction.
 *
 * @param {string} query   The search term (max 200 characters).
 * @param {number} limit   Maximum rows to return (1–100, default 20).
 * @param {number} offset  Zero-based row offset (default 0).
 * @returns {Promise<{ users: Object[], total: number }>}
 *
 * @example
 *   const { users, total } = await searchUsers('alice', 10, 0);
 */
async function searchUsers(query, limit = 20, offset = 0) {
  // --- Validate search term ------------------------------------------------
  if (typeof query !== 'string' || query.trim().length === 0) {
    throw validationError('"query" must be a non-empty string');
  }
  if (query.length > MAX_SEARCH_LENGTH) {
    throw validationError(
      `"query" must not exceed ${MAX_SEARCH_LENGTH} characters (got: ${query.length})`
    );
  }

  // --- Validate pagination --------------------------------------------------
  const { limit: safeLimit, offset: safeOffset } = normalisePagination(limit, offset);

  // --- Build safe ILIKE pattern (still sent as a parameter) ----------------
  const pattern = buildLikePattern(query.trim());

  // $1 = ILIKE pattern, $2 = LIMIT, $3 = OFFSET
  // The same $1 is reused for both the name and email columns.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const result = await timedQuery('searchUsers', sql, [pattern, safeLimit, safeOffset]);

  return {
    users: result.rows.map(({ total_count, ...user }) => user),
    total: result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0,
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
};

/**
 * app.js — Express application
 *
 * /users endpoints
 * ────────────────
 *  GET /users               → paginated list  (query: limit, offset)
 *  GET /users/search        → ILIKE search    (query: q, limit, offset)
 *  GET /users/:id           → single user
 *
 * All database access goes through queries.js which uses parameterised
 * queries and a shared connection pool (db.js).
 */

'use strict';

require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler so that any thrown error (including
 * validation errors from queries.js with a `.statusCode` property, and
 * unexpected DB errors) is forwarded to Express's error middleware rather
 * than crashing the process via an unhandled-rejection.
 *
 * @param {Function} fn  Async (req, res, next) handler.
 * @returns {Function}   Standard Express middleware.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — no DB involvement
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ------------------------------------------------------------------
// GET /users
// Returns a paginated list of all users.
//
// Query parameters:
//   limit  {number}  Rows per page.  Default 20, max 100.
//   offset {number}  Zero-based starting row.  Default 0.
//
// Response 200:
//   {
//     "data":   [ { id, name, email, created_at, updated_at }, … ],
//     "total":  <number>,   // total rows matching (ignores pagination)
//     "limit":  <number>,
//     "offset": <number>
//   }
// ------------------------------------------------------------------
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    const limit  = req.query.limit  ?? 20;
    const offset = req.query.offset ?? 0;

    const { users, total } = await getAllUsers(limit, offset);

    res.json({
      data:   users,
      total,
      limit:  parseInt(limit,  10),
      offset: parseInt(offset, 10),
    });
  })
);

// ------------------------------------------------------------------
// GET /users/search
// ILIKE search over name and email columns.
// Must be declared BEFORE /users/:id so Express does not treat the
// literal string "search" as an :id value.
//
// Query parameters:
//   q      {string}  Search term (required, max 200 chars).
//   limit  {number}  Default 20, max 100.
//   offset {number}  Default 0.
//
// Response 200: same shape as GET /users
// Response 400: { "error": "<validation message>" }
// ------------------------------------------------------------------
app.get(
  '/users/search',
  asyncHandler(async (req, res) => {
    const { q, limit = 20, offset = 0 } = req.query;

    if (!q || String(q).trim().length === 0) {
      return res.status(400).json({
        error: 'Missing required query parameter: q',
      });
    }

    const { users, total } = await searchUsers(q, limit, offset);

    res.json({
      data:   users,
      total,
      query:  q,
      limit:  parseInt(limit,  10),
      offset: parseInt(offset, 10),
    });
  })
);

// ------------------------------------------------------------------
// GET /users/:id
// Fetches a single user by primary key.
//
// URL parameters:
//   id  {number}  Positive integer primary key.
//
// Response 200: { id, name, email, created_at, updated_at }
// Response 400: { "error": "<validation message>" }
// Response 404: { "error": "User not found" }
// ------------------------------------------------------------------
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  })
);

// ---------------------------------------------------------------------------
// Centralised error handler
// Catches both validation errors (statusCode 400) from queries.js and
// unexpected errors (statusCode defaults to 500).
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  const status = err.statusCode ?? 500;

  if (status >= 500) {
    console.error('[app] Unhandled error:', err.message, err.stack);
  }

  res.status(status).json({
    error: status >= 500 ? 'Internal server error' : err.message,
  });
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = parseInt(process.env.PORT || '3000', 10);
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * The pg Pool is mocked entirely so these tests run without a real
 * PostgreSQL instance.  The mock is set up once per test file and each
 * individual test can override `mockQuery` to control what the pool returns.
 *
 * Run with:  node queries.test.js
 * (Uses only Node built-ins — no test framework required.)
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock pg *before* requiring queries.js so the module picks up the fake pool
// ---------------------------------------------------------------------------

/** Holds the function that the next pool.query() call will execute. */
let mockQuery = async () => ({ rows: [], rowCount: 0 });

jest.mock('pg', () => {
  return {
    Pool: jest.fn().mockImplementation(() => ({
      query: jest.fn((...args) => mockQuery(...args)),
      on:    jest.fn(),
      end:   jest.fn().mockResolvedValue(undefined),
      get totalCount()  { return 1; },
      get idleCount()   { return 1; },
      get waitingCount(){ return 0; },
    })),
  };
});

jest.mock('dotenv', () => ({ config: jest.fn() }));

// ---------------------------------------------------------------------------
// Re-require the module under test after mocks are in place
// ---------------------------------------------------------------------------
const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ---------------------------------------------------------------------------
// A tiny assertion helper (avoids a test-framework dependency while keeping
// the tests readable).
// ---------------------------------------------------------------------------
let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    console.log(`  ✓  ${message}`);
    passed++;
  } else {
    console.error(`  ✗  ${message}`);
    failed++;
  }
}

async function assertRejects(fn, expectedMessageFragment, testLabel) {
  try {
    await fn();
    console.error(`  ✗  ${testLabel} — expected an error but none was thrown`);
    failed++;
  } catch (err) {
    if (err.message.includes(expectedMessageFragment)) {
      console.log(`  ✓  ${testLabel}`);
      passed++;
    } else {
      console.error(
        `  ✗  ${testLabel} — wrong error message.\n` +
        `       Expected to contain: "${expectedMessageFragment}"\n` +
        `       Got: "${err.message}"`
      );
      failed++;
    }
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

async function testGetUserById() {
  console.log('\n── getUserById ──');

  // Happy path: row found
  mockQuery = async (_sql, params) => ({
    rows:     [{ id: params[0], name: 'Alice', email: 'alice@example.com',
                 created_at: new Date(), updated_at: new Date() }],
    rowCount: 1,
  });
  const user = await getUserById(1);
  assert(user !== null,              'returns a user object when found');
  assert(user.id === 1,              'returns correct id');
  assert(user.name === 'Alice',      'returns correct name');

  // Not found: empty rows → null
  mockQuery = async () => ({ rows: [], rowCount: 0 });
  const missing = await getUserById(999);
  assert(missing === null, 'returns null when user is not found');

  // Validation: non-numeric id
  await assertRejects(
    () => getUserById('abc'),
    '"id" must be a positive integer',
    'throws validation error for non-numeric id'
  );

  // Validation: negative id
  await assertRejects(
    () => getUserById(-5),
    '"id" must be a positive integer',
    'throws validation error for negative id'
  );

  // Validation: zero
  await assertRejects(
    () => getUserById(0),
    '"id" must be a positive integer',
    'throws validation error for id = 0'
  );

  // SQL injection check: verify query uses parameterised form
  let capturedSql, capturedParams;
  mockQuery = async (sql, params) => {
    capturedSql    = sql;
    capturedParams = params;
    return { rows: [], rowCount: 0 };
  };
  await getUserById(7);
  assert(
    capturedSql.includes('$1') && !capturedSql.includes('7'),
    'SQL template uses $1 placeholder, not inline value'
  );
  assert(
    Array.isArray(capturedParams) && capturedParams[0] === 7,
    'Numeric id is passed as a parameter, not interpolated'
  );
}

async function testGetAllUsers() {
  console.log('\n── getAllUsers ──');

  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com',
      created_at: new Date(), updated_at: new Date(), total_count: '2' },
    { id: 2, name: 'Bob',   email: 'bob@example.com',
      created_at: new Date(), updated_at: new Date(), total_count: '2' },
  ];

  mockQuery = async () => ({ rows: fakeRows, rowCount: 2 });

  // Happy path
  const { users, total } = await getAllUsers(10, 0);
  assert(Array.isArray(users),    'returns users array');
  assert(users.length === 2,      'returns correct number of rows');
  assert(total === 2,             'returns correct total count');
  assert(!('total_count' in users[0]), 'strips internal total_count field from row');

  // Default parameters
  mockQuery = async (_sql, params) => {
    assert(params[0] === 20, 'default limit is 20');
    assert(params[1] === 0,  'default offset is 0');
    return { rows: [], rowCount: 0 };
  };
  await getAllUsers();

  // Validation: limit too large
  await assertRejects(
    () => getAllUsers(101, 0),
    '"limit" may not exceed 100',
    'rejects limit > 100'
  );

  // Validation: negative offset
  await assertRejects(
    () => getAllUsers(10, -1),
    '"offset" must be a non-negative integer',
    'rejects negative offset'
  );

  // Validation: non-numeric limit
  await assertRejects(
    () => getAllUsers('banana', 0),
    '"limit" must be a positive integer',
    'rejects non-numeric limit'
  );

  // Parameterisation check
  let capturedSql2, capturedParams2;
  mockQuery = async (sql, params) => {
    capturedSql2    = sql;
    capturedParams2 = params;
    return { rows: [], rowCount: 0 };
  };
  await getAllUsers(5, 10);
  assert(
    capturedSql2.includes('$1') && capturedSql2.includes('$2'),
    'SQL uses $1 and $2 placeholders for LIMIT and OFFSET'
  );
  assert(
    capturedParams2[0] === 5 && capturedParams2[1] === 10,
    'Correct limit/offset values passed as parameters'
  );
}

async function testSearchUsers() {
  console.log('\n── searchUsers ──');

  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com',
      created_at: new Date(), updated_at: new Date(), total_count: '1' },
  ];

  mockQuery = async () => ({ rows: fakeRows, rowCount: 1 });

  // Happy path
  const { users, total } = await searchUsers('alice', 10, 0);
  assert(users.length === 1, 'returns matching users');
  assert(total === 1,        'returns correct total');

  // ILIKE pattern construction
  let capturedParams3;
  mockQuery = async (_sql, params) => {
    capturedParams3 = params;
    return { rows: [], rowCount: 0 };
  };
  await searchUsers('alice', 10, 0);
  assert(
    capturedParams3[0] === '%alice%',
    'search term is wrapped in % wildcards'
  );

  // LIKE metacharacter escaping
  await searchUsers('100%off', 10, 0);
  assert(
    capturedParams3[0] === '%100\\%off%',
    '% in search term is escaped to prevent unintended wildcard'
  );

  await searchUsers('user_name', 10, 0);
  assert(
    capturedParams3[0] === '%user\\_name%',
    '_ in search term is escaped to prevent single-char wildcard'
  );

  await searchUsers('back\\slash', 10, 0);
  assert(
    capturedParams3[0] === '%back\\\\slash%',
    '\\ in search term is escaped'
  );

  // Verify $1 is reused for both name and email columns
  let capturedSql3;
  mockQuery = async (sql, params) => {
    capturedSql3    = sql;
    capturedParams3 = params;
    return { rows: [], rowCount: 0 };
  };
  await searchUsers('test', 10, 0);
  const occurrences = (capturedSql3.match(/\$1/g) || []).length;
  assert(
    occurrences >= 2,
    '$1 placeholder appears at least twice (name ILIKE $1 AND email ILIKE $1)'
  );
  assert(
    !capturedSql3.includes("'test'"),
    'Raw search string is NOT interpolated into SQL text'
  );

  // Validation: empty query
  await assertRejects(
    () => searchUsers('', 10, 0),
    '"query" must be a non-empty string',
    'rejects empty search query'
  );

  // Validation: whitespace-only query
  await assertRejects(
    () => searchUsers('   ', 10, 0),
    '"query" must be a non-empty string',
    'rejects whitespace-only search query'
  );

  // Validation: query too long
  await assertRejects(
    () => searchUsers('x'.repeat(201), 10, 0),
    '"query" must not exceed 200 characters',
    'rejects search query longer than 200 characters'
  );

  // Validation: limit exceeded
  await assertRejects(
    () => searchUsers('alice', 200, 0),
    '"limit" may not exceed 100',
    'rejects limit > 100 in searchUsers'
  );
}

// ---------------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------------

(async () => {
  try {
    await testGetUserById();
    await testGetAllUsers();
    await testSearchUsers();
  } catch (err) {
    console.error('\nTest runner crashed:', err);
    process.exit(1);
  }

  console.log(`\n${'─'.repeat(40)}`);
  console.log(`Results: ${passed} passed, ${failed} failed`);
  process.exit(failed > 0 ? 1 : 0);
})();

