// A tiny assertion helper (avoids a test-framework dependency while keeping
// the tests readable).
// ---------------------------------------------------------------------------
let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    console.log(`  ✓  ${message}`);
    passed++;
  } else {
    console.error(`  ✗  ${message}`);
    failed++;
  }
}

async function assertRejects(fn, expectedMessageFragment, testLabel) {
  try {
    await fn();
    console.error(`  ✗  ${testLabel} — expected an error but none was thrown`);
    failed++;
  } catch (err) {
    if (err.message.includes(expectedMessageFragment)) {
      console.log(`  ✓  ${testLabel}`);
      passed++;
    } else {
      console.error(
        `  ✗  ${testLabel} — wrong error message.\n` +
        `       Expected to contain: "${expectedMessageFragment}"\n` +
        `       Got: "${err.message}"`
      );
      failed++;
    }
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

async function testGetUserById() {
  console.log('\n── getUserById ──');

  // Happy path: row found
  mockQuery = async (_sql, params) => ({
    rows:     [{ id: params[0], name: 'Alice', email: 'alice@example.com',
                 created_at: new Date(), updated_at: new Date() }],
    rowCount: 1,
  });
  const user = await getUserById(1);
  assert(user !== null,              'returns a user object when found');
  assert(user.id === 1,              'returns correct id');
  assert(user.name === 'Alice',      'returns correct name');

  // Not found: empty rows → null
  mockQuery = async () => ({ rows: [], rowCount: 0 });
  const missing = await getUserById(999);
  assert(missing === null, 'returns null when user is not found');

  // Validation: non-numeric id
  await assertRejects(
    () => getUserById('abc'),
    '"id" must be a positive integer',
    'throws validation error for non-numeric id'
  );

  // Validation: negative id
  await assertRejects(
    () => getUserById(-5),
    '"id" must be a positive integer',
    'throws validation error for negative id'
  );

  // Validation: zero
  await assertRejects(
    () => getUserById(0),
    '"id" must be a positive integer',
    'throws validation error for id = 0'
  );

  // SQL injection check: verify query uses parameterised form
  let capturedSql, capturedParams;
  mockQuery = async (sql, params) => {
    capturedSql    = sql;
    capturedParams = params;
    return { rows: [], rowCount: 0 };
  };
  await getUserById(7);
  assert(
    capturedSql.includes('$1') && !capturedSql.includes('7'),
    'SQL template uses $1 placeholder, not inline value'
  );
  assert(
    Array.isArray(capturedParams) && capturedParams[0] === 7,
    'Numeric id is passed as a parameter, not interpolated'
  );
}

async function testGetAllUsers() {
  console.log('\n── getAllUsers ──');

  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com',
      created_at: new Date(), updated_at: new Date(), total_count: '2' },
    { id: 2, name: 'Bob',   email: 'bob@example.com',
      created_at: new Date(), updated_at: new Date(), total_count: '2' },
  ];

  mockQuery = async () => ({ rows: fakeRows, rowCount: 2 });

  // Happy path
  const { users, total } = await getAllUsers(10, 0);
  assert(Array.isArray(users),    'returns users array');
  assert(users.length === 2,      'returns correct number of rows');
  assert(total === 2,             'returns correct total count');
  assert(!('total_count' in users[0]), 'strips internal total_count field from row');

  // Default parameters
  mockQuery = async (_sql, params) => {
    assert(params[0] === 20, 'default limit is 20');
    assert(params[1] === 0,  'default offset is 0');
    return { rows: [], rowCount: 0 };
  };
  await getAllUsers();

  // Validation: limit too large
  await assertRejects(
    () => getAllUsers(101, 0),
    '"limit" may not exceed 100',
    'rejects limit > 100'
  );

  // Validation: negative offset
  await assertRejects(
    () => getAllUsers(10, -1),
    '"offset" must be a non-negative integer',
    'rejects negative offset'
  );

  // Validation: non-numeric limit
  await assertRejects(
    () => getAllUsers('banana', 0),
    '"limit" must be a positive integer',
    'rejects non-numeric limit'
  );

  // Parameterisation check
  let capturedSql2, capturedParams2;
  mockQuery = async (sql, params) => {
    capturedSql2    = sql;
    capturedParams2 = params;
    return { rows: [], rowCount: 0 };
  };
  await getAllUsers(5, 10);
  assert(
    capturedSql2.includes('$1') && capturedSql2.includes('$2'),
    'SQL uses $1 and $2 placeholders for LIMIT and OFFSET'
  );
  assert(
    capturedParams2[0] === 5 && capturedParams2[1] === 10,
    'Correct limit/offset values passed as parameters'
  );
}

async function testSearchUsers() {
  console.log('\n── searchUsers ──');

  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com',
      created_at: new Date(), updated_at: new Date(), total_count: '1' },
  ];

  mockQuery = async () => ({ rows: fakeRows, rowCount: 1 });

  // Happy path
  const { users, total } = await searchUsers('alice', 10, 0);
  assert(users.length === 1, 'returns matching users');
  assert(total === 1,        'returns correct total');

  // ILIKE pattern construction
  let capturedParams3;
  mockQuery = async (_sql, params) => {
    capturedParams3 = params;
    return { rows: [], rowCount: 0 };
  };
  await searchUsers('alice', 10, 0);
  assert(
    capturedParams3[0] === '%alice%',
    'search term is wrapped in % wildcards'
  );

  // LIKE metacharacter escaping
  await searchUsers('100%off', 10, 0);
  assert(
    capturedParams3[0] === '%100\\%off%',
    '% in search term is escaped to prevent unintended wildcard'
  );

  await searchUsers('user_name', 10, 0);
  assert(
    capturedParams3[0] === '%user\\_name%',
    '_ in search term is escaped to prevent single-char wildcard'
  );

  await searchUsers('back\\slash', 10, 0);
  assert(
    capturedParams3[0] === '%back\\\\slash%',
    '\\ in search term is escaped'
  );

  // Verify $1 is reused for both name and email columns
  let capturedSql3;
  mockQuery = async (sql, params) => {
    capturedSql3    = sql;
    capturedParams3 = params;
    return { rows: [], rowCount: 0 };
  };
  await searchUsers('test', 10, 0);
  const occurrences = (capturedSql3.match(/\$1/g) || []).length;
  assert(
    occurrences >= 2,
    '$1 placeholder appears at least twice (name ILIKE $1 AND email ILIKE $1)'
  );
  assert(
    !capturedSql3.includes("'test'"),
    'Raw search string is NOT interpolated into SQL text'
  );

  // Validation: empty query
  await assertRejects(
    () => searchUsers('', 10, 0),
    '"query" must be a non-empty string',
    'rejects empty search query'
  );

  // Validation: whitespace-only query
  await assertRejects(
    () => searchUsers('   ', 10, 0),
    '"query" must be a non-empty string',
    'rejects whitespace-only search query'
  );

  // Validation: query too long
  await assertRejects(
    () => searchUsers('x'.repeat(201), 10, 0),
    '"query" must not exceed 200 characters',
    'rejects search query longer than 200 characters'
  );

  // Validation: limit exceeded
  await assertRejects(
    () => searchUsers('alice', 200, 0),
    '"limit" may not exceed 100',
    'rejects limit > 100 in searchUsers'
  );
}

