/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared `pg.Pool` instance so that every module
 * in the application reuses the same set of connections instead of
 * opening a new one per request.
 *
 * The pool is configured entirely from environment variables so that
 * no credentials ever appear in source code.
 */

'use strict';

const { Pool } = require('pg');

// ─── Pool configuration ───────────────────────────────────────────────────────

const poolConfig = {
  // If DATABASE_URL is present it wins; otherwise fall back to discrete vars.
  ...(process.env.DATABASE_URL
    ? {
        connectionString: process.env.DATABASE_URL,
        // Require SSL in production unless explicitly disabled.
        ssl:
          process.env.NODE_ENV === 'production'
            ? { rejectUnauthorized: true }
            : false,
      }
    : {
        host:     process.env.DB_HOST     || 'localhost',
        port:     parseInt(process.env.DB_PORT || '5432', 10),
        database: process.env.DB_NAME     || 'myapp',
        user:     process.env.DB_USER     || 'myapp_user',
        password: process.env.DB_PASSWORD,          // never supply a default
        ssl:
          process.env.NODE_ENV === 'production'
            ? { rejectUnauthorized: true }
            : false,
      }),

  // Pool sizing
  max:              parseInt(process.env.DB_POOL_MAX            || '10',   10),
  idleTimeoutMillis:parseInt(process.env.DB_POOL_IDLE_MS        || '10000',10),
  connectionTimeoutMillis:
                    parseInt(process.env.DB_POOL_CONN_TIMEOUT_MS || '3000', 10),

  // Keep underlying TCP connections alive so the OS does not silently
  // drop idle sockets (common on cloud NATs).
  keepAlive: true,
};

const pool = new Pool(poolConfig);

// ─── Pool-level event hooks ───────────────────────────────────────────────────

/**
 * Emitted once per *new physical connection* (not per checkout from the pool).
 * Use this to set session-level configuration that should apply to every
 * connection, e.g. search_path or application_name.
 */
pool.on('connect', (client) => {
  // Tag connections so they are identifiable in pg_stat_activity.
  client.query("SELECT set_config('application_name', 'users-api', false)")
    .catch(() => { /* non-fatal */ });
});

/**
 * Emitted whenever a pool client raises an error while it is idle
 * (i.e. not currently checked out by application code).  Without this
 * handler the error would be an unhandled rejection and crash the process.
 */
pool.on('error', (err) => {
  console.error('[db] Idle client error:', err.message);
});

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Gracefully drain the pool.  Call this during SIGTERM / SIGINT handling so
 * in-flight queries finish before the process exits.
 */
async function closePool() {
  await pool.end();
  console.log('[db] Pool closed.');
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * ─────────────────
 * 1. SQL injection prevention
 *    Every piece of user-supplied data is passed as a *parameter* ($1, $2 …)
 *    never interpolated into the query string.  The `pg` driver sends the
 *    query text and the parameter array to PostgreSQL separately over the
 *    wire protocol, so the database engine itself keeps them apart — the
 *    parameters are never parsed as SQL.
 *
 *    Input validation (type coercion + range checks) is performed before the
 *    query is issued as a second line of defence.
 *
 * 2. Connection pooling
 *    All functions receive the shared `pool` exported by db.js and call
 *    `pool.query()`.  The pool automatically acquires a client, executes the
 *    query, and returns the client to the pool — no manual checkout/release
 *    required for single-statement operations.
 *
 * 3. Query timing logs
 *    Every query is wrapped in `timedQuery()` which records wall-clock
 *    duration, logs it, and emits a WARNING when the duration exceeds the
 *    configurable `DB_SLOW_QUERY_MS` threshold (default 200 ms).
 *
 * 4. Structured error handling
 *    Database errors are caught, stripped of internal details, and re-thrown
 *    as typed `QueryError` instances so callers can distinguish DB failures
 *    from validation failures without leaking stack traces or SQL to clients.
 */

'use strict';

// ─── Constants ───────────────────────────────────────────────────────────────

const SLOW_QUERY_THRESHOLD_MS = parseInt(
  process.env.DB_SLOW_QUERY_MS || '200',
  10,
);

/** Hard ceiling on how many rows a single request may fetch. */
const MAX_LIMIT = 100;

/** Columns the searchUsers ILIKE filter is permitted to act on. */
const SEARCHABLE_COLUMNS = new Set(['name', 'email']);

/**
 * Columns that getAllUsers / getUserById are allowed to ORDER BY.
 * Maintained as an allowlist so a caller cannot inject an arbitrary
 * expression into the ORDER BY clause.
 */
const SORTABLE_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);

// ─── Typed error class ────────────────────────────────────────────────────────

class QueryError extends Error {
  /**
   * @param {string}  message   Safe, client-visible description.
   * @param {string}  code      Short machine-readable code.
   * @param {Error}  [cause]    Original pg error (kept server-side only).
   */
  constructor(message, code, cause) {
    super(message);
    this.name    = 'QueryError';
    this.code    = code;
    this.cause   = cause;   // NOT forwarded to HTTP responses
  }
}

// ─── Validation helpers ───────────────────────────────────────────────────────

/**
 * Parse and validate a user-supplied integer.
 * Throws a `QueryError` (code: 'VALIDATION_ERROR') if the value is not a
 * safe positive integer within [min, max].
 *
 * @param {unknown} value
 * @param {string}  name   Field name used in the error message.
 * @param {object}  [opts]
 * @param {number}  [opts.min=1]
 * @param {number}  [opts.max=Number.MAX_SAFE_INTEGER]
 * @returns {number}
 */
function parsePositiveInt(value, name, { min = 1, max = Number.MAX_SAFE_INTEGER } = {}) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < min || n > max) {
    throw new QueryError(
      `"${name}" must be an integer between ${min} and ${max}; received: ${JSON.stringify(value)}`,
      'VALIDATION_ERROR',
    );
  }
  return n;
}

/**
 * Validate that `column` is in the given allowlist Set.
 * Throws a `QueryError` (code: 'VALIDATION_ERROR') otherwise.
 *
 * @param {string}  column
 * @param {Set<string>} allowlist
 * @param {string}  paramName   Used in the error message.
 * @returns {string}
 */
function validateColumn(column, allowlist, paramName) {
  if (typeof column !== 'string' || !allowlist.has(column)) {
    throw new QueryError(
      `Invalid ${paramName} "${column}". Allowed values: ${[...allowlist].join(', ')}.`,
      'VALIDATION_ERROR',
    );
  }
  return column;
}

/**
 * Validate sort direction ('ASC' | 'DESC').
 * Always returns an upper-cased string from the fixed set {'ASC','DESC'} so it
 * is safe to interpolate directly into a query string.
 *
 * @param {string} [direction='ASC']
 * @returns {'ASC'|'DESC'}
 */
function validateSortDirection(direction = 'ASC') {
  const upper = String(direction).toUpperCase();
  if (upper !== 'ASC' && upper !== 'DESC') {
    throw new QueryError(
      `Sort direction must be "ASC" or "DESC"; received: ${JSON.stringify(direction)}`,
      'VALIDATION_ERROR',
    );
  }
  return upper;
}

/**
 * Sanitise a free-text search string.
 * - Trims surrounding whitespace.
 * - Rejects empty strings.
 * - Enforces a maximum length to prevent oversized queries.
 *
 * The returned value is still passed as a parameterised value ($N) — this
 * function does NOT attempt to escape SQL metacharacters itself.
 *
 * @param {unknown} value
 * @returns {string}
 */
function validateSearchQuery(value) {
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new QueryError(
      '"query" must be a non-empty string.',
      'VALIDATION_ERROR',
    );
  }
  const trimmed = value.trim();
  if (trimmed.length > 200) {
    throw new QueryError(
      '"query" must not exceed 200 characters.',
      'VALIDATION_ERROR',
    );
  }
  return trimmed;
}

// ─── Query timing wrapper ─────────────────────────────────────────────────────

/**
 * Execute a parameterised query, log its duration, and warn on slow queries.
 *
 * @param {import('pg').Pool} pool        Shared connection pool.
 * @param {string}            queryName   Human-readable label for log output.
 * @param {string}            text        SQL query text (with $N placeholders).
 * @param {unknown[]}         params      Bound parameter values.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(pool, queryName, text, params) {
  const startedAt = Date.now();

  try {
    const result = await pool.query(text, params);
    const durationMs = Date.now() - startedAt;

    const level = durationMs >= SLOW_QUERY_THRESHOLD_MS ? 'WARN ' : 'INFO ';
    const slowTag = durationMs >= SLOW_QUERY_THRESHOLD_MS ? ' ⚠ SLOW QUERY' : '';

    console.log(
      `[db] ${level} query="${queryName}" rows=${result.rowCount} duration=${durationMs}ms${slowTag}`,
    );

    return result;
  } catch (err) {
    const durationMs = Date.now() - startedAt;

    // Log the full pg error server-side (includes query text + params for
    // debugging) but do NOT let it propagate to HTTP response bodies.
    console.error(
      `[db] ERROR query="${queryName}" duration=${durationMs}ms code=${err.code} message=${err.message}`,
    );

    throw new QueryError(
      'A database error occurred. Please try again later.',
      'DB_ERROR',
      err,   // attached as .cause — never serialised to JSON by default
    );
  }
}

// ─── Query functions ──────────────────────────────────────────────────────────

/**
 * Fetch a single user by their primary key.
 *
 * SQL injection prevention
 * ────────────────────────
 * `id` is validated as a positive integer and then passed as the bound
 * parameter $1.  The query text never changes.
 *
 * @param {import('pg').Pool} pool
 * @param {number|string} id   User ID (will be coerced to a positive integer).
 * @returns {Promise<object|null>}  The user row, or `null` if not found.
 *
 * @example
 * const user = await getUserById(pool, 42);
 * // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: Date }
 */
async function getUserById(pool, id) {
  // Validate — throws QueryError on bad input before any DB round-trip.
  const safeId = parsePositiveInt(id, 'id');

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
  `;

  const result = await timedQuery(pool, 'getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * Return a paginated list of users.
 *
 * SQL injection prevention
 * ────────────────────────
 * - `limit` and `offset` are validated as non-negative integers and passed as
 *   bound parameters $1 and $2.
 * - `orderBy` is validated against the `SORTABLE_COLUMNS` allowlist and then
 *   interpolated into the query string as a bare identifier — only after
 *   allowlist membership is confirmed, making injection impossible.
 * - `direction` is validated to be exactly 'ASC' or 'DESC' before
 *   interpolation; no user string ever reaches the query as-is.
 *
 * @param {import('pg').Pool} pool
 * @param {number}  [limit=20]      Rows per page (1–100).
 * @param {number}  [offset=0]      Number of rows to skip (≥ 0).
 * @param {string}  [orderBy='id']  Column to sort by.
 * @param {string}  [direction='ASC']  'ASC' or 'DESC'.
 * @returns {Promise<{ users: object[], total: number }>}
 *
 * @example
 * const { users, total } = await getAllUsers(pool, 10, 0, 'name', 'ASC');
 */
async function getAllUsers(pool, limit = 20, offset = 0, orderBy = 'id', direction = 'ASC') {
  // Validate numeric params.
  const safeLimit  = parsePositiveInt(limit,  'limit',  { min: 1, max: MAX_LIMIT });
  const safeOffset = parsePositiveInt(offset, 'offset', { min: 0 });

  // Validate and allowlist-check sorting inputs before any interpolation.
  const safeOrderBy   = validateColumn(orderBy, SORTABLE_COLUMNS, 'orderBy');
  const safeDirection = validateSortDirection(direction);

  // `safeOrderBy` and `safeDirection` are safe to interpolate: they have been
  // validated against closed sets and cannot contain SQL metacharacters.
  // All user-supplied numeric values remain as bound parameters.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER () AS total_count
    FROM users
    ORDER BY ${safeOrderBy} ${safeDirection}
    LIMIT  $1
    OFFSET $2
  `;

  const result = await timedQuery(pool, 'getAllUsers', sql, [safeLimit, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  // Strip the synthetic total_count column from each row before returning.
  const users = result.rows.map(({ total_count, ...rest }) => rest);

  return { users, total };
}

/**
 * Full-text style search across user name and email using case-insensitive
 * pattern matching.
 *
 * SQL injection prevention
 * ────────────────────────
 * - `query` (the search term) is passed entirely as the bound parameter $1
 *   wrapped in `%…%` wildcards.  The `pg` driver handles escaping, so LIKE
 *   metacharacters (%, _, \) in the user's string match literally against the
 *   stored data without being interpreted as SQL.
 * - `searchIn` is validated against the `SEARCHABLE_COLUMNS` allowlist before
 *   being interpolated as an identifier.
 * - `limit` and `offset` are bound parameters $2 and $3.
 *
 * @param {import('pg').Pool} pool
 * @param {string}   query          Search term (non-empty, max 200 chars).
 * @param {object}   [options]
 * @param {string}   [options.searchIn='name']  Column to search in.
 * @param {number}   [options.limit=20]
 * @param {number}   [options.offset=0]
 * @returns {Promise<{ users: object[], total: number }>}
 *
 * @example
 * const { users, total } = await searchUsers(pool, 'ali', { searchIn: 'name' });
 */
async function searchUsers(pool, query, { searchIn = 'name', limit = 20, offset = 0 } = {}) {
  // Validate free-text input.
  const safeQuery = validateSearchQuery(query);

  // Validate allowlisted column identifier.
  const safeColumn = validateColumn(searchIn, SEARCHABLE_COLUMNS, 'searchIn');

  // Validate numeric pagination params.
  const safeLimit  = parsePositiveInt(limit,  'limit',  { min: 1, max: MAX_LIMIT });
  const safeOffset = parsePositiveInt(offset, 'offset', { min: 0 });

  // The wildcard pattern is built server-side and passed as a bound parameter.
  // The pg driver handles any LIKE metacharacters inside safeQuery safely.
  const pattern = `%${safeQuery}%`;

  // `safeColumn` is safe to interpolate (allowlist-validated identifier only).
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER () AS total_count
    FROM users
    WHERE ${safeColumn} ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const result = await timedQuery(pool, 'searchUsers', sql, [pattern, safeLimit, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  const users = result.rows.map(({ total_count, ...rest }) => rest);

  return { users, total };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryError,     // exported so route handlers can instanceof-check it
  // Expose constants so tests can reference them without magic numbers.
  MAX_LIMIT,
  SEARCHABLE_COLUMNS,
  SORTABLE_COLUMNS,
};

/**
 * app.js — Express application with PostgreSQL query layer
 *
 * Endpoints
 * ─────────
 *   GET /health
 *   GET /users              — paginated list  (limit, offset, orderBy, direction)
 *   GET /users/search       — search users    (q, searchIn, limit, offset)
 *   GET /users/:id          — single user by ID
 */

'use strict';

// Load environment variables from .env before any other module reads
// process.env.  In production these are usually injected by the runtime.
require('dotenv').config();

const express = require('express');
const { pool, closePool } = require('./db');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryError,
} = require('./queries');

const app = express();
const PORT = parseInt(process.env.PORT || '3000', 10);

// ─── Middleware ───────────────────────────────────────────────────────────────

app.use(express.json());

/**
 * Request logger — records method, path, status code, and wall-clock duration
 * for every request so slow handlers are visible in the same log stream as
 * slow queries.
 */
app.use((req, res, next) => {
  const startedAt = Date.now();

  res.on('finish', () => {
    const durationMs = Date.now() - startedAt;
    console.log(
      `[http] ${req.method} ${req.originalUrl} → ${res.statusCode} (${durationMs}ms)`,
    );
  });

  next();
});

// ─── Routes ───────────────────────────────────────────────────────────────────

// ── GET /health ──────────────────────────────────────────────────────────────
/**
 * Liveness + database connectivity probe.
 * Returns 200 when the app is running and the pool can reach the database,
 * or 503 with a JSON error body if the database is unreachable.
 */
app.get('/health', async (req, res) => {
  try {
    // A cheap query that every PostgreSQL server supports.
    const result = await pool.query('SELECT NOW() AS server_time');
    res.json({
      status:      'ok',
      timestamp:   new Date().toISOString(),
      db:          'connected',
      serverTime:  result.rows[0].server_time,
    });
  } catch {
    res.status(503).json({
      status:    'error',
      timestamp: new Date().toISOString(),
      db:        'unreachable',
    });
  }
});

// ── GET /users/search ────────────────────────────────────────────────────────
/**
 * Search users by name or email.
 *
 * Query parameters
 * ────────────────
 * q          {string}  Required. Search term (max 200 chars).
 * searchIn   {string}  Optional. Column to search in: "name" | "email".  Default: "name".
 * limit      {number}  Optional. Rows per page (1–100).   Default: 20.
 * offset     {number}  Optional. Rows to skip  (≥ 0).     Default: 0.
 *
 * Response
 * ────────
 * 200  { data: User[], meta: { total, limit, offset, query, searchIn } }
 * 400  { error: string, code: "VALIDATION_ERROR" }
 * 500  { error: string, code: "DB_ERROR" }
 *
 * NOTE: This route MUST be registered before /users/:id so that Express
 * does not treat the literal string "search" as an :id value.
 */
app.get('/users/search', async (req, res) => {
  const { q, searchIn = 'name', limit = 20, offset = 0 } = req.query;

  // `q` is required.
  if (!q) {
    return res.status(400).json({
      error: 'Query parameter "q" is required.',
      code:  'VALIDATION_ERROR',
    });
  }

  try {
    const { users, total } = await searchUsers(pool, q, {
      searchIn,
      limit:  Number(limit),
      offset: Number(offset),
    });

    return res.json({
      data: users,
      meta: {
        total,
        limit:    Number(limit),
        offset:   Number(offset),
        query:    q,
        searchIn,
      },
    });
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// ── GET /users ───────────────────────────────────────────────────────────────
/**
 * Return a paginated, optionally sorted list of all users.
 *
 * Query parameters
 * ────────────────
 * limit      {number}  Optional. Rows per page (1–100).                 Default: 20.
 * offset     {number}  Optional. Rows to skip  (≥ 0).                   Default: 0.
 * orderBy    {string}  Optional. Sort column: id | name | email | created_at. Default: "id".
 * direction  {string}  Optional. Sort order:  ASC | DESC.               Default: "ASC".
 *
 * Response
 * ────────
 * 200  { data: User[], meta: { total, limit, offset, orderBy, direction } }
 * 400  { error: string, code: "VALIDATION_ERROR" }
 * 500  { error: string, code: "DB_ERROR" }
 */
app.get('/users', async (req, res) => {
  const { limit = 20, offset = 0, orderBy = 'id', direction = 'ASC' } = req.query;

  try {
    const { users, total } = await getAllUsers(
      pool,
      Number(limit),
      Number(offset),
      orderBy,
      direction,
    );

    return res.json({
      data: users,
      meta: {
        total,
        limit:     Number(limit),
        offset:    Number(offset),
        orderBy,
        direction: String(direction).toUpperCase(),
      },
    });
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// ── GET /users/:id ────────────────────────────────────────────────────────────
/**
 * Fetch a single user by their numeric ID.
 *
 * Path parameters
 * ───────────────
 * id  {number}  Required. Positive integer.
 *
 * Response
 * ────────
 * 200  { data: User }
 * 400  { error: string, code: "VALIDATION_ERROR" }
 * 404  { error: string, code: "NOT_FOUND" }
 * 500  { error: string, code: "DB_ERROR" }
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(pool, req.params.id);

    if (!user) {
      return res.status(404).json({
        error: `User with id ${req.params.id} not found.`,
        code:  'NOT_FOUND',
      });
    }

    return res.json({ data: user });
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// ─── Error helpers ────────────────────────────────────────────────────────────

/**
 * Map a `QueryError` (or any unexpected error) to an HTTP response.
 * Validation errors → 400; everything else → 500.
 * Internal error details are NEVER forwarded to the client.
 *
 * @param {unknown}                     err
 * @param {import('express').Response}  res
 */
function handleQueryError(err, res) {
  if (err instanceof QueryError) {
    const statusCode = err.code === 'VALIDATION_ERROR' ? 400 : 500;
    return res.status(statusCode).json({
      error: err.message,
      code:  err.code,
    });
  }

  // Unexpected (non-QueryError) exception — log and return a generic message.
  console.error('[app] Unhandled error:', err);
  return res.status(500).json({
    error: 'An unexpected error occurred.',
    code:  'INTERNAL_ERROR',
  });
}

// ─── 404 catch-all ────────────────────────────────────────────────────────────

app.use((req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found.`,
    code:  'NOT_FOUND',
  });
});

// ─── Server lifecycle ─────────────────────────────────────────────────────────

let server;

if (require.main === module) {
  server = app.listen(PORT, () => {
    console.log(`[app] Server listening on port ${PORT} (${process.env.NODE_ENV || 'development'})`);
  });
}

/**
 * Graceful shutdown: stop accepting new connections, wait for in-flight
 * requests to finish, then close the database pool.
 */
async function shutdown(signal) {
  console.log(`[app] ${signal} received — shutting down gracefully…`);

  server?.close(async () => {
    await closePool();
    console.log('[app] Clean exit.');
    process.exit(0);
  });

  // Force-exit if graceful shutdown takes more than 10 seconds.
  setTimeout(() => {
    console.error('[app] Forced exit after timeout.');
    process.exit(1);
  }, 10_000).unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = app;   // exported for testing

/**
 * queries.test.js — Unit tests for queries.js
 *
 * All tests use a mock pool so no real database connection is required.
 * The mock allows tests to control the query result and assert that:
 *   - The correct SQL structure is produced.
 *   - Only parameterised placeholders ($N) are used for user-supplied values.
 *   - Validation rejects bad input before any query is issued.
 *   - Query timing logs are emitted.
 *   - SQL injection strings are passed as bound parameters, not interpolated.
 */

'use strict';

const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryError,
  MAX_LIMIT,
} = require('./queries');

// ─── Mock pool factory ────────────────────────────────────────────────────────

/**
 * Build a minimal pool mock whose `.query()` resolves to `mockResult`.
 * Captures every call so tests can assert on text and params.
 */
function makePool(mockRows = [], rowCount = null) {
  const calls = [];

  const pool = {
    calls,
    query: jest.fn(async (text, params) => {
      calls.push({ text, params });
      return {
        rows:     mockRows,
        rowCount: rowCount ?? mockRows.length,
      };
    }),
  };

  return pool;
}

// Silence console.log / console.error during tests to keep output clean.
beforeAll(() => {
  jest.spyOn(console, 'log').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterAll(() => {
  jest.restoreAllMocks();
});

// ─── getUserById ──────────────────────────────────────────────────────────────

describe('getUserById', () => {
  test('returns the matching user row', async () => {
    const row  = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };
    const pool = makePool([row]);

    const user = await getUserById(pool, 1);
    expect(user).toEqual(row);
  });

  test('returns null when no row matches', async () => {
    const pool = makePool([]);  // empty result set
    const user = await getUserById(pool, 999);
    expect(user).toBeNull();
  });

  test('passes id as a bound parameter, not interpolated into SQL', async () => {
    const pool = makePool([{ id: 5, name: 'Bob', email: 'bob@example.com', created_at: new Date() }]);
    await getUserById(pool, 5);

    const { text, params } = pool.calls[0];

    // The query text must not contain the literal id value.
    expect(text).not.toContain('5');
    // The id must appear as the first bound parameter.
    expect(params).toEqual([5]);
    // The query text must use the $1 placeholder.
    expect(text).toMatch(/WHERE\s+id\s*=\s*\$1/i);
  });

  // ── Input validation ───────────────────────────────────────────────────────

  test('rejects a non-numeric id', async () => {
    const pool = makePool();
    await expect(getUserById(pool, 'abc')).rejects.toMatchObject({
      name: 'QueryError',
      code: 'VALIDATION_ERROR',
    });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects a negative id', async () => {
    const pool = makePool();
    await expect(getUserById(pool, -1)).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects id = 0', async () => {
    const pool = makePool();
    await expect(getUserById(pool, 0)).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
  });

  test('rejects a float id', async () => {
    const pool = makePool();
    await expect(getUserById(pool, 1.5)).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
  });

  // ── SQL injection attempts ────────────────────────────────────────────────

  test('SQL injection string in id is rejected before hitting the DB', async () => {
    const pool = makePool();
    await expect(getUserById(pool, "1 OR 1=1 --")).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
    });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('UNION-based injection string in id is rejected', async () => {
    const pool = makePool();
    await expect(
      getUserById(pool, '1 UNION SELECT username,password,3,4 FROM admin--'),
    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
    expect(pool.query).not.toHaveBeenCalled();
  });
});

// ─── getAllUsers ──────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), total_count: '2' },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), total_count: '2' },
  ];

  test('returns users and total count', async () => {
    const pool = makePool(fakeRows);
    const { users, total } = await getAllUsers(pool, 20, 0);

    expect(total).toBe(2);
    expect(users).toHaveLength(2);
    // total_count must be stripped from the returned objects.
    expect(users[0]).not.toHaveProperty('total_count');
  });

  test('passes limit and offset as bound parameters', async () => {
    const pool = makePool(fakeRows);
    await getAllUsers(pool, 10, 5);

    const { text, params } = pool.calls[0];
    expect(params).toEqual([10, 5]);
    expect(text).toMatch(/LIMIT\s+\$1/i);
    expect(text).toMatch(/OFFSET\s+\$2/i);
  });

  test('does NOT pass orderBy or direction as bound parameters (they are allowlist-checked)', async () => {
    const pool = makePool(fakeRows);
    await getAllUsers(pool, 20, 0, 'name', 'DESC');

    const { text, params } = pool.calls[0];
    // Only 2 params (limit, offset).
    expect(params).toHaveLength(2);
    // Validated identifier is safely interpolated.
    expect(text).toMatch(/ORDER BY name DESC/i);
  });

  test('returns empty array and total=0 when no rows', async () => {
    const pool = makePool([]);
    const { users, total } = await getAllUsers(pool);
    expect(users).toEqual([]);
    expect(total).toBe(0);
  });

  // ── Input validation ───────────────────────────────────────────────────────

  test('rejects limit > MAX_LIMIT', async () => {
    const pool = makePool();
    await expect(getAllUsers(pool, MAX_LIMIT + 1, 0)).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
    });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects limit = 0', async () => {
    const pool = makePool();
    await expect(getAllUsers(pool, 0, 0)).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
  });

  test('rejects negative offset', async () => {
    const pool = makePool();
    await expect(getAllUsers(pool, 10, -5)).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
  });

  test('rejects non-integer limit', async () => {
    const pool = makePool();
    await expect(getAllUsers(pool, 'ten', 0)).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
  });

  // ── orderBy injection prevention ───────────────────────────────────────────

  test('rejects an orderBy value not in the allowlist', async () => {
    const pool = makePool();
    await expect(getAllUsers(pool, 10, 0, 'password')).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
    });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects SQL injection in orderBy', async () => {
    const pool = makePool();
    await expect(
      getAllUsers(pool, 10, 0, 'id; DROP TABLE users; --'),
    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects invalid sort direction', async () => {
    const pool = makePool();
    await expect(getAllUsers(pool, 10, 0, 'id', 'SIDEWAYS')).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
    });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects SQL injection in direction', async () => {
    const pool = makePool();
    await expect(
      getAllUsers(pool, 10, 0, 'id', 'ASC; DROP TABLE users; --'),
    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
    expect(pool.query).not.toHaveBeenCalled();
  });
});

// ─── searchUsers ─────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), total_count: '1' },
  ];

  test('returns matching users and total', async () => {
    const pool = makePool(fakeRows);
    const { users, total } = await searchUsers(pool, 'ali');

    expect(total).toBe(1);
    expect(users[0].name).toBe('Alice');
    expect(users[0]).not.toHaveProperty('total_count');
  });

  test('passes pattern as a bound parameter with % wildcards', async () => {
    const pool = makePool(fakeRows);
    await searchUsers(pool, 'alice');

    const { text, params } = pool.calls[0];
    // First param must be the wrapped wildcard pattern.
    expect(params[0]).toBe('%alice%');
    // It must appear as $1, not interpolated.
    expect(text).toMatch(/ILIKE\s+\$1/i);
  });

  test('passes limit and offset as bound parameters $2 and $3', async () => {
    const pool = makePool(fakeRows);
    await searchUsers(pool, 'bob', { limit: 5, offset: 10 });

    const { params } = pool.calls[0];
    expect(params).toEqual(['%bob%', 5, 10]);
  });

  test('defaults to searching the name column', async () => {
    const pool = makePool(fakeRows);
    await searchUsers(pool, 'alice');

    const { text } = pool.calls[0];
    expect(text).toMatch(/WHERE\s+name\s+ILIKE/i);
  });

  test('accepts searchIn="email"', async () => {
    const pool = makePool(fakeRows);
    await searchUsers(pool, 'example.com', { searchIn: 'email' });

    const { text } = pool.calls[0];
    expect(text).toMatch(/WHERE\s+email\s+ILIKE/i);
  });

  // ── SQL injection in search term ───────────────────────────────────────────

  test('SQL injection in search term is passed as bound param, not executed', async () => {
    const pool = makePool([]);
    // A classic tautology injection — the DB would receive it as a literal
    // string, not SQL, because it is a bound parameter.
    const injectionAttempt = "' OR '1'='1";
    await searchUsers(pool, injectionAttempt);

    const { text, params } = pool.calls[0];
    // Verify the injection string is in the params array, not the query text.
    expect(params[0]).toBe(`%${injectionAttempt}%`);
    expect(text).not.toContain(injectionAttempt);
  });

  test('UNION-based injection in search term is passed as bound param', async () => {
    const pool = makePool([]);
    const injection = "' UNION SELECT table_name,2,3,4 FROM information_schema.tables--";
    await searchUsers(pool, injection);

    const { params } = pool.calls[0];
    expect(params[0]).toContain(injection);
  });

  test('percent signs in search term are passed through (not interpreted as wildcards by user)', async () => {
    // The user's literal "%" should reach the ILIKE pattern as "%\%%" in some
    // DB drivers, but the important thing here is it arrives as a bound param.
    const pool = makePool([]);
    await searchUsers(pool, '100%');

    const { params } = pool.calls[0];
    expect(params[0]).toBe('%100%%');
  });

  // ── Input validation ───────────────────────────────────────────────────────

  test('rejects empty search query', async () => {
    const pool = makePool();
    await expect(searchUsers(pool, '')).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects whitespace-only search query', async () => {
    const pool = makePool();
    await expect(searchUsers(pool, '   ')).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects query longer than 200 characters', async () => {
    const pool = makePool();
    await expect(searchUsers(pool, 'a'.repeat(201))).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
    });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects searchIn column not in allowlist', async () => {
    const pool = makePool();
    await expect(
      searchUsers(pool, 'alice', { searchIn: 'password_hash' }),
    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('rejects SQL injection in searchIn column', async () => {
    const pool = makePool();
    await expect(
      searchUsers(pool, 'test', { searchIn: 'name; DROP TABLE users; --' }),
    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
    expect(pool.query).not.toHaveBeenCalled();
  });
});

// ─── Query timing logs ────────────────────────────────────────────────────────

describe('query timing logs', () => {
  test('logs query name, row count, and duration for getUserById', async () => {
    const row  = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };
    const pool = makePool([row]);

    await getUserById(pool, 1);

    // console.log should have been called with a timing message.
    const logCalls = console.log.mock.calls.map((args) => args.join(' '));
    const timingLog = logCalls.find((msg) => msg.includes('getUserById'));

    expect(timingLog).toBeDefined();
    expect(timingLog).toMatch(/rows=\d+/);
    expect(timingLog).toMatch(/duration=\d+ms/);
  });

  test('logs for getAllUsers', async () => {
    const pool = makePool([]);
    await getAllUsers(pool, 10, 0);

    const logCalls = console.log.mock.calls.map((args) => args.join(' '));
    expect(logCalls.some((m) => m.includes('getAllUsers') && m.includes('duration='))).toBe(true);
  });

  test('logs for searchUsers', async () => {
    const pool = makePool([]);
    await searchUsers(pool, 'alice');

    const logCalls = console.log.mock.calls.map((args) => args.join(' '));
    expect(logCalls.some((m) => m.includes('searchUsers') && m.includes('duration='))).toBe(true);
  });
});

// ─── DB error handling ────────────────────────────────────────────────────────

describe('database error handling', () => {
  test('wraps pg errors in a QueryError with code DB_ERROR', async () => {
    const pgError = Object.assign(new Error('connection refused'), { code: '08006' });
    const pool = { query: jest.fn().mockRejectedValue(pgError) };

    await expect(getUserById(pool, 1)).rejects.toMatchObject({
      name: 'QueryError',
      code: 'DB_ERROR',
    });
  });

  test('does not expose internal pg error message to caller', async () => {
    const pgError = new Error('password authentication failed for user "admin"');
    const pool = { query: jest.fn().mockRejectedValue(pgError) };

    await expect(getUserById(pool, 1)).rejects.toMatchObject({
      message: 'A database error occurred. Please try again later.',
    });
  });

  test('attaches original pg error as .cause for server-side debugging', async () => {
    const pgError = new Error('internal pg error');
    const pool = { query: jest.fn().mockRejectedValue(pgError) };

    try {
      await getUserById(pool, 1);
    } catch (err) {
      expect(err.cause).toBe(pgError);
    }
  });
});

