/**
 * db.js — PostgreSQL connection pool
 *
 * Reads connection config from environment variables only.
 * Never hard-code credentials here or anywhere in source code.
 * Set the variables listed below in your local .env (git-ignored)
 * or in your deployment secrets manager.
 *
 * Required env vars:
 *   DB_HOST      – e.g. localhost
 *   DB_PORT      – e.g. 5432
 *   DB_NAME      – e.g. myapp
 *   DB_USER      – database user
 *   DB_PASSWORD  – database password
 *
 * Optional env vars (pool tuning):
 *   DB_POOL_MAX          – max connections (default: 10)
 *   DB_POOL_IDLE_TIMEOUT – ms before idle connection is released (default: 30000)
 *   DB_POOL_CONN_TIMEOUT – ms to wait for a connection (default: 5000)
 *   DB_SSL               – set to "true" to require TLS (default: false)
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate that every required variable is present at startup so the
// application fails fast with a clear message rather than a cryptic
// runtime error deep inside a query.
// ---------------------------------------------------------------------------
const REQUIRED_ENV_VARS = ['DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_USER', 'DB_PASSWORD'];

const missing = REQUIRED_ENV_VARS.filter((key) => !process.env[key]);
if (missing.length > 0) {
  throw new Error(
    `Database configuration error: missing required environment variable(s): ${missing.join(', ')}.\n` +
      'Copy .env.example to .env and fill in your local credentials. ' +
      'Never commit real credentials to source control.'
  );
}

// ---------------------------------------------------------------------------
// Build pool config exclusively from environment variables.
// ---------------------------------------------------------------------------
const poolConfig = {
  host:     process.env.DB_HOST,
  port:     parseInt(process.env.DB_PORT, 10),
  database: process.env.DB_NAME,
  user:     process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max:              parseInt(process.env.DB_POOL_MAX          ?? '10',    10),
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT ?? '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN_TIMEOUT ?? '5000', 10),

  // Enforce TLS when DB_SSL=true (recommended for production)
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  console.log(
    `[db] New client connected — pool size: ${pool.totalCount} ` +
    `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );

  // Harden every connection:
  //   • statement_timeout   – prevents runaway queries
  //   • lock_timeout        – prevents indefinite lock waits
  //   • search_path         – pins schema so there's no search-path injection risk
  client.query(
    "SET statement_timeout = '30s'; SET lock_timeout = '5s'; SET search_path = public;"
  ).catch((err) => console.error('[db] Failed to apply session settings:', err.message));
});

pool.on('error', (err) => {
  // Emitted for idle clients; log and continue — the pool will recover.
  console.error('[db] Unexpected pool error (idle client):', err.message);
});

pool.on('remove', () => {
  console.log(
    `[db] Client removed — pool size: ${pool.totalCount} ` +
    `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper — call this in your SIGTERM / SIGINT handlers.
// ---------------------------------------------------------------------------
async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] Pool closed.');
}

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design decisions
 * ────────────────
 * 1. SQL injection prevention
 *    Every piece of user-supplied data is passed as a parameterised value
 *    ($1, $2 …) via node-postgres's built-in prepared-statement mechanism.
 *    No string interpolation or concatenation is used to build WHERE clauses
 *    or any other SQL fragment that touches user data.
 *
 *    The one exception that requires care is dynamic ORDER BY / column names,
 *    which cannot be parameterised. Those are handled through an explicit
 *    allowlist (ALLOWED_SORT_COLUMNS, ALLOWED_SORT_DIRECTIONS) so that
 *    arbitrary SQL can never be injected via sort parameters.
 *
 * 2. Connection pooling
 *    All queries borrow a connection from the shared pool in db.js and
 *    release it immediately after the query completes (using pool.query).
 *    For operations that need a transaction, pool.connect() is used
 *    explicitly and the client is always released in a finally block.
 *
 * 3. Query timing
 *    Every exported function is wrapped by the withTiming() helper, which
 *    logs the function name, duration, and row count at the DEBUG level
 *    and emits a WARN when a query exceeds SLOW_QUERY_THRESHOLD_MS.
 *
 * 4. Input validation
 *    All parameters are validated and normalised before they reach the SQL
 *    layer so that database errors are never the first line of defence.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Queries slower than this (ms) are flagged in the logs. */
const SLOW_QUERY_THRESHOLD_MS = 200;

/** Maximum rows getAllUsers may return in a single call. */
const MAX_LIMIT = 100;

/** Default page size for getAllUsers. */
const DEFAULT_LIMIT = 20;

/**
 * Columns that callers are allowed to sort by.
 * Anything not in this set is silently replaced with the default ('id').
 * This is the only safe way to allow dynamic ORDER BY without risking
 * SQL injection, because column identifiers cannot be parameterised.
 */
const ALLOWED_SORT_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);

/** Likewise for sort direction. */
const ALLOWED_SORT_DIRECTIONS = new Set(['ASC', 'DESC']);

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Wraps a query function so it automatically logs:
 *   • the function name
 *   • how long the query took
 *   • how many rows were returned
 *   • a SLOW-QUERY warning when the threshold is exceeded
 *
 * @param {string}   name  – label used in log output
 * @param {Function} fn    – async function that returns { rows, rowCount, … }
 * @returns {Function} wrapped async function with the same signature
 */
function withTiming(name, fn) {
  return async function timedQuery(...args) {
    const start = process.hrtime.bigint();

    let result;
    try {
      result = await fn(...args);
    } catch (err) {
      const durationMs = nanosToMs(process.hrtime.bigint() - start);
      console.error(`[query] ${name} FAILED after ${durationMs} ms — ${err.message}`);
      throw err;                    // re-throw; callers decide how to handle
    }

    const durationMs = nanosToMs(process.hrtime.bigint() - start);
    const rowCount   = result?.rowCount ?? result?.rows?.length ?? 0;
    const logLine    = `[query] ${name} — ${durationMs} ms, ${rowCount} row(s)`;

    if (durationMs >= SLOW_QUERY_THRESHOLD_MS) {
      console.warn(`[query] SLOW QUERY: ${logLine}`);
    } else {
      console.debug(logLine);
    }

    return result;
  };
}

/** Convert BigInt nanoseconds to a rounded millisecond string. */
function nanosToMs(ns) {
  return (Number(ns) / 1_000_000).toFixed(3);
}

/**
 * Sanitise and clamp a pagination limit value.
 *
 * @param {*}      raw          – raw value from the caller
 * @param {number} defaultValue – fallback
 * @returns {number}
 */
function parseLimit(raw, defaultValue = DEFAULT_LIMIT) {
  const n = parseInt(raw, 10);
  if (Number.isNaN(n) || n < 1) return defaultValue;
  return Math.min(n, MAX_LIMIT);
}

/**
 * Sanitise a pagination offset value.
 *
 * @param {*} raw – raw value from the caller
 * @returns {number}
 */
function parseOffset(raw) {
  const n = parseInt(raw, 10);
  if (Number.isNaN(n) || n < 0) return 0;
  return n;
}

/**
 * Sanitise a sort column name against the allowlist.
 * Returns 'id' for any value not in ALLOWED_SORT_COLUMNS.
 *
 * @param {*} raw
 * @returns {string} a value that is guaranteed to be safe for interpolation
 */
function parseSortColumn(raw) {
  const col = typeof raw === 'string' ? raw.toLowerCase() : '';
  return ALLOWED_SORT_COLUMNS.has(col) ? col : 'id';
}

/**
 * Sanitise a sort direction against the allowlist.
 * Returns 'ASC' for any value not in ALLOWED_SORT_DIRECTIONS.
 *
 * @param {*} raw
 * @returns {'ASC'|'DESC'}
 */
function parseSortDirection(raw) {
  const dir = typeof raw === 'string' ? raw.toUpperCase() : '';
  return ALLOWED_SORT_DIRECTIONS.has(dir) ? dir : 'ASC';
}

// ---------------------------------------------------------------------------
// Query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by primary key.
 *
 * The id is passed as a parameterised value ($1) — not interpolated —
 * so there is no risk of SQL injection regardless of what `id` contains.
 *
 * @param {number|string} id – user primary key
 * @returns {Promise<object|null>} user row, or null if not found
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function _getUserById(id) {
  const parsed = parseInt(id, 10);
  if (Number.isNaN(parsed) || parsed < 1) {
    throw new RangeError(`getUserById: invalid id "${id}" — must be a positive integer`);
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM   users
    WHERE  id = $1
      AND  deleted_at IS NULL
  `;

  // pool.query() acquires a connection, runs the query, and releases it
  // back to the pool automatically — no manual client management needed.
  const { rows } = await pool.query(sql, [parsed]);
  return rows[0] ?? null;
}

/**
 * Fetch a paginated, optionally sorted list of all (non-deleted) users.
 *
 * @param {object} [options]
 * @param {number|string} [options.limit=20]   – max rows to return (capped at 100)
 * @param {number|string} [options.offset=0]   – number of rows to skip
 * @param {string}        [options.sortBy='id']  – column to sort by (allowlisted)
 * @param {string}        [options.sortDir='ASC'] – 'ASC' or 'DESC' (allowlisted)
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number }>}
 *
 * @example
 *   const page = await getAllUsers({ limit: 10, offset: 20, sortBy: 'name' });
 *   res.json(page);
 */
async function _getAllUsers({
  limit   = DEFAULT_LIMIT,
  offset  = 0,
  sortBy  = 'id',
  sortDir = 'ASC',
} = {}) {
  const safeLimit  = parseLimit(limit);
  const safeOffset = parseOffset(offset);

  // Column name and direction are validated against an allowlist before
  // being interpolated into the SQL string — they are NOT parameterisable.
  const safeColumn = parseSortColumn(sortBy);
  const safeDir    = parseSortDirection(sortDir);

  // We need a total count for pagination metadata.  Running two queries
  // in a single transaction keeps the count consistent with the data page.
  const client = await pool.connect();
  try {
    await client.query('BEGIN READ ONLY');

    const countResult = await client.query(
      'SELECT COUNT(*) AS total FROM users WHERE deleted_at IS NULL'
    );

    // LIMIT and OFFSET are safe to parameterise.
    // The ORDER BY column/direction have already been allowlist-checked above.
    const dataResult = await client.query(
      `
      SELECT
        id,
        name,
        email,
        created_at,
        updated_at
      FROM   users
      WHERE  deleted_at IS NULL
      ORDER  BY ${safeColumn} ${safeDir}
      LIMIT  $1
      OFFSET $2
      `,
      [safeLimit, safeOffset]
    );

    await client.query('COMMIT');

    return {
      users:  dataResult.rows,
      total:  parseInt(countResult.rows[0].total, 10),
      limit:  safeLimit,
      offset: safeOffset,
    };
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});  // best-effort rollback
    throw err;
  } finally {
    // ALWAYS release — even if an error is thrown above.
    client.release();
  }
}

/**
 * Full-text search across name and email fields.
 *
 * Uses PostgreSQL's ILIKE with a parameterised wildcard pattern.
 * The search term is NEVER concatenated into SQL — it is always $1,
 * which eliminates SQL injection at the driver level.
 *
 * @param {string}        searchTerm          – user-supplied search string
 * @param {object}        [options]
 * @param {number|string} [options.limit=20]  – max rows (capped at 100)
 * @param {number|string} [options.offset=0]  – pagination offset
 * @returns {Promise<{ users: object[], total: number, searchTerm: string, limit: number, offset: number }>}
 *
 * @example
 *   const results = await searchUsers('alice', { limit: 5 });
 *   res.json(results);
 */
async function _searchUsers(searchTerm, { limit = DEFAULT_LIMIT, offset = 0 } = {}) {
  if (typeof searchTerm !== 'string') {
    throw new TypeError(`searchUsers: searchTerm must be a string, got ${typeof searchTerm}`);
  }

  const trimmed = searchTerm.trim();
  if (trimmed.length === 0) {
    throw new RangeError('searchUsers: searchTerm must not be empty or whitespace');
  }
  if (trimmed.length > 200) {
    throw new RangeError('searchUsers: searchTerm must be 200 characters or fewer');
  }

  const safeLimit  = parseLimit(limit);
  const safeOffset = parseOffset(offset);

  // Build the ILIKE wildcard pattern on the application side, not in SQL.
  // node-postgres will bind this as a plain string value, not SQL syntax.
  // Even if `trimmed` contained %; DROP TABLE users; --, it would be treated
  // as a literal string to match against, not as SQL.
  const likePattern = `%${trimmed}%`;

  const client = await pool.connect();
  try {
    await client.query('BEGIN READ ONLY');

    // COUNT query — same filter, no pagination
    const countResult = await client.query(
      `
      SELECT COUNT(*) AS total
      FROM   users
      WHERE  deleted_at IS NULL
        AND  (name ILIKE $1 OR email ILIKE $1)
      `,
      [likePattern]
    );

    // Data query — adds LIMIT / OFFSET
    const dataResult = await client.query(
      `
      SELECT
        id,
        name,
        email,
        created_at,
        updated_at
      FROM   users
      WHERE  deleted_at IS NULL
        AND  (name ILIKE $1 OR email ILIKE $1)
      ORDER  BY id ASC
      LIMIT  $2
      OFFSET $3
      `,
      [likePattern, safeLimit, safeOffset]
    );

    await client.query('COMMIT');

    return {
      users:      dataResult.rows,
      total:      parseInt(countResult.rows[0].total, 10),
      searchTerm: trimmed,
      limit:      safeLimit,
      offset:     safeOffset,
    };
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

// ---------------------------------------------------------------------------
// Export timing-wrapped versions of every query function
// ---------------------------------------------------------------------------

const getUserById  = withTiming('getUserById',  _getUserById);
const getAllUsers   = withTiming('getAllUsers',   _getAllUsers);
const searchUsers  = withTiming('searchUsers',   _searchUsers);

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,

  // Expose constants so tests can assert on boundary behaviour
  MAX_LIMIT,
  DEFAULT_LIMIT,
  ALLOWED_SORT_COLUMNS,
  ALLOWED_SORT_DIRECTIONS,
};

/**
 * app.js — Express application
 *
 * /users endpoint wired to the parameterised query layer in queries.js.
 * The database connection pool is started once and shut down cleanly
 * on SIGTERM / SIGINT so that in-flight requests are not dropped.
 */

'use strict';

const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helper — normalise errors into a consistent JSON shape
// ---------------------------------------------------------------------------

/**
 * Map an error thrown by the query layer to an HTTP status code.
 *
 * @param {Error} err
 * @returns {number}
 */
function httpStatusForError(err) {
  if (err instanceof RangeError || err instanceof TypeError) return 400;
  return 500;
}

/**
 * Send a structured error response.
 * In production, generic 500 messages are returned so that internal
 * details (table names, column names, etc.) are never leaked to clients.
 *
 * @param {import('express').Response} res
 * @param {Error}  err
 * @param {string} context  – short label for server-side logs
 */
function sendError(res, err, context) {
  const status = httpStatusForError(err);

  // Always log the real error server-side
  console.error(`[${context}] ${err.name}: ${err.message}`);

  const message =
    status === 400
      ? err.message                         // validation errors are safe to surface
      : 'An unexpected error occurred. Please try again later.';

  res.status(status).json({ error: message });
}

// ---------------------------------------------------------------------------
// GET /health
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
//
// Query parameters
//   limit   {number}  – page size (1–100, default 20)
//   offset  {number}  – rows to skip (default 0)
//   sortBy  {string}  – column: id | name | email | created_at (default id)
//   sortDir {string}  – ASC | DESC (default ASC)
//   search  {string}  – if present, delegates to searchUsers()
//
// Examples
//   GET /users
//   GET /users?limit=10&offset=20
//   GET /users?search=alice
//   GET /users?sortBy=name&sortDir=DESC&limit=5
// ---------------------------------------------------------------------------

app.get('/users', async (req, res) => {
  const { limit, offset, sortBy, sortDir, search } = req.query;

  try {
    if (search !== undefined) {
      // search path — delegates to searchUsers()
      const result = await searchUsers(search, { limit, offset });
      return res.json(result);
    }

    // list path — delegates to getAllUsers()
    const result = await getAllUsers({ limit, offset, sortBy, sortDir });
    return res.json(result);
  } catch (err) {
    return sendError(res, err, 'GET /users');
  }
});

// ---------------------------------------------------------------------------
// GET /users/:id
//
// Path parameters
//   id  {number}  – positive integer user ID
//
// Examples
//   GET /users/1
//   GET /users/42
// ---------------------------------------------------------------------------

app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: `User with id ${req.params.id} not found` });
    }

    return res.json(user);
  } catch (err) {
    return sendError(res, err, `GET /users/${req.params.id}`);
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown
//
// On SIGTERM (sent by container orchestrators like Kubernetes) or SIGINT
// (Ctrl-C in development), we:
//   1. Stop accepting new connections.
//   2. Drain the connection pool so in-flight DB queries can finish.
//   3. Exit with code 0.
// ---------------------------------------------------------------------------

let server; // assigned below so the signal handlers can reference it

function shutdown(signal) {
  console.log(`[app] ${signal} received — shutting down gracefully…`);
  server.close(async () => {
    console.log('[app] HTTP server closed.');
    try {
      await closePool();
    } catch (err) {
      console.error('[app] Error while closing pool:', err.message);
    } finally {
      process.exit(0);
    }
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

const PORT = parseInt(process.env.PORT ?? '3000', 10);

server = app.listen(PORT, () => {
  console.log(`[app] Server running on port ${PORT}`);
});

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * The PostgreSQL pool is mocked so that tests run without a real database.
 * Each test verifies both the SQL that is generated and the arguments that
 * are passed to pool.query() / client.query(), ensuring:
 *   - user input always travels as a parameterised value, never in the SQL
 *   - boundary / validation rules are applied correctly
 *   - timing logs fire (via a spy on console.debug / console.warn)
 *   - slow-query warnings fire when a query exceeds the threshold
 */

'use strict';

const {
  getUserById,
  getAllUsers,
  searchUsers,
  MAX_LIMIT,
  DEFAULT_LIMIT,
} = require('./queries');

// ---------------------------------------------------------------------------
// Mock the pool (db.js) before anything in queries.js runs
// ---------------------------------------------------------------------------

// Mock client returned by pool.connect()
const mockClient = {
  query:   jest.fn(),
  release: jest.fn(),
};

// pool.query is used for single-shot queries (getUserById)
// pool.connect is used for transactional queries (getAllUsers, searchUsers)
jest.mock('./db', () => ({
  pool: {
    query:   jest.fn(),
    connect: jest.fn(),
  },
  closePool: jest.fn(),
}));

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Wire up mockClient for the next pool.connect() call. */
function setupMockClient({ queryResponses = [] } = {}) {
  pool.connect.mockResolvedValueOnce(mockClient);

  // Responses are consumed in call order:
  //   call 0 → BEGIN
  //   call 1 → COUNT (or first real query)
  //   call 2 → data  (or second real query)
  //   call 3 → COMMIT
  queryResponses.forEach((resp) =>
    mockClient.query.mockResolvedValueOnce(resp)
  );
}

// ---------------------------------------------------------------------------
// Test suites
// ---------------------------------------------------------------------------

describe('getUserById', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    jest.spyOn(console, 'debug').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
    jest.spyOn(console, 'error').mockImplementation(() => {});
  });

  afterEach(() => jest.restoreAllMocks());

  test('executes a parameterised query with the correct id', async () => {
    pool.query.mockResolvedValueOnce({ rows: [{ id: 1, name: 'Alice' }], rowCount: 1 });

    const result = await getUserById(1);

    expect(pool.query).toHaveBeenCalledTimes(1);
    const [sql, params] = pool.query.mock.calls[0];

    // The id must be passed as a parameter, never interpolated into the SQL
    expect(params).toEqual([1]);
    expect(sql).toMatch(/WHERE\s+id\s*=\s*\$1/i);
    expect(result).toEqual({ id: 1, name: 'Alice' });
  });

  test('returns null when no row is found', async () => {
    pool.query.mockResolvedValueOnce({ rows: [], rowCount: 0 });
    const result = await getUserById(99);
    expect(result).toBeNull();
  });

  test('accepts a numeric string id', async () => {
    pool.query.mockResolvedValueOnce({ rows: [{ id: 7, name: 'Bob' }], rowCount: 1 });
    await getUserById('7');
    expect(pool.query.mock.calls[0][1]).toEqual([7]);
  });

  test('throws RangeError for a non-numeric id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(RangeError);
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws RangeError for id = 0', async () => {
    await expect(getUserById(0)).rejects.toThrow(RangeError);
  });

  test('throws RangeError for a negative id', async () => {
    await expect(getUserById(-5)).rejects.toThrow(RangeError);
  });

  test('throws RangeError for SQL injection attempt in id', async () => {
    await expect(getUserById("1; DROP TABLE users; --")).rejects.toThrow(RangeError);
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('logs query duration on success', async () => {
    pool.query.mockResolvedValueOnce({ rows: [{ id: 1 }], rowCount: 1 });
    await getUserById(1);
    expect(console.debug).toHaveBeenCalledWith(
      expect.stringMatching(/\[query\] getUserById — .+ ms, 1 row/)
    );
  });

  test('emits a slow-query warning when the query is slow', async () => {
    // Make Date.now-like timing appear slow by delaying the mock resolution
    pool.query.mockImplementationOnce(
      () =>
        new Promise((resolve) =>
          setTimeout(() => resolve({ rows: [{ id: 1 }], rowCount: 1 }), 250)
        )
    );

    await getUserById(1);

    expect(console.warn).toHaveBeenCalledWith(
      expect.stringMatching(/SLOW QUERY/)
    );
  });

  test('re-throws pool errors and logs them', async () => {
    const dbError = new Error('connection refused');
    pool.query.mockRejectedValueOnce(dbError);

    await expect(getUserById(1)).rejects.toThrow('connection refused');
    expect(console.error).toHaveBeenCalledWith(
      expect.stringMatching(/getUserById FAILED/)
    );
  });
});

// ---------------------------------------------------------------------------

describe('getAllUsers', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    jest.spyOn(console, 'debug').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
    jest.spyOn(console, 'error').mockImplementation(() => {});
  });

  afterEach(() => jest.restoreAllMocks());

  test('returns paginated users with total count', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },                                  // BEGIN
        { rows: [{ total: '42' }], rowCount: 1 },                   // COUNT
        { rows: [{ id: 1 }, { id: 2 }], rowCount: 2 },             // data
        { rows: [], rowCount: 0 },                                  // COMMIT
      ],
    });

    const result = await getAllUsers({ limit: 2, offset: 0 });

    expect(result.users).toHaveLength(2);
    expect(result.total).toBe(42);
    expect(result.limit).toBe(2);
    expect(result.offset).toBe(0);
  });

  test('limit and offset are passed as parameterised values', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '5' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
        { rows: [], rowCount: 0 },
      ],
    });

    await getAllUsers({ limit: 5, offset: 10 });

    // The data query is the third call (index 2): BEGIN, COUNT, data, COMMIT
    const dataCall = mockClient.query.mock.calls[2];
    const [sql, params] = dataCall;

    expect(params).toEqual([5, 10]);
    expect(sql).toMatch(/LIMIT\s+\$1/i);
    expect(sql).toMatch(/OFFSET\s+\$2/i);
  });

  test('sortBy column is NOT passed as a parameter — it is allowlist-checked', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '0' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
        { rows: [], rowCount: 0 },
      ],
    });

    await getAllUsers({ sortBy: 'name', sortDir: 'DESC' });

    const dataCall = mockClient.query.mock.calls[2];
    const [sql, params] = dataCall;

    // Column name is safe-interpolated, not a param
    expect(sql).toMatch(/ORDER\s+BY\s+name\s+DESC/i);
    // Only limit and offset are parameterised
    expect(params).toHaveLength(2);
  });

  test('rejects unknown sortBy values — falls back to id', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '0' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
        { rows: [], rowCount: 0 },
      ],
    });

    // Malicious attempt to inject via sortBy
    await getAllUsers({ sortBy: "id; DROP TABLE users; --" });

    const dataCall = mockClient.query.mock.calls[2];
    const [sql] = dataCall;

    // Falls back to safe default
    expect(sql).toMatch(/ORDER\s+BY\s+id\s+ASC/i);
    expect(sql).not.toMatch(/DROP/i);
  });

  test('rejects unknown sortDir values — falls back to ASC', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '0' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
        { rows: [], rowCount: 0 },
      ],
    });

    await getAllUsers({ sortDir: 'SIDEWAYS' });

    const dataCall = mockClient.query.mock.calls[2];
    const [sql] = dataCall;
    expect(sql).toMatch(/ASC/);
    expect(sql).not.toMatch(/SIDEWAYS/);
  });

  test('caps limit at MAX_LIMIT', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '0' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
        { rows: [], rowCount: 0 },
      ],
    });

    await getAllUsers({ limit: 9999 });
    const dataCall = mockClient.query.mock.calls[2];
    expect(dataCall[1][0]).toBe(MAX_LIMIT);
  });

  test('uses DEFAULT_LIMIT when limit is absent', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '0' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
        { rows: [], rowCount: 0 },
      ],
    });

    await getAllUsers();
    const dataCall = mockClient.query.mock.calls[2];
    expect(dataCall[1][0]).toBe(DEFAULT_LIMIT);
  });

  test('offset is clamped to 0 for negative values', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '0' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
        { rows: [], rowCount: 0 },
      ],
    });

    await getAllUsers({ offset: -100 });
    const dataCall = mockClient.query.mock.calls[2];
    expect(dataCall[1][1]).toBe(0);
  });

  test('releases the client even when a query throws', async () => {
    pool.connect.mockResolvedValueOnce(mockClient);
    mockClient.query
      .mockResolvedValueOnce({ rows: [], rowCount: 0 })   // BEGIN
      .mockRejectedValueOnce(new Error('disk full'));       // COUNT fails

    await expect(getAllUsers()).rejects.toThrow('disk full');

    // release() must still be called
    expect(mockClient.release).toHaveBeenCalledTimes(1);
  });
});

// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    jest.spyOn(console, 'debug').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
    jest.spyOn(console, 'error').mockImplementation(() => {});
  });

  afterEach(() => jest.restoreAllMocks());

  test('passes the search term as a parameterised ILIKE pattern', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '2' }], rowCount: 1 },
        { rows: [{ id: 1, name: 'Alice' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
      ],
    });

    await searchUsers('alice');

    // COUNT query is call index 1; data query is call index 2
    const countCall = mockClient.query.mock.calls[1];
    const dataCall  = mockClient.query.mock.calls[2];

    expect(countCall[1]).toEqual(['%alice%']);
    expect(countCall[0]).toMatch(/\$1/);
    expect(countCall[0]).not.toMatch(/alice/);   // term is NEVER in the SQL string

    expect(dataCall[1][0]).toBe('%alice%');
  });

  test('SQL injection attempt is treated as a literal string', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '0' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
        { rows: [], rowCount: 0 },
      ],
    });

    const malicious = "' OR '1'='1";
    await searchUsers(malicious);

    const countCall = mockClient.query.mock.calls[1];

    // The malicious string must appear only in the params array, never in SQL
    expect(countCall[0]).not.toMatch(/OR/);
    expect(countCall[1][0]).toBe(`%${malicious}%`);
  });

  test('throws TypeError if searchTerm is not a string', async () => {
    await expect(searchUsers(null)).rejects.toThrow(TypeError);
    await expect(searchUsers(123)).rejects.toThrow(TypeError);
    expect(pool.connect).not.toHaveBeenCalled();
  });

  test('throws RangeError for an empty search term', async () => {
    await expect(searchUsers('')).rejects.toThrow(RangeError);
    await expect(searchUsers('   ')).rejects.toThrow(RangeError);
  });

  test('throws RangeError for a search term longer than 200 characters', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toThrow(RangeError);
  });

  test('returns structured result including searchTerm, total, limit, offset', async () => {
    setupMockClient({
      queryResponses: [
        { rows: [], rowCount: 0 },
        { rows: [{ total: '1' }], rowCount: 1 },
        { rows: [{ id: 1, name: 'Alice' }], rowCount: 1 },
        { rows: [], rowCount: 0 },
      ],
    });

    const result = await searchUsers('Alice', { limit: 10, offset: 0 });

    expect(result).toMatchObject({
      users:      [{ id: 1, name: 'Alice' }],
      total:      1,
      searchTerm: 'Alice',
      limit:      10,
      offset:     0,
    });
  });

  test('releases the client even when a query throws', async () => {
    pool.connect.mockResolvedValueOnce(mockClient);
    mockClient.query
      .mockResolvedValueOnce({ rows: [], rowCount: 0 })  // BEGIN
      .mockRejectedValueOnce(new Error('timeout'));       // COUNT fails

    await expect(searchUsers('bob')).rejects.toThrow('timeout');
    expect(mockClient.release).toHaveBeenCalledTimes(1);
  });
});

/**
 * queries.node-test.js — Unit tests for queries.js
 *
 * Uses Node.js built-in test runner (node:test + node:assert) — no npm
 * packages required.  Run with:
 *
 *   node --test queries.node-test.js
 *
 * The pg pool is monkey-patched via a simple module registry trick so that
 * every assertion still targets real queries.js code paths.
 */

'use strict';

const { test, describe, beforeEach, afterEach, mock } = require('node:test');
const assert = require('node:assert/strict');
const path   = require('node:path');

// ---------------------------------------------------------------------------
// Build a fresh, isolated module registry for each describe block so that
// mock state never leaks between suites.
//
// Strategy:
//   1. Craft a fake `db` module with controllable mock functions.
//   2. Inject it into require.cache under the real db.js path.
//   3. Delete queries.js from the cache so it re-requires the fake db.
//   4. Re-require queries.js to get a fresh copy wired to the mock.
// ---------------------------------------------------------------------------

const DB_PATH      = path.resolve(__dirname, 'db.js');
const QUERIES_PATH = path.resolve(__dirname, 'queries.js');

// Shared mock state — reset in beforeEach
let mockPoolQuery;
let mockClientQuery;
let mockClientRelease;
let mockConnect;

function buildFakeDb() {
  mockPoolQuery      = mock.fn();
  mockClientQuery    = mock.fn();
  mockClientRelease  = mock.fn();
  mockConnect        = mock.fn(async () => ({
    query:   mockClientQuery,
    release: mockClientRelease,
  }));

  return {
    pool: {
      query:   mockPoolQuery,
      connect: mockConnect,
    },
    closePool: mock.fn(),
  };
}

/** Load a fresh queries module wired to a fresh fake db. */
function loadQueries() {
  delete require.cache[DB_PATH];
  delete require.cache[QUERIES_PATH];

  require.cache[DB_PATH] = {
    id:       DB_PATH,
    filename: DB_PATH,
    loaded:   true,
    exports:  buildFakeDb(),
  };

  return require(QUERIES_PATH);
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Default no-op responses for a full transactional flow: BEGIN, COUNT, data, COMMIT */
function setupClientFlow(queries, countTotal, dataRows) {
  // Reset all previous mock calls
  mockClientQuery.mock.resetCalls();
  mockClientRelease.mock.resetCalls();
  mockConnect.mock.resetCalls();

  let callIdx = 0;
  mockClientQuery.mock.mockImplementation(async (_sql, _params) => {
    const i = callIdx++;
    if (i === 0) return { rows: [], rowCount: 0 };  // BEGIN
    if (i === 1) return { rows: [{ total: String(countTotal) }], rowCount: 1 };  // COUNT
    if (i === 2) return { rows: dataRows, rowCount: dataRows.length };           // data
    return { rows: [], rowCount: 0 };                                            // COMMIT / ROLLBACK
  });
}

// Suppress timing logs globally for cleaner test output
const origDebug = console.debug;
const origWarn  = console.warn;
const origError = console.error;

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

describe('getUserById', () => {
  let Q;

  beforeEach(() => {
    Q = loadQueries();
    console.debug = () => {};
    console.warn  = () => {};
    console.error = () => {};
  });

  afterEach(() => {
    console.debug = origDebug;
    console.warn  = origWarn;
    console.error = origError;
  });

  test('calls pool.query with a parameterised $1 placeholder', async () => {
    mockPoolQuery.mock.mockImplementationOnce(async () => ({
      rows: [{ id: 1, name: 'Alice' }],
      rowCount: 1,
    }));

    const result = await Q.getUserById(1);

    assert.equal(mockPoolQuery.mock.callCount(), 1, 'pool.query called once');
    const [sql, params] = mockPoolQuery.mock.calls[0].arguments;

    assert.match(sql, /WHERE\s+id\s*=\s*\$1/i, 'id compared via $1');
    assert.deepEqual(params, [1], 'param is the integer 1');
    assert.deepEqual(result, { id: 1, name: 'Alice' });
  });

  test('returns null when no rows are found', async () => {
    mockPoolQuery.mock.mockImplementationOnce(async () => ({ rows: [], rowCount: 0 }));
    const result = await Q.getUserById(42);
    assert.equal(result, null);
  });

  test('coerces a string id to integer', async () => {
    mockPoolQuery.mock.mockImplementationOnce(async () => ({ rows: [{ id: 7 }], rowCount: 1 }));
    await Q.getUserById('7');
    const params = mockPoolQuery.mock.calls[0].arguments[1];
    assert.deepEqual(params, [7]);
  });

  test('throws RangeError for non-numeric id — no DB call', async () => {
    await assert.rejects(() => Q.getUserById('abc'),  { name: 'RangeError' });
    assert.equal(mockPoolQuery.mock.callCount(), 0);
  });

  test('throws RangeError for id = 0', async () => {
    await assert.rejects(() => Q.getUserById(0), { name: 'RangeError' });
  });

  test('throws RangeError for negative id', async () => {
    await assert.rejects(() => Q.getUserById(-1), { name: 'RangeError' });
  });

  test('SQL injection in id rejected before DB call', async () => {
    await assert.rejects(
      () => Q.getUserById("1; DROP TABLE users; --"),
      { name: 'RangeError' }
    );
    assert.equal(mockPoolQuery.mock.callCount(), 0);
  });

  test('re-throws DB errors', async () => {
    mockPoolQuery.mock.mockImplementationOnce(async () => {
      throw new Error('connection reset');
    });
    await assert.rejects(() => Q.getUserById(1), /connection reset/);
  });

  test('logs duration via console.debug on success', async () => {
    const logs = [];
    console.debug = (...args) => logs.push(args.join(' '));

    mockPoolQuery.mock.mockImplementationOnce(async () => ({ rows: [{ id: 1 }], rowCount: 1 }));
    await Q.getUserById(1);

    assert.ok(
      logs.some((l) => l.includes('getUserById') && l.includes('ms')),
      'debug log contains function name and ms'
    );
  });
});

// ---------------------------------------------------------------------------
// getAllUsers
// ---------------------------------------------------------------------------

describe('getAllUsers', () => {
  let Q;

  beforeEach(() => {
    Q = loadQueries();
    console.debug = () => {};
    console.warn  = () => {};
    console.error = () => {};
  });

  afterEach(() => {
    console.debug = origDebug;
    console.warn  = origWarn;
    console.error = origError;
  });

  test('returns structured result with users, total, limit, offset', async () => {
    setupClientFlow(Q, 42, [{ id: 1 }, { id: 2 }]);

    const result = await Q.getAllUsers({ limit: 2, offset: 0 });

    assert.equal(result.total, 42);
    assert.equal(result.limit, 2);
    assert.equal(result.offset, 0);
    assert.equal(result.users.length, 2);
  });

  test('LIMIT and OFFSET are parameterised', async () => {
    setupClientFlow(Q, 10, []);

    await Q.getAllUsers({ limit: 7, offset: 14 });

    // calls: 0=BEGIN 1=COUNT 2=data 3=COMMIT
    const dataCall = mockClientQuery.mock.calls[2].arguments;
    assert.deepEqual(dataCall[1], [7, 14], 'limit=7 offset=14 as params');
    assert.match(dataCall[0], /LIMIT\s+\$1/i);
    assert.match(dataCall[0], /OFFSET\s+\$2/i);
  });

  test('sortBy is interpolated (not a param) but validated via allowlist', async () => {
    setupClientFlow(Q, 0, []);

    await Q.getAllUsers({ sortBy: 'name', sortDir: 'DESC' });

    const dataCall = mockClientQuery.mock.calls[2].arguments;
    assert.match(dataCall[0], /ORDER\s+BY\s+name\s+DESC/i);
    assert.equal(dataCall[1].length, 2, 'only limit+offset are params');
  });

  test('malicious sortBy falls back to "id" — no injection', async () => {
    setupClientFlow(Q, 0, []);

    await Q.getAllUsers({ sortBy: "id; DROP TABLE users; --" });

    const [sql] = mockClientQuery.mock.calls[2].arguments;
    assert.match(sql, /ORDER\s+BY\s+id\s+ASC/i);
    assert.doesNotMatch(sql, /DROP/i);
  });

  test('malicious sortDir falls back to ASC', async () => {
    setupClientFlow(Q, 0, []);
    await Q.getAllUsers({ sortDir: 'UNION SELECT' });
    const [sql] = mockClientQuery.mock.calls[2].arguments;
    assert.match(sql, /ASC/);
    assert.doesNotMatch(sql, /UNION/i);
  });

  test('limit is capped at MAX_LIMIT', async () => {
    setupClientFlow(Q, 0, []);
    await Q.getAllUsers({ limit: 99999 });
    const dataCall = mockClientQuery.mock.calls[2].arguments;
    assert.equal(dataCall[1][0], Q.MAX_LIMIT);
  });

  test('absent limit defaults to DEFAULT_LIMIT', async () => {
    setupClientFlow(Q, 0, []);
    await Q.getAllUsers();
    const dataCall = mockClientQuery.mock.calls[2].arguments;
    assert.equal(dataCall[1][0], Q.DEFAULT_LIMIT);
  });

  test('negative offset is clamped to 0', async () => {
    setupClientFlow(Q, 0, []);
    await Q.getAllUsers({ offset: -50 });
    const dataCall = mockClientQuery.mock.calls[2].arguments;
    assert.equal(dataCall[1][1], 0);
  });

  test('client.release() is called even when a query throws', async () => {
    mockClientQuery.mock.resetCalls();
    mockClientRelease.mock.resetCalls();
    let callIdx = 0;
    mockClientQuery.mock.mockImplementation(async () => {
      if (callIdx++ === 1) throw new Error('disk full');
      return { rows: [], rowCount: 0 };
    });

    await assert.rejects(() => Q.getAllUsers(), /disk full/);
    assert.equal(mockClientRelease.mock.callCount(), 1, 'release called once');
  });
});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  let Q;

  beforeEach(() => {
    Q = loadQueries();
    console.debug = () => {};
    console.warn  = () => {};
    console.error = () => {};
  });

  afterEach(() => {
    console.debug = origDebug;
    console.warn  = origWarn;
    console.error = origError;
  });

  test('passes search term as parameterised ILIKE pattern', async () => {
    setupClientFlow(Q, 1, [{ id: 1, name: 'Alice' }]);

    await Q.searchUsers('alice');

    // COUNT call is index 1
    const countCall = mockClientQuery.mock.calls[1].arguments;
    assert.deepEqual(countCall[1], ['%alice%'], 'pattern is %alice%');
    assert.match(countCall[0], /\$1/, 'term bound as $1');
    assert.doesNotMatch(countCall[0], /alice/, 'literal term never in SQL string');
  });

  test('SQL injection attempt is only ever a literal param value', async () => {
    setupClientFlow(Q, 0, []);

    const evil = "' OR '1'='1; DROP TABLE users; --";
    await Q.searchUsers(evil);

    const countCall = mockClientQuery.mock.calls[1].arguments;
    // The whole malicious string is just a LIKE pattern value
    assert.equal(countCall[1][0], `%${evil}%`);
    assert.doesNotMatch(countCall[0], /OR/);
    assert.doesNotMatch(countCall[0], /DROP/i);
  });

  test('throws TypeError for non-string searchTerm', async () => {
    await assert.rejects(() => Q.searchUsers(null),  { name: 'TypeError' });
    await assert.rejects(() => Q.searchUsers(123),   { name: 'TypeError' });
    await assert.rejects(() => Q.searchUsers({}),    { name: 'TypeError' });
    assert.equal(mockConnect.mock.callCount(), 0);
  });

  test('throws RangeError for empty string', async () => {
    await assert.rejects(() => Q.searchUsers(''),    { name: 'RangeError' });
    await assert.rejects(() => Q.searchUsers('   '), { name: 'RangeError' });
  });

  test('throws RangeError for search term > 200 chars', async () => {
    await assert.rejects(
      () => Q.searchUsers('x'.repeat(201)),
      { name: 'RangeError' }
    );
  });

  test('returns structured result object', async () => {
    setupClientFlow(Q, 3, [{ id: 1 }, { id: 2 }, { id: 3 }]);

    const result = await Q.searchUsers('bob', { limit: 10, offset: 5 });

    assert.equal(result.total, 3);
    assert.equal(result.searchTerm, 'bob');
    assert.equal(result.limit, 10);
    assert.equal(result.offset, 5);
    assert.equal(result.users.length, 3);
  });

  test('trims whitespace from searchTerm before building pattern', async () => {
    setupClientFlow(Q, 1, [{ id: 1 }]);

    await Q.searchUsers('  alice  ');

    const countCall = mockClientQuery.mock.calls[1].arguments;
    assert.equal(countCall[1][0], '%alice%', 'term is trimmed');
  });

  test('client.release() called on query error', async () => {
    mockClientQuery.mock.resetCalls();
    mockClientRelease.mock.resetCalls();
    let callIdx = 0;
    mockClientQuery.mock.mockImplementation(async () => {
      if (callIdx++ === 1) throw new Error('timeout');
      return { rows: [], rowCount: 0 };
    });

    await assert.rejects(() => Q.searchUsers('bob'), /timeout/);
    assert.equal(mockClientRelease.mock.callCount(), 1);
  });

  test('data query receives limit and offset as params', async () => {
    setupClientFlow(Q, 5, []);

    await Q.searchUsers('carol', { limit: 3, offset: 6 });

    // data call is index 2
    const dataCall = mockClientQuery.mock.calls[2].arguments;
    // params: $1=pattern, $2=limit, $3=offset
    assert.equal(dataCall[1][1], 3,  'limit param');
    assert.equal(dataCall[1][2], 6,  'offset param');
    assert.match(dataCall[0], /LIMIT\s+\$2/i);
    assert.match(dataCall[0], /OFFSET\s+\$3/i);
  });
});

