    await expect(getAllUsers('bad', 0)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('accepts limit=1 (minimum boundary)', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await expect(getAllUsers(1, 0)).resolves.toEqual([]);
  });

  test('accepts limit=100 (maximum boundary)', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await expect(getAllUsers(100, 0)).resolves.toEqual([]);
  });

  // ── Pool error propagation ───────────────────────────────────────────────

  test('wraps pool errors with operation name', async () => {
    mockQuery.mockRejectedValueOnce(new Error('deadlock detected'));

    await expect(getAllUsers()).rejects.toThrow('getAllUsers');
  });
});

// ===========================================================================
// searchUsers
// ===========================================================================

describe('searchUsers', () => {
  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() },
  ];

  // ── Happy path ──────────────────────────────────────────────────────────

  test('returns matching users', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(fakeUsers));

    const result = await searchUsers('alice', 20, 0);

    expect(result).toEqual(fakeUsers);
  });

  test('uses default limit=20 and offset=0 when not supplied', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('bob');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[1]).toBe(20);
    expect(params[2]).toBe(0);
  });

  test('returns an empty array when no matches exist', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const result = await searchUsers('zzznomatch');

    expect(result).toEqual([]);
  });

  // ── SQL / parameter correctness ──────────────────────────────────────────

  test('wraps the search term in a %…% ILIKE pattern passed as $1', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('alice');

    const [sql, params] = mockQuery.mock.calls[0];
    expect(sql.toUpperCase()).toContain('ILIKE');
    expect(params[0]).toBe('%alice%');
  });

  test('sends limit as $2 and offset as $3', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('test', 10, 5);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[1]).toBe(10);
    expect(params[2]).toBe(5);
  });

  test('does NOT interpolate the search term into the SQL string', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    const term = 'uniqueSearchTerm';

    await searchUsers(term);

    const [sql] = mockQuery.mock.calls[0];
    // The raw search term must never appear inside the query string itself.
    expect(sql).not.toContain(term);
  });

  // ── Wildcard injection prevention ────────────────────────────────────────

  test('escapes % in search term to prevent wildcard injection', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('100%');

    const [, params] = mockQuery.mock.calls[0];
    // % must be escaped so it is treated as a literal character.
    expect(params[0]).toContain('\\%');
    expect(params[0]).not.toMatch(/(?<!\\)%(?!$)/); // no unescaped % except trailing
  });

  test('escapes _ in search term to prevent single-char wildcard injection', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('user_name');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toContain('\\_');
  });

  test('escapes backslash in search term before escaping other metacharacters', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('path\\to');

    const [, params] = mockQuery.mock.calls[0];
    // The backslash must be doubled.
    expect(params[0]).toContain('\\\\');
  });

  test('a search for "%" does not match all rows (pattern is escaped)', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('%');

    const [, params] = mockQuery.mock.calls[0];
    // If the % were unescaped the pattern would be "%%%" matching everything.
    // With escaping it must be "%\\%%".
    expect(params[0]).toBe('%\\%%');
  });

  test('SQL includes ESCAPE clause alongside ILIKE', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('test');

    const [sql] = mockQuery.mock.calls[0];
    expect(sql.toUpperCase()).toContain('ESCAPE');
  });

  // ── Query timing log ────────────────────────────────────────────────────

  test('logs a timing line for searchUsers', async () => {
    infoSpy.mockRestore();
    infoSpy = jest.spyOn(console, 'info');
    mockQuery.mockResolvedValueOnce(fakeResult(fakeUsers));

    await searchUsers('alice');

    const calls = infoSpy.mock.calls.map((c) => c[0]);
    const timingLog = calls.find((msg) => msg.includes('searchUsers'));
    expect(timingLog).toBeDefined();
    expect(timingLog).toMatch(/duration=\d+\.\d{3}ms/);
    expect(timingLog).toMatch(/rows=\d+/);
  });

  // ── Input validation ─────────────────────────────────────────────────────

  test('throws RangeError for an empty search string', async () => {
    await expect(searchUsers('')).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws RangeError for a whitespace-only search string', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws RangeError for a search term longer than 200 characters', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('accepts a search term of exactly 200 characters', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await expect(searchUsers('a'.repeat(200))).resolves.toEqual([]);
  });

  test('throws TypeError when query is not a string', async () => {
    await expect(searchUsers(123)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws TypeError when query is null', async () => {
    await expect(searchUsers(null)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws RangeError when limit exceeds 100', async () => {
    await expect(searchUsers('alice', 200)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws RangeError when offset is negative', async () => {
    await expect(searchUsers('alice', 10, -5)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  // ── Pool error propagation ───────────────────────────────────────────────

  test('wraps pool errors with operation name', async () => {
    mockQuery.mockRejectedValueOnce(new Error('query cancelled'));

    await expect(searchUsers('alice')).rejects.toThrow('searchUsers');
  });
});

