/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared pg.Pool instance so every module in the
 * application reuses the same set of connections rather than opening
 * a new socket per query.
 *
 * Configuration is read exclusively from environment variables so
 * that no credentials ever appear in source code.  In development
 * a `.env` file is loaded by dotenv; in production the variables
 * must be injected by the platform (e.g. Docker / Kubernetes secrets,
 * a secrets manager, or the hosting provider's config UI).
 *
 * Required env vars
 * ─────────────────
 *   DB_HOST      – hostname of the PostgreSQL server   (default: localhost)
 *   DB_PORT      – port                                (default: 5432)
 *   DB_NAME      – database name                       (required)
 *   DB_USER      – login role                          (required)
 *   DB_PASSWORD  – password                            (required)
 *   DB_SSL       – set to "true" to enable TLS         (default: false)
 *
 * Pool-tuning env vars (optional)
 * ────────────────────────────────
 *   DB_POOL_MAX               – maximum open connections   (default: 10)
 *   DB_POOL_IDLE_TIMEOUT_MS   – ms before idle conn closed (default: 30000)
 *   DB_POOL_CONN_TIMEOUT_MS   – ms to wait for a free conn (default: 5000)
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate that the minimum required variables are present at startup so the
// problem is caught immediately rather than on the first inbound request.
// ---------------------------------------------------------------------------
const REQUIRED_VARS = ['DB_NAME', 'DB_USER', 'DB_PASSWORD'];
const missing = REQUIRED_VARS.filter((v) => !process.env[v]);
if (missing.length > 0) {
  throw new Error(
    `Database configuration error: missing required environment variable(s): ${missing.join(', ')}. ` +
      'Set them in your environment or in a .env file (never commit credentials to source control).'
  );
}

// ---------------------------------------------------------------------------
// Build the Pool.  All values come from environment variables; there are no
// hard-coded credentials anywhere in this file.
// ---------------------------------------------------------------------------
const pool = new Pool({
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME,
  user:     process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // TLS — strongly recommended in production
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,

  // Pool sizing
  max:              parseInt(process.env.DB_POOL_MAX             || '10',    10),
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT_MS || '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN_TIMEOUT_MS || '5000', 10),
});

// ---------------------------------------------------------------------------
// Lifecycle logging — surfaced at the pool level so individual query modules
// don't need to wire this up themselves.
// ---------------------------------------------------------------------------
pool.on('connect', (client) => {
  // Log new physical connections (not every pool.query() call).
  console.info('[db] New client connected to PostgreSQL pool');
});

pool.on('acquire', () => {
  // Fired when a client is checked out of the pool.
  // Useful for tracking pool pressure in verbose mode.
  if (process.env.DB_LOG_ACQUIRE === 'true') {
    console.debug('[db] Client acquired from pool');
  }
});

pool.on('remove', () => {
  console.info('[db] Client removed from pool');
});

pool.on('error', (err, client) => {
  // Idle-client errors must be handled here; otherwise they become
  // uncaught exceptions and crash the process.
  console.error('[db] Unexpected error on idle pool client:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown — release all connections when the process exits so
// PostgreSQL does not see abrupt disconnects.
// ---------------------------------------------------------------------------
const shutdown = async (signal) => {
  console.info(`[db] ${signal} received — draining connection pool…`);
  try {
    await pool.end();
    console.info('[db] Pool drained. Exiting.');
  } catch (err) {
    console.error('[db] Error during pool shutdown:', err.message);
  }
  process.exit(0);
};

process.once('SIGINT',  () => shutdown('SIGINT'));
process.once('SIGTERM', () => shutdown('SIGTERM'));

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Every public function in this module follows the same contract:
 *
 *   • Inputs are passed as bound parameters ($1, $2, …) — never
 *     interpolated into the SQL string — so PostgreSQL handles all
 *     escaping and the driver can reuse prepared-statement plans.
 *
 *   • Each call is wrapped in a timing harness that logs the
 *     operation name, elapsed milliseconds, and row count so slow
 *     queries are easy to spot in production logs.
 *
 *   • Validation is performed before the query reaches the database
 *     so obviously bad input is rejected with a clear error rather
 *     than a cryptic pg error message.
 *
 * Exported functions
 * ──────────────────
 *   getUserById(id)                       → single user row or null
 *   getAllUsers(limit, offset)            → paginated array of users
 *   searchUsers(query, limit, offset)     → full-text / ILIKE search
 */

'use strict';

const pool = require('./db');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Wraps a pg pool.query() call with:
 *  • input validation via the provided `validate` function
 *  • high-resolution query timing
 *  • structured console logs (operation name, duration, row count)
 *  • consistent error re-throwing with context
 *
 * @param {string}   operationName  - Human-readable label used in logs.
 * @param {Function} validate       - Throws a RangeError/TypeError on bad input.
 * @param {string}   sql            - Parameterised SQL string.
 * @param {Array}    params         - Bound parameter values (never interpolated).
 * @returns {Promise<pg.QueryResult>}
 */
async function timedQuery(operationName, validate, sql, params) {
  // Run validation before touching the database.
  validate();

  const start = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, params);

    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.info(
      `[query] ${operationName} | rows=${result.rowCount} | duration=${elapsedMs.toFixed(3)}ms`
    );

    return result;
  } catch (err) {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error(
      `[query] ${operationName} FAILED | duration=${elapsedMs.toFixed(3)}ms | error=${err.message}`
    );

    // Re-throw with context so callers / middleware can distinguish a
    // query failure from an application logic failure.
    const wrapped = new Error(`Query "${operationName}" failed: ${err.message}`);
    wrapped.cause       = err;
    wrapped.operationName = operationName;
    throw wrapped;
  }
}

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

/**
 * Asserts that `value` is a safe integer (whole number, no NaN/Infinity).
 * Throws a TypeError with a descriptive message when the check fails.
 */
function assertSafeInteger(value, label) {
  if (!Number.isInteger(value) || !Number.isFinite(value)) {
    throw new TypeError(`"${label}" must be a finite integer, got: ${JSON.stringify(value)}`);
  }
}

/**
 * Asserts that a pagination limit is within the allowed range so callers
 * cannot request an unreasonably large result set.
 */
const MIN_LIMIT = 1;
const MAX_LIMIT = 100; // Hard cap — callers may not exceed this.

function assertLimit(limit) {
  assertSafeInteger(limit, 'limit');
  if (limit < MIN_LIMIT || limit > MAX_LIMIT) {
    throw new RangeError(
      `"limit" must be between ${MIN_LIMIT} and ${MAX_LIMIT}, got: ${limit}`
    );
  }
}

/**
 * Asserts that a pagination offset is a non-negative integer.
 */
function assertOffset(offset) {
  assertSafeInteger(offset, 'offset');
  if (offset < 0) {
    throw new RangeError(`"offset" must be >= 0, got: ${offset}`);
  }
}

/**
 * Asserts that a search query string is non-empty and within a safe length.
 * Extremely long strings are rejected before they reach the database.
 */
const MAX_SEARCH_LEN = 200;

function assertSearchQuery(query) {
  if (typeof query !== 'string') {
    throw new TypeError(`"query" must be a string, got: ${typeof query}`);
  }
  const trimmed = query.trim();
  if (trimmed.length === 0) {
    throw new RangeError('"query" must not be blank');
  }
  if (trimmed.length > MAX_SEARCH_LEN) {
    throw new RangeError(
      `"query" must be at most ${MAX_SEARCH_LEN} characters, got: ${trimmed.length}`
    );
  }
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * getUserById
 * ───────────
 * Retrieves a single user by their numeric primary-key ID.
 *
 * SQL injection prevention
 *   The id value is passed as the bound parameter $1.  The pg driver
 *   sends it over the wire as a separate binary value; it is never
 *   concatenated into the query string.
 *
 * @param  {number} id  - Integer primary key.
 * @returns {Promise<Object|null>}  User row object, or null if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: … }
 */
async function getUserById(id) {
  // Coerce to number so callers can pass a string from req.params safely.
  const numericId = Number(id);

  const result = await timedQuery(
    'getUserById',
    () => {
      assertSafeInteger(numericId, 'id');
      if (numericId <= 0) {
        throw new RangeError(`"id" must be a positive integer, got: ${numericId}`);
      }
    },
    // $1 is the only interpolation point; the pg driver handles escaping.
    `SELECT
       id,
       name,
       email,
       created_at
     FROM users
     WHERE id = $1
     LIMIT 1`,
    [numericId]
  );

  return result.rows[0] ?? null;
}

/**
 * getAllUsers
 * ───────────
 * Returns a paginated slice of the users table, ordered by id ascending
 * for stable pagination across requests.
 *
 * SQL injection prevention
 *   Both limit and offset are passed as bound parameters ($1, $2).
 *   Input validation further ensures they are safe integers within
 *   acceptable bounds before the query is sent.
 *
 * @param  {number} [limit=20]   - Rows per page (1–100).
 * @param  {number} [offset=0]   - Row offset for pagination.
 * @returns {Promise<Object[]>}  Array of user row objects (may be empty).
 *
 * @example
 *   const page2 = await getAllUsers(20, 20);
 */
async function getAllUsers(limit = 20, offset = 0) {
  const numLimit  = Number(limit);
  const numOffset = Number(offset);

  const result = await timedQuery(
    'getAllUsers',
    () => {
      assertLimit(numLimit);
      assertOffset(numOffset);
    },
    `SELECT
       id,
       name,
       email,
       created_at
     FROM users
     ORDER BY id ASC
     LIMIT  $1
     OFFSET $2`,
    [numLimit, numOffset]
  );

  return result.rows;
}

/**
 * searchUsers
 * ───────────
 * Searches users whose name or email contains the given string
 * (case-insensitive).  The search term is passed as a parameterised
 * ILIKE pattern, which means the pg driver handles all quoting.
 *
 * SQL injection prevention
 *   • The search term is passed as bound parameter $1 — never
 *     interpolated into SQL.
 *   • Special LIKE metacharacters (%, _, \) inside the user-supplied
 *     string are escaped so they are treated as literals rather than
 *     wildcards, preventing "wildcard injection" attacks where an
 *     attacker passes `%` to match every row or crafts a pattern
 *     designed to cause a catastrophic backtrack.
 *
 * @param  {string} query          - Search term (max 200 chars).
 * @param  {number} [limit=20]     - Rows per page (1–100).
 * @param  {number} [offset=0]     - Row offset for pagination.
 * @returns {Promise<Object[]>}    Array of matching user row objects.
 *
 * @example
 *   const results = await searchUsers('alice', 10, 0);
 */
async function searchUsers(query, limit = 20, offset = 0) {
  const numLimit  = Number(limit);
  const numOffset = Number(offset);

  // Escape LIKE metacharacters before building the pattern so that a
  // search for "100%" finds users whose name literally contains "100%"
  // rather than every user.  The escape character used here is '\'.
  const escapedQuery = query
    .trim()
    .replace(/\\/g, '\\\\')   // escape the escape character itself first
    .replace(/%/g,  '\\%')    // literal percent sign
    .replace(/_/g,  '\\_');   // literal underscore

  const likePattern = `%${escapedQuery}%`;

  const result = await timedQuery(
    'searchUsers',
    () => {
      assertSearchQuery(query);
      assertLimit(numLimit);
      assertOffset(numOffset);
    },
    // ILIKE = case-insensitive LIKE in PostgreSQL.
    // The ESCAPE clause tells PostgreSQL which character we used above.
    // $1 = LIKE pattern, $2 = limit, $3 = offset — all bound parameters.
    `SELECT
       id,
       name,
       email,
       created_at
     FROM users
     WHERE name  ILIKE $1 ESCAPE '\\'
        OR email ILIKE $1 ESCAPE '\\'
     ORDER BY id ASC
     LIMIT  $2
     OFFSET $3`,
    [likePattern, numLimit, numOffset]
  );

  return result.rows;
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Exported for testing purposes only — do not use directly in routes.
  _pool: pool,
};

// app.js — Express application
//
// The /users endpoint now delegates all data access to queries.js,
// which uses a shared connection pool and parameterised queries.

'use strict';

require('dotenv').config();
const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Utility — uniform error responses
// ---------------------------------------------------------------------------

/**
 * Sends a structured JSON error response.
 *
 * @param {import('express').Response} res
 * @param {number} status       - HTTP status code
 * @param {string} code         - Machine-readable error code
 * @param {string} message      - Human-readable description
 * @param {Object} [details]    - Optional extra context (never raw SQL/stack)
 */
function sendError(res, status, code, message, details) {
  const body = { error: { code, message } };
  if (details) body.error.details = details;
  return res.status(status).json(body);
}

// ---------------------------------------------------------------------------
// Input-parsing helpers for query-string parameters
// ---------------------------------------------------------------------------

/**
 * Parses and validates the `limit` and `offset` query-string parameters
 * used by paginated endpoints.
 *
 * Returns `{ limit, offset }` as integers on success, or throws a
 * RangeError / TypeError whose message is safe to expose to the client.
 */
function parsePagination(query) {
  const limit  = query.limit  !== undefined ? Number(query.limit)  : 20;
  const offset = query.offset !== undefined ? Number(query.offset) : 0;

  if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
    throw new RangeError('limit must be an integer between 1 and 100');
  }
  if (!Number.isInteger(offset) || offset < 0) {
    throw new RangeError('offset must be a non-negative integer');
  }
  return { limit, offset };
}

// ---------------------------------------------------------------------------
// GET /health
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
//
// Returns a paginated list of users or, when the `search` query-string
// parameter is present, a filtered list.
//
// Query-string parameters
//   search  {string}  – free-text search across name and email
//   limit   {number}  – rows per page, 1–100 (default: 20)
//   offset  {number}  – row offset for pagination (default: 0)
//
// Examples
//   GET /users                         → first 20 users
//   GET /users?limit=5&offset=10       → users 11–15
//   GET /users?search=alice            → users matching "alice"
//   GET /users?search=alice&limit=5    → first 5 users matching "alice"
// ---------------------------------------------------------------------------

app.get('/users', async (req, res) => {
  let pagination;
  try {
    pagination = parsePagination(req.query);
  } catch (err) {
    return sendError(res, 400, 'INVALID_PAGINATION', err.message);
  }

  const { limit, offset } = pagination;
  const searchTerm = req.query.search;

  try {
    let users;

    if (searchTerm !== undefined) {
      // ── Validate the search term length before it reaches queries.js ──
      // Maximum length mirrors the cap in queries.js; the check here gives
      // the HTTP layer control over the error response shape.
      if (typeof searchTerm !== 'string' || searchTerm.trim().length === 0) {
        return sendError(res, 400, 'INVALID_SEARCH', '"search" must be a non-empty string');
      }
      if (searchTerm.length > 200) {
        return sendError(
          res, 400, 'INVALID_SEARCH',
          '"search" must be at most 200 characters'
        );
      }

      users = await searchUsers(searchTerm, limit, offset);
    } else {
      users = await getAllUsers(limit, offset);
    }

    res.json({
      data:   users,
      meta: {
        limit,
        offset,
        count:  users.length,
        search: searchTerm ?? null,
      },
    });
  } catch (err) {
    // Do NOT expose internal error details (SQL, stack traces) to the client.
    console.error('[/users] Unhandled error:', err.message);
    sendError(res, 500, 'INTERNAL_ERROR', 'An unexpected error occurred. Please try again later.');
  }
});

// ---------------------------------------------------------------------------
// GET /users/:id
//
// Retrieves a single user by numeric ID.
//
// URL parameters
//   id  {number}  – positive integer primary key
//
// Examples
//   GET /users/1        → { id: 1, name: 'Alice', … }
//   GET /users/999      → 404 if not found
//   GET /users/abc      → 400 bad request
// ---------------------------------------------------------------------------

app.get('/users/:id', async (req, res) => {
  // Coerce and validate the :id segment before it reaches the query layer.
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    return sendError(
      res, 400, 'INVALID_ID',
      '"id" must be a positive integer',
      { received: req.params.id }
    );
  }

  try {
    const user = await getUserById(id);

    if (!user) {
      return sendError(res, 404, 'NOT_FOUND', `No user found with id ${id}`);
    }

    res.json({ data: user });
  } catch (err) {
    console.error(`[/users/${id}] Unhandled error:`, err.message);
    sendError(res, 500, 'INTERNAL_ERROR', 'An unexpected error occurred. Please try again later.');
  }
});

