/**
 * db.js
 *
 * Creates and exports a single shared pg.Pool instance for the entire
 * application.  Every caller that does `require('./db')` receives the
 * same pool, so database connections are reused rather than opened on
 * every request.
 *
 * Configuration is read exclusively from environment variables so that
 * no credentials are ever hard-coded in source files.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// All values fall back to safe defaults so the app can start in development
// without a full environment setup, while production values are always
// injected through environment variables / secrets management.
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pass@host:5432/db

  // Individual fields (used when DATABASE_URL is not set)
  host:     process.env.DB_HOST     || 'localhost',
  port:     Number(process.env.DB_PORT)     || 5432,
  database: process.env.DB_NAME     || 'app',
  user:     process.env.DB_USER     || 'postgres',
  password: process.env.DB_PASSWORD || '',

  // Connection-pool tunables
  min:               Number(process.env.DB_POOL_MIN)            || 2,   // keep at least 2 idle connections
  max:               Number(process.env.DB_POOL_MAX)            || 10,  // never open more than 10
  idleTimeoutMillis: Number(process.env.DB_IDLE_TIMEOUT_MS)     || 30_000,  // release idle conn after 30 s
  connectionTimeoutMillis: Number(process.env.DB_CONN_TIMEOUT_MS) || 5_000, // give up after 5 s

  // Always use SSL in production unless explicitly disabled
  ssl: process.env.DB_SSL === 'false'
    ? false
    : process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,
});

// ---------------------------------------------------------------------------
// Pool-level event hooks
// ---------------------------------------------------------------------------

/** Logs every new physical connection that the pool opens. */
pool.on('connect', (client) => {
  console.log(`[db] New client connected (total pool size: ${pool.totalCount})`);
});

/**
 * Surface unexpected errors on idle clients.
 * Without this handler the error would be an unhandled rejection and
 * crash the process.
 */
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drains the pool cleanly.  Call this during SIGTERM / SIGINT handling so
 * in-flight queries can finish before the process exits.
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  await pool.end();
  console.log('[db] Connection pool closed.');
}

module.exports = { pool, closePool };

/**
 * queries.js
 *
 * Parameterised query functions for the /users resource.
 *
 * Security guarantees
 * -------------------
 * • Every piece of user-supplied data is passed as a *parameter* ($1, $2 …),
 *   never interpolated into the SQL string.  This is the canonical defence
 *   against SQL injection: the pg driver sends the query text and the
 *   parameter array to PostgreSQL over separate protocol channels, so the
 *   database server always treats parameter values as data, not as SQL.
 * • LIKE wildcards inside the `searchUsers` pattern are escaped before the
 *   value is bound, preventing wildcard-injection / catastrophic backtracking.
 * • `limit` and `offset` are coerced to integers with a hard upper cap so a
 *   caller cannot request an unbounded result set.
 * • No raw SQL is ever constructed by string concatenation.
 *
 * Performance
 * -----------
 * • Queries are issued through the shared pool exported by db.js, so
 *   connections are reused across requests.
 * • Every query is surrounded by high-resolution timing (process.hrtime.bigint)
 *   and the duration is logged so slow queries are visible immediately.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Hard upper limit on page size — prevents accidental or malicious table dumps */
const MAX_LIMIT = 100;

/** Default page size when the caller does not supply one */
const DEFAULT_LIMIT = 20;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Executes a parameterised query against the shared pool and logs the
 * elapsed wall-clock time.
 *
 * Using `pool.query()` (rather than acquiring a client manually) is
 * intentional: the pool checks out a client, runs the query, and returns
 * the client automatically, which is the safest pattern for one-shot
 * queries that do not need a transaction.
 *
 * @param {string}  label       - Short human-readable description used in logs.
 * @param {string}  text        - Parameterised SQL string.
 * @param {Array}   params      - Ordered array of bind values ($1, $2 …).
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, text, params) {
  const start = process.hrtime.bigint(); // nanosecond precision

  try {
    const result = await pool.query(text, params);
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log(
      `[query] ${label} | rows=${result.rowCount} | duration=${elapsedMs.toFixed(3)}ms`
    );

    return result;
  } catch (err) {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    // Log without leaking the bind values (they might contain PII).
    console.error(
      `[query:error] ${label} | duration=${elapsedMs.toFixed(3)}ms | ${err.message}`
    );

    throw err; // re-throw so the caller / route handler can respond appropriately
  }
}

/**
 * Clamps a value to a safe integer in [min, max].
 *
 * @param {*}      value  - Raw input (may be a string from query params).
 * @param {number} min
 * @param {number} max
 * @param {number} fallback - Returned when `value` is not a finite number.
 * @returns {number}
 */
function clampInt(value, min, max, fallback) {
  const n = parseInt(value, 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, n));
}

/**
 * Escapes the special LIKE metacharacters (`%`, `_`, `\`) inside a search
 * term so they are treated as literals.
 *
 * Without this, a caller supplying `%` would match every row, and a
 * pathological pattern could cause significant server-side work.
 *
 * The escaped value is still passed as a *parameter*, so this is an
 * additional layer of defence on top of parameterisation.
 *
 * @param {string} raw
 * @returns {string}
 */
function escapeLikePattern(raw) {
  // Order matters: escape the escape character first.
  return raw
    .replace(/\\/g, '\\\\') // backslash → \\
    .replace(/%/g,  '\\%')  // percent  → \%
    .replace(/_/g,  '\\_'); // underscore → \_
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetches a single user by their primary-key ID.
 *
 * The ID is passed as $1 — PostgreSQL will reject the query entirely if it
 * cannot be cast to the column type, so type-confusion injection is not
 * possible.
 *
 * @param {number|string} id  - The user's numeric ID.
 * @returns {Promise<Object|null>}  The user row, or null if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   // => { id: 42, name: 'Alice', email: 'alice@example.com', created_at: ... }
 */
async function getUserById(id) {
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const { rows } = await timedQuery('getUserById', sql, [id]);
  return rows[0] ?? null;
}

/**
 * Returns a page of users ordered by creation date (newest first).
 *
 * `limit` and `offset` are coerced to safe integers before being bound,
 * and are still passed as parameters ($1 / $2) — not interpolated — so
 * even if the coercion were somehow bypassed the query would be safe.
 *
 * @param {number} [limit=20]   - Page size (1 – MAX_LIMIT).
 * @param {number} [offset=0]   - Number of rows to skip.
 * @returns {Promise<{ users: Object[], total: number }>}
 *
 * @example
 *   const { users, total } = await getAllUsers(10, 20);
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
  const safeLimit  = clampInt(limit,  1, MAX_LIMIT, DEFAULT_LIMIT);
  const safeOffset = clampInt(offset, 0, Number.MAX_SAFE_INTEGER, 0);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY created_at DESC, id DESC
    LIMIT  $1
    OFFSET $2
  `;

  const { rows } = await timedQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  // `total_count` is a window-function aggregate present on every row.
  // Pull it from the first row so callers can build pagination metadata
  // without a separate COUNT(*) round-trip.
  const total = rows.length > 0 ? Number(rows[0].total_count) : 0;

  // Strip the internal aggregate column from the returned objects.
  const users = rows.map(({ total_count, ...user }) => user);

  return { users, total };
}

/**
 * Searches users whose `name` or `email` contains the supplied query string
 * (case-insensitive).
 *
 * Attack-surface considerations:
 * 1. The raw search term is LIKE-escaped before binding → wildcard injection
 *    is neutralised.
 * 2. The escaped term is still bound as a parameter ($1) → SQL injection is
 *    not possible regardless of its content.
 * 3. `limit` and `offset` follow the same safe-integer path as `getAllUsers`.
 *
 * We deliberately do NOT use `ILIKE '%' || $1 || '%'` string concatenation
 * in SQL; the wrapping of wildcards around the already-escaped term happens
 * in JavaScript where it is clearly visible and testable.
 *
 * @param {string} query         - The search term.
 * @param {number} [limit=20]    - Page size (1 – MAX_LIMIT).
 * @param {number} [offset=0]    - Number of rows to skip.
 * @returns {Promise<{ users: Object[], total: number }>}
 *
 * @example
 *   const { users, total } = await searchUsers('alice', 5, 0);
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = 0) {
  if (typeof query !== 'string' || query.trim() === '') {
    // Delegate to the general listing when the search term is empty.
    return getAllUsers(limit, offset);
  }

  const safeLimit   = clampInt(limit,  1, MAX_LIMIT, DEFAULT_LIMIT);
  const safeOffset  = clampInt(offset, 0, Number.MAX_SAFE_INTEGER, 0);

  // Wrap the escaped literal with LIKE wildcards *in JavaScript*, not in SQL.
  const likePattern = `%${escapeLikePattern(query.trim())}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY
      -- Exact matches float to the top; partial matches follow.
      CASE
        WHEN name  ILIKE $2 THEN 0
        WHEN email ILIKE $2 THEN 1
        ELSE 2
      END,
      created_at DESC,
      id DESC
    LIMIT  $3
    OFFSET $4
  `;

  // $1 / $3 = LIKE pattern  |  $2 = exact-match check  |  $3 / $4 = pagination
  const exactPattern = query.trim(); // passed as $2 for the ranking CASE
  const { rows } = await timedQuery('searchUsers', sql, [
    likePattern,   // $1 — ILIKE filter
    exactPattern,  // $2 — exact-match ranking (still parameterised)
    safeLimit,     // $3
    safeOffset,    // $4
  ]);

  const total = rows.length > 0 ? Number(rows[0].total_count) : 0;
  const users = rows.map(({ total_count, ...user }) => user);

  return { users, total };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,

  // Exported for unit testing only — not part of the public API.
  _internal: {
    escapeLikePattern,
    clampInt,
    MAX_LIMIT,
    DEFAULT_LIMIT,
  },
};

/**
 * app.js
 *
 * Express application wired to a PostgreSQL connection pool via queries.js.
 *
 * Endpoints
 * ---------
 *   GET /health              — liveness probe
 *   GET /users               — paginated list  (?limit=&offset=)
 *   GET /users/search        — search          (?q=&limit=&offset=)
 *   GET /users/:id           — single user by ID
 *
 * All database interaction goes through the parameterised helpers in
 * queries.js; no SQL is written here.
 */

'use strict';

// Load environment variables from a .env file in development.
// In production the variables are injected by the platform / secrets manager,
// so dotenv is a no-op when the file is absent.
require('dotenv').config();

const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Request-level timing middleware
// Attaches a high-resolution start timestamp to every incoming request and
// logs method, path, status code, and wall-clock duration when the response
// is finished.
// ---------------------------------------------------------------------------
app.use((req, res, next) => {
  req._startAt = process.hrtime.bigint();

  res.on('finish', () => {
    const elapsedMs = Number(process.hrtime.bigint() - req._startAt) / 1_000_000;
    console.log(
      `[http] ${req.method} ${req.originalUrl} → ${res.statusCode} (${elapsedMs.toFixed(3)}ms)`
    );
  });

  next();
});

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 *
 * Returns a 200 with a timestamp.  Used by load-balancers and orchestrators
 * to verify that the process is alive.  Does not touch the database
 * intentionally — a deep health check (DB ping) would be a separate endpoint.
 */
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ------------------------------------------------------------------
// NOTE: /users/search MUST be registered before /users/:id so that
// Express does not try to look up the literal string "search" as a
// numeric user ID.
// ------------------------------------------------------------------

/**
 * GET /users/search?q=<term>&limit=<n>&offset=<n>
 *
 * Searches users by name or email (case-insensitive, partial match).
 *
 * Query parameters
 *   q      {string}  Search term.  Empty / absent → returns all users.
 *   limit  {number}  Page size (default 20, max 100).
 *   offset {number}  Rows to skip for pagination (default 0).
 *
 * Response 200
 *   {
 *     "data":   [ { id, name, email, created_at }, … ],
 *     "total":  <number>,   // total matching rows across all pages
 *     "limit":  <number>,
 *     "offset": <number>
 *   }
 */
app.get('/users/search', async (req, res) => {
  const { q = '', limit, offset } = req.query;

  try {
    const { users, total } = await searchUsers(q, limit, offset);

    res.json({
      data:   users,
      total,
      limit:  Number(limit)  || 20,
      offset: Number(offset) || 0,
    });
  } catch (err) {
    console.error('[route] GET /users/search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * GET /users?limit=<n>&offset=<n>
 *
 * Returns a paginated list of all users, ordered newest first.
 *
 * Query parameters
 *   limit  {number}  Page size (default 20, max 100).
 *   offset {number}  Rows to skip (default 0).
 *
 * Response 200
 *   {
 *     "data":   [ { id, name, email, created_at }, … ],
 *     "total":  <number>,
 *     "limit":  <number>,
 *     "offset": <number>
 *   }
 */
app.get('/users', async (req, res) => {
  const { limit, offset } = req.query;

  try {
    const { users, total } = await getAllUsers(limit, offset);

    res.json({
      data:   users,
      total,
      limit:  Number(limit)  || 20,
      offset: Number(offset) || 0,
    });
  } catch (err) {
    console.error('[route] GET /users error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * GET /users/:id
 *
 * Fetches a single user.  Returns 400 when :id is not a positive integer
 * (before any database round-trip), and 404 when no row is found.
 *
 * Path parameter
 *   id  {number}  Positive integer user ID.
 *
 * Response 200
 *   { id, name, email, created_at }
 *
 * Response 400
 *   { error: "Invalid user ID" }
 *
 * Response 404
 *   { error: "User not found" }
 */
app.get('/users/:id', async (req, res) => {
  // Validate the ID *before* hitting the database.
  // parseInt rejects non-numeric strings; the > 0 check rejects 0 and
  // negatives.  The value is still passed as a parameter inside getUserById,
  // so this is defence-in-depth rather than the sole protection.
  const id = parseInt(req.params.id, 10);

  if (!Number.isFinite(id) || id <= 0) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  try {
    const user = await getUserById(id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (err) {
    console.error(`[route] GET /users/${id} error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ---------------------------------------------------------------------------
// 404 catch-all
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// Gives in-flight requests time to finish and drains the DB pool cleanly.
// ---------------------------------------------------------------------------
async function shutdown(signal) {
  console.log(`\n[server] Received ${signal}. Shutting down gracefully…`);

  try {
    await closePool();
  } catch (err) {
    console.error('[server] Error during shutdown:', err.message);
  }

  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
const PORT = Number(process.env.PORT) || 3000;

// Only start listening when this file is executed directly (not when it is
// require()-d by a test suite).
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`[server] Running on port ${PORT} (NODE_ENV=${process.env.NODE_ENV || 'development'})`);
  });
}

module.exports = app;

/**
 * queries.test.js
 *
 * Unit tests for every public function in queries.js, plus the internal
 * helpers exported under `_internal`.
 *
 * The pool is mocked at the module level so no real database connection is
 * required.  Each test controls the value that `pool.query` resolves with,
 * letting us verify the exact SQL and parameters that each helper produces.
 *
 * Run with:
 *   npx jest --testPathPattern=queries.test.js
 * or simply:
 *   npx jest
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the shared pool BEFORE requiring queries.js so that the module picks
// up the mock instead of the real pg pool.
// ---------------------------------------------------------------------------
const mockQuery = jest.fn();

jest.mock('./db', () => ({
  pool: { query: mockQuery },
}));

const {
  getUserById,
  getAllUsers,
  searchUsers,
  _internal: { escapeLikePattern, clampInt, MAX_LIMIT, DEFAULT_LIMIT },
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Builds a fake pg QueryResult with the supplied rows. */
function makeResult(rows) {
  return { rows, rowCount: rows.length };
}

/** Returns the SQL string passed to pool.query on the most recent call. */
function lastSql() {
  return mockQuery.mock.calls.at(-1)[0].trim().replace(/\s+/g, ' ');
}

/** Returns the params array passed to pool.query on the most recent call. */
function lastParams() {
  return mockQuery.mock.calls.at(-1)[1];
}

beforeEach(() => mockQuery.mockReset());

// ===========================================================================
// escapeLikePattern
// ===========================================================================
describe('escapeLikePattern', () => {
  test('returns the string unchanged when there are no metacharacters', () => {
    expect(escapeLikePattern('alice')).toBe('alice');
  });

  test('escapes a bare percent sign', () => {
    expect(escapeLikePattern('100%')).toBe('100\\%');
  });

  test('escapes a bare underscore', () => {
    expect(escapeLikePattern('a_b')).toBe('a\\_b');
  });

  test('escapes a backslash first (prevents double-escaping)', () => {
    expect(escapeLikePattern('a\\%b')).toBe('a\\\\\\%b');
  });

  test('escapes multiple metacharacters in one string', () => {
    expect(escapeLikePattern('%_test_%')).toBe('\\%\\_test\\_\\%');
  });

  test('handles an empty string', () => {
    expect(escapeLikePattern('')).toBe('');
  });
});

// ===========================================================================
// clampInt
// ===========================================================================
describe('clampInt', () => {
  test('returns the value unchanged when it is within bounds', () => {
    expect(clampInt(5, 1, 10, 3)).toBe(5);
  });

  test('clamps to the minimum', () => {
    expect(clampInt(-5, 0, 100, 10)).toBe(0);
  });

  test('clamps to the maximum', () => {
    expect(clampInt(200, 0, 100, 10)).toBe(100);
  });

  test('returns the fallback when given NaN', () => {
    expect(clampInt(NaN, 0, 100, 42)).toBe(42);
  });

  test('returns the fallback when given a non-numeric string', () => {
    expect(clampInt('abc', 0, 100, 7)).toBe(7);
  });

  test('parses a numeric string correctly', () => {
    expect(clampInt('15', 1, 100, 5)).toBe(15);
  });
});

// ===========================================================================
// getUserById
// ===========================================================================
describe('getUserById', () => {
  test('returns the matched user row', async () => {
    const row = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };
    mockQuery.mockResolvedValueOnce(makeResult([row]));

    const result = await getUserById(1);

    expect(result).toEqual(row);
  });

  test('passes the id as the first (and only) parameter', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([{ id: 42 }]));

    await getUserById(42);

    expect(lastParams()).toEqual([42]);
  });

  test('SQL contains WHERE id = $1 and LIMIT 1', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([{}]));

    await getUserById(1);

    const sql = lastSql();
    expect(sql).toMatch(/WHERE id = \$1/i);
    expect(sql).toMatch(/LIMIT 1/i);
  });

  test('returns null when no row is found', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    const result = await getUserById(999);

    expect(result).toBeNull();
  });

  test('propagates database errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('DB connection lost'));

    await expect(getUserById(1)).rejects.toThrow('DB connection lost');
  });
});

// ===========================================================================
// getAllUsers
// ===========================================================================
describe('getAllUsers', () => {
  function rowsWithTotal(n, total) {
    return Array.from({ length: n }, (_, i) => ({
      id: i + 1,
      name: `User ${i + 1}`,
      email: `user${i + 1}@example.com`,
      created_at: new Date(),
      total_count: String(total),
    }));
  }

  test('returns users and total without total_count on each object', async () => {
    const rows = rowsWithTotal(2, 50);
    mockQuery.mockResolvedValueOnce(makeResult(rows));

    const { users, total } = await getAllUsers();

    expect(total).toBe(50);
    expect(users).toHaveLength(2);
    users.forEach((u) => expect(u).not.toHaveProperty('total_count'));
  });

  test('applies default limit and offset when called with no arguments', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await getAllUsers();

    expect(lastParams()).toEqual([DEFAULT_LIMIT, 0]);
  });

  test('clamps limit to MAX_LIMIT', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await getAllUsers(9999, 0);

    expect(lastParams()[0]).toBe(MAX_LIMIT);
  });

  test('clamps limit to 1 at the lower bound', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await getAllUsers(0, 0);

    expect(lastParams()[0]).toBe(1);
  });

  test('accepts a string limit from query-string parsing', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await getAllUsers('10', '5');

    expect(lastParams()).toEqual([10, 5]);
  });

  test('SQL uses LIMIT $1 and OFFSET $2', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await getAllUsers(10, 20);

    const sql = lastSql();
    expect(sql).toMatch(/LIMIT\s+\$1/i);
    expect(sql).toMatch(/OFFSET\s+\$2/i);
  });

  test('returns total 0 and empty array when table is empty', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    const { users, total } = await getAllUsers();

    expect(total).toBe(0);
    expect(users).toEqual([]);
  });

  test('propagates database errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('timeout'));

    await expect(getAllUsers()).rejects.toThrow('timeout');
  });
});

// ===========================================================================
// searchUsers
// ===========================================================================
describe('searchUsers', () => {
  function makeRows(n, total) {
    return Array.from({ length: n }, (_, i) => ({
      id: i + 1,
      name: `Alice ${i}`,
      email: `alice${i}@example.com`,
      created_at: new Date(),
      total_count: String(total),
    }));
  }

  test('strips total_count from returned user objects', async () => {
    mockQuery.mockResolvedValueOnce(makeResult(makeRows(1, 1)));

    const { users } = await searchUsers('alice');

    expect(users[0]).not.toHaveProperty('total_count');
  });

  test('wraps the escaped term in LIKE wildcards as $1', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('alice');

    const [likePattern] = lastParams();
    expect(likePattern).toBe('%alice%');
  });

  test('passes the raw term (no wildcards) as $2 for ranking', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('alice');

    const [, exactPattern] = lastParams();
    expect(exactPattern).toBe('alice');
  });

  test('escapes percent signs in the search term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('100%');

    const [likePattern] = lastParams();
    expect(likePattern).toBe('%100\\%%');
  });

  test('escapes underscores in the search term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('a_b');

    const [likePattern] = lastParams();
    expect(likePattern).toBe('%a\\_b%');
  });

  test('trims whitespace from the search term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('  alice  ');

    const [likePattern] = lastParams();
    expect(likePattern).toBe('%alice%');
  });

  test('falls back to getAllUsers when query is empty string', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('');

    // getAllUsers binds [limit, offset] — only 2 params, not 4.
    expect(lastParams()).toHaveLength(2);
  });

  test('falls back to getAllUsers when query is whitespace only', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('   ');

    expect(lastParams()).toHaveLength(2);
  });

  test('falls back to getAllUsers when query is not a string', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers(null);

    expect(lastParams()).toHaveLength(2);
  });

  test('clamps limit to MAX_LIMIT', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('x', 500, 0);

    // params: [$1=like, $2=exact, $3=limit, $4=offset]
    expect(lastParams()[2]).toBe(MAX_LIMIT);
  });

  test('SQL uses ILIKE $1 and LIMIT $3 OFFSET $4', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('alice', 10, 0);

    const sql = lastSql();
    expect(sql).toMatch(/ILIKE \$1/i);
    expect(sql).toMatch(/LIMIT\s+\$3/i);
    expect(sql).toMatch(/OFFSET\s+\$4/i);
  });

  test('returns correct total from window function', async () => {
    mockQuery.mockResolvedValueOnce(makeResult(makeRows(2, 17)));

    const { total } = await searchUsers('alice');

    expect(total).toBe(17);
  });

  test('propagates database errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('deadlock'));

    await expect(searchUsers('alice')).rejects.toThrow('deadlock');
  });
});

