/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared `pg.Pool` instance so that every module in the
 * application reuses the same set of connections rather than opening a fresh
 * socket per request.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials ever appear in source code.  A `.env` file (git-ignored) is
 * loaded in non-production environments for local development convenience.
 */

'use strict';

const { Pool } = require('pg');

// Load .env only outside production — production platforms inject vars directly.
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
// All values fall back to pg's own defaults when the variable is absent so
// the module is usable with a bare DATABASE_URL alone.

const poolConfig = {
  // Primary connection string — postgres://user:pass@host:port/dbname
  connectionString: process.env.DATABASE_URL,

  // Maximum number of clients the pool will hold open simultaneously.
  // Tune this to stay below your database's max_connections limit.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Milliseconds a client can sit idle in the pool before being closed.
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),

  // Milliseconds to wait when all pool slots are in use before returning an
  // error to the caller.
  connectionTimeoutMillis: parseInt(
    process.env.DB_CONNECT_TIMEOUT_MS ?? '5000',
    10,
  ),

  // Enforce TLS in production so credentials travel encrypted.
  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

// Log unexpected errors on idle clients — these would otherwise crash the
// process in older versions of node-postgres.
pool.on('error', (err) => {
  console.error('[db] Unexpected idle-client error:', err.message);
});

// Visibility into pool lifecycle — useful during development / load tests.
pool.on('connect', () => {
  console.log(
    `[db] New client connected (pool size: ${pool.totalCount}/${poolConfig.max})`,
  );
});

pool.on('remove', () => {
  console.log(
    `[db] Client removed from pool (remaining: ${pool.totalCount}/${poolConfig.max})`,
  );
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------
// Call pool.end() when the process is stopping so that in-flight queries
// complete and PostgreSQL does not log unexpected disconnections.

async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] Pool closed.');
}

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Every public function in this module:
 *   1. Accepts only typed, validated arguments — never raw strings interpolated
 *      into SQL — so SQL injection is structurally impossible.
 *   2. Uses the shared pg.Pool for connection reuse.
 *   3. Records and logs query execution time for performance observability.
 *   4. Returns plain objects; HTTP concerns (status codes, res.json) live in
 *      the route layer (app.js).
 *
 * SQL injection prevention strategy
 * ──────────────────────────────────
 *  • All dynamic values are passed as members of the `values` array and
 *    referenced in the SQL string as $1, $2 … $N.  The pg driver sends values
 *    and query text to PostgreSQL as separate protocol messages, so the
 *    database server never parses user-supplied data as SQL.
 *  • Input validation (validateId, validatePagination, validateSearchQuery)
 *    provides a defence-in-depth layer: malformed inputs are rejected before
 *    they even reach the database driver.
 *  • No string concatenation, template-literal interpolation, or dynamic
 *    identifier construction is used anywhere in query text.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Hard ceiling on rows returned in a single getAllUsers call. */
const MAX_LIMIT = 100;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/** Maximum length accepted for a search query string. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * queryWithTiming
 * Wraps pool.query, measures wall-clock duration, and emits a structured log
 * line so slow queries are immediately visible in log aggregators.
 *
 * @param {string}        text   - Parameterised SQL string
 * @param {unknown[]}     values - Bind parameters ($1, $2 …)
 * @param {string}        label  - Human-readable label used in log output
 * @returns {Promise<import('pg').QueryResult>}
 */
async function queryWithTiming(text, values, label) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query({ text, values });
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log(
      `[query] ${label} | rows=${result.rowCount} | duration=${durationMs.toFixed(2)}ms`,
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    // Log the error WITHOUT echoing back user-supplied values so that
    // sensitive data never leaks into log files.
    console.error(
      `[query] ${label} | ERROR after ${durationMs.toFixed(2)}ms | ${err.message}`,
    );

    throw err; // re-throw so the route layer can return a proper HTTP error
  }
}

// ---------------------------------------------------------------------------
// Input validators
// ---------------------------------------------------------------------------
// These run before any database interaction, providing defence-in-depth on
// top of parameterised queries.

/**
 * Validates and coerces a user ID.
 * Accepts strings (from query-string parsing) or numbers.
 *
 * @param {unknown} id
 * @returns {{ valid: true; value: number } | { valid: false; reason: string }}
 */
function validateId(id) {
  const n = Number(id);

  if (!Number.isInteger(n)) {
    return { valid: false, reason: 'id must be an integer' };
  }
  if (n < 1) {
    return { valid: false, reason: 'id must be a positive integer' };
  }
  if (n > Number.MAX_SAFE_INTEGER) {
    return { valid: false, reason: 'id exceeds maximum safe integer' };
  }

  return { valid: true, value: n };
}

/**
 * Validates and coerces pagination parameters.
 *
 * @param {unknown} limit
 * @param {unknown} offset
 * @returns {{ valid: true; limit: number; offset: number } | { valid: false; reason: string }}
 */
function validatePagination(limit, offset) {
  const l = limit === undefined ? DEFAULT_LIMIT : Number(limit);
  const o = offset === undefined ? 0 : Number(offset);

  if (!Number.isInteger(l)) {
    return { valid: false, reason: 'limit must be an integer' };
  }
  if (!Number.isInteger(o)) {
    return { valid: false, reason: 'offset must be an integer' };
  }
  if (l < 1 || l > MAX_LIMIT) {
    return { valid: false, reason: `limit must be between 1 and ${MAX_LIMIT}` };
  }
  if (o < 0) {
    return { valid: false, reason: 'offset must be >= 0' };
  }

  return { valid: true, limit: l, offset: o };
}

/**
 * Validates a search query string.
 *
 * @param {unknown} query
 * @returns {{ valid: true; value: string } | { valid: false; reason: string }}
 */
function validateSearchQuery(query) {
  if (typeof query !== 'string') {
    return { valid: false, reason: 'query must be a string' };
  }

  const trimmed = query.trim();

  if (trimmed.length === 0) {
    return { valid: false, reason: 'query must not be empty' };
  }
  if (trimmed.length > MAX_SEARCH_LENGTH) {
    return {
      valid: false,
      reason: `query must not exceed ${MAX_SEARCH_LENGTH} characters`,
    };
  }

  return { valid: true, value: trimmed };
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * getUserById
 * Fetches a single user row by primary key.
 *
 * SQL injection prevention:
 *   The id is passed as the bind value $1.  pg sends it as a binary parameter
 *   in the extended query protocol, completely separate from the SQL text.
 *
 * @param {number|string} id - The user's primary key (positive integer)
 * @returns {Promise<{ user: object }|{ notFound: true }|{ error: string }>}
 *
 * @example
 *   const result = await getUserById(42);
 *   if (result.error)    return res.status(400).json({ error: result.error });
 *   if (result.notFound) return res.status(404).json({ error: 'Not found' });
 *   return res.json(result.user);
 */
async function getUserById(id) {
  // ── 1. Validate ──────────────────────────────────────────────────────────
  const validation = validateId(id);
  if (!validation.valid) {
    return { error: validation.reason };
  }

  // ── 2. Query ─────────────────────────────────────────────────────────────
  // $1 is the parameterised placeholder; the actual value travels out-of-band.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await queryWithTiming(sql, [validation.value], `getUserById(${validation.value})`);

  if (result.rows.length === 0) {
    return { notFound: true };
  }

  return { user: result.rows[0] };
}

/**
 * getAllUsers
 * Returns a page of users ordered by id.  Uses LIMIT/OFFSET pagination.
 *
 * SQL injection prevention:
 *   Both limit and offset are coerced to integers by validatePagination before
 *   being passed as bind parameters $1 and $2.  No user input ever touches the
 *   SQL string.
 *
 * @param {number} [limit=20]  - Rows per page (1–100)
 * @param {number} [offset=0]  - Zero-based row offset
 * @returns {Promise<{ users: object[]; total: number; limit: number; offset: number }|{ error: string }>}
 *
 * @example
 *   const result = await getAllUsers(10, 20);
 *   if (result.error) return res.status(400).json({ error: result.error });
 *   return res.json(result);
 */
async function getAllUsers(limit, offset) {
  // ── 1. Validate ──────────────────────────────────────────────────────────
  const validation = validatePagination(limit, offset);
  if (!validation.valid) {
    return { error: validation.reason };
  }

  const { limit: safeLimit, offset: safeOffset } = validation;

  // ── 2. Query ─────────────────────────────────────────────────────────────
  // We issue two queries in parallel:
  //   • The paginated data slice
  //   • The total count (needed for the caller to render pagination controls)
  //
  // LIMIT $1 OFFSET $2 — both are integer bind parameters, never interpolated.

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY id ASC
    LIMIT $1 OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
  `;

  const [dataResult, countResult] = await Promise.all([
    queryWithTiming(dataSql, [safeLimit, safeOffset], `getAllUsers(limit=${safeLimit},offset=${safeOffset})`),
    queryWithTiming(countSql, [], 'getAllUsers[count]'),
  ]);

  return {
    users: dataResult.rows,
    total: parseInt(countResult.rows[0].total, 10),
    limit: safeLimit,
    offset: safeOffset,
  };
}

/**
 * searchUsers
 * Full-text search over the `name` and `email` columns using PostgreSQL's
 * ILIKE operator with a parameterised pattern.
 *
 * SQL injection prevention:
 *   The search term is passed as the bind value $3 (a `%term%` pattern built
 *   server-side from a validated, trimmed string).  The LIKE wildcard
 *   characters % and _ that might appear in user input are escaped before the
 *   pattern is constructed so they cannot widen the match unexpectedly.
 *
 * @param {string}  query          - Search term (non-empty, ≤200 chars)
 * @param {number}  [limit=20]     - Rows per page (1–100)
 * @param {number}  [offset=0]     - Zero-based row offset
 * @returns {Promise<{ users: object[]; total: number; query: string; limit: number; offset: number }|{ error: string }>}
 *
 * @example
 *   const result = await searchUsers('alice', 10, 0);
 *   if (result.error) return res.status(400).json({ error: result.error });
 *   return res.json(result);
 */
async function searchUsers(query, limit, offset) {
  // ── 1. Validate ──────────────────────────────────────────────────────────
  const queryValidation = validateSearchQuery(query);
  if (!queryValidation.valid) {
    return { error: queryValidation.reason };
  }

  const pageValidation = validatePagination(limit, offset);
  if (!pageValidation.valid) {
    return { error: pageValidation.reason };
  }

  const { limit: safeLimit, offset: safeOffset } = pageValidation;

  // ── 2. Build a safe LIKE pattern ─────────────────────────────────────────
  // Escape any literal LIKE metacharacters (% and _) present in the user's
  // search term so they match literally rather than as wildcards.
  // The escape character is chosen as '\' (standard SQL).
  // The constructed pattern is still sent as a bind parameter — not inlined.
  const escapedTerm = queryValidation.value
    .replace(/\\/g, '\\\\') // must be first to avoid double-escaping
    .replace(/%/g, '\\%')
    .replace(/_/g, '\\_');

  const likePattern = `%${escapedTerm}%`;

  // ── 3. Query ─────────────────────────────────────────────────────────────
  // $1 = likePattern, $2 = safeLimit, $3 = safeOffset
  // ESCAPE '\\' tells PostgreSQL which character introduces a literal match.

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR email ILIKE $1 ESCAPE '\\'
    ORDER BY id ASC
    LIMIT $2 OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR email ILIKE $1 ESCAPE '\\'
  `;

  const label = `searchUsers(query="${queryValidation.value}",limit=${safeLimit},offset=${safeOffset})`;

  const [dataResult, countResult] = await Promise.all([
    queryWithTiming(dataSql, [likePattern, safeLimit, safeOffset], label),
    queryWithTiming(countSql, [likePattern], `${label}[count]`),
  ]);

  return {
    users: dataResult.rows,
    total: parseInt(countResult.rows[0].total, 10),
    query: queryValidation.value,
    limit: safeLimit,
    offset: safeOffset,
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export validators so they can be unit-tested independently of the DB.
  _validators: {
    validateId,
    validatePagination,
    validateSearchQuery,
  },
};

/**
 * app.js — Express application with a PostgreSQL-backed /users endpoint
 *
 * Architecture
 * ────────────
 *   app.js        HTTP routing, request parsing, error formatting
 *   queries.js    Parameterised SQL, input validation, query timing
 *   db.js         pg.Pool singleton, connection lifecycle
 *
 * All database work is delegated to queries.js; this file contains no SQL.
 */

'use strict';

// Load environment variables from .env before anything else touches process.env.
// In production the platform injects vars directly; dotenv is a no-op there.
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}

const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------

app.use(express.json());

// Lightweight request logger — logs method, path, and response time.
app.use((req, _res, next) => {
  const start = Date.now();
  _res.on('finish', () => {
    console.log(
      `[http] ${req.method} ${req.originalUrl} → ${_res.statusCode} (${Date.now() - start}ms)`,
    );
  });
  next();
});

// ---------------------------------------------------------------------------
// Route helpers
// ---------------------------------------------------------------------------

/**
 * Formats a query-layer result that may carry a validation error into a
 * standard { error } HTTP response, returning false when there is no error
 * so callers can use an early-return guard cleanly.
 *
 * @param {object} result - Value returned by a queries.js function
 * @param {import('express').Response} res
 * @returns {boolean} true when an error response was sent, false otherwise
 */
function handleQueryError(result, res) {
  if (result.error) {
    res.status(400).json({ error: result.error });
    return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health — liveness probe (no DB dependency)
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── /users routes ──────────────────────────────────────────────────────────

/**
 * GET /users
 * Returns a paginated list of all users.
 *
 * Query parameters:
 *   limit  {integer, 1–100, default 20}  — number of rows per page
 *   offset {integer, ≥0,    default  0}  — zero-based row offset
 *
 * Response 200:
 *   { users: User[], total: number, limit: number, offset: number }
 *
 * Response 400:
 *   { error: string }   — invalid limit/offset
 *
 * Response 500:
 *   { error: string }   — unexpected database error
 */
app.get('/users', async (req, res) => {
  try {
    const { limit, offset } = req.query;
    const result = await getAllUsers(limit, offset);

    if (handleQueryError(result, res)) return;

    res.json(result);
  } catch (err) {
    console.error('[route] GET /users unexpected error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * GET /users/search
 * Searches users by name or email (case-insensitive, partial match).
 *
 * ⚠️  This route MUST be registered before GET /users/:id so that the literal
 * path segment "search" is not mistaken for a numeric id.
 *
 * Query parameters:
 *   q      {string, required, ≤200 chars} — search term
 *   limit  {integer, 1–100, default 20}   — rows per page
 *   offset {integer, ≥0,    default  0}   — zero-based row offset
 *
 * Response 200:
 *   { users: User[], total: number, query: string, limit: number, offset: number }
 *
 * Response 400:
 *   { error: string }   — missing/invalid parameters
 *
 * Response 500:
 *   { error: string }   — unexpected database error
 */
app.get('/users/search', async (req, res) => {
  try {
    const { q, limit, offset } = req.query;

    if (!q) {
      return res.status(400).json({ error: 'Missing required query parameter: q' });
    }

    const result = await searchUsers(q, limit, offset);

    if (handleQueryError(result, res)) return;

    res.json(result);
  } catch (err) {
    console.error('[route] GET /users/search unexpected error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * GET /users/:id
 * Returns a single user by primary key.
 *
 * Path parameters:
 *   id {positive integer} — the user's primary key
 *
 * Response 200:
 *   { id, name, email, created_at, updated_at }
 *
 * Response 400:
 *   { error: string }   — id is not a valid positive integer
 *
 * Response 404:
 *   { error: string }   — no user with that id
 *
 * Response 500:
 *   { error: string }   — unexpected database error
 */
app.get('/users/:id', async (req, res) => {
  try {
    const result = await getUserById(req.params.id);

    if (handleQueryError(result, res)) return;

    if (result.notFound) {
      return res.status(404).json({ error: `User ${req.params.id} not found` });
    }

    res.json(result.user);
  } catch (err) {
    console.error(`[route] GET /users/${req.params.id} unexpected error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ---------------------------------------------------------------------------
// 404 fallthrough handler
// ---------------------------------------------------------------------------

app.use((_req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ---------------------------------------------------------------------------
// Global error handler (catches any error passed to next(err))
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  console.error('[app] Unhandled error:', err.message);
  res.status(500).json({ error: 'Internal server error' });
});

// ---------------------------------------------------------------------------
// Server startup & graceful shutdown
// ---------------------------------------------------------------------------

// Only start listening when this file is run directly, not when imported by
// tests (which simply require('./app')).
if (require.main === module) {
  const PORT = parseInt(process.env.PORT ?? '3000', 10);

  const server = app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT} (NODE_ENV=${process.env.NODE_ENV ?? 'development'})`);
  });

  // Graceful shutdown: stop accepting new connections, drain in-flight
  // requests, then close the DB pool.
  async function shutdown(signal) {
    console.log(`[app] Received ${signal} — shutting down gracefully…`);

    server.close(async () => {
      try {
        await closePool();
        console.log('[app] Shutdown complete.');
        process.exit(0);
      } catch (err) {
        console.error('[app] Error during shutdown:', err.message);
        process.exit(1);
      }
    });

    // Force-exit if graceful shutdown takes too long.
    setTimeout(() => {
      console.error('[app] Graceful shutdown timed out — forcing exit.');
      process.exit(1);
    }, 10_000).unref();
  }

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

module.exports = app;

