  const mPool = {
    query: (...args) => mockQuery(...args),
    on: jest.fn(),          // suppress event-listener registrations
    totalCount: 1,
    end: jest.fn().mockResolvedValue(undefined),
  };
  return { Pool: jest.fn(() => mPool) };
});

// Mock dotenv so the test environment never tries to read a real .env file.
jest.mock('dotenv', () => ({ config: jest.fn() }));

