/**
 * Builds a mock pg QueryResult.
 *
 * @param {object[]} rows
 * @returns {import('pg').QueryResult}
 */
function makeResult(rows) {
  return { rows, rowCount: rows.length, command: 'SELECT', oid: null, fields: [] };
}

// Silence console output during tests so Jest output stays readable.
