describe('getUserById', () => {
  const mockUser = {
    id: 1, name: 'Alice', email: 'alice@example.com',
    created_at: new Date(), updated_at: new Date(),
  };

  test('returns the user when found', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([mockUser]));

    const result = await getUserById(1);

    expect(result).toEqual({ user: mockUser });
  });

  test('passes id as a bind parameter, never inline in SQL', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([mockUser]));

    await getUserById(7);

    const [{ text, values }] = mockQuery.mock.calls[0];
    // The id must NOT be interpolated into the SQL text.
    expect(text).not.toContain('7');
    // It must appear in the values array.
    expect(values).toContain(7);
    // The placeholder must be present.
    expect(text).toContain('$1');
  });

  test('returns { notFound: true } when no rows are returned', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    const result = await getUserById(999);

    expect(result).toEqual({ notFound: true });
  });

  test('returns { error } for an invalid (non-integer) id', async () => {
    const result = await getUserById('not-an-id');

    expect(result.error).toBeDefined();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns { error } for a negative id', async () => {
    const result = await getUserById(-1);

    expect(result.error).toBeDefined();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects SQL injection in the id parameter', async () => {
    const result = await getUserById("1; DROP TABLE users;--");

    // Validation rejects before reaching the DB.
    expect(result.error).toBeDefined();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('propagates pool.query errors to the caller', async () => {
    mockQuery.mockRejectedValueOnce(new Error('connection refused'));

    await expect(getUserById(1)).rejects.toThrow('connection refused');
  });

  test('emits a timing log line on success', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([mockUser]));

    await getUserById(1);

    expect(console.log).toHaveBeenCalledWith(
      expect.stringMatching(/\[query\].*getUserById.*rows=1.*duration=/),
    );
  });

  test('emits an error log and rethrows on DB failure', async () => {
    mockQuery.mockRejectedValueOnce(new Error('timeout'));

    await expect(getUserById(1)).rejects.toThrow('timeout');
    expect(console.error).toHaveBeenCalledWith(
      expect.stringMatching(/\[query\].*ERROR/),
    );
  });
});

