describe('getAllUsers', () => {
  const mockUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), updated_at: new Date() },
  ];

  function mockAllUsersQueries(users, total) {
    // getAllUsers fires two queries concurrently via Promise.all.
    // mockQuery must be set up twice — once for data, once for count.
    mockQuery
      .mockResolvedValueOnce(makeResult(users))
      .mockResolvedValueOnce(makeResult([{ total: String(total) }]));
  }

  test('returns users, total, limit, and offset', async () => {
    mockAllUsersQueries(mockUsers, 2);

    const result = await getAllUsers(10, 0);

    expect(result).toMatchObject({
      users: mockUsers,
      total: 2,
      limit: 10,
      offset: 0,
    });
  });

  test('uses default limit=20 and offset=0 when not supplied', async () => {
    mockAllUsersQueries(mockUsers, 2);

    const result = await getAllUsers();

    expect(result.limit).toBe(20);
    expect(result.offset).toBe(0);
  });

  test('passes limit and offset as bind parameters', async () => {
    mockAllUsersQueries(mockUsers, 2);

    await getAllUsers(5, 15);

    // First call is the data query.
    const [{ text, values }] = mockQuery.mock.calls[0];
    expect(text).toContain('$1');
    expect(text).toContain('$2');
    expect(values).toEqual([5, 15]);
    // Neither value should appear inline in the SQL.
    expect(text).not.toContain('LIMIT 5');
    expect(text).not.toContain('OFFSET 15');
  });

  test('returns { error } for limit > 100', async () => {
    const result = await getAllUsers(200, 0);

    expect(result.error).toBeDefined();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns { error } for negative offset', async () => {
    const result = await getAllUsers(10, -5);

    expect(result.error).toBeDefined();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('converts total count string to integer', async () => {
    mockAllUsersQueries([], 42);

    const result = await getAllUsers(10, 0);

    expect(typeof result.total).toBe('number');
    expect(result.total).toBe(42);
  });

  test('propagates pool.query errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('db error'));

    await expect(getAllUsers(10, 0)).rejects.toThrow('db error');
  });

  test('logs timing for both the data and count queries', async () => {
    mockAllUsersQueries(mockUsers, 2);

    await getAllUsers(10, 0);

    const logCalls = console.log.mock.calls.map((c) => c[0]);
    const timingLogs = logCalls.filter((m) => typeof m === 'string' && m.includes('[query]'));
    expect(timingLogs.length).toBeGreaterThanOrEqual(2);
  });
});

