describe('searchUsers', () => {
  const mockUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
  ];

  function mockSearchQueries(users, total) {
    mockQuery
      .mockResolvedValueOnce(makeResult(users))
      .mockResolvedValueOnce(makeResult([{ total: String(total) }]));
  }

  test('returns matching users, total, query, limit, and offset', async () => {
    mockSearchQueries(mockUsers, 1);

    const result = await searchUsers('alice', 10, 0);

    expect(result).toMatchObject({
      users: mockUsers,
      total: 1,
      query: 'alice',
      limit: 10,
      offset: 0,
    });
  });

  test('passes the LIKE pattern as a bind parameter, not inline SQL', async () => {
    mockSearchQueries(mockUsers, 1);

    await searchUsers('alice', 10, 0);

    const [{ text, values }] = mockQuery.mock.calls[0];
    // The pattern is the first bind param.
    expect(values[0]).toBe('%alice%');
    // It must NOT be spliced into the SQL text.
    expect(text).not.toContain('alice');
    // Placeholders must be present.
    expect(text).toContain('$1');
    expect(text).toContain('$2');
    expect(text).toContain('$3');
  });

  test('escapes literal % in the search term', async () => {
    mockSearchQueries([], 0);

    await searchUsers('100%', 10, 0);

    const [{ values }] = mockQuery.mock.calls[0];
    // The % inside the term should be escaped; outer % are LIKE wildcards.
    expect(values[0]).toBe('%100\\%%');
  });

  test('escapes literal _ in the search term', async () => {
    mockSearchQueries([], 0);

    await searchUsers('user_name', 10, 0);

    const [{ values }] = mockQuery.mock.calls[0];
    expect(values[0]).toBe('%user\\_name%');
  });

  test('escapes backslash in the search term', async () => {
    mockSearchQueries([], 0);

    await searchUsers('C:\\path', 10, 0);

    const [{ values }] = mockQuery.mock.calls[0];
    // Backslash is doubled, then wrapped in % wildcards.
    expect(values[0]).toBe('%C:\\\\path%');
  });

  test('a SQL injection attempt in the search term is treated as a literal string', async () => {
    mockSearchQueries([], 0);

    const injection = "' OR '1'='1";
    await searchUsers(injection, 10, 0);

    // The entire injection string is passed as a bind parameter value.
    const [{ text, values }] = mockQuery.mock.calls[0];
    expect(values[0]).toContain(injection.trim());
    // None of the SQL keywords from the injection appear in the query text.
    expect(text.toUpperCase()).not.toContain("OR '1'='1");
  });

  test('trims the query string before using it', async () => {
    mockSearchQueries(mockUsers, 1);

    const result = await searchUsers('  alice  ', 10, 0);

    expect(result.query).toBe('alice');
    const [{ values }] = mockQuery.mock.calls[0];
    expect(values[0]).toBe('%alice%');
  });

  test('returns { error } for an empty search query', async () => {
    const result = await searchUsers('', 10, 0);

    expect(result.error).toBeDefined();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns { error } for a non-string search query', async () => {
    const result = await searchUsers(null, 10, 0);

    expect(result.error).toBeDefined();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns { error } for a search query exceeding 200 chars', async () => {
    const result = await searchUsers('x'.repeat(201), 10, 0);

    expect(result.error).toBeDefined();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns { error } for invalid pagination', async () => {
    const result = await searchUsers('alice', 999, 0);

    expect(result.error).toBeDefined();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('uses default pagination when limit/offset are omitted', async () => {
    mockSearchQueries(mockUsers, 1);

    const result = await searchUsers('alice');

    expect(result.limit).toBe(20);
    expect(result.offset).toBe(0);
  });

  test('propagates pool.query errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('query timeout'));

    await expect(searchUsers('alice', 10, 0)).rejects.toThrow('query timeout');
  });
});

