  test('passes limit and offset query params to getAllUsers', async () => {
    getAllUsers.mockResolvedValueOnce({ ...mockResponse, limit: 5, offset: 10 });

    await request(app).get('/users?limit=5&offset=10');

    expect(getAllUsers).toHaveBeenCalledWith('5', '10');
  });

  test('returns 400 when getAllUsers returns a validation error', async () => {
    getAllUsers.mockResolvedValueOnce({ error: 'limit must be between 1 and 100' });

    const res = await request(app).get('/users?limit=999');

    expect(res.status).toBe(400);
