    expect(res.status).toBe(200);
    expect(res.body).toEqual(mockResponse);
  });

  test('passes q, limit, offset to searchUsers', async () => {
    searchUsers.mockResolvedValueOnce(mockResponse);

    await request(app).get('/users/search?q=alice&limit=5&offset=10');

