  });

  test('returns 400 when q param is missing', async () => {
    const res = await request(app).get('/users/search');

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/q/i);
    expect(searchUsers).not.toHaveBeenCalled();
  });

  test('returns 400 when searchUsers returns a validation error', async () => {
    searchUsers.mockResolvedValueOnce({ error: 'query must not be empty' });

    const res = await request(app).get('/users/search?q=');

    // Express will give us 400 from the missing-q guard.
    expect(res.status).toBe(400);
  });

  test('returns 500 when searchUsers throws', async () => {
    searchUsers.mockRejectedValueOnce(new Error('DB error'));

    const res = await request(app).get('/users/search?q=alice');

