{
  "name": "p15-test-gf75iz",
  "version": "1.0.0",
  "description": "Express API with PostgreSQL query layer",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "node --watch app.js",
    "test": "node --test tests/queries.test.js"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "express": "^4.18.2",
    "pg": "^8.11.3"
  },
  "devDependencies": {
    "dotenv": "^16.3.1"
  }
}

// db.js — Connection pool singleton
// Reads connection config from environment variables ONLY.
// Never hard-code credentials here or anywhere else in the codebase.

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// All values are sourced exclusively from environment variables so that no
// credentials ever appear in source code.  Set these in your .env file (dev)
// or your secrets manager / deployment environment (staging/production).
//
// Required env vars:
//   DB_HOST      – hostname of the PostgreSQL server          (default: localhost)
//   DB_PORT      – TCP port                                    (default: 5432)
//   DB_NAME      – database name                              (default: app)
//   DB_USER      – login role                                 (default: postgres)
//   DB_PASSWORD  – password for the login role                (no default — must be set)
//   DB_SSL       – set to "true" to require TLS               (default: false)
//
// Optional tuning vars:
//   DB_POOL_MAX          – maximum pool size                  (default: 10)
//   DB_POOL_MIN          – minimum idle connections           (default: 2)
//   DB_IDLE_TIMEOUT_MS   – ms before idle client is released  (default: 30000)
//   DB_CONN_TIMEOUT_MS   – ms to wait for a free client       (default: 5000)
//   DB_STATEMENT_TIMEOUT – max ms a single query may run      (default: 10000)
// ---------------------------------------------------------------------------

const poolConfig = {
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME     || 'app',
  user:     process.env.DB_USER     || 'postgres',
  password: process.env.DB_PASSWORD,          // intentionally no fallback

  // Pool sizing
  max:             parseInt(process.env.DB_POOL_MAX        || '10',    10),
  min:             parseInt(process.env.DB_POOL_MIN        || '2',     10),
  idleTimeoutMillis:    parseInt(process.env.DB_IDLE_TIMEOUT_MS  || '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT_MS  || '5000',  10),

  // Hard cap on how long any single statement may run (server-side enforcement)
  statement_timeout: parseInt(process.env.DB_STATEMENT_TIMEOUT || '10000', 10),

  // Enable SSL/TLS when DB_SSL=true (strongly recommended for production)
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
};

// Create the singleton pool — shared across all modules that require('./db').
const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers
// ---------------------------------------------------------------------------

// Uncaught errors on idle clients (e.g. unexpected server disconnects) must be
// handled here; otherwise they crash the process via an unhandled 'error' event.
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', {
    message: err.message,
    code:    err.code,
  });
  // Do NOT exit the process here — let the pool recover by creating a new client.
});

pool.on('connect', () => {
  console.log('[db] New client connected to the pool');
});

pool.on('remove', () => {
  console.log('[db] Client removed from the pool');
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// Call pool.end() when the process is shutting down so that all idle clients
// are released cleanly before the process exits.
// ---------------------------------------------------------------------------
async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] Pool drained — all connections closed');
}

module.exports = { pool, closePool };

// queries.js — Parameterised query functions for the /users endpoint
//
// Design principles applied here:
//
//  1. SQL INJECTION PREVENTION
//     Every value that originates from user input is passed as a parameter ($1,
//     $2, …) in the `values` array of a parameterised query.  The pg driver
//     sends parameters to PostgreSQL over the wire separately from the SQL
//     text, so the database engine never interpolates them into the query
//     string — making injection structurally impossible regardless of the
//     input content.
//
//     LIMIT / OFFSET are cast to integers with Number.parseInt() and validated
//     before use; any non-integer causes an immediate, explicit error rather
//     than a silent coercion that might produce unexpected behaviour.
//
//     Column names and sort directions used in ORDER BY clauses are chosen from
//     a strict allowlist — they are NEVER taken directly from user input.
//
//  2. CONNECTION POOLING
//     All functions use pool.query() which automatically acquires a client from
//     the shared pool in db.js, executes the query, and releases the client
//     back to the pool.  No client is ever checked out manually in this module,
//     so there is no risk of pool exhaustion through leaked clients.
//
//  3. QUERY TIMING LOGS
//     A lightweight wrapper (timedQuery) records the wall-clock duration of
//     every database round-trip and emits a structured log line.  Slow queries
//     (> SLOW_QUERY_THRESHOLD_MS) are flagged as warnings.
//
//  4. INPUT VALIDATION
//     All public functions validate their arguments before issuing any SQL,
//     throwing typed errors (QueryValidationError) that callers can inspect.

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Queries that take longer than this threshold are logged as warnings. */
const SLOW_QUERY_THRESHOLD_MS = 500;

/**
 * Hard upper bound on the number of rows that may be returned by getAllUsers
 * and searchUsers to prevent accidental full-table scans from a single request.
 */
const MAX_LIMIT = 100;

/** Default page size when the caller does not supply a limit. */
const DEFAULT_LIMIT = 20;

// ---------------------------------------------------------------------------
// Error types
// ---------------------------------------------------------------------------

/**
 * Thrown when a caller supplies an argument that fails validation before any
 * SQL is issued.  The `field` property names the offending parameter.
 */
class QueryValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name  = 'QueryValidationError';
    this.field = field;
  }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Wraps pool.query() with structured timing + slow-query logging.
 *
 * @param {string}   label   – Human-readable label used in log lines.
 * @param {string}   sql     – The parameterised SQL string.
 * @param {any[]}    params  – Positional parameter values ($1, $2, …).
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, sql, params = []) {
  const startAt = process.hrtime.bigint();

  let result;
  try {
    result = await pool.query(sql, params);
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - startAt) / 1_000_000;
    console.error('[queries] Query error', {
      label,
      durationMs: durationMs.toFixed(3),
      errorCode:  err.code,
      message:    err.message,
      // Deliberately NOT logging `sql` or `params` at error level in production
      // to avoid leaking query structure / partial data into log aggregators.
    });
    throw err;
  }

  const durationMs = Number(process.hrtime.bigint() - startAt) / 1_000_000;
  const logPayload = {
    label,
    durationMs:  durationMs.toFixed(3),
    rowCount:    result.rowCount,
  };

  if (durationMs > SLOW_QUERY_THRESHOLD_MS) {
    console.warn('[queries] SLOW QUERY detected', logPayload);
  } else {
    console.log('[queries] Query completed', logPayload);
  }

  return result;
}

/**
 * Validates and coerces a raw value to a safe integer.
 * Throws QueryValidationError when the value is not a finite integer.
 *
 * @param {any}    raw    – Value supplied by the caller.
 * @param {string} field  – Parameter name for the error message.
 * @param {number} min    – Inclusive lower bound.
 * @param {number} max    – Inclusive upper bound.
 * @returns {number}
 */
function toSafeInt(raw, field, min, max) {
  const n = parseInt(raw, 10);
  if (!Number.isFinite(n)) {
    throw new QueryValidationError(
      `"${field}" must be a finite integer, received: ${JSON.stringify(raw)}`,
      field,
    );
  }
  if (n < min || n > max) {
    throw new QueryValidationError(
      `"${field}" must be between ${min} and ${max}, received: ${n}`,
      field,
    );
  }
  return n;
}

/**
 * Validates that a search term is a non-empty string within an acceptable
 * length.  Returns the trimmed value.
 *
 * @param {any}    raw    – Value supplied by the caller.
 * @param {string} field  – Parameter name for the error message.
 * @returns {string}
 */
function toSafeSearchTerm(raw, field) {
  if (typeof raw !== 'string') {
    throw new QueryValidationError(
      `"${field}" must be a string, received: ${typeof raw}`,
      field,
    );
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new QueryValidationError(`"${field}" must not be empty`, field);
  }
  if (trimmed.length > 200) {
    throw new QueryValidationError(
      `"${field}" must not exceed 200 characters`,
      field,
    );
  }
  return trimmed;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Retrieves a single user by their primary-key ID.
 *
 * SQL injection prevention:
 *   `id` is cast to a safe integer and then passed as a $1 parameter.
 *   The pg driver transmits it to PostgreSQL as a typed value, completely
 *   separate from the query text.
 *
 * @param {number|string} id – The user's integer ID.
 * @returns {Promise<object|null>} The user row, or null if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: … }
 */
async function getUserById(id) {
  // Validate: must be a positive integer.
  const safeId = toSafeInt(id, 'id', 1, Number.MAX_SAFE_INTEGER);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);

  // Return the row or null — never throw on "not found"; let the caller decide.
  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users, ordered by id ascending.
 *
 * SQL injection prevention:
 *   `limit` and `offset` are validated as safe integers and passed as $1 / $2
 *   parameters.  PostgreSQL accepts numeric parameters for LIMIT and OFFSET
 *   in prepared statements, so no string interpolation is needed or used.
 *
 * @param {number} [limit=DEFAULT_LIMIT]  – Maximum rows to return (1–MAX_LIMIT).
 * @param {number} [offset=0]             – Number of rows to skip.
 * @returns {Promise<{ rows: object[], total: number }>}
 *   `rows`  – The current page of user records.
 *   `total` – Total number of users in the table (for pagination metadata).
 *
 * @example
 *   const { rows, total } = await getAllUsers(10, 20);
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
  // Validate both pagination parameters before issuing any SQL.
  const safeLimit  = toSafeInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // Fetch the requested page and the total row count in a single round-trip
  // using a window function — avoids a second COUNT(*) query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await timedQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  // Strip the window-function column from every row before returning.
  const rows = result.rows.map(({ total_count, ...rest }) => rest);

  return { rows, total };
}

/**
 * Full-text search across the `name` and `email` columns.
 *
 * SQL injection prevention:
 *   The search term is passed exclusively as a parameterised value ($1).
 *   The ILIKE wildcards (%) are prepended/appended in JavaScript as a plain
 *   string and then passed as a single parameter — they are NOT concatenated
 *   into the SQL text.  This means the database treats the entire wildcard
 *   expression as a literal value and never re-interprets it as SQL.
 *
 * @param {string} query             – Search term (trimmed; max 200 chars).
 * @param {number} [limit=DEFAULT_LIMIT]  – Maximum rows to return (1–MAX_LIMIT).
 * @param {number} [offset=0]            – Number of rows to skip.
 * @returns {Promise<{ rows: object[], total: number }>}
 *
 * @example
 *   const { rows, total } = await searchUsers('alice', 5, 0);
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = 0) {
  // Validate the search term first (type + length checks).
  const safeTerm   = toSafeSearchTerm(query, 'query');
  const safeLimit  = toSafeInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // Build the wildcard pattern entirely in JavaScript; pass as one parameter.
  // The pg driver sends this as a bind value — PostgreSQL never parses it
  // as SQL syntax.
  const pattern = `%${safeTerm}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const result = await timedQuery('searchUsers', sql, [pattern, safeLimit, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  const rows = result.rows.map(({ total_count, ...rest }) => rest);

  return { rows, total };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export the error class so route handlers can do instanceof checks.
  QueryValidationError,
};

// app.js — Express application with a PostgreSQL-backed /users endpoint
'use strict';

const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
} = require('./queries');
const { closePool } = require('./db');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler and forwards any unhandled promise rejections
 * to Express's next() so they are handled by the centralised error middleware
 * rather than crashing the process.
 *
 * @param {Function} fn – Async (req, res, next) → Promise route handler.
 * @returns {Function}
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health ----------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users -----------------------------------------------------------------
// Returns a paginated, optionally-searched list of users.
//
// Query parameters:
//   q       {string}  – Optional free-text search applied to name and email.
//   limit   {number}  – Page size (1–100, default 20).
//   offset  {number}  – Number of rows to skip (default 0).
//
// Examples:
//   GET /users
//   GET /users?limit=10&offset=20
//   GET /users?q=alice&limit=5
app.get('/users', asyncHandler(async (req, res) => {
  const { q, limit = 20, offset = 0 } = req.query;

  let data;
  if (q !== undefined) {
    // Search path — delegates to searchUsers which validates all inputs.
    data = await searchUsers(q, limit, offset);
  } else {
    // Plain listing — delegates to getAllUsers which validates all inputs.
    data = await getAllUsers(limit, offset);
  }

  res.json({
    data:   data.rows,
    total:  data.total,
    limit:  parseInt(limit,  10),
    offset: parseInt(offset, 10),
  });
}));

// GET /users/:id -------------------------------------------------------------
// Returns a single user by numeric ID.
//
// Example:
//   GET /users/42
app.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await getUserById(req.params.id);

  if (!user) {
    return res.status(404).json({
      error: 'User not found',
      id:    req.params.id,
    });
  }

  res.json(user);
}));

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// Must be registered AFTER all routes (Express identifies it by arity === 4).
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Validation errors from queries.js are client mistakes → 400.
  if (err instanceof QueryValidationError) {
    return res.status(400).json({
      error: err.message,
      field: err.field,
    });
  }

  // Database connectivity / constraint errors → 503 / 500.
  if (err.code) {
    // PostgreSQL error codes: https://www.postgresql.org/docs/current/errcodes-appendix.html
    const pgClientErrors = new Set([
      '23502', // not_null_violation
      '23503', // foreign_key_violation
      '23505', // unique_violation
      '22P02', // invalid_text_representation (e.g. bad UUID)
    ]);

    if (pgClientErrors.has(err.code)) {
      return res.status(400).json({ error: 'Database constraint error', code: err.code });
    }

    // Connection / pool errors → 503 Service Unavailable.
    console.error('[app] Database error:', { code: err.code, message: err.message });
    return res.status(503).json({ error: 'Database temporarily unavailable' });
  }

  // Unexpected errors — log the full error server-side but return a generic
  // message to the client so internal details are never leaked.
  console.error('[app] Unhandled error:', err);
  res.status(500).json({ error: 'Internal server error' });
});

// ---------------------------------------------------------------------------
// Start server
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT || '3000', 10);

// Export app before calling listen so that test frameworks can import and
// wrap it without actually binding a port.
module.exports = app;

// Only bind when this file is run directly (not when required by tests).
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });

  // Graceful shutdown: finish in-flight requests, drain the DB pool, then exit.
  const shutdown = async (signal) => {
    console.log(`[app] ${signal} received — shutting down gracefully`);
    server.close(async () => {
      await closePool();
      console.log('[app] Shutdown complete');
      process.exit(0);
    });

    // Force-kill if graceful shutdown takes too long.
    setTimeout(() => {
      console.error('[app] Graceful shutdown timed out — forcing exit');
      process.exit(1);
    }, 10_000).unref();
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT',  () => shutdown('SIGINT'));
}

// tests/queries.test.js
// Unit tests for queries.js using Node's built-in test runner (node:test).
// The pg Pool is mocked so no real database is required.
//
// Run: node --test tests/queries.test.js

'use strict';

const { test, describe, beforeEach, mock } = require('node:test');
const assert = require('node:assert/strict');

// ---------------------------------------------------------------------------
// Mock the pg Pool BEFORE requiring queries.js so that the module-level
// `require('./db')` in queries.js receives our fake instead of real pg.
// ---------------------------------------------------------------------------

/** Rows returned by default for any mocked pool.query() call. */
const MOCK_USERS = [
  {
    id: 1,
    name: 'Alice',
    email: 'alice@example.com',
    created_at: new Date('2024-01-01'),
    updated_at: new Date('2024-01-01'),
    total_count: '2',
  },
  {
    id: 2,
    name: 'Bob',
    email: 'bob@example.com',
    created_at: new Date('2024-01-02'),
    updated_at: new Date('2024-01-02'),
    total_count: '2',
  },
];

/** Configurable mock pool state shared across tests. */
let mockQueryImpl = async () => ({ rows: MOCK_USERS, rowCount: MOCK_USERS.length });

const mockPool = {
  query: async (sql, params) => mockQueryImpl(sql, params),
  on:    () => {},          // pool.on('error', …) etc. — no-op in tests
  end:   async () => {},
};

// Override the module cache entry for './db' before loading queries.js.
// We use a simple cache-injection approach that works without any test framework magic.
require.cache[require.resolve('../db')] = {
  id:       require.resolve('../db'),
  filename: require.resolve('../db'),
  loaded:   true,
  exports:  { pool: mockPool, closePool: async () => {} },
};

// Now it's safe to load queries.js — it will use mockPool.
const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
} = require('../queries');

// ---------------------------------------------------------------------------
// Helper to reset the mock before each test
// ---------------------------------------------------------------------------
beforeEach(() => {
  mockQueryImpl = async () => ({ rows: MOCK_USERS, rowCount: MOCK_USERS.length });
});

// ===========================================================================
// getUserById
// ===========================================================================
describe('getUserById', () => {

  test('returns the matching user row', async () => {
    mockQueryImpl = async (_sql, params) => ({
      rows: [MOCK_USERS.find(u => u.id === params[0])],
      rowCount: 1,
    });

    const user = await getUserById(1);
    assert.equal(user.id,    1);
    assert.equal(user.name,  'Alice');
    assert.equal(user.email, 'alice@example.com');
  });

  test('returns null when the user is not found', async () => {
    mockQueryImpl = async () => ({ rows: [], rowCount: 0 });
    const user = await getUserById(999);
    assert.equal(user, null);
  });

  test('passes id as a parameterised value — not interpolated into SQL', async () => {
    let capturedSql    = '';
    let capturedParams = [];

    mockQueryImpl = async (sql, params) => {
      capturedSql    = sql;
      capturedParams = params;
      return { rows: [MOCK_USERS[0]], rowCount: 1 };
    };

    await getUserById(42);

    // The SQL must contain a placeholder, not the literal value.
    assert.match(capturedSql, /\$1/, 'SQL should use $1 placeholder');
    assert.ok(
      !capturedSql.includes('42'),
      'SQL text must NOT contain the raw id value',
    );
    assert.deepEqual(capturedParams, [42]);
  });

  test('throws QueryValidationError for a non-numeric id', async () => {
    await assert.rejects(
      () => getUserById('not-a-number'),
      (err) => {
        assert.ok(err instanceof QueryValidationError);
        assert.equal(err.field, 'id');
        return true;
      },
    );
  });

  test('throws QueryValidationError for a negative id', async () => {
    await assert.rejects(
      () => getUserById(-5),
      (err) => {
        assert.ok(err instanceof QueryValidationError);
        assert.equal(err.field, 'id');
        return true;
      },
    );
  });

  test('throws QueryValidationError for id = 0', async () => {
    await assert.rejects(
      () => getUserById(0),
      QueryValidationError,
    );
  });

  test('rejects SQL injection attempt in id parameter', async () => {
    // Classic injection: "1 OR 1=1"
    await assert.rejects(
      () => getUserById('1 OR 1=1'),
      QueryValidationError,
      'Should reject non-integer id that looks like SQL injection',
    );
  });

});

// ===========================================================================
// getAllUsers
// ===========================================================================
describe('getAllUsers', () => {

  test('returns rows and total count', async () => {
    const { rows, total } = await getAllUsers(20, 0);
    assert.equal(rows.length, 2);
    assert.equal(total, 2);
  });

  test('strips total_count from returned rows', async () => {
    const { rows } = await getAllUsers(20, 0);
    rows.forEach(row => {
      assert.ok(!Object.prototype.hasOwnProperty.call(row, 'total_count'),
        'total_count should be stripped from user rows');
    });
  });

  test('passes limit and offset as parameters — not in SQL text', async () => {
    let capturedSql    = '';
    let capturedParams = [];

    mockQueryImpl = async (sql, params) => {
      capturedSql    = sql;
      capturedParams = params;
      return { rows: MOCK_USERS, rowCount: MOCK_USERS.length };
    };

    await getAllUsers(15, 30);

    assert.match(capturedSql, /\$1/, 'SQL should use $1 for LIMIT');
    assert.match(capturedSql, /\$2/, 'SQL should use $2 for OFFSET');
    assert.ok(!capturedSql.includes('15'), 'SQL text must not contain raw limit');
    assert.ok(!capturedSql.includes('30'), 'SQL text must not contain raw offset');
    assert.deepEqual(capturedParams, [15, 30]);
  });

  test('uses default limit and offset when not provided', async () => {
    let capturedParams = [];
    mockQueryImpl = async (_sql, params) => {
      capturedParams = params;
      return { rows: [], rowCount: 0 };
    };

    await getAllUsers();
    assert.equal(capturedParams[0], 20,  'default limit should be 20');
    assert.equal(capturedParams[1],  0,  'default offset should be 0');
  });

  test('returns empty rows and total=0 when table is empty', async () => {
    mockQueryImpl = async () => ({ rows: [], rowCount: 0 });
    const { rows, total } = await getAllUsers();
    assert.deepEqual(rows,  []);
    assert.equal(total, 0);
  });

  test('throws QueryValidationError when limit exceeds MAX_LIMIT (100)', async () => {
    await assert.rejects(
      () => getAllUsers(101, 0),
      (err) => {
        assert.ok(err instanceof QueryValidationError);
        assert.equal(err.field, 'limit');
        return true;
      },
    );
  });

  test('throws QueryValidationError for non-integer limit', async () => {
    await assert.rejects(
      () => getAllUsers('abc', 0),
      QueryValidationError,
    );
  });

  test('throws QueryValidationError for negative offset', async () => {
    await assert.rejects(
      () => getAllUsers(10, -1),
      (err) => {
        assert.ok(err instanceof QueryValidationError);
        assert.equal(err.field, 'offset');
        return true;
      },
    );
  });

  test('throws QueryValidationError for limit = 0', async () => {
    await assert.rejects(
      () => getAllUsers(0, 0),
      QueryValidationError,
    );
  });

  test('rejects SQL injection attempt in limit parameter', async () => {
    await assert.rejects(
      () => getAllUsers('10; DROP TABLE users--', 0),
      QueryValidationError,
    );
  });

  test('rejects SQL injection attempt in offset parameter', async () => {
    await assert.rejects(
      () => getAllUsers(10, '0 UNION SELECT * FROM secrets--'),
      QueryValidationError,
    );
  });

});

// ===========================================================================
// searchUsers
// ===========================================================================
describe('searchUsers', () => {

  test('returns matching rows and total', async () => {
    mockQueryImpl = async () => ({
      rows: [MOCK_USERS[0]],
      rowCount: 1,
    });

    const { rows, total } = await searchUsers('alice');
    assert.equal(rows.length, 1);
    assert.equal(total, 1);
  });

  test('strips total_count from returned rows', async () => {
    const { rows } = await searchUsers('alice');
    rows.forEach(row => {
      assert.ok(!Object.prototype.hasOwnProperty.call(row, 'total_count'));
    });
  });

  test('passes search term as a parameter — not interpolated into SQL', async () => {
    let capturedSql    = '';
    let capturedParams = [];

    mockQueryImpl = async (sql, params) => {
      capturedSql    = sql;
      capturedParams = params;
      return { rows: [MOCK_USERS[0]], rowCount: 1 };
    };

    await searchUsers('alice');

    assert.match(capturedSql, /\$1/, 'SQL should use $1 for the search pattern');
    assert.ok(
      !capturedSql.includes('alice'),
      'Raw search term must NOT appear in the SQL text',
    );
    // The pattern is built in JS and passed as a bind value.
    assert.equal(capturedParams[0], '%alice%');
  });

  test('wildcards are in the parameter value, not in the SQL text', async () => {
    let capturedSql = '';
    mockQueryImpl = async (sql, params) => {
      capturedSql = sql;
      return { rows: [], rowCount: 0 };
    };

    await searchUsers('test');

    // Confirm there are no literal % characters in the SQL string itself.
    assert.ok(
      !capturedSql.includes('%'),
      'SQL text must not contain literal % wildcard — it should be in the parameter value',
    );
  });

  test('throws QueryValidationError for empty search term', async () => {
    await assert.rejects(
      () => searchUsers('  '),
      (err) => {
        assert.ok(err instanceof QueryValidationError);
        assert.equal(err.field, 'query');
        return true;
      },
    );
  });

  test('throws QueryValidationError for non-string search term', async () => {
    await assert.rejects(
      () => searchUsers(123),
      QueryValidationError,
    );
  });

  test('throws QueryValidationError for search term exceeding 200 chars', async () => {
    await assert.rejects(
      () => searchUsers('a'.repeat(201)),
      (err) => {
        assert.ok(err instanceof QueryValidationError);
        assert.equal(err.field, 'query');
        return true;
      },
    );
  });

  test('rejects SQL injection attempt in search term (structural safety)', async () => {
    let capturedParams = [];
    mockQueryImpl = async (_sql, params) => {
      capturedParams = params;
      return { rows: [], rowCount: 0 };
    };

    // This injection attempt is valid as a string, but it must reach the DB
    // as a literal parameter value — never parsed as SQL.
    const injection = "' OR '1'='1";
    await searchUsers(injection);

    // The injection string must appear verbatim inside the bind value (with
    // wildcards), proving it was sent as data, not as SQL syntax.
    assert.equal(capturedParams[0], `%${injection}%`);
  });

  test('returns empty result when no rows match', async () => {
    mockQueryImpl = async () => ({ rows: [], rowCount: 0 });
    const { rows, total } = await searchUsers('zzz_no_match');
    assert.deepEqual(rows,  []);
    assert.equal(total, 0);
  });

  test('applies limit and offset parameters', async () => {
    let capturedParams = [];
    mockQueryImpl = async (_sql, params) => {
      capturedParams = params;
      return { rows: [], rowCount: 0 };
    };

    await searchUsers('bob', 5, 10);
    assert.equal(capturedParams[1], 5,  'limit should be $2');
    assert.equal(capturedParams[2], 10, 'offset should be $3');
  });

  test('throws QueryValidationError for invalid limit in searchUsers', async () => {
    await assert.rejects(
      () => searchUsers('alice', 0),
      QueryValidationError,
    );
  });

});

// ===========================================================================
// QueryValidationError shape
// ===========================================================================
describe('QueryValidationError', () => {

  test('has correct name, message, and field properties', () => {
    const err = new QueryValidationError('bad value', 'myField');
    assert.equal(err.name,    'QueryValidationError');
    assert.equal(err.message, 'bad value');
    assert.equal(err.field,   'myField');
    assert.ok(err instanceof Error);
    assert.ok(err instanceof QueryValidationError);
  });

});

