/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single pg.Pool instance shared across the whole process.
 * All configuration is read from environment variables so that no
 * credentials are ever hard-coded in source files.
 *
 * Environment variables (set these in your .env file or deployment config):
 *   DB_HOST      — hostname of the Postgres server   (default: localhost)
 *   DB_PORT      — port number                        (default: 5432)
 *   DB_NAME      — database name                      (default: app)
 *   DB_USER      — login role                         (required)
 *   DB_PASSWORD  — password for that role             (required)
 *   DB_SSL       — "true" to enforce TLS              (default: false)
 *   DB_POOL_MAX  — maximum pool size                  (default: 10)
 *   DB_POOL_IDLE — ms before idle client is released  (default: 30000)
 *   DB_POOL_CONN — ms to wait for a connection        (default: 2000)
 *
 * Alternatively you may set DATABASE_URL as a full connection string and
 * the pool will use it directly, ignoring the individual variables above.
 */

'use strict';

const { Pool } = require('pg');

// ─── Build pool config ────────────────────────────────────────────────────────

function buildPoolConfig() {
  // Prefer a full connection string when provided, but never fall back to a
  // hard-coded default — if neither is present we fail fast with a clear error.
  if (process.env.DATABASE_URL) {
    return {
      connectionString: process.env.DATABASE_URL,
      ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
      max: parseInt(process.env.DB_POOL_MAX  ?? '10', 10),
      idleTimeoutMillis:    parseInt(process.env.DB_POOL_IDLE ?? '30000', 10),
      connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN ?? '2000',  10),
    };
  }

  // Validate required individual variables
  const missing = ['DB_USER', 'DB_PASSWORD', 'DB_NAME'].filter(
    (key) => !process.env[key],
  );
  if (missing.length) {
    throw new Error(
      `Database configuration error: missing required environment variable(s): ${missing.join(', ')}. ` +
      'Set them in your .env file or provide DATABASE_URL.',
    );
  }

  return {
    host:     process.env.DB_HOST ?? 'localhost',
    port:     parseInt(process.env.DB_PORT ?? '5432', 10),
    database: process.env.DB_NAME,
    user:     process.env.DB_USER,
    password: process.env.DB_PASSWORD,
    ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
    max: parseInt(process.env.DB_POOL_MAX  ?? '10', 10),
    idleTimeoutMillis:    parseInt(process.env.DB_POOL_IDLE ?? '30000', 10),
    connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN ?? '2000',  10),
  };
}

// ─── Create pool ──────────────────────────────────────────────────────────────

const pool = new Pool(buildPoolConfig());

// Surface connection errors immediately rather than silently at query time
pool.on('error', (err) => {
  console.error('[db] Unexpected pool client error:', err.message);
});

// Confirm the pool can reach the database during startup (non-fatal warning)
pool.connect()
  .then((client) => {
    console.log('[db] Connection pool established successfully');
    client.release();
  })
  .catch((err) => {
    console.warn('[db] Warning: could not verify initial connection —', err.message);
  });

// ─── Helpers exported alongside the pool ─────────────────────────────────────

/**
 * Run a single parameterised query and return the pg QueryResult.
 * Prefer calling this from queries.js rather than using pool.query directly,
 * so that all timing and error handling flows through one place.
 *
 * @param {string}  sql    — SQL text with $1 … $N placeholders
 * @param {Array}   params — values that replace the placeholders
 */
async function query(sql, params = []) {
  return pool.query(sql, params);
}

/**
 * Borrow a client from the pool for operations that need an explicit
 * transaction (BEGIN / COMMIT / ROLLBACK).  The caller is responsible
 * for calling client.release() in a finally block.
 */
async function getClient() {
  return pool.connect();
}

/**
 * Gracefully drain and close all pool connections — call this on
 * process shutdown to allow in-flight queries to finish first.
 */
async function closePool() {
  await pool.end();
  console.log('[db] Connection pool closed');
}

module.exports = { pool, query, getClient, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Security guarantees
 * ───────────────────
 * • Every external value (id, search term, pagination numbers) is passed as a
 *   bind parameter ($1, $2, …) — never interpolated into the SQL string.
 *   This makes SQL injection structurally impossible for these queries.
 * • Numeric inputs (id, limit, offset) are explicitly coerced and range-checked
 *   before they reach the driver, providing defence-in-depth.
 * • The ILIKE search pattern is escaped to neutralise the SQL wildcard
 *   characters % and _ that could otherwise widen the result set unexpectedly.
 * • pg's parameterised query API sends query text and parameters in separate
 *   protocol messages, so the database server never combines them into a raw
 *   string where injection could occur.
 *
 * Query timing
 * ────────────
 * Every function wraps its query in a timer and emits a structured log line:
 *   [query] <functionName> completed in <N>ms  (rows: <N>)
 * Slow queries (> SLOW_QUERY_THRESHOLD_MS) are flagged as warnings.
 */

'use strict';

const { query } = require('./db');

// ─── Constants ────────────────────────────────────────────────────────────────

const SLOW_QUERY_THRESHOLD_MS = parseInt(process.env.SLOW_QUERY_MS ?? '200', 10);

/** Hard ceiling on how many rows a single list request may return */
const MAX_LIMIT = 100;

/** Default page size when the caller does not supply one */
const DEFAULT_LIMIT = 20;

// ─── Input sanitisation helpers ───────────────────────────────────────────────

/**
 * Parse and validate a positive integer.
 * Throws a RangeError with a human-readable message on invalid input so that
 * route handlers can convert it to a 400 response without a stack trace leak.
 *
 * @param {*}      value   — raw input (string, number, undefined, …)
 * @param {string} name    — parameter name used in the error message
 * @param {number} min     — inclusive lower bound
 * @param {number} max     — inclusive upper bound
 * @returns {number}
 */
function parsePositiveInt(value, name, min = 1, max = Number.MAX_SAFE_INTEGER) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < min || n > max) {
    throw new RangeError(
      `Invalid parameter "${name}": expected an integer between ${min} and ${max}, got ${JSON.stringify(value)}.`,
    );
  }
  return n;
}

/**
 * Escape ILIKE wildcard characters in a caller-supplied search string.
 * Without this, a term like "50% off" would be treated as a pattern that
 * matches any row containing "50" followed by any characters — not the
 * literal text the user typed.
 *
 * Characters escaped: % _ \
 *
 * @param {string} raw — the unescaped user input
 * @returns {string}   — safe for use inside a LIKE / ILIKE expression
 */
function escapeWildcards(raw) {
  // Escape the SQL escape character first, then the two wildcard characters
  return raw.replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
}

/**
 * Trim a search string and enforce a length cap.
 * Very long search terms are almost always either a mistake or an attempt to
 * cause excessive work on the database.
 *
 * @param {string} raw
 * @param {number} maxLength
 * @returns {string}
 */
function sanitiseSearchQuery(raw, maxLength = 200) {
  if (typeof raw !== 'string') {
    throw new TypeError(`Search query must be a string, got ${typeof raw}.`);
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new RangeError('Search query must not be empty.');
  }
  if (trimmed.length > maxLength) {
    throw new RangeError(`Search query must not exceed ${maxLength} characters.`);
  }
  return trimmed;
}

// ─── Timing helper ────────────────────────────────────────────────────────────

/**
 * Execute a pg parameterised query, emit a structured timing log, and return
 * the QueryResult.  All query functions in this module delegate to this helper
 * so that observability is consistent and cannot be accidentally bypassed.
 *
 * @param {string} label   — human-readable name used in log output
 * @param {string} sql     — parameterised SQL text ($1 … $N placeholders)
 * @param {Array}  params  — bind parameters (never interpolated into sql)
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, sql, params) {
  const start = process.hrtime.bigint();

  try {
    const result = await query(sql, params);
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    const logFn = elapsedMs > SLOW_QUERY_THRESHOLD_MS ? console.warn : console.log;
    logFn(
      `[query] ${label} completed in ${elapsedMs.toFixed(2)}ms` +
      ` | rows: ${result.rowCount}` +
      (elapsedMs > SLOW_QUERY_THRESHOLD_MS ? ' ⚠ SLOW QUERY' : ''),
    );

    return result;
  } catch (err) {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.error(
      `[query] ${label} FAILED after ${elapsedMs.toFixed(2)}ms | error: ${err.message}`,
    );
    throw err; // re-throw so the route handler can return an appropriate HTTP status
  }
}

// ─── Query functions ──────────────────────────────────────────────────────────

/**
 * Fetch a single user by their primary-key id.
 *
 * SQL injection prevention:
 *   The id is validated as a positive integer and then passed as bind
 *   parameter $1.  The SQL text never contains the raw caller value.
 *
 * @param {number|string} id — the user's numeric primary key
 * @returns {Promise<object|null>}  the user row, or null when not found
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(id) {
  // Coerce and validate — rejects non-integers, negatives, and non-numeric strings
  const safeId = parsePositiveInt(id, 'id');

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * Return a paginated list of all users, ordered by id for stable pagination.
 *
 * SQL injection prevention:
 *   Both limit and offset are validated as non-negative integers and passed as
 *   bind parameters $1 and $2.  PostgreSQL's parameterised protocol ensures
 *   they are treated as numeric values, not SQL fragments.
 *
 * @param {number|string} limit  — max rows to return (1–100, default 20)
 * @param {number|string} offset — rows to skip for pagination (default 0)
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number}>}
 *
 * @example
 *   const page = await getAllUsers(20, 40);  // page 3 with page-size 20
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
  const safeLimit  = parsePositiveInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = parsePositiveInt(offset, 'offset', 0);          // 0 is valid

  // A separate COUNT query lets the client build pagination controls without
  // fetching all rows.  Both queries share a pool connection transparently.
  const countSql = `SELECT COUNT(*)::integer AS total FROM users`;
  const countResult = await timedQuery('getAllUsers:count', countSql, []);
  const total = countResult.rows[0].total;

  const listSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const listResult = await timedQuery('getAllUsers:list', listSql, [safeLimit, safeOffset]);

  return {
    users:  listResult.rows,
    total,
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * Full-text search across user names and email addresses using a
 * case-insensitive prefix/substring match.
 *
 * SQL injection prevention:
 *   1. The raw query string is trimmed and length-capped.
 *   2. SQL wildcard characters (%, _, \) inside the term are escaped so the
 *      ILIKE pattern matches the literal characters the caller typed.
 *   3. The escaped pattern is passed as bind parameter $1 — the database
 *      driver transmits it out-of-band from the SQL text, so it can never be
 *      parsed as SQL by the server.
 *
 * @param {string}        searchQuery — the search term entered by the user
 * @param {number|string} limit       — max rows to return (1–100, default 20)
 * @param {number|string} offset      — rows to skip for pagination (default 0)
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number, query: string}>}
 *
 * @example
 *   const results = await searchUsers('alice', 10, 0);
 */
async function searchUsers(searchQuery, limit = DEFAULT_LIMIT, offset = 0) {
  const safeTerm   = sanitiseSearchQuery(searchQuery);
  const safeLimit  = parsePositiveInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = parsePositiveInt(offset, 'offset', 0);

  // Surround the escaped term with % to match the pattern anywhere in the field
  const pattern = `%${escapeWildcards(safeTerm)}%`;

  // A single parameterised pattern is shared by both the WHERE clause and the
  // COUNT subquery — the bind parameter $1 is sent once.
  const countSql = `
    SELECT COUNT(*)::integer AS total
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
  `;
  const countResult = await timedQuery('searchUsers:count', countSql, [pattern]);
  const total = countResult.rows[0].total;

  const searchSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY
      -- Exact matches sort first, then prefix matches, then substring matches
      CASE
        WHEN name  ILIKE $1 AND name  = $2 THEN 0
        WHEN email ILIKE $1 AND email = $2 THEN 0
        WHEN name  ILIKE $3               THEN 1
        WHEN email ILIKE $3               THEN 1
        ELSE 2
      END,
      id ASC
    LIMIT  $4
    OFFSET $5
  `;

  // $2 = exact match value (case-sensitive equality handled by ILIKE above)
  // $3 = prefix-match pattern
  const exactMatch  = safeTerm;
  const prefixMatch = `${escapeWildcards(safeTerm)}%`;

  const searchResult = await timedQuery('searchUsers:list', searchSql, [
    pattern,      // $1  substring match for WHERE + ORDER BY relevance
    exactMatch,   // $2  exact match detection in ORDER BY
    prefixMatch,  // $3  prefix match detection in ORDER BY
    safeLimit,    // $4
    safeOffset,   // $5
  ]);

  return {
    users:  searchResult.rows,
    total,
    limit:  safeLimit,
    offset: safeOffset,
    query:  safeTerm,   // echo back the sanitised term (never the raw input)
  };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Expose internal helpers for unit testing
  _internal: { parsePositiveInt, escapeWildcards, sanitiseSearchQuery },
};

/**
 * app.js — Express application with a PostgreSQL-backed /users endpoint
 *
 * Route summary
 * ─────────────
 *   GET /health              — liveness probe
 *   GET /users               — paginated list  (?limit=&offset=)
 *   GET /users/search        — search by name or email (?q=&limit=&offset=)
 *   GET /users/:id           — single user by id
 */

'use strict';

// Load .env variables before anything else (no-op when the file is absent,
// which is correct in production where variables are injected by the platform)
require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');
const { closePool } = require('./db');

const app = express();
app.use(express.json());

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Wrap an async route handler so that any thrown error is forwarded to
 * Express's error-handling middleware instead of crashing the process.
 *
 * @param {Function} fn — async (req, res, next) handler
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Map well-known error types to appropriate HTTP status codes.
 *
 * @param {Error} err
 * @returns {number}
 */
function httpStatusFor(err) {
  if (err instanceof RangeError || err instanceof TypeError) return 400;
  return 500;
}

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Basic liveness probe — does not touch the database.
 */
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users/search?q=<term>[&limit=<n>][&offset=<n>]
 *
 * Search users by name or email (case-insensitive substring match).
 * Must be registered BEFORE /users/:id so that "search" is not treated as an id.
 *
 * Query parameters:
 *   q      (required) — the search term
 *   limit  (optional) — max results, 1–100, default 20
 *   offset (optional) — pagination offset, default 0
 *
 * Responses:
 *   200 { users, total, limit, offset, query }
 *   400 { error }   — missing/invalid parameters
 *   500 { error }   — unexpected database error
 */
app.get(
  '/users/search',
  asyncHandler(async (req, res) => {
    const { q, limit = '20', offset = '0' } = req.query;

    if (!q || typeof q !== 'string' || q.trim() === '') {
      return res.status(400).json({
        error: 'Missing required query parameter "q" (search term).',
      });
    }

    const data = await searchUsers(q, limit, offset);
    return res.json(data);
  }),
);

/**
 * GET /users?[limit=<n>][&offset=<n>]
 *
 * Return a paginated list of all users.
 *
 * Query parameters:
 *   limit  (optional) — max results, 1–100, default 20
 *   offset (optional) — pagination offset, default 0
 *
 * Responses:
 *   200 { users, total, limit, offset }
 *   400 { error }   — invalid pagination parameters
 *   500 { error }   — unexpected database error
 */
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    const { limit = '20', offset = '0' } = req.query;
    const data = await getAllUsers(limit, offset);
    return res.json(data);
  }),
);

/**
 * GET /users/:id
 *
 * Return a single user by their numeric id.
 *
 * URL parameters:
 *   id (required) — positive integer
 *
 * Responses:
 *   200 { id, name, email, created_at, updated_at }
 *   400 { error }   — id is not a valid positive integer
 *   404 { error }   — no user with that id exists
 *   500 { error }   — unexpected database error
 */
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({
        error: `User with id ${req.params.id} not found.`,
      });
    }

    return res.json(user);
  }),
);

// ─── Error-handling middleware ─────────────────────────────────────────────────

/**
 * Centralised error handler — catches anything thrown by asyncHandler,
 * converts it to a structured JSON response, and avoids leaking stack traces.
 *
 * eslint-disable-next-line no-unused-vars  (four-argument signature is required by Express)
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  const status = httpStatusFor(err);

  // Log server errors in full; keep client-error logs terse
  if (status >= 500) {
    console.error('[error]', err);
  } else {
    console.warn('[error]', err.message);
  }

  // Never expose raw stack traces or internal details to the client
  res.status(status).json({ error: err.message });
});

// ─── Server startup / shutdown ────────────────────────────────────────────────

const PORT = parseInt(process.env.PORT ?? '3000', 10);

const server = app.listen(PORT, () => {
  console.log(`[app] Server running on port ${PORT}`);
});

// Graceful shutdown: finish in-flight requests, then drain the pool
function shutdown(signal) {
  console.log(`[app] Received ${signal} — shutting down gracefully…`);
  server.close(async () => {
    await closePool();
    process.exit(0);
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;

/**
 * queries.test.js — Unit tests for the queries module
 *
 * Strategy: mock the db module so tests run without a real database.
 * All SQL injection prevention and input validation logic is exercised here.
 * Integration tests that hit a real pg instance belong in a separate
 * queries.integration.test.js file (needs a running Postgres server).
 */

'use strict';

// ─── Mock the database layer ──────────────────────────────────────────────────

// We mock db.js before requiring queries.js so that no real pg Pool is created.
jest.mock('./db', () => ({
  query: jest.fn(),
  getClient: jest.fn(),
  closePool: jest.fn(),
}));

const db = require('./db');
const { getUserById, getAllUsers, searchUsers, _internal } = require('./queries');
const { parsePositiveInt, escapeWildcards, sanitiseSearchQuery } = _internal;

// ─── Shared fixtures ──────────────────────────────────────────────────────────

const ALICE = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() };
const BOB   = { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), updated_at: new Date() };

function makeQueryResult(rows) {
  return { rows, rowCount: rows.length };
}

beforeEach(() => {
  jest.clearAllMocks();
  // Suppress console output during tests to keep the output clean
  jest.spyOn(console, 'log').mockImplementation(() => {});
  jest.spyOn(console, 'warn').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  jest.restoreAllMocks();
});

// ─────────────────────────────────────────────────────────────────────────────
// Internal helpers
// ─────────────────────────────────────────────────────────────────────────────

describe('parsePositiveInt()', () => {
  test('accepts a valid integer string', () => {
    expect(parsePositiveInt('5', 'id')).toBe(5);
  });

  test('accepts a numeric number value', () => {
    expect(parsePositiveInt(42, 'id')).toBe(42);
  });

  test('accepts 0 when min is set to 0', () => {
    expect(parsePositiveInt(0, 'offset', 0)).toBe(0);
  });

  test('rejects negative numbers', () => {
    expect(() => parsePositiveInt(-1, 'id')).toThrow(RangeError);
  });

  test('rejects floating-point numbers', () => {
    expect(() => parsePositiveInt(1.5, 'id')).toThrow(RangeError);
  });

  test('rejects non-numeric strings — SQL injection attempt', () => {
    expect(() => parsePositiveInt("1; DROP TABLE users;--", 'id')).toThrow(RangeError);
  });

  test('rejects UNION-based injection attempt', () => {
    expect(() => parsePositiveInt("1 UNION SELECT * FROM secrets", 'id')).toThrow(RangeError);
  });

  test('rejects empty string', () => {
    expect(() => parsePositiveInt('', 'id')).toThrow(RangeError);
  });

  test('rejects undefined', () => {
    expect(() => parsePositiveInt(undefined, 'id')).toThrow(RangeError);
  });

  test('enforces upper bound', () => {
    expect(() => parsePositiveInt(101, 'limit', 1, 100)).toThrow(RangeError);
  });

  test('accepts value at upper bound', () => {
    expect(parsePositiveInt(100, 'limit', 1, 100)).toBe(100);
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('escapeWildcards()', () => {
  test('passes through plain strings unchanged', () => {
    expect(escapeWildcards('alice')).toBe('alice');
  });

  test('escapes % character', () => {
    expect(escapeWildcards('50% off')).toBe('50\\% off');
  });

  test('escapes _ character', () => {
    expect(escapeWildcards('user_name')).toBe('user\\_name');
  });

  test('escapes the escape character \\ itself', () => {
    expect(escapeWildcards('C:\\path')).toBe('C:\\\\path');
  });

  test('escapes all three special characters in one string', () => {
    expect(escapeWildcards('a%b_c\\')).toBe('a\\%b\\_c\\\\');
  });

  test('returns empty string unchanged', () => {
    expect(escapeWildcards('')).toBe('');
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('sanitiseSearchQuery()', () => {
  test('returns trimmed version of a valid string', () => {
    expect(sanitiseSearchQuery('  alice  ')).toBe('alice');
  });

  test('throws on empty string', () => {
    expect(() => sanitiseSearchQuery('')).toThrow(RangeError);
  });

  test('throws on whitespace-only string', () => {
    expect(() => sanitiseSearchQuery('   ')).toThrow(RangeError);
  });

  test('throws when string exceeds maxLength', () => {
    expect(() => sanitiseSearchQuery('a'.repeat(201))).toThrow(RangeError);
  });

  test('accepts string at exact maxLength limit', () => {
    const s = 'a'.repeat(200);
    expect(sanitiseSearchQuery(s)).toBe(s);
  });

  test('throws on non-string input', () => {
    expect(() => sanitiseSearchQuery(123)).toThrow(TypeError);
    expect(() => sanitiseSearchQuery(null)).toThrow(TypeError);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// getUserById
// ─────────────────────────────────────────────────────────────────────────────

describe('getUserById()', () => {
  test('returns the user row when found', async () => {
    db.query.mockResolvedValueOnce(makeQueryResult([ALICE]));
    const result = await getUserById(1);
    expect(result).toEqual(ALICE);
  });

  test('returns null when no user is found', async () => {
    db.query.mockResolvedValueOnce(makeQueryResult([]));
    const result = await getUserById(999);
    expect(result).toBeNull();
  });

  test('passes id as a bind parameter — never interpolated into SQL', async () => {
    db.query.mockResolvedValueOnce(makeQueryResult([ALICE]));
    await getUserById(1);

    const [sql, params] = db.query.mock.calls[0];
    // The SQL text must contain a placeholder, not the literal value
    expect(sql).toContain('$1');
    expect(params).toEqual([1]);
    // Confirm the raw id value is NOT embedded in the SQL string
    expect(sql).not.toContain('1');
  });

  test('rejects a string SQL injection payload', async () => {
    await expect(getUserById("1; DROP TABLE users;--")).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('rejects a UNION-based injection attempt', async () => {
    await expect(getUserById("0 UNION SELECT username, password FROM admin--")).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('rejects a negative id', async () => {
    await expect(getUserById(-1)).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('rejects a float id', async () => {
    await expect(getUserById(1.5)).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('propagates db errors to the caller', async () => {
    db.query.mockRejectedValueOnce(new Error('Connection refused'));
    await expect(getUserById(1)).rejects.toThrow('Connection refused');
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// getAllUsers
// ─────────────────────────────────────────────────────────────────────────────

describe('getAllUsers()', () => {
  test('returns paginated users with total count', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 2 }]))   // count query
      .mockResolvedValueOnce(makeQueryResult([ALICE, BOB]));     // list query

    const result = await getAllUsers(20, 0);
    expect(result).toEqual({ users: [ALICE, BOB], total: 2, limit: 20, offset: 0 });
  });

  test('passes limit and offset as bind parameters', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 2 }]))
      .mockResolvedValueOnce(makeQueryResult([BOB]));

    await getAllUsers(1, 1);

    const [listSql, listParams] = db.query.mock.calls[1];
    expect(listSql).toContain('$1');
    expect(listSql).toContain('$2');
    expect(listParams).toEqual([1, 1]);
  });

  test('uses default limit and offset when none supplied', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 0 }]))
      .mockResolvedValueOnce(makeQueryResult([]));

    const result = await getAllUsers();
    expect(result.limit).toBe(20);
    expect(result.offset).toBe(0);
  });

  test('rejects limit above MAX_LIMIT (100)', async () => {
    await expect(getAllUsers(101, 0)).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('rejects negative offset', async () => {
    await expect(getAllUsers(20, -1)).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('rejects SQL-injection string as limit', async () => {
    await expect(getAllUsers('20; DROP TABLE users;--', 0)).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('rejects SQL-injection string as offset', async () => {
    await expect(getAllUsers(20, '0 UNION SELECT 1')).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('returns empty list when no users exist', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 0 }]))
      .mockResolvedValueOnce(makeQueryResult([]));

    const result = await getAllUsers();
    expect(result.users).toEqual([]);
    expect(result.total).toBe(0);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// searchUsers
// ─────────────────────────────────────────────────────────────────────────────

describe('searchUsers()', () => {
  test('returns matching users with metadata', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 1 }]))
      .mockResolvedValueOnce(makeQueryResult([ALICE]));

    const result = await searchUsers('alice', 10, 0);
    expect(result).toMatchObject({ users: [ALICE], total: 1, limit: 10, offset: 0, query: 'alice' });
  });

  test('wraps the search term in % wildcards for ILIKE', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 0 }]))
      .mockResolvedValueOnce(makeQueryResult([]));

    await searchUsers('alice', 10, 0);

    const [, countParams] = db.query.mock.calls[0];
    expect(countParams[0]).toBe('%alice%');
  });

  test('escapes % in the search term to prevent wildcard injection', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 0 }]))
      .mockResolvedValueOnce(makeQueryResult([]));

    await searchUsers('50% off', 10, 0);

    const [, countParams] = db.query.mock.calls[0];
    // The literal % from the user's term must be escaped
    expect(countParams[0]).toBe('%50\\% off%');
  });

  test('escapes _ in the search term to prevent single-char wildcard injection', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 0 }]))
      .mockResolvedValueOnce(makeQueryResult([]));

    await searchUsers('user_admin', 10, 0);

    const [, countParams] = db.query.mock.calls[0];
    expect(countParams[0]).toBe('%user\\_admin%');
  });

  test('echoes back the sanitised query (never the raw input)', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 0 }]))
      .mockResolvedValueOnce(makeQueryResult([]));

    const result = await searchUsers('  alice  ', 10, 0);
    expect(result.query).toBe('alice');
  });

  test('passes the search pattern as a bind parameter — not in SQL text', async () => {
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 0 }]))
      .mockResolvedValueOnce(makeQueryResult([]));

    await searchUsers('alice', 10, 0);

    const [countSql, countParams] = db.query.mock.calls[0];
    expect(countSql).toContain('$1');
    expect(countParams[0]).toBe('%alice%');
    // The literal word "alice" must NOT appear in the SQL string
    expect(countSql).not.toContain('alice');
  });

  test("rejects a classic SQL injection payload: ' OR '1'='1", async () => {
    // Even if validation passed, the value is a bind param — but length/type
    // checks should still catch absurd payloads; here we just verify no db call
    db.query
      .mockResolvedValueOnce(makeQueryResult([{ total: 0 }]))
      .mockResolvedValueOnce(makeQueryResult([]));

    // This is a valid (short) string so validation won't throw — but the
    // critical assertion is that it arrives at the DB as a bound value, not SQL
    await searchUsers("' OR '1'='1", 10, 0);

    const [, countParams] = db.query.mock.calls[0];
    // The injection payload is just a string inside a bind parameter
    expect(countParams[0]).toContain("' OR '1'='1");
  });

  test('rejects empty search query', async () => {
    await expect(searchUsers('', 10, 0)).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('rejects excessively long search query', async () => {
    await expect(searchUsers('x'.repeat(201), 10, 0)).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('rejects non-string query', async () => {
    await expect(searchUsers(null, 10, 0)).rejects.toThrow(TypeError);
    expect(db.query).not.toHaveBeenCalled();
  });

  test('rejects limit above MAX_LIMIT', async () => {
    await expect(searchUsers('alice', 101, 0)).rejects.toThrow(RangeError);
    expect(db.query).not.toHaveBeenCalled();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// Query timing log
// ─────────────────────────────────────────────────────────────────────────────

describe('query timing', () => {
  test('emits a timing log for successful queries', async () => {
    db.query.mockResolvedValueOnce(makeQueryResult([ALICE]));
    await getUserById(1);
    const logCalls = console.log.mock.calls.map((c) => c.join(' '));
    expect(logCalls.some((msg) => msg.includes('[query]') && msg.includes('ms'))).toBe(true);
  });

  test('emits an error log for failed queries', async () => {
    db.query.mockRejectedValueOnce(new Error('timeout'));
    await expect(getUserById(1)).rejects.toThrow('timeout');
    const errCalls = console.error.mock.calls.map((c) => c.join(' '));
    expect(errCalls.some((msg) => msg.includes('[query]') && msg.includes('FAILED'))).toBe(true);
  });
});

