/**
 * db.js – Connection pool singleton
 *
 * Creates a single `pg.Pool` that is shared across the whole process.
 * All configuration is read from environment variables (never hard-coded).
 *
 * Environment variables (see .env.example):
 *   DB_HOST, DB_PORT, DB_NAME, DB_USER, DB_PASSWORD
 *   DB_POOL_MAX               – max connections in pool  (default 10)
 *   DB_POOL_IDLE_TIMEOUT_MS   – ms before idle client released (default 30 000)
 *   DB_POOL_CONNECTION_TIMEOUT_MS – ms to wait for a free client (default 2 000)
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate that every required variable is present before the pool is created.
// This surfaces misconfiguration at startup rather than at the first query.
// ---------------------------------------------------------------------------
const REQUIRED_ENV_VARS = ['DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_USER', 'DB_PASSWORD'];

for (const key of REQUIRED_ENV_VARS) {
  if (!process.env[key]) {
    throw new Error(
      `[db] Missing required environment variable: ${key}. ` +
        'Copy .env.example → .env and fill in your real credentials.'
    );
  }
}

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
const poolConfig = {
  host:     process.env.DB_HOST,
  port:     Number(process.env.DB_PORT),
  database: process.env.DB_NAME,
  user:     process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Maximum number of clients the pool should contain.
  max: Number(process.env.DB_POOL_MAX ?? 10),

  // How long (ms) a client may sit idle before being removed from the pool.
  idleTimeoutMillis: Number(process.env.DB_POOL_IDLE_TIMEOUT_MS ?? 30_000),

  // How long (ms) to wait for a client to become available before throwing.
  connectionTimeoutMillis: Number(process.env.DB_POOL_CONNECTION_TIMEOUT_MS ?? 2_000),

  // Reject self-signed certs in production; allow them in other environments.
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: true } : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event hooks
// ---------------------------------------------------------------------------

// Surfaces background errors (e.g. a client whose connection was severed
// by the server) so they don't go silently missing.
pool.on('error', (err, client) => {
  console.error('[db:pool] Unexpected error on idle client:', err.message);
});

pool.on('connect', () => {
  if (process.env.NODE_ENV !== 'test') {
    console.log('[db:pool] New client connected to the pool');
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool and close all connections.
 * Call this during SIGTERM / SIGINT handlers.
 */
async function closePool() {
  await pool.end();
  console.log('[db:pool] Pool has ended – all connections closed');
}

module.exports = { pool, closePool };

/**
 * queries.js – Parameterised query functions for the /users endpoint
 *
 * Design principles
 * -----------------
 * 1. SQL INJECTION PREVENTION
 *    Every piece of user-supplied data is passed as a parameter ($1, $2 …)
 *    and never interpolated into the SQL string.  pg sends the query text and
 *    the parameter array in separate protocol messages, so the database driver
 *    handles all escaping – there is no string-building at all.
 *
 * 2. CONNECTION POOLING
 *    All functions borrow a client from the shared `pg.Pool` in db.js via the
 *    pool.query() convenience method.  The client is automatically returned to
 *    the pool when the query finishes (or throws), so there is no risk of
 *    connection leaks.
 *
 * 3. QUERY TIMING LOGS
 *    Every public function wraps execution in a `queryWithTiming()` helper
 *    that records start / end timestamps and emits a structured log line that
 *    includes the operation name, row count, and elapsed milliseconds.
 *
 * 4. INPUT VALIDATION
 *    Before any SQL is executed, arguments are validated for correct types and
 *    safe ranges.  This is a second-layer defence that also produces friendlier
 *    error messages than a raw database error would.
 *
 * 5. SAFE DEFAULTS
 *    `getAllUsers` enforces a maximum page size (MAX_LIMIT) so callers cannot
 *    request an unbounded result set.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Hard ceiling on the number of rows returned by getAllUsers. */
const MAX_LIMIT = 100;

/** Default number of rows when the caller does not specify a limit. */
const DEFAULT_LIMIT = 20;

/** Default page offset. */
const DEFAULT_OFFSET = 0;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Executes a parameterised query against the shared pool and emits a
 * structured timing log on both success and failure.
 *
 * @param {string}   operationName  – Human-readable label used in log output.
 * @param {string}   sql            – The SQL statement with $n placeholders.
 * @param {Array}    params         – Positional parameter values.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function queryWithTiming(operationName, sql, params) {
  const startedAt = Date.now();

  try {
    const result = await pool.query(sql, params);
    const elapsedMs = Date.now() - startedAt;

    console.log(
      JSON.stringify({
        level:       'info',
        timestamp:   new Date().toISOString(),
        context:     'db:query',
        operation:   operationName,
        rowCount:    result.rowCount,
        elapsedMs,
      })
    );

    return result;
  } catch (err) {
    const elapsedMs = Date.now() - startedAt;

    console.error(
      JSON.stringify({
        level:     'error',
        timestamp: new Date().toISOString(),
        context:   'db:query',
        operation: operationName,
        elapsedMs,
        // Never log parameter values – they may contain PII.
        error:     err.message,
        code:      err.code,
      })
    );

    // Re-throw so the caller (route handler) can decide how to respond.
    throw err;
  }
}

/**
 * Asserts that `value` is a safe positive integer.
 * Throws a TypeError with a descriptive message when the assertion fails.
 *
 * @param {*}      value – The value to check.
 * @param {string} name  – Variable name used in the error message.
 */
function assertPositiveInteger(value, name) {
  if (!Number.isInteger(value) || value < 0) {
    throw new TypeError(
      `[queries] "${name}" must be a non-negative integer, received: ${JSON.stringify(value)}`
    );
  }
}

/**
 * Asserts that `value` is a non-empty string within a safe length.
 * Throws a TypeError with a descriptive message when the assertion fails.
 *
 * @param {*}      value     – The value to check.
 * @param {string} name      – Variable name used in the error message.
 * @param {number} [maxLen]  – Maximum allowed string length (default 200).
 */
function assertSafeString(value, name, maxLen = 200) {
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new TypeError(
      `[queries] "${name}" must be a non-empty string, received: ${JSON.stringify(value)}`
    );
  }
  if (value.length > maxLen) {
    throw new TypeError(
      `[queries] "${name}" must be ≤ ${maxLen} characters, received length: ${value.length}`
    );
  }
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetches a single user by their primary-key ID.
 *
 * SQL injection prevention
 * ─────────────────────────
 * `id` is type-checked (must be a positive integer) before the query is
 * executed, and is passed as the parameter $1 – never concatenated into the
 * SQL string.
 *
 * @param {number} id – The user's numeric primary key.
 * @returns {Promise<object|null>} The user row, or null if not found.
 */
async function getUserById(id) {
  // --- Input validation (first line of defence) ---
  if (!Number.isInteger(id) || id <= 0) {
    throw new TypeError(
      `[queries:getUserById] "id" must be a positive integer, received: ${JSON.stringify(id)}`
    );
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  // $1 is bound to `id` by the driver — the value never touches the SQL text.
  const result = await queryWithTiming('getUserById', sql, [id]);

  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users, ordered by creation date descending.
 *
 * SQL injection prevention
 * ─────────────────────────
 * `limit` and `offset` are both validated as non-negative integers and then
 * passed as $1 and $2 — they are never interpolated into the SQL string.
 * The hard ceiling MAX_LIMIT prevents runaway queries.
 *
 * @param {number} [limit=DEFAULT_LIMIT]   – Maximum rows to return (≤ MAX_LIMIT).
 * @param {number} [offset=DEFAULT_OFFSET] – Number of rows to skip (for pagination).
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number}>}
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = DEFAULT_OFFSET) {
  // --- Input validation ---
  assertPositiveInteger(limit,  'limit');
  assertPositiveInteger(offset, 'offset');

  // Silently clamp to the ceiling instead of rejecting, so callers that send
  // large limits still get a valid (just smaller) result.
  const safeLimit = Math.min(limit, MAX_LIMIT);

  // Two queries run inside a single pool checkout for consistency:
  //   1. The paginated data slice
  //   2. The total count (needed to build pagination metadata)
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY created_at DESC
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
  `;

  // Both queries are dispatched in parallel to minimise latency.
  const [dataResult, countResult] = await Promise.all([
    queryWithTiming('getAllUsers:data',  dataSql,  [safeLimit, offset]),
    queryWithTiming('getAllUsers:count', countSql, []),
  ]);

  return {
    users:  dataResult.rows,
    total:  Number(countResult.rows[0].total),
    limit:  safeLimit,
    offset,
  };
}

/**
 * Full-text search across users' name and email columns using PostgreSQL's
 * ILIKE operator (case-insensitive prefix/infix match).
 *
 * SQL injection prevention
 * ─────────────────────────
 * The raw search term is NEVER interpolated into SQL.  Instead:
 *   a) `query` is validated as a safe string (non-empty, max 200 chars).
 *   b) The wildcard pattern ('%' + query + '%') is built in JavaScript and
 *      passed as parameter $1.  pg sends it to the server as a bind parameter
 *      via the extended query protocol, so no quoting or escaping is needed.
 *
 * This means a query of  '; DROP TABLE users; --  is treated as a literal
 * search string by the database and will simply return zero rows.
 *
 * @param {string} query  – The search term (will be matched with ILIKE).
 * @param {number} [limit=DEFAULT_LIMIT]   – Maximum rows to return.
 * @param {number} [offset=DEFAULT_OFFSET] – Rows to skip.
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number, query: string}>}
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = DEFAULT_OFFSET) {
  // --- Input validation ---
  assertSafeString(query, 'query');
  assertPositiveInteger(limit,  'limit');
  assertPositiveInteger(offset, 'offset');

  const safeLimit = Math.min(limit, MAX_LIMIT);

  // Build the wildcard pattern in JS and pass it as a parameter.
  // The '%' characters are part of the bind value, not part of the SQL text,
  // so they cannot be used to escape out of the ILIKE expression.
  const pattern = `%${query}%`;

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY
      -- Exact name matches first, then email matches, then partial matches.
      CASE
        WHEN name  ILIKE $2 THEN 0
        WHEN email ILIKE $2 THEN 1
        ELSE 2
      END,
      created_at DESC
    LIMIT  $3
    OFFSET $4
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
  `;

  // Exact-match pattern is passed as a separate bind value ($2) so the CASE
  // expression can rank results without repeating logic.
  const exactPattern = query;

  const [dataResult, countResult] = await Promise.all([
    queryWithTiming('searchUsers:data',  dataSql,  [pattern, exactPattern, safeLimit, offset]),
    queryWithTiming('searchUsers:count', countSql, [pattern]),
  ]);

  return {
    users:  dataResult.rows,
    total:  Number(countResult.rows[0].total),
    limit:  safeLimit,
    offset,
    query,          // Echo back the original term so clients can display it.
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Expose constants so tests (and callers) can reference canonical values.
  MAX_LIMIT,
  DEFAULT_LIMIT,
  DEFAULT_OFFSET,
};

/**
 * app.js – Express application
 *
 * Wires the query layer (queries.js) to the /users HTTP routes.
 * The raw `pool` / SQL concerns live entirely in queries.js and db.js;
 * this file only handles HTTP parsing, validation, and response shaping.
 */

'use strict';

// Load environment variables from .env before any other module reads them.
// In production, variables are injected by the platform and dotenv is a no-op.
require('dotenv').config();

const express = require('express');
const { closePool } = require('./db');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  MAX_LIMIT,
  DEFAULT_LIMIT,
  DEFAULT_OFFSET,
} = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parses `raw` as a base-10 integer.
 * Returns NaN when the value is undefined, null, or non-numeric.
 *
 * @param {*}      raw          – The raw query-string value.
 * @param {number} defaultValue – Fallback when raw is absent.
 */
function parseIntParam(raw, defaultValue) {
  if (raw === undefined || raw === null) return defaultValue;
  const n = parseInt(raw, 10);
  return Number.isNaN(n) ? NaN : n;
}

/**
 * Sends a consistent JSON error response.
 *
 * @param {import('express').Response} res
 * @param {number} status
 * @param {string} message
 */
function sendError(res, status, message) {
  res.status(status).json({ error: message });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health – liveness probe (unchanged)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
//
// Returns a paginated list of users.
//
// Query parameters:
//   limit   {integer, 1–100}  – Page size (default 20).
//   offset  {integer, ≥ 0}    – Number of rows to skip (default 0).
//   search  {string}          – When present, delegates to searchUsers().
//
// Examples:
//   GET /users
//   GET /users?limit=5&offset=10
//   GET /users?search=alice
//   GET /users?search=example.com&limit=50
// ---------------------------------------------------------------------------
app.get('/users', async (req, res) => {
  const { search } = req.query;

  // --- Parse & validate pagination params ---
  const limit  = parseIntParam(req.query.limit,  DEFAULT_LIMIT);
  const offset = parseIntParam(req.query.offset, DEFAULT_OFFSET);

  if (Number.isNaN(limit) || limit < 1 || limit > MAX_LIMIT) {
    return sendError(res, 400, `"limit" must be an integer between 1 and ${MAX_LIMIT}.`);
  }
  if (Number.isNaN(offset) || offset < 0) {
    return sendError(res, 400, '"offset" must be a non-negative integer.');
  }

  try {
    if (search !== undefined) {
      // --- Delegated to searchUsers() ---
      if (typeof search !== 'string' || search.trim().length === 0) {
        return sendError(res, 400, '"search" must be a non-empty string.');
      }
      if (search.length > 200) {
        return sendError(res, 400, '"search" must be 200 characters or fewer.');
      }

      const result = await searchUsers(search.trim(), limit, offset);
      return res.json(result);
    }

    // --- Default: getAllUsers() ---
    const result = await getAllUsers(limit, offset);
    return res.json(result);
  } catch (err) {
    console.error(
      JSON.stringify({
        level:     'error',
        timestamp: new Date().toISOString(),
        context:   'route:GET /users',
        error:     err.message,
      })
    );
    return sendError(res, 500, 'An internal error occurred. Please try again later.');
  }
});

// ---------------------------------------------------------------------------
// GET /users/:id
//
// Returns a single user by numeric ID.
//
// Examples:
//   GET /users/1
//   GET /users/42
// ---------------------------------------------------------------------------
app.get('/users/:id', async (req, res) => {
  const id = parseInt(req.params.id, 10);

  // The id must be a positive integer; reject anything else before it reaches
  // the database layer.
  if (!Number.isInteger(id) || id <= 0) {
    return sendError(res, 400, '"id" must be a positive integer.');
  }

  try {
    const user = await getUserById(id);

    if (!user) {
      return sendError(res, 404, `No user found with id ${id}.`);
    }

    return res.json(user);
  } catch (err) {
    console.error(
      JSON.stringify({
        level:     'error',
        timestamp: new Date().toISOString(),
        context:   `route:GET /users/${id}`,
        error:     err.message,
      })
    );
    return sendError(res, 500, 'An internal error occurred. Please try again later.');
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------

async function shutdown(signal) {
  console.log(`[app] Received ${signal} – shutting down gracefully`);
  try {
    await closePool();
  } catch (err) {
    console.error('[app] Error during shutdown:', err.message);
  }
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Start server (only when this file is run directly, not when imported)
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js – Unit tests for queries.js
 *
 * The pg pool is mocked so these tests run without a real database.
 * Every test verifies:
 *   • The correct SQL is sent (parameterised, no string interpolation)
 *   • The correct $n bind values are sent (injection prevention)
 *   • Input validation rejects bad values before any SQL is executed
 *   • Query timing logs are emitted (console.log spy)
 *   • Pool errors are re-thrown so the caller can handle them
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock environment – must happen before db.js is first required
// ---------------------------------------------------------------------------
process.env.DB_HOST     = 'localhost';
process.env.DB_PORT     = '5432';
process.env.DB_NAME     = 'testdb';
process.env.DB_USER     = 'testuser';
process.env.DB_PASSWORD = 'testpassword';
process.env.NODE_ENV    = 'test';

// ---------------------------------------------------------------------------
// Mock pg so no real TCP connection is ever attempted
// ---------------------------------------------------------------------------
const mockQuery = jest.fn();
const mockPoolOn = jest.fn();
const mockPoolEnd = jest.fn().mockResolvedValue(undefined);

jest.mock('pg', () => {
  return {
    Pool: jest.fn().mockImplementation(() => ({
      query:  mockQuery,
      on:     mockPoolOn,
      end:    mockPoolEnd,
    })),
  };
});

// Now import the module under test (pool mock is already in place)
const {
  getUserById,
  getAllUsers,
  searchUsers,
  MAX_LIMIT,
  DEFAULT_LIMIT,
  DEFAULT_OFFSET,
} = require('./queries');

// ---------------------------------------------------------------------------
// Shared test fixtures
// ---------------------------------------------------------------------------

const FAKE_USER = {
  id:         1,
  name:       'Alice',
  email:      'alice@example.com',
  created_at: new Date('2024-01-01T00:00:00Z'),
  updated_at: new Date('2024-01-01T00:00:00Z'),
};

/** Builds a pg QueryResult-like object. */
function makeResult(rows = [], rowCount = rows.length) {
  return { rows, rowCount };
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

beforeEach(() => {
  jest.clearAllMocks();
  // Silence timing logs during tests unless a specific test needs them
  jest.spyOn(console, 'log').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  jest.restoreAllMocks();
});

// ===========================================================================
// getUserById
// ===========================================================================

describe('getUserById', () => {
  test('returns the user row when found', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([FAKE_USER], 1));

    const result = await getUserById(1);

    expect(result).toEqual(FAKE_USER);
  });

  test('returns null when no row matches', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    const result = await getUserById(999);

    expect(result).toBeNull();
  });

  test('sends id as a bind parameter ($1) — not interpolated', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([FAKE_USER], 1));

    await getUserById(42);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([42]);
    // The SQL must NOT contain the literal id value
    expect(sql).not.toContain('42');
    // The SQL must reference the placeholder
    expect(sql).toContain('$1');
  });

  test('SQL injection string is never placed in the query text', async () => {
    // Because parseInt in app.js will reject this, the query layer itself
    // should throw a TypeError before pool.query is called.
    await expect(getUserById("1; DROP TABLE users; --")).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects non-integer id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(TypeError);
    await expect(getUserById(1.5)).rejects.toThrow(TypeError);
    await expect(getUserById(-1)).rejects.toThrow(TypeError);
    await expect(getUserById(0)).rejects.toThrow(TypeError);
    await expect(getUserById(null)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('emits a structured timing log on success', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([FAKE_USER], 1));
    const logSpy = jest.spyOn(console, 'log');

    await getUserById(1);

    expect(logSpy).toHaveBeenCalledTimes(1);
    const logArg = JSON.parse(logSpy.mock.calls[0][0]);
    expect(logArg).toMatchObject({
      level:     'info',
      context:   'db:query',
      operation: 'getUserById',
      rowCount:  1,
    });
    expect(typeof logArg.elapsedMs).toBe('number');
    expect(logArg.elapsedMs).toBeGreaterThanOrEqual(0);
  });

  test('emits an error log and re-throws on db failure', async () => {
    const dbError = new Error('connection refused');
    mockQuery.mockRejectedValueOnce(dbError);
    const errSpy = jest.spyOn(console, 'error');

    await expect(getUserById(1)).rejects.toThrow('connection refused');

    expect(errSpy).toHaveBeenCalledTimes(1);
    const logArg = JSON.parse(errSpy.mock.calls[0][0]);
    expect(logArg).toMatchObject({
      level:     'error',
      context:   'db:query',
      operation: 'getUserById',
    });
  });
});

