    const logSpy = jest.spyOn(console, 'log');

    await getAllUsers(10, 0);

    const calls = logSpy.mock.calls.map(c => JSON.parse(c[0]));
    const ops   = calls.map(c => c.operation);
    expect(ops).toContain('getAllUsers:data');
    expect(ops).toContain('getAllUsers:count');
  });

  test('total is coerced to a number (pg returns COUNT as string)', async () => {
    mockQuery
      .mockResolvedValueOnce(makeResult([], 0))
      .mockResolvedValueOnce(makeResult([{ total: '42' }], 1));

    const result = await getAllUsers();

    expect(result.total).toBe(42);
    expect(typeof result.total).toBe('number');
  });

  test('rejects invalid limit', async () => {
    await expect(getAllUsers(-1, 0)).rejects.toThrow(TypeError);
    await expect(getAllUsers(1.5, 0)).rejects.toThrow(TypeError);
    await expect(getAllUsers('10', 0)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects invalid offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toThrow(TypeError);
    await expect(getAllUsers(10, '5')).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

