/**
 * queries.test.js – Unit tests for queries.js
 *
 * Uses Node's built-in `node:test` runner (available from Node 18+).
 * Runs without any npm packages — zero install required.
 *
 * Run:   node --test queries.test.js
 *
 * Every test verifies:
 *   • The correct SQL is sent (parameterised, no string interpolation)
 *   • The correct $n bind values are sent (SQL injection prevention)
 *   • Input validation rejects bad values before any SQL is executed
 *   • Query timing logs are emitted (console.log spy)
 *   • Pool errors are re-thrown so the caller can handle them
 */

'use strict';

const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');

// ---------------------------------------------------------------------------
// Fake environment – must be set before db.js / queries.js are required
// ---------------------------------------------------------------------------
process.env.DB_HOST     = 'localhost';
process.env.DB_PORT     = '5432';
process.env.DB_NAME     = 'testdb';
process.env.DB_USER     = 'testuser';
process.env.DB_PASSWORD = 'testpassword';
process.env.NODE_ENV    = 'test';

// ---------------------------------------------------------------------------
// Manual mock for the `pg` module
//
// Node's built-in test runner has no module-mock API, so we use
// Module._resolveFilename + a hand-rolled entry in the module cache.
// ---------------------------------------------------------------------------
const Module = require('module');
const path   = require('path');

// We store the mock objects in variables so individual tests can control them.
let mockQueryImpl;   // set per-test
const mockCalls = [];  // cleared per-test

const fakePool = {
  query: (...args) => {
    mockCalls.push(args);
    return mockQueryImpl(...args);
  },
  on:  () => {},
  end: () => Promise.resolve(),
};

// Intercept `require('pg')` at the module cache level.
const pgResolved = Module._resolveFilename('pg', module);
require.cache[pgResolved] = {
  id:       pgResolved,
  filename: pgResolved,
  loaded:   true,
  exports:  {
    Pool: class FakePool {
      constructor() { return fakePool; }
    },
  },
};

// Now load the module under test (pool mock already in cache)
const {
  getUserById,
  getAllUsers,
  searchUsers,
  MAX_LIMIT,
  DEFAULT_LIMIT,
  DEFAULT_OFFSET,
} = require('./queries');

// ---------------------------------------------------------------------------
// Console spy helpers
// ---------------------------------------------------------------------------
let logMessages  = [];
let errorMessages = [];
const origLog   = console.log.bind(console);
const origError = console.error.bind(console);

function startSpy() {
  logMessages   = [];
  errorMessages = [];
  console.log   = (...a) => logMessages.push(a.join(' '));
  console.error = (...a) => errorMessages.push(a.join(' '));
}
function stopSpy() {
  console.log   = origLog;
  console.error = origError;
}

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------
const FAKE_USER = {
  id:         1,
  name:       'Alice',
  email:      'alice@example.com',
  created_at: new Date('2024-01-01T00:00:00Z'),
  updated_at: new Date('2024-01-01T00:00:00Z'),
};

function makeResult(rows = [], rowCount = rows.length) {
  return { rows, rowCount };
}

// ---------------------------------------------------------------------------
// Reset state before each test
// ---------------------------------------------------------------------------
beforeEach(() => {
  mockCalls.length = 0;
  mockQueryImpl = undefined;
  startSpy();
});

afterEach(() => {
  stopSpy();
});

// ===========================================================================
// getUserById
// ===========================================================================

describe('getUserById', () => {
  it('returns the user row when found', async () => {
    mockQueryImpl = async () => makeResult([FAKE_USER], 1);
    const result = await getUserById(1);
    assert.deepEqual(result, FAKE_USER);
  });

  it('returns null when no row matches', async () => {
    mockQueryImpl = async () => makeResult([], 0);
    const result = await getUserById(999);
    assert.equal(result, null);
  });

  it('sends id as a bind parameter ($1) — not interpolated into SQL', async () => {
    mockQueryImpl = async () => makeResult([FAKE_USER], 1);
    await getUserById(42);

    assert.equal(mockCalls.length, 1);
    const [sql, params] = mockCalls[0];
    assert.deepEqual(params, [42]);
    assert.ok(!sql.includes('42'),  'id literal must not appear in SQL text');
    assert.ok(sql.includes('$1'),   'SQL must use the $1 placeholder');
  });

  it('rejects a SQL injection string — TypeError thrown before pool.query', async () => {
    await assert.rejects(
      () => getUserById("1; DROP TABLE users; --"),
      TypeError
    );
    assert.equal(mockCalls.length, 0);
  });

  it('rejects non-positive-integer ids', async () => {
    for (const bad of ['abc', 1.5, -1, 0, null, undefined]) {
      await assert.rejects(() => getUserById(bad), TypeError,
        `expected TypeError for id=${JSON.stringify(bad)}`);
    }
    assert.equal(mockCalls.length, 0);
  });

  it('emits a structured timing log on success', async () => {
    mockQueryImpl = async () => makeResult([FAKE_USER], 1);
    await getUserById(1);

    assert.equal(logMessages.length, 1);
    const log = JSON.parse(logMessages[0]);
    assert.equal(log.level,     'info');
    assert.equal(log.context,   'db:query');
    assert.equal(log.operation, 'getUserById');
    assert.equal(log.rowCount,  1);
    assert.equal(typeof log.elapsedMs, 'number');
    assert.ok(log.elapsedMs >= 0);
  });

  it('emits an error log and re-throws on db failure', async () => {
    mockQueryImpl = async () => { throw new Error('connection refused'); };
    await assert.rejects(() => getUserById(1), /connection refused/);
    assert.equal(errorMessages.length, 1);
    const log = JSON.parse(errorMessages[0]);
    assert.equal(log.level,   'error');
    assert.equal(log.context, 'db:query');
    assert.equal(log.operation, 'getUserById');
    assert.equal(log.error,   'connection refused');
  });

  it('error log does not include bind parameter values (PII guard)', async () => {
    mockQueryImpl = async () => { throw new Error('db error'); };
    await assert.rejects(() => getUserById(7));
    const serialised = errorMessages.join('');
    // The id value must not be in the error log
    assert.ok(!serialised.includes('"params"'), 'params key must not appear in error log');
  });
});

