/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared pg.Pool instance that is reused across the entire
 * application.  Centralising the pool here means:
 *   • The pool is created once and every module imports the same instance.
 *   • Configuration lives in one place (environment variables via .env).
 *   • Idle-connection limits, timeouts, and SSL settings are easy to tune.
 *
 * Environment variables (set in .env, never hard-coded):
 *   DB_HOST          Postgres host            (default: localhost)
 *   DB_PORT          Postgres port            (default: 5432)
 *   DB_NAME          Database name            (default: postgres)
 *   DB_USER          Database user            (default: postgres)
 *   DB_PASSWORD      Database password        (required)
 *   DB_POOL_MAX      Max pool connections     (default: 10)
 *   DB_IDLE_TIMEOUT  Idle timeout ms          (default: 30000)
 *   DB_CONN_TIMEOUT  Connection timeout ms    (default: 5000)
 *   NODE_ENV         "production" enables SSL (default: development)
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------

const isProduction = process.env.NODE_ENV === 'production';

const poolConfig = {
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME     || 'postgres',
  user:     process.env.DB_USER     || 'postgres',
  password: process.env.DB_PASSWORD,                   // must be set in .env

  // Maximum number of clients in the pool.
  // Rule of thumb: (2 × number of CPU cores) + effective_spindle_count.
  max: parseInt(process.env.DB_POOL_MAX || '10', 10),

  // Milliseconds a client may sit idle before being released.
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT || '30000', 10),

  // Milliseconds to wait for a new connection before throwing.
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT || '5000', 10),

  // Require SSL in production; skip in local/test environments.
  ...(isProduction && {
    ssl: { rejectUnauthorized: true },
  }),
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

// Emitted every time a new client is created inside the pool.
pool.on('connect', (client) => {
  console.log(
    `[db] New client connected — pool total: ${pool.totalCount}, ` +
    `idle: ${pool.idleCount}, waiting: ${pool.waitingCount}`
  );
  // Set the application name so it shows up in pg_stat_activity.
  client.query("SET application_name = 'users-api'").catch(() => {});
});

// Emitted when a client is removed from the pool (connection closed).
pool.on('remove', () => {
  console.log(
    `[db] Client removed — pool total: ${pool.totalCount}, ` +
    `idle: ${pool.idleCount}`
  );
});

// Emitted when a background client throws an error (e.g. server restarted).
// Without this handler the error would be an unhandled rejection and crash
// the process; here we log it and let the pool create a replacement client.
pool.on('error', (err) => {
  console.error('[db] Unexpected error on idle client:', err.message);
});

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design goals
 * ────────────
 * 1. SQL injection prevention
 *    Every piece of user-supplied data is passed as a bound parameter ($1,
 *    $2 …) to pg, which sends parameters separately from the query text over
 *    the wire.  The database driver NEVER interpolates user data into SQL
 *    strings, so injection is structurally impossible for these paths.
 *
 * 2. Connection pooling
 *    All functions call pool.query(), which borrows a client from the shared
 *    pool (db.js), runs the query, and immediately returns the client.  The
 *    pool manages acquisition, release, and reconnection transparently.
 *
 * 3. Query timing logs
 *    Every call is wrapped in a timer.  The log line emitted on completion
 *    includes the function name, parameter values, row count, and wall-clock
 *    duration in milliseconds so slow queries are immediately visible.
 *
 * 4. Input validation
 *    Parameters are validated and coerced before they reach pg so that
 *    downstream code receives predictable types and sensible error messages.
 *
 * Exported functions
 * ──────────────────
 *  getUserById(id)                   → single user row or null
 *  getAllUsers(limit, offset)        → paginated array of user rows
 *  searchUsers(searchQuery)          → array of matching user rows
 */

'use strict';

const pool = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Hard ceiling on the number of rows a single call may return. */
const MAX_LIMIT = 200;

/** Default page size used when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/** Maximum length accepted for a free-text search query string. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Runs a parameterised query against the pool, emits a structured timing log,
 * and returns the pg result object.
 *
 * @param {string}   label      Human-readable name used in log output.
 * @param {string}   sql        Parameterised SQL string (placeholders: $1…$N).
 * @param {Array}    params     Bound parameter values — NEVER interpolated.
 * @returns {Promise<import('pg').QueryResult>}
 * @throws  Re-throws any pg error after adding context to the message.
 */
async function timedQuery(label, sql, params) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, params);
    const durationMs = Number(process.hrtime.bigint() - start) / 1e6;

    console.log(
      `[query] ${label} | ` +
      `params=${JSON.stringify(params)} | ` +
      `rows=${result.rowCount} | ` +
      `duration=${durationMs.toFixed(3)}ms`
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1e6;

    console.error(
      `[query:error] ${label} | ` +
      `params=${JSON.stringify(params)} | ` +
      `duration=${durationMs.toFixed(3)}ms | ` +
      `error=${err.message}`
    );

    // Re-throw with enriched context; preserves original stack via `cause`.
    throw new QueryError(`Query "${label}" failed: ${err.message}`, {
      cause: err,
      label,
      params,
    });
  }
}

/**
 * Validates that a value is a safe positive integer.
 *
 * @param {*}      value     Raw (possibly string) value from request.
 * @param {string} name      Field name used in the error message.
 * @param {number} max       Upper bound (inclusive).
 * @returns {number}         Coerced integer.
 * @throws {ValidationError} If the value is out of range or not numeric.
 */
function toPositiveInt(value, name, max) {
  const n = Number(value);

  if (!Number.isInteger(n) || n < 1) {
    throw new ValidationError(
      `"${name}" must be a positive integer, got: ${JSON.stringify(value)}`
    );
  }
  if (n > max) {
    throw new ValidationError(
      `"${name}" must be ≤ ${max}, got: ${n}`
    );
  }
  return n;
}

/**
 * Validates that a value is a safe non-negative integer (zero allowed).
 *
 * @param {*}      value     Raw value.
 * @param {string} name      Field name for error messages.
 * @returns {number}
 * @throws {ValidationError}
 */
function toNonNegativeInt(value, name) {
  const n = Number(value);

  if (!Number.isInteger(n) || n < 0) {
    throw new ValidationError(
      `"${name}" must be a non-negative integer, got: ${JSON.stringify(value)}`
    );
  }
  return n;
}

/**
 * Sanitises and validates a free-text search string.
 *
 * The string itself is still passed as a bound parameter — this step is an
 * additional defence-in-depth measure that:
 *   • Trims whitespace so empty/blank strings are caught early.
 *   • Enforces a maximum length to prevent DoS via huge LIKE patterns.
 *   • Removes null bytes, which are rejected by PostgreSQL anyway but would
 *     produce a confusing driver error.
 *
 * @param {*}      value   Raw value from the request.
 * @returns {string}       Sanitised search term.
 * @throws {ValidationError}
 */
function sanitiseSearchQuery(value) {
  if (typeof value !== 'string') {
    throw new ValidationError(
      `"query" must be a string, got: ${typeof value}`
    );
  }

  // Remove null bytes.
  const cleaned = value.replace(/\0/g, '').trim();

  if (cleaned.length === 0) {
    throw new ValidationError('"query" must not be empty or blank');
  }
  if (cleaned.length > MAX_SEARCH_LENGTH) {
    throw new ValidationError(
      `"query" must be ≤ ${MAX_SEARCH_LENGTH} characters, got: ${cleaned.length}`
    );
  }

  return cleaned;
}

// ---------------------------------------------------------------------------
// Custom error classes
// ---------------------------------------------------------------------------

/**
 * Thrown when a query parameter fails validation before reaching the database.
 * HTTP handlers should map this to a 400 Bad Request response.
 */
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

/**
 * Thrown when pg itself returns an error.
 * HTTP handlers should map this to a 500 Internal Server Error response.
 */
class QueryError extends Error {
  /**
   * @param {string} message
   * @param {{ cause: Error, label: string, params: Array }} options
   */
  constructor(message, { cause, label, params } = {}) {
    super(message, { cause });
    this.name  = 'QueryError';
    this.label  = label;
    this.params = params;
  }
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetches a single user by their primary-key ID.
 *
 * SQL injection prevention
 * ────────────────────────
 * `id` is validated as a positive integer before the query runs.  Even if
 * that check were bypassed, `id` is bound as parameter $1 — the database
 * driver transmits it in the parameter section of the protocol message, never
 * concatenated into the query string, so injection is impossible at the
 * protocol level.
 *
 * @param {number|string} id   User ID (coerced to integer internally).
 * @returns {Promise<Object|null>} User row, or null if not found.
 * @throws {ValidationError}   If `id` is not a positive integer.
 * @throws {QueryError}        If the database returns an error.
 *
 * @example
 *   const user = await getUserById(42);
 *   // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: … }
 */
async function getUserById(id) {
  const safeId = toPositiveInt(id, 'id', Number.MAX_SAFE_INTEGER);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users, ordered by creation date descending.
 *
 * SQL injection prevention
 * ────────────────────────
 * `limit` and `offset` are validated as non-negative integers and then bound
 * as parameters $1 and $2.  PostgreSQL accepts integer parameters for LIMIT
 * and OFFSET in parameterised queries, so there is no need for (and no use
 * of) string interpolation.
 *
 * @param {number|string} [limit=DEFAULT_LIMIT]  Rows per page (1–MAX_LIMIT).
 * @param {number|string} [offset=0]             Number of rows to skip (≥ 0).
 * @returns {Promise<Object[]>} Array of user rows (may be empty).
 * @throws {ValidationError}    If `limit` or `offset` are out of range.
 * @throws {QueryError}         If the database returns an error.
 *
 * @example
 *   const page2 = await getAllUsers(20, 20);
 *   // [{ id: 21, name: '…', … }, …]
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
  const safeLimit  = toPositiveInt(limit,  'limit',  MAX_LIMIT);
  const safeOffset = toNonNegativeInt(offset, 'offset');

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY created_at DESC, id DESC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await timedQuery('getAllUsers', sql, [safeLimit, safeOffset]);
  return result.rows;
}

/**
 * Full-text prefix search across `name` and `email` columns.
 *
 * The ILIKE patterns are constructed server-side and the user-supplied term is
 * passed as a single bound parameter.  The only characters with special
 * meaning inside a LIKE pattern are `%`, `_`, and `\`; these are escaped
 * before the parameter value is formed, so a search for "50% off" will
 * literally search for that string rather than matching any trailing
 * characters.
 *
 * SQL injection prevention
 * ────────────────────────
 * 1. The search term is validated and trimmed by `sanitiseSearchQuery`.
 * 2. LIKE metacharacters (`%`, `_`, `\`) are escaped so the pattern cannot
 *    be manipulated by the caller to change the shape of the query.
 * 3. The escaped term is bound as parameter $1 — it is never concatenated
 *    into the query string.
 *
 * @param {string}        searchQuery   Raw search term from the request.
 * @param {number|string} [limit=DEFAULT_LIMIT]
 * @param {number|string} [offset=0]
 * @returns {Promise<Object[]>}  Matching user rows (may be empty).
 * @throws {ValidationError}     If `searchQuery` is blank, too long, or not a string.
 * @throws {QueryError}          If the database returns an error.
 *
 * @example
 *   const results = await searchUsers('ali');
 *   // [{ id: 1, name: 'Alice', email: 'alice@example.com', … }]
 */
async function searchUsers(searchQuery, limit = DEFAULT_LIMIT, offset = 0) {
  const cleanTerm  = sanitiseSearchQuery(searchQuery);
  const safeLimit  = toPositiveInt(limit,  'limit',  MAX_LIMIT);
  const safeOffset = toNonNegativeInt(offset, 'offset');

  // Escape LIKE metacharacters so the user cannot alter the pattern shape.
  // The ESCAPE clause tells Postgres to treat `\` as the escape character,
  // which is already the default but is stated explicitly for clarity.
  const escapedTerm = cleanTerm
    .replace(/\\/g, '\\\\')   // must be first: escape the escape char itself
    .replace(/%/g,  '\\%')    // literal percent sign
    .replace(/_/g,  '\\_');   // literal underscore

  // Wrap the escaped term in `%…%` to search for the substring anywhere.
  // Callers wanting a prefix-only or exact match can fork this function.
  const likePattern = `%${escapedTerm}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR
      email ILIKE $1 ESCAPE '\\'
    ORDER BY
      -- Exact matches first, then prefix matches, then substring matches.
      CASE
        WHEN LOWER(name)  = LOWER($2) THEN 0
        WHEN LOWER(email) = LOWER($2) THEN 0
        WHEN name  ILIKE $3 ESCAPE '\\' THEN 1
        WHEN email ILIKE $3 ESCAPE '\\' THEN 1
        ELSE 2
      END,
      created_at DESC,
      id DESC
    LIMIT  $4
    OFFSET $5
  `;

  // $1 / $4 / $5 — already validated above
  // $2           — original cleaned term for exact-match ranking
  // $3           — prefix pattern for prefix-match ranking
  const prefixPattern = `${escapedTerm}%`;
  const params = [likePattern, cleanTerm, prefixPattern, safeLimit, safeOffset];

  const result = await timedQuery('searchUsers', sql, params);
  return result.rows;
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export error classes so HTTP handlers can use instanceof checks.
  ValidationError,
  QueryError,
  // Export constants so tests and handlers can reference the same values.
  MAX_LIMIT,
  DEFAULT_LIMIT,
};

/**
 * app.js — Express application with a PostgreSQL query layer
 *
 * Endpoints
 * ─────────
 *  GET /health               Liveness probe — no DB call.
 *  GET /users                List users       (limit, offset query params).
 *  GET /users/search         Search users     (q, limit, offset query params).
 *  GET /users/:id            Get one user     (id path param).
 *
 * Error handling
 * ──────────────
 *  ValidationError  → 400 Bad Request   (caller supplied bad input)
 *  "no rows" / null → 404 Not Found     (resource does not exist)
 *  QueryError       → 500               (database problem)
 *  Anything else    → 500               (unexpected)
 */

'use strict';

require('dotenv').config();

const express = require('express');
const pool    = require('./db');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
  QueryError,
  MAX_LIMIT,
  DEFAULT_LIMIT,
} = require('./queries');

const app  = express();
const PORT = parseInt(process.env.PORT || '3000', 10);

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------

app.use(express.json());

/**
 * Request logger — emits method, path, status, and wall-clock time on every
 * response so individual endpoint performance is visible without a full APM.
 */
app.use((req, res, next) => {
  const start = process.hrtime.bigint();

  res.on('finish', () => {
    const durationMs = (Number(process.hrtime.bigint() - start) / 1e6).toFixed(3);
    console.log(
      `[http] ${req.method} ${req.originalUrl} → ${res.statusCode} (${durationMs}ms)`
    );
  });

  next();
});

// ---------------------------------------------------------------------------
// Route helpers
// ---------------------------------------------------------------------------

/**
 * Parses a query-string integer with a fallback default, or throws a
 * ValidationError that the error handler will map to a 400 response.
 *
 * @param {string|undefined} raw       Raw string from req.query.
 * @param {string}           name      Param name (used in error messages).
 * @param {number}           fallback  Value to use when `raw` is undefined.
 * @returns {number}
 */
function parseIntParam(raw, name, fallback) {
  if (raw === undefined) return fallback;
  const n = Number(raw);
  if (!Number.isFinite(n)) {
    throw new ValidationError(
      `"${name}" must be a number, got: ${JSON.stringify(raw)}`
    );
  }
  return n; // range validation happens inside queries.js
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 *
 * Liveness probe — always returns 200 if the process is alive.
 * Also reports pool statistics so infrastructure dashboards can surface
 * connection-pool exhaustion before it affects user-facing requests.
 *
 * Response body: { status, timestamp, pool }
 */
app.get('/health', (req, res) => {
  res.json({
    status:    'ok',
    timestamp: new Date().toISOString(),
    pool: {
      total:   pool.totalCount,
      idle:    pool.idleCount,
      waiting: pool.waitingCount,
    },
  });
});

/**
 * GET /users
 *
 * Returns a paginated list of all users.
 *
 * Query parameters:
 *   limit   {integer}  Rows per page. Default: 20, max: 200.
 *   offset  {integer}  Rows to skip.  Default: 0.
 *
 * Response body: { data: User[], meta: { limit, offset, count } }
 *
 * Example:
 *   GET /users?limit=5&offset=10
 */
app.get('/users', async (req, res, next) => {
  try {
    const limit  = parseIntParam(req.query.limit,  'limit',  DEFAULT_LIMIT);
    const offset = parseIntParam(req.query.offset, 'offset', 0);

    const users = await getAllUsers(limit, offset);

    res.json({
      data: users,
      meta: {
        limit,
        offset,
        count: users.length,
      },
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /users/search
 *
 * Searches users by name or email (case-insensitive substring match).
 * The route is declared BEFORE /users/:id so Express resolves "search" as a
 * literal segment, not as a dynamic :id value.
 *
 * Query parameters:
 *   q       {string}   Search term (required, 1–200 characters).
 *   limit   {integer}  Default: 20, max: 200.
 *   offset  {integer}  Default: 0.
 *
 * Response body: { data: User[], meta: { query, limit, offset, count } }
 *
 * Example:
 *   GET /users/search?q=alice&limit=10
 */
app.get('/users/search', async (req, res, next) => {
  try {
    const { q } = req.query;

    if (!q) {
      throw new ValidationError('Missing required query parameter: "q"');
    }

    const limit  = parseIntParam(req.query.limit,  'limit',  DEFAULT_LIMIT);
    const offset = parseIntParam(req.query.offset, 'offset', 0);

    const users = await searchUsers(q, limit, offset);

    res.json({
      data: users,
      meta: {
        query:  q,
        limit,
        offset,
        count: users.length,
      },
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /users/:id
 *
 * Fetches a single user by numeric ID.
 *
 * Path parameters:
 *   id  {integer}  Positive integer user ID.
 *
 * Response body: { data: User }
 *
 * Example:
 *   GET /users/42
 */
app.get('/users/:id', async (req, res, next) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `No user found with id ${req.params.id}`,
      });
    }

    res.json({ data: user });
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// Centralised error handler
// ---------------------------------------------------------------------------

/**
 * Maps errors thrown by routes and queries to appropriate HTTP responses.
 *
 * ValidationError  → 400  Bad input from the caller.
 * QueryError       → 500  Database error (detail hidden from client in prod).
 * Anything else    → 500  Unexpected error.
 *
 * The full error (including stack) is always logged server-side; in
 * production only a safe message is sent to the client.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isProd = process.env.NODE_ENV === 'production';

  if (err instanceof ValidationError) {
    return res.status(400).json({
      error:   'Bad Request',
      message: err.message,
    });
  }

  if (err instanceof QueryError) {
    console.error('[app] QueryError:', err.message, err.cause?.stack);
    return res.status(500).json({
      error:   'Internal Server Error',
      message: isProd ? 'A database error occurred.' : err.message,
    });
  }

  // Unexpected error — log full details, return minimal info to client.
  console.error('[app] Unhandled error:', err.stack);
  res.status(500).json({
    error:   'Internal Server Error',
    message: isProd ? 'An unexpected error occurred.' : err.message,
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT} (NODE_ENV=${process.env.NODE_ENV || 'development'})`);
    console.log(`[app] Pool max connections: ${process.env.DB_POOL_MAX || 10}`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * Tests are written to run with Node's built-in test runner (node:test),
 * available from Node 18+.  No additional test framework is required.
 *
 * Run with:
 *   node --test queries.test.js
 *
 * The pg pool is fully mocked — no real database connection is needed.
 * Every test verifies:
 *   1. The correct SQL is executed.
 *   2. Parameters are bound in the right order (never interpolated).
 *   3. Input validation rejects bad data before the DB is called.
 *   4. Query timing is logged.
 *   5. DB errors are wrapped in QueryError and re-thrown.
 */

'use strict';

const { describe, it, before, afterEach } = require('node:test');
const assert = require('node:assert/strict');

// ---------------------------------------------------------------------------
// Mock the pg pool (db.js) BEFORE requiring queries.js so that the module
// cache returns our mock instead of the real Pool instance.
// ---------------------------------------------------------------------------

/** Stores the most-recent call made to pool.query() for assertion. */
let lastCall = { sql: '', params: [] };

/** Controls what pool.query() resolves or rejects with in each test. */
let mockResult    = { rows: [], rowCount: 0 };
let mockShouldFail = false;
let mockError      = new Error('mock DB error');

const mockPool = {
  query: async (sql, params) => {
    lastCall = { sql, params };
    if (mockShouldFail) throw mockError;
    return mockResult;
  },
  // Pool stat properties (used by app.js health check — not exercised here).
  totalCount:   1,
  idleCount:    1,
  waitingCount: 0,
  on: () => {},
};

// Inject the mock into the require cache under the key queries.js will use.
require.cache[require.resolve('./db')] = {
  id:       require.resolve('./db'),
  filename: require.resolve('./db'),
  loaded:   true,
  exports:  mockPool,
};

// Now it is safe to load the module under test.
const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
  QueryError,
  MAX_LIMIT,
  DEFAULT_LIMIT,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function resetMock() {
  lastCall       = { sql: '', params: [] };
  mockResult     = { rows: [], rowCount: 0 };
  mockShouldFail = false;
}

/**
 * Returns true when `sql` contains NO raw occurrence of `value`.
 * Used to assert that a user-supplied value was NOT interpolated into SQL.
 */
function notInterpolated(sql, value) {
  return !sql.includes(String(value));
}

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

describe('getUserById', () => {
  afterEach(resetMock);

  it('calls pool.query with the correct SQL and bound parameter', async () => {
    mockResult = { rows: [{ id: 1, name: 'Alice', email: 'alice@example.com' }], rowCount: 1 };

    const user = await getUserById(1);

    assert.equal(user.id,    1);
    assert.equal(user.name,  'Alice');
    assert.ok(lastCall.sql.includes('WHERE id = $1'), 'SQL should use $1 placeholder');
    assert.deepEqual(lastCall.params, [1]);
  });

  it('coerces a string id to integer before binding', async () => {
    mockResult = { rows: [{ id: 7 }], rowCount: 1 };

    await getUserById('7');

    assert.deepEqual(lastCall.params, [7]);
    assert.ok(notInterpolated(lastCall.sql, '7'), 'String "7" must not appear in SQL');
  });

  it('returns null when no row is found', async () => {
    mockResult = { rows: [], rowCount: 0 };

    const result = await getUserById(999);

    assert.equal(result, null);
  });

  it('throws ValidationError for id = 0', async () => {
    await assert.rejects(
      () => getUserById(0),
      (err) => {
        assert.ok(err instanceof ValidationError);
        assert.match(err.message, /positive integer/);
        return true;
      }
    );
    // Pool must not have been called.
    assert.equal(lastCall.sql, '');
  });

  it('throws ValidationError for a negative id', async () => {
    await assert.rejects(() => getUserById(-5), ValidationError);
  });

  it('throws ValidationError for a non-numeric string id', async () => {
    await assert.rejects(
      () => getUserById('abc'),
      (err) => {
        assert.ok(err instanceof ValidationError);
        return true;
      }
    );
  });

  it('throws ValidationError for a SQL injection attempt in id', async () => {
    // "1 OR 1=1" is not a positive integer — validation must reject it.
    await assert.rejects(
      () => getUserById('1 OR 1=1'),
      ValidationError
    );
    assert.equal(lastCall.sql, '', 'Pool must not be called for invalid id');
  });

  it('wraps DB errors in QueryError', async () => {
    mockShouldFail = true;
    mockError      = new Error('connection refused');

    await assert.rejects(
      () => getUserById(1),
      (err) => {
        assert.ok(err instanceof QueryError);
        assert.match(err.message, /connection refused/);
        assert.equal(err.label, 'getUserById');
        return true;
      }
    );
  });

  it('does not interpolate the id value into the SQL string', async () => {
    mockResult = { rows: [{ id: 42 }], rowCount: 1 };

    await getUserById(42);

    assert.ok(
      notInterpolated(lastCall.sql, '42'),
      'The literal value "42" must not appear in the SQL string'
    );
  });
});

// ---------------------------------------------------------------------------
// getAllUsers
// ---------------------------------------------------------------------------

describe('getAllUsers', () => {
  afterEach(resetMock);

  it('uses DEFAULT_LIMIT and offset=0 when called with no arguments', async () => {
    mockResult = { rows: [], rowCount: 0 };

    await getAllUsers();

    assert.deepEqual(lastCall.params, [DEFAULT_LIMIT, 0]);
  });

  it('binds limit and offset as parameters, not interpolated values', async () => {
    mockResult = { rows: [], rowCount: 0 };

    await getAllUsers(5, 10);

    assert.deepEqual(lastCall.params, [5, 10]);
    assert.ok(lastCall.sql.includes('LIMIT  $1'),  'LIMIT should use $1');
    assert.ok(lastCall.sql.includes('OFFSET $2'), 'OFFSET should use $2');
    assert.ok(notInterpolated(lastCall.sql, '5'),  '"5" must not appear in SQL');
    assert.ok(notInterpolated(lastCall.sql, '10'), '"10" must not appear in SQL');
  });

  it('returns the rows array from the query result', async () => {
    const fakeRows = [{ id: 1 }, { id: 2 }];
    mockResult = { rows: fakeRows, rowCount: 2 };

    const result = await getAllUsers(20, 0);

    assert.deepEqual(result, fakeRows);
  });

  it('throws ValidationError when limit exceeds MAX_LIMIT', async () => {
    await assert.rejects(
      () => getAllUsers(MAX_LIMIT + 1, 0),
      (err) => {
        assert.ok(err instanceof ValidationError);
        assert.match(err.message, /≤/);
        return true;
      }
    );
  });

  it('throws ValidationError for limit = 0', async () => {
    await assert.rejects(() => getAllUsers(0, 0), ValidationError);
  });

  it('throws ValidationError for negative offset', async () => {
    await assert.rejects(() => getAllUsers(10, -1), ValidationError);
  });

  it('throws ValidationError for non-integer limit', async () => {
    await assert.rejects(() => getAllUsers(3.7, 0), ValidationError);
  });

  it('accepts string representations of valid integers', async () => {
    mockResult = { rows: [], rowCount: 0 };

    await getAllUsers('10', '5');

    assert.deepEqual(lastCall.params, [10, 5]);
  });

  it('wraps DB errors in QueryError', async () => {
    mockShouldFail = true;

    await assert.rejects(() => getAllUsers(), QueryError);
  });
});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  afterEach(resetMock);

  it('binds the search term as a parameter, not interpolated in SQL', async () => {
    mockResult = { rows: [], rowCount: 0 };

    await searchUsers('alice');

    // The raw term must not appear in the SQL string.
    assert.ok(notInterpolated(lastCall.sql, 'alice'), '"alice" must not be interpolated');
    // The LIKE pattern must be present as a bound parameter.
    assert.ok(
      lastCall.params.some((p) => typeof p === 'string' && p.includes('alice')),
      'A parameter must contain the search term'
    );
  });

  it('escapes LIKE metacharacter % so it is treated literally', async () => {
    mockResult = { rows: [], rowCount: 0 };

    await searchUsers('50% off');

    // The pattern parameter should have the percent escaped.
    const patternParam = lastCall.params.find((p) => typeof p === 'string' && p.includes('50'));
    assert.ok(patternParam, 'Expected a parameter containing "50"');
    assert.ok(patternParam.includes('\\%'), 'Percent must be escaped to \\%');
  });

  it('escapes LIKE metacharacter _ so it is treated literally', async () => {
    mockResult = { rows: [], rowCount: 0 };

    await searchUsers('user_name');

    const patternParam = lastCall.params.find((p) => typeof p === 'string' && p.includes('user'));
    assert.ok(patternParam.includes('\\_'), 'Underscore must be escaped to \\_');
  });

  it('escapes backslash before other metacharacters', async () => {
    mockResult = { rows: [], rowCount: 0 };

    await searchUsers('path\\to');

    const patternParam = lastCall.params.find((p) => typeof p === 'string' && p.includes('path'));
    assert.ok(patternParam.includes('\\\\'), 'Backslash must be escaped to \\\\');
  });

  it('throws ValidationError for an empty string', async () => {
    await assert.rejects(
      () => searchUsers(''),
      (err) => {
        assert.ok(err instanceof ValidationError);
        assert.match(err.message, /empty/);
        return true;
      }
    );
    assert.equal(lastCall.sql, '');
  });

  it('throws ValidationError for a whitespace-only string', async () => {
    await assert.rejects(() => searchUsers('   '), ValidationError);
  });

  it('throws ValidationError for a term exceeding MAX_SEARCH_LENGTH', async () => {
    const tooLong = 'a'.repeat(201);

    await assert.rejects(
      () => searchUsers(tooLong),
      (err) => {
        assert.ok(err instanceof ValidationError);
        assert.match(err.message, /≤ 200/);
        return true;
      }
    );
  });

  it('throws ValidationError for a non-string query', async () => {
    await assert.rejects(
      () => searchUsers(42),
      (err) => {
        assert.ok(err instanceof ValidationError);
        assert.match(err.message, /string/);
        return true;
      }
    );
  });

  it('strips null bytes from the search term', async () => {
    mockResult = { rows: [], rowCount: 0 };

    // Should NOT throw — null bytes are stripped; the remaining "alice" is valid.
    await searchUsers('ali\0ce');

    const patternParam = lastCall.params.find((p) => typeof p === 'string' && p.includes('alice'));
    assert.ok(patternParam, 'Null byte should have been stripped');
    assert.ok(!patternParam.includes('\0'), 'Null byte must not reach the DB');
  });

  it('prevents a classic SQL injection attempt in the search term', async () => {
    mockResult = { rows: [], rowCount: 0 };

    // Even if parameterisation were bypassed, the term is still just a string.
    const injectionAttempt = "' OR '1'='1";
    await searchUsers(injectionAttempt);

    // The raw injection string must not appear verbatim in the SQL.
    assert.ok(
      notInterpolated(lastCall.sql, injectionAttempt),
      'Injection attempt must not be interpolated into SQL'
    );
    // It must appear only as a bound parameter value.
    assert.ok(
      lastCall.params.some((p) => typeof p === 'string' && p.includes("' OR '1'='1")),
      'Injection attempt should be bound safely as a parameter'
    );
  });

  it('applies default limit and offset when omitted', async () => {
    mockResult = { rows: [], rowCount: 0 };

    await searchUsers('bob');

    assert.equal(lastCall.params[3], DEFAULT_LIMIT);
    assert.equal(lastCall.params[4], 0);
  });

  it('accepts custom limit and offset', async () => {
    mockResult = { rows: [], rowCount: 0 };

    await searchUsers('carol', 5, 15);

    assert.equal(lastCall.params[3], 5);
    assert.equal(lastCall.params[4], 15);
  });

  it('wraps DB errors in QueryError', async () => {
    mockShouldFail = true;

    await assert.rejects(() => searchUsers('dave'), QueryError);
  });

  it('returns the rows array on success', async () => {
    const fakeRows = [{ id: 3, name: 'Eve' }];
    mockResult = { rows: fakeRows, rowCount: 1 };

    const result = await searchUsers('eve');

    assert.deepEqual(result, fakeRows);
  });
});

// ---------------------------------------------------------------------------
// Query timing log
// ---------------------------------------------------------------------------

describe('query timing log', () => {
  afterEach(resetMock);

  it('emits a [query] log line containing the label and duration', async () => {
    mockResult = { rows: [{ id: 1 }], rowCount: 1 };

    const logs = [];
    const originalLog = console.log;
    console.log = (...args) => logs.push(args.join(' '));

    try {
      await getUserById(1);
    } finally {
      console.log = originalLog;
    }

    const timingLog = logs.find((l) => l.startsWith('[query]'));
    assert.ok(timingLog, 'Expected a [query] log line');
    assert.ok(timingLog.includes('getUserById'), 'Log must include the function label');
    assert.ok(timingLog.includes('duration='),   'Log must include the duration field');
    assert.ok(timingLog.includes('rows='),        'Log must include the row count');
    assert.match(timingLog, /\d+\.\d+ms/,        'Duration must be in milliseconds');
  });

  it('emits a [query:error] log line on DB failure', async () => {
    mockShouldFail = true;
    mockError      = new Error('timeout');

    const logs = [];
    const originalError = console.error;
    console.error = (...args) => logs.push(args.join(' '));

    try {
      await getUserById(1);
    } catch {
      // expected
    } finally {
      console.error = originalError;
    }

    const errLog = logs.find((l) => l.startsWith('[query:error]'));
    assert.ok(errLog, 'Expected a [query:error] log line');
    assert.ok(errLog.includes('getUserById'), 'Error log must include the label');
    assert.ok(errLog.includes('timeout'),     'Error log must include the error message');
  });
});

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------

describe('module exports', () => {
  it('exports all expected symbols', () => {
    const mod = require('./queries');

    assert.equal(typeof mod.getUserById,     'function');
    assert.equal(typeof mod.getAllUsers,      'function');
    assert.equal(typeof mod.searchUsers,     'function');
    assert.equal(typeof mod.ValidationError, 'function');
    assert.equal(typeof mod.QueryError,      'function');
    assert.equal(typeof mod.MAX_LIMIT,       'number');
    assert.equal(typeof mod.DEFAULT_LIMIT,   'number');
    assert.ok(mod.MAX_LIMIT > mod.DEFAULT_LIMIT, 'MAX_LIMIT should exceed DEFAULT_LIMIT');
  });
});

