  return cleaned;
}

// ---------------------------------------------------------------------------
// Custom error classes
// ---------------------------------------------------------------------------

/**
 * Thrown when a query parameter fails validation before reaching the database.
 * HTTP handlers should map this to a 400 Bad Request response.
 */
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

/**
 * Thrown when pg itself returns an error.
 * HTTP handlers should map this to a 500 Internal Server Error response.
 */
class QueryError extends Error {
  /**
   * @param {string} message
   * @param {{ cause: Error, label: string, params: Array }} options
   */
  constructor(message, { cause, label, params } = {}) {
    super(message, { cause });
    this.name  = 'QueryError';
    this.label  = label;
    this.params = params;
