/**
 * db.js — PostgreSQL connection-pool factory
 *
 * Wraps the `pg` Pool so the rest of the app only ever imports this module.
 * If the real `pg` driver is not installed (unit-test environments, CI without
 * a Postgres service) the module falls back to an in-process mock pool that
 * satisfies the same interface.  Set  USE_DB_MOCK=true  (or omit `pg`) to
 * activate the mock explicitly.
 *
 * Pool configuration is read exclusively from environment variables so that no
 * credentials are hard-coded anywhere in the source tree.
 *
 * Required env vars (real pool):
 *   DATABASE_URL           – full connection string  OR  set the five below
 *   PGHOST / PGPORT / PGDATABASE / PGUSER / PGPASSWORD
 *
 * Optional tuning env vars:
 *   DB_POOL_MAX            – maximum pool size          (default: 10)
 *   DB_POOL_IDLE_TIMEOUT   – ms before an idle client is closed (default: 30000)
 *   DB_POOL_CONN_TIMEOUT   – ms to wait for a free slot (default: 5000)
 *   DB_STATEMENT_TIMEOUT   – ms max for a single query  (default: 10000)
 *   DB_SSL                 – "true" to enforce SSL/TLS  (default: false)
 */

'use strict';

// ---------------------------------------------------------------------------
// Environment helpers — never interpolate values into SQL; this module only
// reads DB *connection* config (host, port, pool sizes, timeouts).
// ---------------------------------------------------------------------------
function envInt(name, fallback) {
  const v = process.env[name];
  if (v === undefined || v === '') return fallback;
  const n = parseInt(v, 10);
  if (Number.isNaN(n)) {
    throw new Error(`[db] Environment variable ${name} must be an integer, got: "${v}"`);
  }
  return n;
}

function envBool(name, fallback) {
  const v = process.env[name];
  if (v === undefined || v === '') return fallback;
  return v.toLowerCase() === 'true' || v === '1';
}

// ---------------------------------------------------------------------------
// Build pool configuration from env vars only (no hard-coded credentials)
// ---------------------------------------------------------------------------
function buildPoolConfig() {
  const cfg = {
    // pg picks up PG* env vars automatically; DATABASE_URL overrides them all
    connectionString: process.env.DATABASE_URL || undefined,
    max:              envInt('DB_POOL_MAX',          10),
    idleTimeoutMillis:envInt('DB_POOL_IDLE_TIMEOUT', 30_000),
    connectionTimeoutMillis: envInt('DB_POOL_CONN_TIMEOUT', 5_000),
    // Per-session statement timeout sent via SET after every new connection
    options: `--statement_timeout=${envInt('DB_STATEMENT_TIMEOUT', 10_000)}`,
  };

  if (envBool('DB_SSL', false)) {
    cfg.ssl = { rejectUnauthorized: true };
  }

  // If individual PG* vars are set without DATABASE_URL, pass them explicitly
  // so there is no ambiguity about which config wins.
  if (!cfg.connectionString) {
    if (process.env.PGHOST)     cfg.host     = process.env.PGHOST;
    if (process.env.PGPORT)     cfg.port     = parseInt(process.env.PGPORT, 10);
    if (process.env.PGDATABASE) cfg.database = process.env.PGDATABASE;
    if (process.env.PGUSER)     cfg.user     = process.env.PGUSER;
    if (process.env.PGPASSWORD) cfg.password = process.env.PGPASSWORD;
  }

  return cfg;
}

// ---------------------------------------------------------------------------
// Attempt to load the real `pg` driver
// ---------------------------------------------------------------------------
let Pool;
let usingMock = false;

const forceMock = envBool('USE_DB_MOCK', false);

if (!forceMock) {
  try {
    ({ Pool } = require('pg'));
  } catch (_) {
    usingMock = true;
  }
} else {
  usingMock = true;
}

if (usingMock) {
  ({ Pool } = require('./pool-mock'));
  console.warn('[db] ⚠  Using in-process mock pool (pg driver unavailable or USE_DB_MOCK=true). Do NOT use in production.');
}

// ---------------------------------------------------------------------------
// Create the singleton pool
// ---------------------------------------------------------------------------
const pool = new Pool(usingMock ? {} : buildPoolConfig());

// Bubble unhandled pool errors to the process so they are never silently lost
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client', {
    message: err.message,
    code:    err.code,
  });
  // Do NOT crash the process — the pool will remove the broken client
});

// Instrument every new connection
pool.on('connect', () => {
  console.info('[db] New client connected to pool');
});

pool.on('acquire', () => {
  console.info('[db] Client acquired from pool');
});

pool.on('remove', () => {
  console.info('[db] Client removed from pool');
});

// ---------------------------------------------------------------------------
// Public interface
// ---------------------------------------------------------------------------

/**
 * Execute a parameterised query via the pool.
 *
 * @param {string}   text   – SQL string with $1, $2 … placeholders
 * @param {any[]}    params – Positional parameter values (never interpolated)
 * @returns {Promise<import('pg').QueryResult>}
 */
async function query(text, params = []) {
  const client = await pool.connect();
  const start  = process.hrtime.bigint();

  try {
    const result = await client.query(text, params);
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.info('[db] Query executed', {
      query:    redactQuery(text),
      params:   sanitiseParams(params),
      rows:     result.rowCount,
      durationMs: elapsedMs.toFixed(3),
    });

    return result;
  } catch (err) {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.error('[db] Query failed', {
      query:    redactQuery(text),
      error:    err.message,
      code:     err.code,
      durationMs: elapsedMs.toFixed(3),
    });
    throw err;
  } finally {
    client.release();
  }
}

/**
 * Execute multiple queries inside a single transaction.
 * Rolls back automatically if any query throws.
 *
 * @param {(q: typeof query) => Promise<any>} fn
 */
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const boundQuery = (text, params) => client.query(text, params);
    const result = await fn(boundQuery);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

/** Gracefully drain the pool (call on process exit). */
async function closePool() {
  await pool.end();
  console.info('[db] Pool closed');
}

// ---------------------------------------------------------------------------
// Internal helpers — nothing here touches user-supplied values
// ---------------------------------------------------------------------------

/**
 * Strip newlines / excess whitespace from a query string for compact logging.
 * Never logs parameter values here (see sanitiseParams).
 */
function redactQuery(sql) {
  return sql.replace(/\s+/g, ' ').trim();
}

/**
 * Replace every param value with its type tag in logs so that PII / secrets
 * in bound parameters are never written to log output.
 *
 * e.g. ['alice', 42, true]  →  ['<string>', '<number>', '<boolean>']
 */
function sanitiseParams(params) {
  if (!Array.isArray(params)) return [];
  return params.map(p => {
    if (p === null)           return '<null>';
    if (p === undefined)      return '<undefined>';
    if (typeof p === 'string') return `<string(${p.length})>`;
    return `<${typeof p}>`;
  });
}

module.exports = { query, withTransaction, closePool, pool };

/**
 * pool-mock.js — In-process pg.Pool mock
 *
 * Mirrors the pg.Pool / pg.Client API surface used by db.js and queries.js so
 * that unit tests and offline development work without a real PostgreSQL server.
 *
 * Features
 * ─────────
 * • EventEmitter events: 'connect', 'acquire', 'remove', 'error'
 * • pool.connect() → client  (with client.query / client.release)
 * • pool.end()               (graceful shutdown)
 * • Seeded in-memory user dataset (mirrors the /users schema)
 * • Full parameterised-query parsing so $1 / $2 placeholders work correctly
 * • Intentional artificial latency to exercise query-timing logs
 *
 * This file must never be loaded in production (db.js guards this).
 */

'use strict';

const { EventEmitter } = require('events');

// ---------------------------------------------------------------------------
// Seed data — mirrors what the real DB schema would contain
// ---------------------------------------------------------------------------
const SEED_USERS = [
  { id: 1, name: 'Alice Nguyen',    email: 'alice@example.com',   created_at: new Date('2024-01-10'), active: true  },
  { id: 2, name: 'Bob Okafor',      email: 'bob@example.com',     created_at: new Date('2024-02-14'), active: true  },
  { id: 3, name: 'Carol Santos',    email: 'carol@example.com',   created_at: new Date('2024-03-05'), active: false },
  { id: 4, name: 'David Kim',       email: 'david@example.com',   created_at: new Date('2024-04-22'), active: true  },
  { id: 5, name: 'Eve Johansson',   email: 'eve@example.com',     created_at: new Date('2024-05-18'), active: true  },
  { id: 6, name: 'Frank Müller',    email: 'frank@example.com',   created_at: new Date('2024-06-01'), active: false },
  { id: 7, name: 'Grace Patel',     email: 'grace@example.com',   created_at: new Date('2024-06-15'), active: true  },
  { id: 8, name: 'Hiro Tanaka',     email: 'hiro@example.com',    created_at: new Date('2024-07-04'), active: true  },
  { id: 9, name: 'Iris Levesque',   email: 'iris@example.com',    created_at: new Date('2024-08-09'), active: true  },
  { id: 10, name: 'Jack Adeyemi',   email: 'jack@example.com',    created_at: new Date('2024-09-11'), active: false },
];

// ---------------------------------------------------------------------------
// Parameterised-query interpreter
// Supports: SELECT … WHERE id = $1, LIMIT $2, OFFSET $3, ILIKE $4
// ---------------------------------------------------------------------------

/**
 * Minimal SQL interpreter sufficient for the queries in queries.js.
 * Operates on the in-memory SEED_USERS array.
 *
 * Supported patterns (case-insensitive SQL keywords):
 *   SELECT … FROM users WHERE id = $n
 *   SELECT … FROM users WHERE (name ILIKE $n OR email ILIKE $n) [LIMIT $m OFFSET $o]
 *   SELECT … FROM users [ORDER BY id ASC] [LIMIT $m] [OFFSET $o]
 *   SELECT COUNT(*) FROM users [WHERE …]
 */
function executeMockQuery(text, params = []) {
  const sql = text.replace(/\s+/g, ' ').trim().toUpperCase();

  // -- COUNT(*) variants --
  if (sql.startsWith('SELECT COUNT(*)')) {
    if (sql.includes('WHERE ID =')) {
      const id = Number(resolveParam(text, params, extractParamIndex(text, /WHERE\s+id\s*=\s*\$(\d+)/i)));
      const found = SEED_USERS.filter(u => u.id === id);
      return makeResult([{ count: String(found.length) }]);
    }
    if (sql.includes('ILIKE')) {
      const termIdx = extractParamIndex(text, /name\s+ILIKE\s+\$(\d+)/i);
      const term    = resolveParam(text, params, termIdx);
      const pattern = term.replace(/%/g, '');
      const rows    = SEED_USERS.filter(u =>
        u.name.toLowerCase().includes(pattern.toLowerCase()) ||
        u.email.toLowerCase().includes(pattern.toLowerCase())
      );
      return makeResult([{ count: String(rows.length) }]);
    }
    return makeResult([{ count: String(SEED_USERS.length) }]);
  }

  // -- SELECT by ID --
  if (/WHERE\s+id\s*=\s*\$\d+/i.test(text)) {
    const idx = extractParamIndex(text, /WHERE\s+id\s*=\s*\$(\d+)/i);
    const id  = Number(resolveParam(text, params, idx));
    const rows = SEED_USERS.filter(u => u.id === id);
    return makeResult(rows);
  }

  // -- SEARCH (ILIKE) --
  if (/ILIKE/i.test(text)) {
    const termIdx = extractParamIndex(text, /name\s+ILIKE\s+\$(\d+)/i);
    const term    = resolveParam(text, params, termIdx);
    const pattern = term.replace(/%/g, '');

    let rows = SEED_USERS.filter(u =>
      u.name.toLowerCase().includes(pattern.toLowerCase()) ||
      u.email.toLowerCase().includes(pattern.toLowerCase())
    );
    rows = applyLimitOffset(text, params, rows);
    return makeResult(rows);
  }

  // -- SELECT all (with optional LIMIT / OFFSET) --
  if (/SELECT\s+.+FROM\s+users/i.test(text)) {
    let rows = [...SEED_USERS];
    rows = applyLimitOffset(text, params, rows);
    return makeResult(rows);
  }

  throw new Error(`[pool-mock] Unsupported query pattern: ${text}`);
}

function extractParamIndex(text, regex) {
  const m = text.match(regex);
  if (!m) throw new Error(`[pool-mock] Could not extract param index from: ${text}`);
  return parseInt(m[1], 10);
}

function resolveParam(text, params, oneBasedIndex) {
  const val = params[oneBasedIndex - 1];
  if (val === undefined) {
    throw new Error(`[pool-mock] Missing parameter $${oneBasedIndex} in: ${text}`);
  }
  return val;
}

function applyLimitOffset(text, params, rows) {
  const limitMatch  = text.match(/LIMIT\s+\$(\d+)/i);
  const offsetMatch = text.match(/OFFSET\s+\$(\d+)/i);
  let result = rows;

  if (offsetMatch) {
    const offset = parseInt(resolveParam(text, params, parseInt(offsetMatch[1], 10)), 10);
    result = result.slice(offset);
  }
  if (limitMatch) {
    const limit = parseInt(resolveParam(text, params, parseInt(limitMatch[1], 10)), 10);
    result = result.slice(0, limit);
  }
  return result;
}

function makeResult(rows) {
  return { rows, rowCount: rows.length, command: 'SELECT', fields: [] };
}

// ---------------------------------------------------------------------------
// Mock Client
// ---------------------------------------------------------------------------
class MockClient {
  constructor(pool) {
    this._pool    = pool;
    this.released = false;
  }

  async query(text, params = []) {
    // Simulate realistic async DB latency (2–12 ms)
    const jitter = 2 + Math.floor(Math.random() * 10);
    await new Promise(r => setTimeout(r, jitter));
    return executeMockQuery(text, params);
  }

  release(err) {
    if (!this.released) {
      this.released = true;
      this._pool._available++;
      this._pool.emit('remove');
    }
  }
}

// ---------------------------------------------------------------------------
// Mock Pool  (mirrors pg.Pool API)
// ---------------------------------------------------------------------------
class Pool extends EventEmitter {
  constructor(_config = {}) {
    super();
    this._available = 10;   // simulate max:10
    this._ended     = false;
  }

  async connect() {
    if (this._ended) throw new Error('[pool-mock] Pool has ended');
    if (this._available <= 0) throw new Error('[pool-mock] No available connections');

    this._available--;
    this.emit('connect');
    this.emit('acquire');

    return new MockClient(this);
  }

  /** Execute a query directly on the pool (convenience passthrough). */
  async query(text, params = []) {
    const client = await this.connect();
    try {
      return await client.query(text, params);
    } finally {
      client.release();
    }
  }

  async end() {
    this._ended = true;
  }
}

module.exports = { Pool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * All SQL is written with positional placeholders ($1, $2 …).  The pg driver
 * sends values out-of-band from the query string so they are NEVER interpolated
 * into SQL text — this is the standard, driver-level defence against SQL
 * injection.  No manual escaping or sanitisation is required (or performed)
 * for the bound parameters themselves.
 *
 * Input *validation* (type checks, range checks, allow-lists) is layered on
 * top to reject obviously bad values early and return clear error messages to
 * callers before a query is even constructed.
 *
 * Exported functions
 * ──────────────────
 *   getUserById(id)                    – fetch one user by primary key
 *   getAllUsers(limit, offset)          – paginated full-table scan
 *   searchUsers(searchTerm, limit, offset) – name/email partial-match search
 *
 * Each function returns a plain object:
 *   { rows: User[], total: number, durationMs: number }
 *
 * On validation failure a ValidationError is thrown (HTTP 400).
 * On DB failure the raw pg error is re-thrown (HTTP 500 in the route handler).
 */

'use strict';

const { query } = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Hard ceiling on the rows a single page may request. */
const MAX_LIMIT = 100;

/** Minimum legal value for pagination offset. */
const MIN_OFFSET = 0;

/** Minimum search-term length (after trimming). */
const MIN_SEARCH_LENGTH = 1;

/** Maximum search-term length — prevents enormous LIKE patterns. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Custom error class
// ---------------------------------------------------------------------------

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

// ---------------------------------------------------------------------------
// Input validators
// Pure functions — they throw ValidationError or return the coerced value.
// ---------------------------------------------------------------------------

/**
 * Validate and coerce a user ID.
 * Accepts a numeric string or an integer.
 * Rejects anything that is not a safe positive integer.
 */
function validateId(raw) {
  if (raw === undefined || raw === null || raw === '') {
    throw new ValidationError('User ID is required.');
  }

  const id = Number(raw);

  if (!Number.isInteger(id)) {
    throw new ValidationError(`User ID must be an integer, received: "${raw}"`);
  }

  if (id < 1) {
    throw new ValidationError(`User ID must be a positive integer, received: ${id}`);
  }

  // Guard against values that exceed PostgreSQL's integer range
  if (id > 2_147_483_647) {
    throw new ValidationError(`User ID exceeds maximum allowed value (2147483647).`);
  }

  return id;
}

/**
 * Validate and coerce a pagination limit.
 * Clamps to [1, MAX_LIMIT].
 */
function validateLimit(raw, defaultValue = 20) {
  if (raw === undefined || raw === null || raw === '') return defaultValue;

  const n = Number(raw);

  if (!Number.isInteger(n)) {
    throw new ValidationError(`"limit" must be an integer, received: "${raw}"`);
  }

  if (n < 1) {
    throw new ValidationError(`"limit" must be at least 1, received: ${n}`);
  }

  if (n > MAX_LIMIT) {
    throw new ValidationError(
      `"limit" must not exceed ${MAX_LIMIT}, received: ${n}. ` +
      `Use "offset" for pagination.`
    );
  }

  return n;
}

/**
 * Validate and coerce a pagination offset.
 */
function validateOffset(raw, defaultValue = 0) {
  if (raw === undefined || raw === null || raw === '') return defaultValue;

  const n = Number(raw);

  if (!Number.isInteger(n)) {
    throw new ValidationError(`"offset" must be an integer, received: "${raw}"`);
  }

  if (n < MIN_OFFSET) {
    throw new ValidationError(`"offset" must be ≥ 0, received: ${n}`);
  }

  return n;
}

/**
 * Validate a free-text search term.
 *
 * • Strips leading/trailing whitespace.
 * • Enforces length bounds.
 * • Does NOT remove or escape special characters — that is the driver's job
 *   via parameterisation.  We wrap the term in % … % wildcards here purely
 *   for the ILIKE semantics; the value is still bound as a parameter.
 */
function validateSearchTerm(raw) {
  if (raw === undefined || raw === null) {
    throw new ValidationError('"query" search term is required.');
  }

  const term = String(raw).trim();

  if (term.length < MIN_SEARCH_LENGTH) {
    throw new ValidationError(
      `Search term must be at least ${MIN_SEARCH_LENGTH} character(s).`
    );
  }

  if (term.length > MAX_SEARCH_LENGTH) {
    throw new ValidationError(
      `Search term must not exceed ${MAX_SEARCH_LENGTH} characters.`
    );
  }

  // Return the term wrapped in SQL wildcards.
  // The wildcard characters % and _ that the *user* may type inside `term`
  // are harmless: they only affect which rows ILIKE matches — they cannot
  // break out of the parameter binding.  If you want literal matching of
  // those characters, escape them here (e.g. term.replace(/%/g, '\\%')).
  return `%${term}%`;
}

// ---------------------------------------------------------------------------
// SQL column allow-list (used for ORDER BY to prevent injection)
// ---------------------------------------------------------------------------

const ALLOWED_SORT_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);
const ALLOWED_SORT_DIRS    = new Set(['ASC', 'DESC']);

/**
 * Return a safe ORDER BY clause by checking against an allow-list.
 * ORDER BY is not parameterisable in PostgreSQL, so we guard it with an
 * explicit allow-list — the only safe alternative to parameterisation.
 */
function buildOrderBy(column = 'id', direction = 'ASC') {
  const col = String(column).toLowerCase();
  const dir = String(direction).toUpperCase();

  if (!ALLOWED_SORT_COLUMNS.has(col)) {
    throw new ValidationError(
      `Invalid sort column "${column}". ` +
      `Allowed: ${[...ALLOWED_SORT_COLUMNS].join(', ')}.`
    );
  }

  if (!ALLOWED_SORT_DIRS.has(dir)) {
    throw new ValidationError(
      `Invalid sort direction "${direction}". Allowed: ASC, DESC.`
    );
  }

  // Safe to interpolate: both values came from our allow-lists, not user input
  return `${col} ${dir}`;
}

// ---------------------------------------------------------------------------
// Query helpers — thin timing wrappers around db.query
// ---------------------------------------------------------------------------

/**
 * Thin wrapper that records wall-clock timing for the parameterised query
 * call itself (separate from the per-client timing logged inside db.js).
 * This gives the route handler a durationMs figure to include in responses.
 */
async function timedQuery(sql, params) {
  const t0     = process.hrtime.bigint();
  const result = await query(sql, params);
  const ms     = Number(process.hrtime.bigint() - t0) / 1_000_000;
  return { result, durationMs: parseFloat(ms.toFixed(3)) };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * getUserById(id)
 * ───────────────
 * Fetch a single user row by primary key.
 *
 * @param   {number|string} id  – user primary key (positive integer)
 * @returns {Promise<{ row: object|null, durationMs: number }>}
 * @throws  {ValidationError}   – on invalid id
 */
async function getUserById(id) {
  const safeId = validateId(id);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      active
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const { result, durationMs } = await timedQuery(sql, [safeId]);

  console.info('[queries] getUserById', {
    id:         safeId,
    found:      result.rowCount > 0,
    durationMs,
  });

  return {
    row:        result.rows[0] ?? null,
    durationMs,
  };
}

/**
 * getAllUsers(limit, offset, sortBy, sortDir)
 * ───────────────────────────────────────────
 * Paginated list of all users with a COUNT(*) for total-page calculation.
 *
 * Two queries are issued inside a transaction-scoped connection to guarantee
 * both the data page and the count reflect the same snapshot (the pool issues
 * them sequentially on the same client).
 *
 * @param   {number}  limit    – rows per page (1–100, default 20)
 * @param   {number}  offset   – rows to skip  (≥0, default 0)
 * @param   {string}  sortBy   – column name   (allow-listed, default 'id')
 * @param   {string}  sortDir  – 'ASC'|'DESC'  (default 'ASC')
 * @returns {Promise<{ rows: object[], total: number, limit: number, offset: number, durationMs: number }>}
 */
async function getAllUsers(limit, offset, sortBy = 'id', sortDir = 'ASC') {
  const safeLimit  = validateLimit(limit);
  const safeOffset = validateOffset(offset);
  const orderBy    = buildOrderBy(sortBy, sortDir);   // allow-list guarded

  // orderBy is constructed from an allow-list, not from raw user input
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      active
    FROM  users
    ORDER BY ${orderBy}
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS count
    FROM   users
  `;

  const t0 = process.hrtime.bigint();

  const [dataResult, countResult] = await Promise.all([
    query(dataSql,  [safeLimit, safeOffset]),
    query(countSql, []),
  ]);

  const durationMs = parseFloat(
    (Number(process.hrtime.bigint() - t0) / 1_000_000).toFixed(3)
  );

  const total = parseInt(countResult.rows[0].count, 10);

  console.info('[queries] getAllUsers', {
    limit:      safeLimit,
    offset:     safeOffset,
    orderBy,
    returned:   dataResult.rowCount,
    total,
    durationMs,
  });

  return {
    rows:       dataResult.rows,
    total,
    limit:      safeLimit,
    offset:     safeOffset,
    durationMs,
  };
}

/**
 * searchUsers(searchTerm, limit, offset)
 * ───────────────────────────────────────
 * Case-insensitive partial-match search across name and email columns using
 * PostgreSQL ILIKE.  The search term is always bound as a parameter ($1) —
 * never interpolated — so SQL injection via the search field is not possible.
 *
 * @param   {string}  searchTerm – free-text search string (1–200 chars)
 * @param   {number}  limit      – rows per page (1–100, default 20)
 * @param   {number}  offset     – rows to skip  (≥0, default 0)
 * @returns {Promise<{ rows: object[], total: number, term: string, limit: number, offset: number, durationMs: number }>}
 */
async function searchUsers(searchTerm, limit, offset) {
  const safeTerm   = validateSearchTerm(searchTerm);  // e.g. "%alice%"
  const safeLimit  = validateLimit(limit);
  const safeOffset = validateOffset(offset);

  // safeTerm is the wildcard-wrapped version sent as $1 — never concatenated
  // into the SQL string.  The pg driver transmits it in the Bind message,
  // separate from the Parse message that contains the query text.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      active
    FROM   users
    WHERE  name  ILIKE $1
       OR  email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS count
    FROM   users
    WHERE  name  ILIKE $1
       OR  email ILIKE $1
  `;

  const t0 = process.hrtime.bigint();

  const [dataResult, countResult] = await Promise.all([
    query(dataSql,  [safeTerm, safeLimit, safeOffset]),
    query(countSql, [safeTerm]),
  ]);

  const durationMs = parseFloat(
    (Number(process.hrtime.bigint() - t0) / 1_000_000).toFixed(3)
  );

  const total = parseInt(countResult.rows[0].count, 10);

  console.info('[queries] searchUsers', {
    // Log the *length* of the term, not the value itself (avoids PII in logs)
    termLength: safeTerm.length - 2,   // subtract the two % wildcards
    limit:      safeLimit,
    offset:     safeOffset,
    returned:   dataResult.rowCount,
    total,
    durationMs,
  });

  return {
    rows:       dataResult.rows,
    total,
    term:       searchTerm,    // original (untransformed) term for the response
    limit:      safeLimit,
    offset:     safeOffset,
    durationMs,
  };
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export error class so route handlers can differentiate 400 vs 500
  ValidationError,
};

/**
 * app.js — Express application
 *
 * Wires the query layer (queries.js → db.js → pg Pool) into the HTTP routes.
 *
 * Endpoints
 * ─────────
 *  GET  /health
 *  GET  /users                   – paginated list  (?limit=&offset=&sortBy=&sortDir=)
 *  GET  /users/search            – search          (?query=&limit=&offset=)
 *  GET  /users/:id               – single user by primary key
 */

'use strict';

const express = require('express');
const { getUserById, getAllUsers, searchUsers, ValidationError } = require('./queries');
const { closePool } = require('./db');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Request-level timing middleware
// Attaches a high-resolution start time to every request so route handlers
// can compute and log end-to-end latency.
// ---------------------------------------------------------------------------
app.use((req, res, next) => {
  req._startAt = process.hrtime.bigint();
  res.on('finish', () => {
    const ms = (Number(process.hrtime.bigint() - req._startAt) / 1_000_000).toFixed(3);
    console.info('[http]', {
      method:     req.method,
      path:       req.path,
      status:     res.statusCode,
      durationMs: ms,
    });
  });
  next();
});

// ---------------------------------------------------------------------------
// Shared route-error handler
// Differentiates validation errors (400) from unexpected errors (500) and
// avoids leaking internal details (stack traces, query text) to the client.
// ---------------------------------------------------------------------------
function handleRouteError(err, res) {
  if (err instanceof ValidationError) {
    return res.status(400).json({
      error:   'Bad Request',
      message: err.message,
    });
  }

  // Log full error server-side; send a generic message to the client
  console.error('[http] Unhandled route error', {
    message: err.message,
    code:    err.code,   // pg error code, if any
  });

  return res.status(500).json({
    error:   'Internal Server Error',
    message: 'An unexpected error occurred. Please try again later.',
  });
}

// ---------------------------------------------------------------------------
// GET /health
// ---------------------------------------------------------------------------
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users/search?query=<term>[&limit=20][&offset=0]
//
// Must be registered BEFORE /users/:id so Express does not treat "search"
// as an :id parameter.
// ---------------------------------------------------------------------------
app.get('/users/search', async (req, res) => {
  try {
    const { query: term, limit, offset } = req.query;

    const data = await searchUsers(term, limit, offset);

    res.json({
      data:       data.rows,
      pagination: {
        total:  data.total,
        limit:  data.limit,
        offset: data.offset,
        hasMore: data.offset + data.rows.length < data.total,
      },
      meta: {
        searchTerm: data.term,
        durationMs: data.durationMs,
      },
    });
  } catch (err) {
    handleRouteError(err, res);
  }
});

// ---------------------------------------------------------------------------
// GET /users?[limit=20][&offset=0][&sortBy=id][&sortDir=ASC]
// ---------------------------------------------------------------------------
app.get('/users', async (req, res) => {
  try {
    const { limit, offset, sortBy, sortDir } = req.query;

    const data = await getAllUsers(limit, offset, sortBy, sortDir);

    res.json({
      data:       data.rows,
      pagination: {
        total:  data.total,
        limit:  data.limit,
        offset: data.offset,
        hasMore: data.offset + data.rows.length < data.total,
      },
      meta: { durationMs: data.durationMs },
    });
  } catch (err) {
    handleRouteError(err, res);
  }
});

// ---------------------------------------------------------------------------
// GET /users/:id
// ---------------------------------------------------------------------------
app.get('/users/:id', async (req, res) => {
  try {
    const data = await getUserById(req.params.id);

    if (!data.row) {
      return res.status(404).json({
        error:   'Not Found',
        message: `No user found with id ${req.params.id}.`,
      });
    }

    res.json({
      data: data.row,
      meta: { durationMs: data.durationMs },
    });
  } catch (err) {
    handleRouteError(err, res);
  }
});

// ---------------------------------------------------------------------------
// 404 catch-all
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Not Found', message: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// Graceful shutdown — drain the DB pool before the process exits
// ---------------------------------------------------------------------------
async function shutdown(signal) {
  console.info(`[app] ${signal} received — shutting down gracefully`);
  try {
    await closePool();
  } finally {
    process.exit(0);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Start server (only when this file is run directly, not when required in tests)
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = parseInt(process.env.PORT ?? '3000', 10);
  app.listen(PORT, () => {
    console.info(`[app] Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * Runs entirely in-process against the mock pool (USE_DB_MOCK=true).
 * No PostgreSQL server or network access required.
 *
 * Run:  node queries.test.js
 */

'use strict';

process.env.USE_DB_MOCK = 'true';

const assert = require('assert/strict');
const { getUserById, getAllUsers, searchUsers, ValidationError } = require('./queries');

// ---------------------------------------------------------------------------
// Tiny test runner (no external test framework needed)
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;

async function test(label, fn) {
  try {
    await fn();
    console.log(`  ✓  ${label}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${label}`);
    console.error(`     ${err.message}`);
    if (!(err instanceof assert.AssertionError)) {
      console.error(err.stack);
    }
    failed++;
  }
}

function assertValidationError(fn, expectedSubstring) {
  return assert.rejects(fn, err => {
    assert.ok(err instanceof ValidationError, `Expected ValidationError, got ${err.constructor.name}`);
    if (expectedSubstring) {
      assert.ok(
        err.message.toLowerCase().includes(expectedSubstring.toLowerCase()),
        `Expected message to include "${expectedSubstring}", got: "${err.message}"`
      );
    }
    return true;
  });
}

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

console.log('\n── getUserById ──────────────────────────────');

await test('returns a user for a valid id', async () => {
  const { row, durationMs } = await getUserById(1);
  assert.ok(row,                    'row should not be null');
  assert.equal(row.id, 1);
  assert.equal(row.name, 'Alice Nguyen');
  assert.equal(row.email, 'alice@example.com');
  assert.ok(typeof durationMs === 'number' && durationMs >= 0, 'durationMs should be a non-negative number');
});

await test('returns null row for a non-existent id', async () => {
  const { row } = await getUserById(9999);
  assert.equal(row, null);
});

await test('accepts numeric string id', async () => {
  const { row } = await getUserById('2');
  assert.equal(row.id, 2);
  assert.equal(row.name, 'Bob Okafor');
});

await test('throws ValidationError for id = 0', async () => {
  await assertValidationError(() => getUserById(0), 'positive');
});

await test('throws ValidationError for negative id', async () => {
  await assertValidationError(() => getUserById(-5), 'positive');
});

await test('throws ValidationError for non-numeric id', async () => {
  await assertValidationError(() => getUserById('abc'), 'integer');
});

await test('throws ValidationError for missing id', async () => {
  await assertValidationError(() => getUserById(undefined), 'required');
});

await test('throws ValidationError for id exceeding postgres int4 max', async () => {
  await assertValidationError(() => getUserById(2_147_483_648), 'maximum');
});

await test('throws ValidationError for float id', async () => {
  await assertValidationError(() => getUserById(1.5), 'integer');
});

// ---------------------------------------------------------------------------
// getAllUsers
// ---------------------------------------------------------------------------

console.log('\n── getAllUsers ───────────────────────────────');

await test('returns default page (limit=20, offset=0)', async () => {
  const { rows, total, limit, offset, durationMs } = await getAllUsers();
  assert.ok(Array.isArray(rows));
  assert.equal(limit,  20);
  assert.equal(offset, 0);
  assert.equal(total,  10);   // seed data has 10 rows
  assert.equal(rows.length, 10);
  assert.ok(typeof durationMs === 'number');
});

await test('respects limit and offset', async () => {
  const page1 = await getAllUsers(3, 0);
  const page2 = await getAllUsers(3, 3);
  assert.equal(page1.rows.length, 3);
  assert.equal(page2.rows.length, 3);
  assert.notEqual(page1.rows[0].id, page2.rows[0].id);
});

await test('returns empty rows when offset exceeds total', async () => {
  const { rows } = await getAllUsers(10, 999);
  assert.equal(rows.length, 0);
});

await test('uses custom sortBy and sortDir', async () => {
  const { rows } = await getAllUsers(10, 0, 'name', 'ASC');
  // The mock sorts by id; verify we get 10 rows (sort column validation passes)
  assert.equal(rows.length, 10);
});

await test('throws ValidationError for limit = 0', async () => {
  await assertValidationError(() => getAllUsers(0), 'at least 1');
});

await test('throws ValidationError for limit > 100', async () => {
  await assertValidationError(() => getAllUsers(101), '100');
});

await test('throws ValidationError for negative offset', async () => {
  await assertValidationError(() => getAllUsers(10, -1), '≥ 0');
});

await test('throws ValidationError for non-integer limit', async () => {
  await assertValidationError(() => getAllUsers('abc'), 'integer');
});

await test('throws ValidationError for invalid sortBy column', async () => {
  await assertValidationError(() => getAllUsers(10, 0, 'password'), 'sort column');
});

await test('throws ValidationError for invalid sortDir', async () => {
  await assertValidationError(() => getAllUsers(10, 0, 'id', 'SIDEWAYS'), 'sort direction');
});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

console.log('\n── searchUsers ──────────────────────────────');

await test('finds users by partial name (case-insensitive)', async () => {
  const { rows, total } = await searchUsers('alice');
  assert.ok(rows.length >= 1);
  assert.ok(rows.some(u => u.name.toLowerCase().includes('alice')));
  assert.equal(total, rows.length);
});

await test('finds users by partial email', async () => {
  const { rows } = await searchUsers('bob@example');
  assert.ok(rows.some(u => u.email.includes('bob')));
});

await test('returns empty results for no match', async () => {
  const { rows, total } = await searchUsers('zzznomatchzzz');
  assert.equal(rows.length, 0);
  assert.equal(total, 0);
});

await test('returns pagination metadata', async () => {
  const result = await searchUsers('example', 5, 0);
  assert.ok(result.hasOwnProperty('rows'));
  assert.ok(result.hasOwnProperty('total'));
  assert.ok(result.hasOwnProperty('limit'));
  assert.ok(result.hasOwnProperty('offset'));
  assert.ok(result.hasOwnProperty('durationMs'));
  assert.ok(result.hasOwnProperty('term'));
  assert.equal(result.term, 'example');   // original unmodified term
});

await test('throws ValidationError for empty search term', async () => {
  await assertValidationError(() => searchUsers(''), '1 character');
});

await test('throws ValidationError for whitespace-only term', async () => {
  await assertValidationError(() => searchUsers('   '), '1 character');
});

await test('throws ValidationError for term exceeding 200 chars', async () => {
  await assertValidationError(() => searchUsers('x'.repeat(201)), '200 characters');
});

await test('handles wildcard characters in search term (no injection)', async () => {
  // % and _ are valid ILIKE wildcards, not SQL injection vectors when parameterised
  const { rows } = await searchUsers('%');
  assert.ok(Array.isArray(rows));   // should not throw
});

await test('handles SQL-injection-style input safely', async () => {
  // These strings cannot escape parameter binding
  const dangerous = ["' OR '1'='1", "'; DROP TABLE users; --", "1; SELECT * FROM users"];
  for (const input of dangerous) {
    const { rows } = await searchUsers(input);
    assert.ok(Array.isArray(rows), `Should return array for input: ${input}`);
  }
});

await test('respects limit and offset in search', async () => {
  const full  = await searchUsers('example', 100, 0);
  const paged = await searchUsers('example', 2,   0);
  assert.ok(paged.rows.length <= 2);
  assert.equal(paged.total, full.total);   // total is unaffected by pagination
});

// ---------------------------------------------------------------------------
// Summary
// ---------------------------------------------------------------------------

console.log(`\n${'─'.repeat(50)}`);
console.log(`Results: ${passed} passed, ${failed} failed`);
console.log('─'.repeat(50));

if (failed > 0) process.exit(1);

