/**
 * db.js
 * Initialises and exports a pg connection pool.
 *
 * All connection parameters are read exclusively from environment variables so
 * that no credentials ever appear in source code. Call `pool.end()` during
 * graceful shutdown to drain the pool cleanly.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// Every value falls back to a safe, clearly-invalid default so that a missing
// env var produces a descriptive connection error rather than a silent bug.
// ---------------------------------------------------------------------------
const pool = new Pool({
  // Accept either a full connection URL or individual components.
  connectionString: process.env.DATABASE_URL || undefined,

  // Individual fields are only used when DATABASE_URL is absent.
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME     || 'app',
  user:     process.env.DB_USER     || 'app_user',
  password: process.env.DB_PASSWORD || undefined,

  // Pool sizing – tune via environment for different deployment sizes.
  max:              parseInt(process.env.DB_POOL_MAX     || '10',   10),
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT || '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT || '5000', 10),

  // Enforce TLS in production; allow plain-text in development.
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

/** Log when a new physical connection is opened. */
pool.on('connect', (client) => {
  console.info('[db] New client connected to the pool ' +
    `(total: ${pool.totalCount}, idle: ${pool.idleCount})`);
});

/** Log and surface background errors so they are never swallowed silently. */
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT exit the process here – let the caller decide on recovery strategy.
});

/** Log when a client is removed from the pool (idle-timeout or shutdown). */
pool.on('remove', () => {
  console.info(`[db] Client removed from pool ` +
    `(total: ${pool.totalCount}, idle: ${pool.idleCount})`);
});

// ---------------------------------------------------------------------------
// Exported helpers
// ---------------------------------------------------------------------------

/**
 * Run a single parameterised query against the pool.
 *
 * @param {string}  text   - Parameterised SQL string (e.g. "SELECT … WHERE id = $1")
 * @param {Array}   params - Positional parameter values
 * @returns {Promise<import('pg').QueryResult>}
 */
pool.query = pool.query.bind(pool); // already present; explicit for clarity

/**
 * Borrow a dedicated client from the pool (needed for transactions).
 * The caller MUST call `client.release()` in a finally block.
 *
 * @returns {Promise<import('pg').PoolClient>}
 */
pool.connect = pool.connect.bind(pool);

module.exports = pool;

/**
 * queries.js
 * Parameterised query functions for the /users resource.
 *
 * Design principles
 * -----------------
 * 1. SQL injection prevention
 *    Every user-supplied value is passed as a positional parameter ($1, $2 …)
 *    to `pool.query()`. The pg driver sends the query text and the parameter
 *    array to PostgreSQL in separate protocol messages (the "extended query"
 *    protocol), so the database engine ALWAYS treats parameters as data, never
 *    as SQL syntax. This is the strongest form of injection prevention
 *    available; no string escaping or sanitisation is needed (or used).
 *
 * 2. Input validation before the query
 *    Parameters are validated and coerced to their expected types before the
 *    query is constructed. Invalid input is rejected with a descriptive error,
 *    preventing garbage reaching the database.
 *
 * 3. Connection pooling
 *    All queries use the shared `pool` exported from db.js. The pool manages
 *    client lifecycle, so individual query functions never call
 *    `client.release()` – they simply await `pool.query()`.
 *
 * 4. Query timing
 *    Every public function wraps the pg call with `performance.now()` and
 *    emits a structured timing log so slow queries are visible in the logs
 *    without any APM dependency.
 *
 * 5. No credentials in source
 *    Connection details live exclusively in environment variables (see db.js).
 */

'use strict';

const { performance } = require('perf_hooks');
const pool = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Hard ceiling on the number of rows a single page can request. */
const MAX_LIMIT = 200;

/** Default page size when the caller supplies no `limit`. */
const DEFAULT_LIMIT = 20;

/** Default page offset when the caller supplies no `offset`. */
const DEFAULT_OFFSET = 0;

/** Maximum byte-length we accept for a free-text search term. */
const MAX_SEARCH_QUERY_LENGTH = 200;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Log the duration of a completed query together with its name and row count.
 *
 * @param {string} queryName  - Human-readable identifier for the query
 * @param {number} startTime  - Value from `performance.now()` taken before the query
 * @param {number} rowCount   - Number of rows returned / affected
 */
function logQueryTiming(queryName, startTime, rowCount) {
  const durationMs = (performance.now() - startTime).toFixed(3);
  console.info(
    `[query] ${queryName} completed in ${durationMs} ms` +
    ` | rows: ${rowCount}`
  );
}

/**
 * Validate that `value` is a finite, positive integer and return it coerced to
 * a JavaScript `number`.  Throws a TypeError with a descriptive message on
 * failure so callers can surface it as a 400 Bad Request.
 *
 * @param {*}      value      - Raw input (likely a string from a query param)
 * @param {string} fieldName  - Label used in the error message
 * @param {number} [min=1]    - Inclusive lower bound
 * @param {number} [max]      - Inclusive upper bound (optional)
 * @returns {number}
 */
function validatePositiveInt(value, fieldName, min = 1, max = undefined) {
  const parsed = Number(value);

  if (!Number.isInteger(parsed)) {
    throw new TypeError(`"${fieldName}" must be an integer, got: ${JSON.stringify(value)}`);
  }
  if (parsed < min) {
    throw new TypeError(`"${fieldName}" must be >= ${min}, got: ${parsed}`);
  }
  if (max !== undefined && parsed > max) {
    throw new TypeError(`"${fieldName}" must be <= ${max}, got: ${parsed}`);
  }

  return parsed;
}

/**
 * Validate and sanitise a free-text search query string.
 *
 * - Strips leading/trailing whitespace.
 * - Rejects empty strings after trimming.
 * - Enforces a maximum length to prevent oversized payloads.
 * - Does NOT apply any SQL escaping – the value is passed as a bound
 *   parameter and the ILIKE wildcard characters ('%') are added in SQL,
 *   keeping user input fully inert.
 *
 * @param {*} value - Raw input
 * @returns {string} Trimmed, validated string
 */
function validateSearchQuery(value) {
  if (typeof value !== 'string') {
    throw new TypeError(`Search "query" must be a string, got: ${typeof value}`);
  }

  const trimmed = value.trim();

  if (trimmed.length === 0) {
    throw new TypeError('Search "query" must not be empty after trimming whitespace');
  }
  if (trimmed.length > MAX_SEARCH_QUERY_LENGTH) {
    throw new TypeError(
      `Search "query" must be <= ${MAX_SEARCH_QUERY_LENGTH} characters`
    );
  }

  return trimmed;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user row by primary key.
 *
 * SQL injection protection: `id` is validated as a positive integer before use
 * and is bound as the `$1` parameter – it is never interpolated into the SQL
 * string.
 *
 * @param {number|string} id - The user's primary key (must be a positive integer)
 * @returns {Promise<Object|null>} The user row, or `null` if not found
 *
 * @example
 * const user = await getUserById(42);
 * // user → { id: 42, name: 'Alice', email: 'alice@example.com', created_at: … }
 */
async function getUserById(id) {
  // --- Validate -------------------------------------------------------
  const safeId = validatePositiveInt(id, 'id');

  // --- Build query (NO string interpolation of user input) ------------
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;
  const params = [safeId];          // ← only ever a validated integer

  // --- Execute with timing --------------------------------------------
  const start = performance.now();

  const { rows } = await pool.query(sql, params);

  logQueryTiming('getUserById', start, rows.length);

  return rows[0] ?? null;           // undefined → null for a cleaner API
}

/**
 * Fetch a paginated list of all users, ordered by id ascending.
 *
 * LIMIT and OFFSET are validated as non-negative integers and bound as
 * positional parameters, so they cannot be used to inject SQL.
 *
 * @param {number|string} [limit=DEFAULT_LIMIT]   - Max rows to return (1–MAX_LIMIT)
 * @param {number|string} [offset=DEFAULT_OFFSET] - Number of rows to skip (>= 0)
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number }>}
 *
 * @example
 * const page = await getAllUsers(10, 20);
 * // page → { users: […], total: 57, limit: 10, offset: 20 }
 */
async function getAllUsers(
  limit  = DEFAULT_LIMIT,
  offset = DEFAULT_OFFSET,
) {
  // --- Validate -------------------------------------------------------
  const safeLimit  = validatePositiveInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = validatePositiveInt(offset, 'offset', 0);

  // --- Build query ----------------------------------------------------
  // The count query runs inside the SAME logical request so callers can
  // build pagination metadata without an extra round-trip.  Both queries
  // use only bound parameters.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
  `;

  const params = [safeLimit, safeOffset];

  // --- Execute both queries in parallel for efficiency ----------------
  const start = performance.now();

  const [dataResult, countResult] = await Promise.all([
    pool.query(dataSql, params),
    pool.query(countSql),
  ]);

  logQueryTiming('getAllUsers', start, dataResult.rows.length);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * Full-text search across users' `name` and `email` columns using a
 * case-insensitive ILIKE pattern match, with pagination support.
 *
 * SQL injection protection
 * ------------------------
 * The raw search string is NEVER concatenated into the SQL.  Instead, the
 * pg driver sends the cleaned string as bound parameter `$1`; PostgreSQL
 * wraps it with '%…%' INSIDE the SQL (via `'%' || $1 || '%'`) so that the
 * wildcard characters are part of the *SQL* expression, not of the user
 * value.  This means a search for "'; DROP TABLE users; --" becomes a
 * literal string search for that text, not an injection vector.
 *
 * @param {string}        query               - Search term (1–MAX_SEARCH_QUERY_LENGTH chars)
 * @param {number|string} [limit=DEFAULT_LIMIT]
 * @param {number|string} [offset=DEFAULT_OFFSET]
 * @returns {Promise<{ users: Object[], total: number, query: string, limit: number, offset: number }>}
 *
 * @example
 * const results = await searchUsers('alice', 5, 0);
 * // results → { users: [{ id: 1, name: 'Alice', … }], total: 1, query: 'alice', … }
 */
async function searchUsers(
  query,
  limit  = DEFAULT_LIMIT,
  offset = DEFAULT_OFFSET,
) {
  // --- Validate -------------------------------------------------------
  const safeQuery  = validateSearchQuery(query);
  const safeLimit  = validatePositiveInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = validatePositiveInt(offset, 'offset', 0);

  // --- Build query ----------------------------------------------------
  // The '%' wildcard characters are added by PostgreSQL string
  // concatenation inside the SQL, so they are NEVER part of the
  // user-supplied value bound to $1.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE '%' || $1 || '%'
      OR
      email ILIKE '%' || $1 || '%'
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE '%' || $1 || '%'
      OR
      email ILIKE '%' || $1 || '%'
  `;

  const dataParams  = [safeQuery, safeLimit, safeOffset];
  const countParams = [safeQuery];

  // --- Execute both queries in parallel -------------------------------
  const start = performance.now();

  const [dataResult, countResult] = await Promise.all([
    pool.query(dataSql,  dataParams),
    pool.query(countSql, countParams),
  ]);

  logQueryTiming('searchUsers', start, dataResult.rows.length);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    query:  safeQuery,
    limit:  safeLimit,
    offset: safeOffset,
  };
}

