// Module exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
};

/**
 * app.js
 * Express application wired up to the database query layer.
 *
 * /users endpoints
 * ─────────────────────────────────────────────────────────────────────────────
 * GET /users                   → paginated list of all users
 * GET /users/search?q=…        → full-text search (name & email)
 * GET /users/:id               → single user by primary key
 *
 * All database interaction is delegated to queries.js which enforces:
 *   • Parameterised queries  (SQL injection prevention)
 *   • Input validation       (type checks & range checks before the DB call)
 *   • Connection pooling     (via the shared pg Pool in db.js)
 *   • Query timing logs      (structured console.info per query)
 */

'use strict';

// Load environment variables from .env (development only – in production these
// are injected by the platform and dotenv is a no-op when the file is absent).
require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wrap an async route handler so that any rejected promise is forwarded to
 * Express's error-handling middleware via `next(err)` instead of causing an
 * unhandled-rejection crash.
 *
 * @param {Function} fn - Async `(req, res, next) => Promise<void>` handler
 * @returns {Function} Standard Express route handler
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Health check
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// /users routes
// ---------------------------------------------------------------------------

/**
 * GET /users/search?q=<term>[&limit=<n>][&offset=<n>]
 *
 * Search users by name or email using a case-insensitive substring match.
 *
 * Query parameters:
 *   q      {string}  required – search term
 *   limit  {number}  optional – page size    (default: 20, max: 200)
 *   offset {number}  optional – page offset  (default: 0)
 *
 * This route MUST be declared before `GET /users/:id` so that the literal
 * path segment "search" is not misinterpreted as a numeric id.
 *
 * @example
 * GET /users/search?q=alice&limit=5&offset=0
 * → 200 { users: […], total: 1, query: "alice", limit: 5, offset: 0 }
 */
app.get('/users/search', asyncHandler(async (req, res) => {
  const { q, limit, offset } = req.query;

  if (!q) {
    return res.status(400).json({
      error:   'Missing required query parameter',
      param:   'q',
      message: 'Provide a search term via ?q=<term>',
    });
  }

  const result = await searchUsers(
    q,
    limit  ?? undefined,
    offset ?? undefined,
  );

  res.json(result);
}));

/**
 * GET /users/:id
 *
 * Fetch a single user by primary key.
 *
 * Path parameters:
 *   id  {positive integer}  required
 *
 * @example
 * GET /users/1
 * → 200 { id: 1, name: "Alice", email: "alice@example.com", created_at: …, updated_at: … }
 *
 * GET /users/99999
 * → 404 { error: "Not found", message: "No user with id 99999" }
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await getUserById(req.params.id);

  if (!user) {
    return res.status(404).json({
      error:   'Not found',
      message: `No user with id ${req.params.id}`,
    });
  }

  res.json(user);
}));

/**
 * GET /users[?limit=<n>][&offset=<n>]
 *
 * Return a paginated list of all users ordered by id ascending.
 *
 * Query parameters:
 *   limit  {number}  optional – page size    (default: 20, max: 200)
 *   offset {number}  optional – page offset  (default: 0)
 *
 * @example
 * GET /users?limit=10&offset=0
 * → 200 { users: […], total: 57, limit: 10, offset: 0 }
 */
app.get('/users', asyncHandler(async (req, res) => {
  const { limit, offset } = req.query;

  const result = await getAllUsers(
    limit  ?? undefined,
    offset ?? undefined,
  );

  res.json(result);
}));

// ---------------------------------------------------------------------------
// Global error handler
// ---------------------------------------------------------------------------

/**
 * Centralised error handler.
 *
 * - TypeError / validation failures → 400 Bad Request
 * - Everything else → 500 Internal Server Error
 *
 * Stack traces are only included when NODE_ENV !== 'production' to avoid
 * leaking implementation details to external clients.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV !== 'production';

  if (err instanceof TypeError) {
    console.warn(`[app] Validation error on ${req.method} ${req.path}:`, err.message);
    return res.status(400).json({
      error:   'Bad request',
      message: err.message,
      ...(isDev && { stack: err.stack }),
    });
  }

  console.error(`[app] Unhandled error on ${req.method} ${req.path}:`, err);
  res.status(500).json({
    error:   'Internal server error',
    message: isDev ? err.message : 'An unexpected error occurred',
    ...(isDev && { stack: err.stack }),
  });
});

// ---------------------------------------------------------------------------
// Start server (skipped when required by tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = parseInt(process.env.PORT || '3000', 10);

  const server = app.listen(PORT, () => {
    console.info(`[app] Server running on port ${PORT} (${process.env.NODE_ENV ?? 'development'})`);
  });

  // Graceful shutdown: drain the connection pool before exiting.
  const shutdown = async (signal) => {
    console.info(`[app] ${signal} received – shutting down gracefully`);
    server.close(async () => {
      const pool = require('./db');
      await pool.end();
      console.info('[app] Database pool closed. Goodbye.');
      process.exit(0);
    });
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT',  () => shutdown('SIGINT'));
}

module.exports = app;

/**
 * queries.test.js
 * Unit tests for queries.js
 *
 * The pg pool is mocked so the tests run without a real PostgreSQL instance.
 * Each test verifies:
 *   1. The correct parameterised SQL is produced
 *   2. User input is never interpolated into the SQL string
 *   3. Validation errors are thrown for bad input
 *   4. Timing logs are emitted
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the pool BEFORE requiring queries.js so the module picks up the mock.
// ---------------------------------------------------------------------------

/** Captures every pool.query() call for assertion. */
const queryCalls = [];

/**
 * Configurable response factory.  Tests override `mockRows` and `mockCount`
 * to control what the fake DB returns.
 */
let mockRows  = [];
let mockCount = '0';

const mockPool = {
  query: jest.fn(async (sql, params) => {
    queryCalls.push({ sql: sql.replace(/\s+/g, ' ').trim(), params });

    // Return a count-shaped result for COUNT queries.
    if (/SELECT COUNT/i.test(sql)) {
      return { rows: [{ total: mockCount }] };
    }
    return { rows: mockRows };
  }),
  on: jest.fn(), // pool.on() is called at module load time in db.js
};

jest.mock('./db', () => mockPool);

// Now it is safe to load the module under test.
const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

beforeEach(() => {
  queryCalls.length = 0;
  mockPool.query.mockClear();
  mockRows  = [];
  mockCount = '0';
  jest.spyOn(console, 'info').mockImplementation(() => {});
});

afterEach(() => {
  jest.restoreAllMocks();
});

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

describe('getUserById', () => {
  test('executes a parameterised query with the validated id', async () => {
    mockRows = [{ id: 1, name: 'Alice', email: 'alice@example.com' }];

    const user = await getUserById(1);

    expect(user).toEqual(mockRows[0]);
    expect(mockPool.query).toHaveBeenCalledTimes(1);

    const [sql, params] = mockPool.query.mock.calls[0];

    // The SQL must NOT contain the literal id value.
    expect(sql).not.toContain('1');

    // The id value must travel via the params array (positional binding).
    expect(params).toEqual([1]);
    expect(sql).toContain('$1');
    expect(sql.toLowerCase()).toContain('where');
  });

  test('accepts a numeric string id (coerces to integer)', async () => {
    mockRows = [{ id: 7, name: 'Bob', email: 'bob@example.com' }];

    const user = await getUserById('7');

    expect(user.id).toBe(7);
    expect(mockPool.query.mock.calls[0][1]).toEqual([7]);
  });

  test('returns null when no row is found', async () => {
    mockRows = [];
    const user = await getUserById(999);
    expect(user).toBeNull();
  });

  test('emits a timing log after the query', async () => {
    mockRows = [{ id: 1, name: 'Alice', email: 'alice@example.com' }];
    await getUserById(1);

    const logCall = console.info.mock.calls.find(
      (args) => args[0].includes('getUserById')
    );
    expect(logCall).toBeDefined();
    expect(logCall[0]).toMatch(/completed in \d+\.\d{3} ms/);
    expect(logCall[0]).toMatch(/rows: 1/);
  });

  // --- Validation / injection-prevention tests -------------------------

  test('throws TypeError for a non-numeric id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for a zero id', async () => {
    await expect(getUserById(0)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for a negative id', async () => {
    await expect(getUserById(-5)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for a float id', async () => {
    await expect(getUserById(1.5)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('SQL injection string is rejected by type validation', async () => {
    const injection = "1; DROP TABLE users; --";
    await expect(getUserById(injection)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('SQL injection number disguised as object is rejected', async () => {
    await expect(getUserById({ id: 1 })).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });
});

// ---------------------------------------------------------------------------
// getAllUsers
// ---------------------------------------------------------------------------

describe('getAllUsers', () => {
  test('returns paginated users with total count', async () => {
    mockRows  = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];
    mockCount = '42';

    const result = await getAllUsers(10, 0);

    expect(result.users).toEqual(mockRows);
    expect(result.total).toBe(42);
    expect(result.limit).toBe(10);
    expect(result.offset).toBe(0);
  });

  test('sends limit and offset as bound parameters, not in the SQL string', async () => {
    mockRows  = [];
    mockCount = '0';

    await getAllUsers(25, 50);

    // Both the data query and the count query are executed.
    expect(mockPool.query).toHaveBeenCalledTimes(2);

    // The data query receives [25, 50] as bound params.
    const dataCall = mockPool.query.mock.calls.find(
      ([sql]) => !/COUNT/i.test(sql)
    );
    expect(dataCall[1]).toEqual([25, 50]);

    // Neither '25' nor '50' should appear as literals in the SQL.
    expect(dataCall[0]).not.toMatch(/\b25\b/);
    expect(dataCall[0]).not.toMatch(/\b50\b/);

    // The SQL must use positional placeholders.
    expect(dataCall[0]).toContain('$1');
    expect(dataCall[0]).toContain('$2');
  });

  test('uses defaults when called with no arguments', async () => {
    mockRows  = [];
    mockCount = '0';

    const result = await getAllUsers();

    expect(result.limit).toBe(20);    // DEFAULT_LIMIT
    expect(result.offset).toBe(0);    // DEFAULT_OFFSET
  });

  test('emits a timing log', async () => {
    mockRows  = [];
    mockCount = '5';

    await getAllUsers(10, 0);

    const logCall = console.info.mock.calls.find(
      (args) => args[0].includes('getAllUsers')
    );
    expect(logCall).toBeDefined();
    expect(logCall[0]).toMatch(/completed in \d+\.\d{3} ms/);
  });

  // --- Validation tests ------------------------------------------------

  test('throws TypeError when limit exceeds MAX_LIMIT (200)', async () => {
    await expect(getAllUsers(201, 0)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for a limit of zero', async () => {
    await expect(getAllUsers(0, 0)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for a negative offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for a non-numeric limit', async () => {
    await expect(getAllUsers('many', 0)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for a float limit', async () => {
    await expect(getAllUsers(10.9, 0)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('SQL injection via limit string is rejected by validation', async () => {
    await expect(getAllUsers('10; DROP TABLE users;', 0))
      .rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });
});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  test('returns matching users with total and echoed query term', async () => {
    mockRows  = [{ id: 1, name: 'Alice', email: 'alice@example.com' }];
    mockCount = '1';

    const result = await searchUsers('alice', 10, 0);

    expect(result.users).toEqual(mockRows);
    expect(result.total).toBe(1);
    expect(result.query).toBe('alice');
    expect(result.limit).toBe(10);
    expect(result.offset).toBe(0);
  });

  test('passes the search term as $1 bound param, not interpolated into SQL', async () => {
    mockRows  = [];
    mockCount = '0';

    const term = 'alice';
    await searchUsers(term, 10, 0);

    expect(mockPool.query).toHaveBeenCalledTimes(2);

    // Both queries receive the search term as the first bound param.
    for (const [sql, params] of mockPool.query.mock.calls) {
      expect(params[0]).toBe(term);

      // The literal search term must NOT appear in the SQL text.
      expect(sql).not.toContain(term);

      // The wildcard '%' must be applied inside SQL (not appended to the value).
      expect(sql).toContain("'%'");
      expect(sql).toContain('$1');
    }
  });

  test('trims leading/trailing whitespace from the search term', async () => {
    mockRows  = [];
    mockCount = '0';

    await searchUsers('  alice  ', 10, 0);

    const firstCall = mockPool.query.mock.calls[0];
    expect(firstCall[1][0]).toBe('alice');   // trimmed
  });

  test('uses defaults when limit/offset are omitted', async () => {
    mockRows  = [];
    mockCount = '0';

    const result = await searchUsers('bob');

    expect(result.limit).toBe(20);
    expect(result.offset).toBe(0);
  });

  test('emits a timing log', async () => {
    mockRows  = [{ id: 1 }];
    mockCount = '1';

    await searchUsers('alice');

    const logCall = console.info.mock.calls.find(
      (args) => args[0].includes('searchUsers')
    );
    expect(logCall).toBeDefined();
    expect(logCall[0]).toMatch(/completed in \d+\.\d{3} ms/);
    expect(logCall[0]).toMatch(/rows: 1/);
  });

  // --- Validation / injection-prevention tests -------------------------

  test('throws TypeError for an empty query string', async () => {
    await expect(searchUsers('')).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for a whitespace-only query string', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError when query exceeds 200 characters', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for a non-string query', async () => {
    await expect(searchUsers(123)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('classic SQL injection string is bound as plain data, not executed', async () => {
    mockRows  = [];
    mockCount = '0';

    // This must NOT throw – it is a valid string. The db driver will treat
    // it as literal text, making the injection attempt completely inert.
    const injection = "'; DROP TABLE users; --";
    await searchUsers(injection);

    const firstCall = mockPool.query.mock.calls[0];

    // The injection string arrives as a bound param, never in the SQL text.
    expect(firstCall[1][0]).toBe(injection);
    expect(firstCall[0]).not.toContain(injection);
  });

  test('UNION-based injection string is bound as plain data', async () => {
    mockRows  = [];
    mockCount = '0';

    const injection = "alice' UNION SELECT id,username,password FROM admins--";
    await searchUsers(injection);

    const firstCall = mockPool.query.mock.calls[0];
    expect(firstCall[1][0]).toBe(injection);
    expect(firstCall[0]).not.toContain('UNION SELECT');
  });

  test('throws TypeError for invalid limit in search', async () => {
    await expect(searchUsers('alice', 0)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError for limit exceeding MAX_LIMIT in search', async () => {
    await expect(searchUsers('alice', 999)).rejects.toThrow(TypeError);
    expect(mockPool.query).not.toHaveBeenCalled();
  });
