    await searchUsers('a_b');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toContain('\\_');
  });

  test('escapes backslash in search query', async () => {
    mockQuery.mockResolvedValueOnce(pgResult([]));

    await searchUsers('C:\\Users');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toContain('\\\\');
  });

  test('rejects empty string query', async () => {
    await expect(searchUsers('')).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects whitespace-only query', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects query longer than 100 characters', async () => {
    await expect(searchUsers('a'.repeat(101))).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects non-string query', async () => {
    await expect(searchUsers(42)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('SQL injection attempt in query string is neutralised via parameterisation', async () => {
    mockQuery.mockResolvedValueOnce(pgResult([]));

    // This would be a classic second-order injection attempt.
    // Because the entire string is passed as $1, pg never parses it as SQL.
    await searchUsers("' OR '1'='1");

    const [, params] = mockQuery.mock.calls[0];
    // The raw injection string appears *inside* the parameter value, not in SQL
    expect(params[0]).toContain("' OR '1'='1");
  });

  test('returns empty list and total=0 when no rows match', async () => {
    mockQuery.mockResolvedValueOnce(pgResult([]));

    const result = await searchUsers('zzznomatch');

    expect(result.users).toEqual([]);
    expect(result.total).toBe(0);
  });

  test('clamps limit above 100 down to 100', async () => {
    mockQuery.mockResolvedValueOnce(pgResult([]));

    await searchUsers('test', 500, 0);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[1]).toBe(100);
  });

  test('rejects negative offset', async () => {
    await expect(searchUsers('test', 10, -1)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('trims leading/trailing whitespace from query', async () => {
    mockQuery.mockResolvedValueOnce(pgResult(SEARCH_ROWS));

    const result = await searchUsers('  alice  ');

    expect(result.query).toBe('alice');
    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%alice%');
  });
});

