/**
 * db/env.js
 *
 * Reads and validates every database-related environment variable used by the
 * pool and query layer.  Values are intentionally read lazily (at module load)
 * so tests can set process.env before require()-ing this module.
 *
 * No external dependencies — uses only Node built-ins.
 */

'use strict';

/**
 * Return a required environment variable or throw a descriptive error.
 * @param {string} key
 * @returns {string}
 */
function required(key) {
  const value = process.env[key];
  if (value === undefined || value === '') {
    throw new Error(
      `[db/env] Missing required environment variable: ${key}. ` +
      'Check your .env file or deployment configuration.',
    );
  }
  return value;
}

/**
 * Return an optional environment variable, falling back to `defaultValue`.
 * @param {string} key
 * @param {string} defaultValue
 * @returns {string}
 */
function optional(key, defaultValue) {
  const value = process.env[key];
  return value !== undefined && value !== '' ? value : defaultValue;
}

/**
 * Parse a strictly-positive integer from an env var.
 * @param {string} key
 * @param {number} defaultValue
 * @returns {number}
 */
function positiveInt(key, defaultValue) {
  const raw = optional(key, String(defaultValue));
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 1) {
    throw new Error(
      `[db/env] ${key} must be a positive integer, got: ${JSON.stringify(raw)}`,
    );
  }
  return n;
}

// ── Exported configuration object ─────────────────────────────────────────────

const dbEnv = {
  host:               optional('DB_HOST', 'localhost'),
  port:               positiveInt('DB_PORT', 5432),
  database:           required('DB_NAME'),
  user:               required('DB_USER'),
  password:           required('DB_PASSWORD'),
  ssl:                optional('DB_SSL', 'false').toLowerCase() === 'true',

  // Pool limits
  poolMin:            positiveInt('DB_POOL_MIN', 2),
  poolMax:            positiveInt('DB_POOL_MAX', 10),
  idleTimeoutMs:      positiveInt('DB_POOL_IDLE_TIMEOUT_MS', 30_000),
  acquireTimeoutMs:   positiveInt('DB_POOL_ACQUIRE_TIMEOUT_MS', 5_000),
};

// Sanity check: min ≤ max
if (dbEnv.poolMin > dbEnv.poolMax) {
  throw new Error(
    `[db/env] DB_POOL_MIN (${dbEnv.poolMin}) must not exceed DB_POOL_MAX (${dbEnv.poolMax}).`,
  );
}

module.exports = dbEnv;

/**
 * db/logger.js
 *
 * Lightweight structured logger used by the database layer.
 *
 * Output format (newline-delimited JSON):
 *   {"ts":"2024-01-01T00:00:00.000Z","level":"info","component":"db","msg":"...","...extra fields}
 *
 * Levels: error > warn > info > debug
 *
 * The active level is controlled by the LOG_LEVEL environment variable
 * (default: "info").  Setting it to "debug" exposes query timing details.
 *
 * No external dependencies.
 */

'use strict';

const LEVELS = { error: 0, warn: 1, info: 2, debug: 3 };

const activeLevel = LEVELS[
  (process.env.LOG_LEVEL || 'info').toLowerCase()
] ?? LEVELS.info;

/**
 * Emit one structured log line.
 * @param {'error'|'warn'|'info'|'debug'} level
 * @param {string} msg
 * @param {object} [extra]
 */
function log(level, msg, extra = {}) {
  if ((LEVELS[level] ?? 0) > activeLevel) return;

  const line = JSON.stringify({
    ts:        new Date().toISOString(),
    level,
    component: 'db',
    msg,
    ...extra,
  });

  if (level === 'error' || level === 'warn') {
    process.stderr.write(line + '\n');
  } else {
    process.stdout.write(line + '\n');
  }
}

const logger = {
  error: (msg, extra)  => log('error', msg, extra),
  warn:  (msg, extra)  => log('warn',  msg, extra),
  info:  (msg, extra)  => log('info',  msg, extra),
  debug: (msg, extra)  => log('debug', msg, extra),
};

module.exports = logger;

