{
  "name": "p15-test-1wdkmh",
  "version": "1.0.0",
  "description": "Express app with PostgreSQL query layer",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node --experimental-vm-modules node_modules/.bin/jest --runInBand 2>/dev/null || node tests/queries.test.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "pg": "^8.11.3"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  },
  "keywords": [],
  "author": "",
  "license": "ISC"
}

/**
 * db.js
 * ─────
 * Singleton PostgreSQL connection pool.
 *
 * Reads configuration exclusively from environment variables so that no
 * credentials are ever hard-coded in source.  See .env.example for the full
 * list of supported variables.
 *
 * Usage
 * ─────
 *   const { query, getClient } = require('./db');
 *
 *   // One-shot query (connection returned to pool automatically)
 *   const { rows } = await query('SELECT $1::text AS msg', ['hello']);
 *
 *   // Explicit client (needed for transactions)
 *   const client = await getClient();
 *   try {
 *     await client.query('BEGIN');
 *     …
 *     await client.query('COMMIT');
 *   } catch (err) {
 *     await client.query('ROLLBACK');
 *     throw err;
 *   } finally {
 *     client.release();
 *   }
 */

'use strict';

const { Pool } = require('pg');

// ── Pool configuration ────────────────────────────────────────────────────────
// All values come from the environment; nothing is defaulted to a secret.
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,          // e.g. postgres://user:pass@host/db

  // Maximum number of clients kept alive in the pool.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // How long (ms) an idle client may sit before being closed.
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT_MS ?? '30000', 10),

  // How long (ms) to wait for an available client before throwing.
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONNECTION_TIMEOUT_MS ?? '2000', 10),

  // Never read SSL certs from the env string; force explicit opt-in via the
  // query-string (?sslmode=require) or the variable below.
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : undefined,
});

// ── Pool-level error handler ──────────────────────────────────────────────────
// Prevents unhandled 'error' events from crashing the process when a pooled
// client experiences a network hiccup between queries.
pool.on('error', (err) => {
  console.error('[db] Unexpected pool client error:', err.message);
});

// ── Pool-level connect/disconnect logging (dev only) ─────────────────────────
if (process.env.NODE_ENV !== 'production') {
  pool.on('connect', () => console.debug('[db] New client connected to pool'));
  pool.on('remove', () => console.debug('[db] Client removed from pool'));
}

// ── Public helpers ────────────────────────────────────────────────────────────

/**
 * Execute a parameterised query using a pool-managed client.
 *
 * @param {string}  text    - SQL string with $1 … $N placeholders.
 * @param {Array}   [params=[]] - Parameter values (never interpolated into SQL).
 * @returns {Promise<import('pg').QueryResult>}
 */
async function query(text, params = []) {
  return pool.query(text, params);
}

/**
 * Check-out a dedicated client from the pool.
 * The caller MUST call client.release() when finished.
 *
 * @returns {Promise<import('pg').PoolClient>}
 */
async function getClient() {
  return pool.connect();
}

/**
 * Gracefully drain the pool (call during process shutdown).
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  await pool.end();
  console.log('[db] Pool closed');
}

/**
 * Return a snapshot of current pool statistics (useful for health checks).
 *
 * @returns {{ total: number, idle: number, waiting: number }}
 */
function poolStats() {
  return {
    total:   pool.totalCount,
    idle:    pool.idleCount,
    waiting: pool.waitingCount,
  };
}

module.exports = { query, getClient, closePool, poolStats };

/**
 * queries.js
 * ──────────
 * Parameterised query functions for the /users endpoint.
 *
 * Security model
 * ──────────────
 *  • Every value that originates from user input travels via the $N placeholder
 *    mechanism provided by node-postgres.  The driver sends the query text and
 *    the parameter array in separate protocol messages, so the database server
 *    binds the values *after* parsing the SQL — making classic string-
 *    interpolation SQL injection structurally impossible for these queries.
 *
 *  • Additional defensive layers are applied at the application level:
 *      – Input types are validated and coerced before touching the DB.
 *      – Allowlist validation is used wherever a value controls query shape
 *        (e.g. sort column / direction) rather than a data value, because
 *        $N placeholders cannot parametrise identifiers.
 *      – Error objects returned to callers never include raw SQL or server
 *        error detail; those are logged server-side only.
 *
 * Observability
 * ─────────────
 *  Every helper wraps its query in `timedQuery()` which records:
 *    – the logical operation name
 *    – elapsed wall-clock time in milliseconds (via process.hrtime.bigint)
 *    – row count
 *    – whether the call succeeded or failed
 *  In production you would forward these structured log lines to your
 *  observability platform (Datadog, Grafana Loki, etc.).
 */

'use strict';

const { query } = require('./db');

// ── Constants ─────────────────────────────────────────────────────────────────

/** Hard upper-bound on rows returned by getAllUsers to prevent runaway queries. */
const MAX_LIMIT = 200;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/**
 * Columns that callers may legally sort by.
 * Using an allowlist prevents an attacker from injecting an identifier such as
 * `(SELECT …)` into the ORDER BY clause (parameterised values cannot be used
 * for SQL identifiers).
 */
const SORTABLE_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);

/** Allowed sort directions. */
const SORT_DIRECTIONS = new Set(['ASC', 'DESC']);

// ── Timing helper ─────────────────────────────────────────────────────────────

/**
 * Execute `fn` and emit a structured timing log line regardless of outcome.
 *
 * @param {string}   operation - Human-readable label (e.g. 'getUserById').
 * @param {Function} fn        - Async function that performs the DB work.
 * @returns {Promise<*>}       - Resolves/rejects with whatever `fn` returns.
 */
async function timedQuery(operation, fn) {
  const start = process.hrtime.bigint();
  let rowCount = 0;
  let success = false;

  try {
    const result = await fn();
    rowCount = result?.rowCount ?? result?.rows?.length ?? 0;
    success = true;
    return result;
  } finally {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    // Structured log — replace `console.log` with your logger of choice.
    console.log(
      JSON.stringify({
        level:     success ? 'info' : 'error',
        event:     'db_query',
        operation,
        elapsedMs: parseFloat(elapsedMs.toFixed(3)),
        rowCount,
        success,
        timestamp: new Date().toISOString(),
      }),
    );
  }
}

// ── Input validation helpers ───────────────────────────────────────────────────

/**
 * Parse a value as a positive integer, throwing a typed error on failure.
 * Used to validate `id`, `limit`, and `offset` before they reach the DB.
 *
 * @param {*}      value - Raw input.
 * @param {string} name  - Parameter name (used in error messages).
 * @returns {number}
 */
function parsePositiveInt(value, name) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    const err = new Error(`Invalid value for '${name}': must be a non-negative integer`);
    err.code = 'INVALID_INPUT';
    throw err;
  }
  return n;
}

/**
 * Validate that `column` is one of the allowed sort columns.
 *
 * @param {string} column
 * @returns {string} The validated column name (safe to interpolate as identifier).
 */
function validateSortColumn(column) {
  if (!SORTABLE_COLUMNS.has(column)) {
    const err = new Error(
      `Invalid sort column '${column}'. Allowed: ${[...SORTABLE_COLUMNS].join(', ')}`,
    );
    err.code = 'INVALID_INPUT';
    throw err;
  }
  return column;
}

/**
 * Validate and normalise a sort direction string.
 *
 * @param {string} direction - 'asc' | 'desc' (case-insensitive).
 * @returns {'ASC'|'DESC'}
 */
function validateSortDirection(direction) {
  const upper = String(direction).toUpperCase();
  if (!SORT_DIRECTIONS.has(upper)) {
    const err = new Error(`Invalid sort direction '${direction}'. Allowed: asc, desc`);
    err.code = 'INVALID_INPUT';
    throw err;
  }
  return upper;
}

// ── Query functions ────────────────────────────────────────────────────────────

/**
 * Fetch a single user by their primary-key ID.
 *
 * Injection prevention
 * ────────────────────
 * `id` is transmitted as the `$1` parameter — it is never concatenated into
 * the SQL string.  Additionally, `parsePositiveInt` rejects anything that
 * cannot be coerced to a non-negative integer, so strings such as
 * `'1; DROP TABLE users'` are rejected before reaching the driver.
 *
 * @param {number|string} id - The user's numeric ID.
 * @returns {Promise<object|null>} The user row, or `null` if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'Not found' });
 */
async function getUserById(id) {
  // Validate — rejects non-numeric / negative / float values early.
  const safeId = parsePositiveInt(id, 'id');

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  return timedQuery('getUserById', async () => {
    const result = await query(sql, [safeId]);
    // Return the single row object or null — never expose the full result set.
    return result.rows[0] ?? null;
  });
}

/**
 * Fetch a paginated, optionally sorted list of all users.
 *
 * Injection prevention
 * ────────────────────
 * `limit` and `offset` are validated as non-negative integers and sent as
 * `$1` / `$2` parameters.
 *
 * `sortBy` and `sortDir` cannot be parameterised (SQL identifiers are not
 * data values) so they are validated against explicit allowlists before being
 * interpolated into the query string.  Any value not in the allowlist causes
 * an immediate `INVALID_INPUT` error.
 *
 * @param {number} [limit=20]    - Rows per page (capped at MAX_LIMIT=200).
 * @param {number} [offset=0]    - Zero-based row offset.
 * @param {string} [sortBy='id'] - Column to sort by (allowlisted).
 * @param {string} [sortDir='ASC'] - 'ASC' or 'DESC' (allowlisted).
 * @returns {Promise<{ rows: object[], total: number }>}
 *
 * @example
 *   const { rows, total } = await getAllUsers(20, 0, 'name', 'asc');
 */
async function getAllUsers(
  limit   = DEFAULT_LIMIT,
  offset  = 0,
  sortBy  = 'id',
  sortDir = 'ASC',
) {
  // --- Input validation ----------------------------------------------------
  const safeLimit  = Math.min(parsePositiveInt(limit,  'limit'),  MAX_LIMIT);
  const safeOffset = parsePositiveInt(offset, 'offset');

  // Identifiers cannot use $N placeholders → allowlist validation is mandatory.
  const safeColumn    = validateSortColumn(sortBy);
  const safeDirection = validateSortDirection(sortDir);

  // -------------------------------------------------------------------------
  // The ORDER BY clause uses validated identifier names — NOT user input.
  // Using a template literal here is safe only because `safeColumn` and
  // `safeDirection` have already been checked against hard-coded allowlists.
  // -------------------------------------------------------------------------
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY ${safeColumn} ${safeDirection}
    LIMIT  $1
    OFFSET $2
  `;

  return timedQuery('getAllUsers', async () => {
    const result = await query(sql, [safeLimit, safeOffset]);

    // `total_count` comes from the window function — extract it once.
    const total = result.rows.length > 0
      ? parseInt(result.rows[0].total_count, 10)
      : 0;

    // Strip the synthetic total_count column from the returned rows.
    const rows = result.rows.map(({ total_count: _omit, ...rest }) => rest);

    return { rows, total };
  });
}

/**
 * Full-text search across name and email columns.
 *
 * Injection prevention
 * ────────────────────
 * The search term is sent as the `$1` parameter wrapped in `%…%` wildcards.
 * The wildcard wrapping is done in application code with a plain string
 * concatenation (`'%' + safeTerm + '%'`) — this is safe because the entire
 * value (including the `%` characters) is still transmitted as a parameter,
 * never interpolated into the SQL text.
 *
 * PostgreSQL's `ILIKE` handles the pattern matching entirely on the server
 * side after binding, so there is no opportunity for SQL injection.
 *
 * `limit` and `offset` follow the same integer-validation path as in
 * `getAllUsers`.
 *
 * @param {string} searchQuery    - Free-text search term (min 1 char).
 * @param {number} [limit=20]     - Maximum rows to return (capped at 200).
 * @param {number} [offset=0]     - Pagination offset.
 * @returns {Promise<{ rows: object[], total: number }>}
 *
 * @example
 *   const { rows, total } = await searchUsers('alice', 10, 0);
 */
async function searchUsers(searchQuery, limit = DEFAULT_LIMIT, offset = 0) {
  // --- Input validation ----------------------------------------------------

  // Reject null / undefined / empty strings before touching the DB.
  if (searchQuery == null || String(searchQuery).trim() === '') {
    const err = new Error("'query' must be a non-empty string");
    err.code = 'INVALID_INPUT';
    throw err;
  }

  // Trim and cap length to prevent excessively long patterns.
  const safeTerm = String(searchQuery).trim().slice(0, 200);

  const safeLimit  = Math.min(parsePositiveInt(limit,  'limit'),  MAX_LIMIT);
  const safeOffset = parsePositiveInt(offset, 'offset');

  // Wildcard wrapping happens in application code; the whole value (including
  // the % chars) is still sent as a single bound parameter → no injection.
  const pattern = `%${safeTerm}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY
      -- Exact matches first, then prefix matches, then substring matches.
      CASE
        WHEN name  ILIKE $2 THEN 0
        WHEN email ILIKE $2 THEN 0
        WHEN name  ILIKE $3 THEN 1
        WHEN email ILIKE $3 THEN 1
        ELSE 2
      END,
      name ASC
    LIMIT  $4
    OFFSET $5
  `;

  const exactPattern  = safeTerm;          // $2 – exact match
  const prefixPattern = `${safeTerm}%`;    // $3 – prefix match

  return timedQuery('searchUsers', async () => {
    const result = await query(sql, [
      pattern,       // $1 – WHERE clause (substring)
      exactPattern,  // $2 – ranking exact
      prefixPattern, // $3 – ranking prefix
      safeLimit,     // $4
      safeOffset,    // $5
    ]);

    const total = result.rows.length > 0
      ? parseInt(result.rows[0].total_count, 10)
      : 0;

    const rows = result.rows.map(({ total_count: _omit, ...rest }) => rest);

    return { rows, total };
  });
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,

  // Expose constants so callers (and tests) can reference them.
  MAX_LIMIT,
  DEFAULT_LIMIT,
  SORTABLE_COLUMNS,
};

/**
 * app.js
 * ──────
 * Express application with a full database query layer for /users.
 *
 * Endpoints
 * ─────────
 *  GET /health              — Liveness check + pool stats
 *  GET /users               — Paginated list of all users
 *  GET /users/search        — Full-text search across name & email
 *  GET /users/:id           — Single user by ID
 *
 * Environment variables
 * ─────────────────────
 *  See .env.example for the full reference.  Load them before starting:
 *    node -r dotenv/config app.js
 *  or set them in your process environment / container config.
 */

'use strict';

const express = require('express');
const { closePool, poolStats } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ── Utility helpers ───────────────────────────────────────────────────────────

/**
 * Parse a query-string value as a positive integer.
 * Returns `defaultValue` when the parameter is absent or blank.
 * Returns NaN (caught downstream) when the value is present but not numeric.
 *
 * @param {string|undefined} value
 * @param {number} defaultValue
 * @returns {number}
 */
function parseIntParam(value, defaultValue) {
  if (value === undefined || value === '') return defaultValue;
  return parseInt(value, 10);
}

/**
 * Centralised error response helper.
 * Logs the full error internally but only returns a safe message to the client.
 *
 * @param {import('express').Response} res
 * @param {Error} err
 */
function handleQueryError(res, err) {
  if (err.code === 'INVALID_INPUT') {
    // Validation errors are safe to surface — they contain no internal detail.
    return res.status(400).json({ error: err.message });
  }

  // For all other errors (DB connection failures, unexpected exceptions, etc.)
  // log full detail server-side but return a generic message to the client to
  // avoid leaking schema information.
  console.error('[app] Unhandled query error:', err);
  return res.status(500).json({ error: 'An internal server error occurred' });
}

// ── Routes ────────────────────────────────────────────────────────────────────

/**
 * GET /health
 *
 * Returns application liveness status plus current connection-pool statistics
 * so that your load-balancer / uptime monitor can detect pool exhaustion.
 *
 * Response shape:
 *   {
 *     status:    'ok',
 *     timestamp: '<ISO-8601>',
 *     pool: { total: 3, idle: 2, waiting: 0 }
 *   }
 */
app.get('/health', (_req, res) => {
  res.json({
    status:    'ok',
    timestamp: new Date().toISOString(),
    pool:      poolStats(),
  });
});

/**
 * GET /users
 *
 * Returns a paginated list of all users.
 *
 * Query parameters
 * ────────────────
 *  limit   {number}  Rows per page. Default 20, max 200.
 *  offset  {number}  Zero-based row offset. Default 0.
 *  sortBy  {string}  Column: id | name | email | created_at. Default 'id'.
 *  sortDir {string}  'asc' or 'desc'. Default 'asc'.
 *
 * Success response (200)
 * ──────────────────────
 *  {
 *    data:       [ { id, name, email, created_at }, … ],
 *    pagination: { total, limit, offset, hasMore }
 *  }
 *
 * Error responses
 * ───────────────
 *  400 – Invalid query parameter (non-integer limit/offset, unknown sortBy, etc.)
 *  500 – Unexpected server / database error
 */
app.get('/users', async (req, res) => {
  const limit   = parseIntParam(req.query.limit,  20);
  const offset  = parseIntParam(req.query.offset, 0);
  const sortBy  = req.query.sortBy  ?? 'id';
  const sortDir = req.query.sortDir ?? 'ASC';

  // Basic type guard before handing off to the query layer.
  if (isNaN(limit) || isNaN(offset)) {
    return res.status(400).json({ error: "'limit' and 'offset' must be integers" });
  }

  try {
    const { rows, total } = await getAllUsers(limit, offset, sortBy, sortDir);

    return res.json({
      data: rows,
      pagination: {
        total,
        limit,
        offset,
        hasMore: offset + rows.length < total,
      },
    });
  } catch (err) {
    return handleQueryError(res, err);
  }
});

/**
 * GET /users/search
 *
 * Full-text search across `name` and `email` columns (case-insensitive).
 * Results are ranked: exact matches → prefix matches → substring matches.
 *
 * Query parameters
 * ────────────────
 *  q       {string}  Required. Search term (1–200 chars).
 *  limit   {number}  Rows per page. Default 20, max 200.
 *  offset  {number}  Zero-based row offset. Default 0.
 *
 * Success response (200)
 * ──────────────────────
 *  {
 *    data:       [ { id, name, email, created_at }, … ],
 *    pagination: { total, limit, offset, hasMore },
 *    query:      '<sanitised echo of the search term>'
 *  }
 *
 * Error responses
 * ───────────────
 *  400 – Missing or empty `q`, invalid limit/offset
 *  500 – Unexpected server / database error
 *
 * NOTE: /users/search MUST be declared before /users/:id so that Express
 * does not treat the literal string "search" as a numeric ID.
 */
app.get('/users/search', async (req, res) => {
  const searchTerm = req.query.q;

  if (!searchTerm || String(searchTerm).trim() === '') {
    return res.status(400).json({ error: "Query parameter 'q' is required" });
  }

  const limit  = parseIntParam(req.query.limit,  20);
  const offset = parseIntParam(req.query.offset, 0);

  if (isNaN(limit) || isNaN(offset)) {
    return res.status(400).json({ error: "'limit' and 'offset' must be integers" });
  }

  try {
    const { rows, total } = await searchUsers(searchTerm, limit, offset);

    return res.json({
      data: rows,
      pagination: {
        total,
        limit,
        offset,
        hasMore: offset + rows.length < total,
      },
      // Echo back the sanitised term so the client can highlight matches.
      query: String(searchTerm).trim().slice(0, 200),
    });
  } catch (err) {
    return handleQueryError(res, err);
  }
});

/**
 * GET /users/:id
 *
 * Fetch a single user by their numeric ID.
 *
 * Path parameter
 * ──────────────
 *  id  {number}  Positive integer.
 *
 * Success response (200)
 * ──────────────────────
 *  { id, name, email, created_at }
 *
 * Error responses
 * ───────────────
 *  400 – Non-integer or negative ID
 *  404 – No user found with that ID
 *  500 – Unexpected server / database error
 */
app.get('/users/:id', async (req, res) => {
  const rawId = parseInt(req.params.id, 10);

  if (isNaN(rawId) || rawId <= 0) {
    return res.status(400).json({ error: "'id' must be a positive integer" });
  }

  try {
    const user = await getUserById(rawId);

    if (!user) {
      return res.status(404).json({ error: `User ${rawId} not found` });
    }

    return res.json(user);
  } catch (err) {
    return handleQueryError(res, err);
  }
});

// ── Graceful shutdown ─────────────────────────────────────────────────────────

/**
 * Drain the connection pool before the process exits.
 * This prevents "connection terminated unexpectedly" errors in PostgreSQL logs.
 */
async function shutdown(signal) {
  console.log(`\n[app] ${signal} received — shutting down gracefully`);
  try {
    await closePool();
  } catch (err) {
    console.error('[app] Error while closing pool:', err.message);
  }
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ── Start server ──────────────────────────────────────────────────────────────

const PORT = parseInt(process.env.PORT ?? '3000', 10);

// Guard: only listen when this file is run directly, not when it is require()'d
// by tests (which import `app` without wanting a real port bound).
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * tests/queries.test.js
 * ─────────────────────
 * Unit + integration-style tests for queries.js and the /users routes in
 * app.js.  The PostgreSQL pool (db.js) is fully mocked so these tests run
 * without a real database.
 *
 * Run with:   node tests/queries.test.js
 * (No external test framework required — uses Node's built-in assert module.)
 */

'use strict';

const assert = require('assert');

// ── Mock the db module BEFORE requiring queries.js or app.js ─────────────────
//
// We replace `require('./db')` with a controllable stub.  Each test can call
// `setMockRows()` / `setMockError()` to define what the next `query()` call
// will return or throw.

let _mockRows    = [];
let _mockError   = null;
let _lastSql     = null;
let _lastParams  = null;
let _queryCount  = 0;

function setMockRows(rows) {
  _mockRows  = rows;
  _mockError = null;
}
function setMockError(err) {
  _mockError = err;
  _mockRows  = [];
}
function resetMock() {
  _mockRows   = [];
  _mockError  = null;
  _lastSql    = null;
  _lastParams = null;
  _queryCount = 0;
}

// Patch require cache so both queries.js and app.js get the same stub.
require.cache[require.resolve('../db')] = {
  id:       require.resolve('../db'),
  filename: require.resolve('../db'),
  loaded:   true,
  exports: {
    query: async (text, params) => {
      _lastSql    = text;
      _lastParams = params;
      _queryCount++;

      if (_mockError) throw _mockError;

      return {
        rows:     _mockRows,
        rowCount: _mockRows.length,
      };
    },
    getClient:  async () => { throw new Error('getClient not stubbed'); },
    closePool:  async () => {},
    poolStats:  () => ({ total: 1, idle: 1, waiting: 0 }),
  },
};

const {
  getUserById,
  getAllUsers,
  searchUsers,
  MAX_LIMIT,
  DEFAULT_LIMIT,
} = require('../queries');

// ── Minimal HTTP test helper ──────────────────────────────────────────────────
// Avoids needing supertest/axios — just uses Node's built-in http module.

const http = require('http');
const app  = require('../app');

let server;
let baseUrl;

async function startServer() {
  return new Promise((resolve) => {
    server = app.listen(0, '127.0.0.1', () => {
      const { port } = server.address();
      baseUrl = `http://127.0.0.1:${port}`;
      resolve();
    });
  });
}

async function stopServer() {
  return new Promise((resolve) => server.close(resolve));
}

/**
 * Simple HTTP GET helper.
 * @param {string} path
 * @returns {Promise<{ status: number, body: object }>}
 */
async function get(path) {
  return new Promise((resolve, reject) => {
    http.get(`${baseUrl}${path}`, (res) => {
      let raw = '';
      res.on('data', (chunk) => { raw += chunk; });
      res.on('end', () => {
        try {
          resolve({ status: res.statusCode, body: JSON.parse(raw) });
        } catch {
          resolve({ status: res.statusCode, body: raw });
        }
      });
    }).on('error', reject);
  });
}

// ── Test runner ───────────────────────────────────────────────────────────────

const results = { passed: 0, failed: 0, errors: [] };

async function test(label, fn) {
  try {
    resetMock();
    await fn();
    console.log(`  ✓  ${label}`);
    results.passed++;
  } catch (err) {
    console.error(`  ✗  ${label}`);
    console.error(`     ${err.message}`);
    if (process.env.VERBOSE) console.error(err.stack);
    results.failed++;
    results.errors.push({ label, message: err.message });
  }
}

// ── queries.js unit tests ─────────────────────────────────────────────────────

async function runQueryUnitTests() {
  console.log('\n── queries.js unit tests ──────────────────────────────────────');

  // ── getUserById ────────────────────────────────────────────────────────────

  await test('getUserById — returns matching user row', async () => {
    const mockUser = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };
    setMockRows([mockUser]);

    const user = await getUserById(1);
    assert.deepStrictEqual(user, mockUser);
    assert.ok(_lastSql.includes('WHERE id = $1'));
    assert.deepStrictEqual(_lastParams, [1]);
  });

  await test('getUserById — returns null when no row found', async () => {
    setMockRows([]);
    const user = await getUserById(999);
    assert.strictEqual(user, null);
  });

  await test('getUserById — rejects non-integer id', async () => {
    await assert.rejects(
      () => getUserById('abc'),
      (err) => err.code === 'INVALID_INPUT',
    );
  });

  await test('getUserById — rejects negative id', async () => {
    await assert.rejects(
      () => getUserById(-5),
      (err) => err.code === 'INVALID_INPUT',
    );
  });

  await test('getUserById — rejects float id', async () => {
    await assert.rejects(
      () => getUserById(1.5),
      (err) => err.code === 'INVALID_INPUT',
    );
  });

  await test('getUserById — SQL injection attempt in id is rejected', async () => {
    // Classic injection attempt: "1; DROP TABLE users"
    await assert.rejects(
      () => getUserById('1; DROP TABLE users'),
      (err) => err.code === 'INVALID_INPUT',
    );
    // Ensure query was never sent to the DB.
    assert.strictEqual(_queryCount, 0);
  });

  await test('getUserById — propagates DB errors', async () => {
    setMockError(new Error('connection refused'));
    await assert.rejects(() => getUserById(1), /connection refused/);
  });

  // ── getAllUsers ────────────────────────────────────────────────────────────

  await test('getAllUsers — returns rows and total', async () => {
    const mockRows = [
      { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), total_count: '2' },
      { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), total_count: '2' },
    ];
    setMockRows(mockRows);

    const { rows, total } = await getAllUsers(20, 0);
    assert.strictEqual(rows.length, 2);
    assert.strictEqual(total, 2);
    // total_count should be stripped from returned rows
    assert.strictEqual(rows[0].total_count, undefined);
  });

  await test('getAllUsers — uses default limit and offset', async () => {
    setMockRows([]);
    await getAllUsers();
    assert.deepStrictEqual(_lastParams, [DEFAULT_LIMIT, 0]);
  });

  await test('getAllUsers — caps limit at MAX_LIMIT', async () => {
    setMockRows([]);
    await getAllUsers(9999, 0);
    assert.strictEqual(_lastParams[0], MAX_LIMIT);
  });

  await test('getAllUsers — valid sortBy column is interpolated safely', async () => {
    setMockRows([]);
    await getAllUsers(10, 0, 'name', 'desc');
    assert.ok(_lastSql.includes('ORDER BY name DESC'));
  });

  await test('getAllUsers — rejects invalid sortBy column', async () => {
    await assert.rejects(
      () => getAllUsers(10, 0, 'password'),
      (err) => err.code === 'INVALID_INPUT',
    );
    assert.strictEqual(_queryCount, 0);
  });

  await test('getAllUsers — rejects SQL injection in sortBy', async () => {
    await assert.rejects(
      () => getAllUsers(10, 0, 'id; DROP TABLE users--'),
      (err) => err.code === 'INVALID_INPUT',
    );
    assert.strictEqual(_queryCount, 0);
  });

  await test('getAllUsers — rejects invalid sortDir', async () => {
    await assert.rejects(
      () => getAllUsers(10, 0, 'id', 'SIDEWAYS'),
      (err) => err.code === 'INVALID_INPUT',
    );
    assert.strictEqual(_queryCount, 0);
  });

  await test('getAllUsers — rejects non-integer limit', async () => {
    await assert.rejects(
      () => getAllUsers('lots', 0),
      (err) => err.code === 'INVALID_INPUT',
    );
  });

  await test('getAllUsers — rejects negative offset', async () => {
    await assert.rejects(
      () => getAllUsers(10, -1),
      (err) => err.code === 'INVALID_INPUT',
    );
  });

  await test('getAllUsers — returns empty result when no rows', async () => {
    setMockRows([]);
    const { rows, total } = await getAllUsers();
    assert.deepStrictEqual(rows,  []);
    assert.strictEqual(total, 0);
  });

  // ── searchUsers ───────────────────────────────────────────────────────────

  await test('searchUsers — sends wildcard pattern as parameter', async () => {
    setMockRows([
      { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), total_count: '1' },
    ]);

    const { rows, total } = await searchUsers('alice');
    assert.strictEqual(rows.length, 1);
    assert.strictEqual(total, 1);

    // $1 must be the wildcard-wrapped pattern, not raw SQL.
    assert.strictEqual(_lastParams[0], '%alice%');
    // The SQL must use $1 placeholder, not a string concatenation.
    assert.ok(_lastSql.includes('ILIKE $1'));
  });

  await test('searchUsers — strips total_count from returned rows', async () => {
    setMockRows([
      { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), total_count: '1' },
    ]);
    const { rows } = await searchUsers('alice');
    assert.strictEqual(rows[0].total_count, undefined);
  });

  await test('searchUsers — rejects empty query string', async () => {
    await assert.rejects(
      () => searchUsers(''),
      (err) => err.code === 'INVALID_INPUT',
    );
    assert.strictEqual(_queryCount, 0);
  });

  await test('searchUsers — rejects whitespace-only query', async () => {
    await assert.rejects(
      () => searchUsers('   '),
      (err) => err.code === 'INVALID_INPUT',
    );
    assert.strictEqual(_queryCount, 0);
  });

  await test('searchUsers — rejects null query', async () => {
    await assert.rejects(
      () => searchUsers(null),
      (err) => err.code === 'INVALID_INPUT',
    );
  });

  await test('searchUsers — caps search term at 200 chars', async () => {
    setMockRows([]);
    const longTerm = 'a'.repeat(300);
    await searchUsers(longTerm);
    // The wildcard pattern should be based on the 200-char truncation.
    assert.strictEqual(_lastParams[0], '%' + 'a'.repeat(200) + '%');
  });

  await test("searchUsers — SQL injection attempt is passed as a bound parameter", async () => {
    setMockRows([]);
    const injection = "' OR '1'='1";
    await searchUsers(injection);

    // The dangerous string must appear ONLY as a bound parameter, never in SQL.
    assert.ok(!_lastSql.includes(injection),
      'Injection string must not be in the SQL text');
    assert.ok(_lastParams[0].includes(injection),
      'Injection string should be in the parameter array (harmless)');
  });

  await test('searchUsers — caps limit at MAX_LIMIT', async () => {
    setMockRows([]);
    await searchUsers('test', 9999, 0);
    assert.strictEqual(_lastParams[3], MAX_LIMIT);
  });

  await test('searchUsers — propagates DB errors', async () => {
    setMockError(new Error('timeout'));
    await assert.rejects(() => searchUsers('alice'), /timeout/);
  });
}

// ── app.js route integration tests ───────────────────────────────────────────

async function runRouteIntegrationTests() {
  console.log('\n── app.js route integration tests ────────────────────────────');

  await startServer();

  // /health ──────────────────────────────────────────────────────────────────

  await test('GET /health — returns 200 with status ok and pool stats', async () => {
    const { status, body } = await get('/health');
    assert.strictEqual(status, 200);
    assert.strictEqual(body.status, 'ok');
    assert.ok(body.timestamp);
    assert.ok(typeof body.pool === 'object');
    assert.ok('total' in body.pool);
  });

  // GET /users ───────────────────────────────────────────────────────────────

  await test('GET /users — 200 with pagination envelope', async () => {
    resetMock();
    setMockRows([
      { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), total_count: '2' },
      { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), total_count: '2' },
    ]);
    const { status, body } = await get('/users');
    assert.strictEqual(status, 200);
    assert.ok(Array.isArray(body.data));
    assert.ok('pagination' in body);
    assert.strictEqual(body.pagination.total, 2);
  });

  await test('GET /users — pagination hasMore is correct', async () => {
    resetMock();
    setMockRows([
      { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), total_count: '5' },
    ]);
    const { status, body } = await get('/users?limit=1&offset=0');
    assert.strictEqual(status, 200);
    assert.strictEqual(body.pagination.hasMore, true);
  });

  await test('GET /users — 400 for non-integer limit', async () => {
    const { status } = await get('/users?limit=abc');
    assert.strictEqual(status, 400);
  });

  await test('GET /users — 400 for invalid sortBy', async () => {
    const { status } = await get('/users?sortBy=password');
    assert.strictEqual(status, 400);
  });

  await test('GET /users — 400 for invalid sortDir', async () => {
    const { status } = await get('/users?sortDir=SIDEWAYS');
    assert.strictEqual(status, 400);
  });

  await test('GET /users — 500 on database error', async () => {
    resetMock();
    setMockError(new Error('DB unavailable'));
    const { status } = await get('/users');
    assert.strictEqual(status, 500);
  });

  // GET /users/search ────────────────────────────────────────────────────────

  await test('GET /users/search — 200 with matched rows', async () => {
    resetMock();
    setMockRows([
      { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), total_count: '1' },
    ]);
    const { status, body } = await get('/users/search?q=alice');
    assert.strictEqual(status, 200);
    assert.ok(Array.isArray(body.data));
    assert.strictEqual(body.query, 'alice');
    assert.strictEqual(body.pagination.total, 1);
  });

  await test('GET /users/search — 400 when q is missing', async () => {
    const { status } = await get('/users/search');
    assert.strictEqual(status, 400);
  });

  await test('GET /users/search — 400 when q is blank', async () => {
    const { status } = await get('/users/search?q=   ');
    assert.strictEqual(status, 400);
  });

  await test("GET /users/search — SQL injection in q gets 200 (value bound, not executed)", async () => {
    resetMock();
    setMockRows([]);
    // The dangerous string is just a bound parameter — harmless.
    const { status, body } = await get("/users/search?q=' OR '1'='1");
    assert.strictEqual(status, 200);
    assert.deepStrictEqual(body.data, []);
  });

  // GET /users/:id ───────────────────────────────────────────────────────────

  await test('GET /users/:id — 200 for existing user', async () => {
    resetMock();
    const mockUser = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };
    setMockRows([mockUser]);

    const { status, body } = await get('/users/1');
    assert.strictEqual(status, 200);
    assert.strictEqual(body.id, 1);
    assert.strictEqual(body.name, 'Alice');
  });

  await test('GET /users/:id — 404 when user not found', async () => {
    resetMock();
    setMockRows([]);
    const { status } = await get('/users/999');
    assert.strictEqual(status, 404);
  });

  await test('GET /users/:id — 400 for non-integer id', async () => {
    const { status } = await get('/users/abc');
    assert.strictEqual(status, 400);
  });

  await test('GET /users/:id — 400 for negative id', async () => {
    const { status } = await get('/users/-1');
    assert.strictEqual(status, 400);
  });

  await test('GET /users/:id — 400 for zero id', async () => {
    const { status } = await get('/users/0');
    assert.strictEqual(status, 400);
  });

  await test('GET /users/:id — 500 on database error', async () => {
    resetMock();
    setMockError(new Error('query timeout'));
    const { status, body } = await get('/users/1');
    assert.strictEqual(status, 500);
    // Must NOT expose internal error detail to client.
    assert.ok(!JSON.stringify(body).includes('query timeout'));
  });

  await stopServer();
}

// ── Main ──────────────────────────────────────────────────────────────────────

(async () => {
  console.log('Running query layer tests…\n');

  await runQueryUnitTests();
  await runRouteIntegrationTests();

  console.log(`\n${'─'.repeat(60)}`);
  console.log(`Results: ${results.passed} passed, ${results.failed} failed`);

  if (results.failed > 0) {
    console.error('\nFailed tests:');
    results.errors.forEach(({ label, message }) => {
      console.error(`  • ${label}\n    ${message}`);
    });
    process.exit(1);
  }
})();

