{
  "name": "express-db-app",
  "version": "1.0.0",
  "description": "Express app with PostgreSQL connection pooling and parameterised queries",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest --runInBand --forceExit"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "pg": "^8.11.5"
  },
  "devDependencies": {
    "jest": "^29.7.0",
    "supertest": "^7.0.0"
  }
}

// db/pool.js
// ---------------------------------------------------------------------------
// Creates and exports a single pg.Pool instance that is shared across the
// entire process lifetime.  All query functions import from this file so that
// connection pooling is never accidentally bypassed.
//
// Configuration is read exclusively from environment variables so that no
// credentials are ever hard-coded in source files.
// ---------------------------------------------------------------------------

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
// pg accepts either a single DATABASE_URL connection string *or* individual
// host/user/password/… variables.  Both patterns are supported here; the
// connection string takes precedence when present.
// ---------------------------------------------------------------------------
const poolConfig = {
  // --- connection -----------------------------------------------------------
  connectionString: process.env.DATABASE_URL, // e.g. postgres://user:pass@host/db
  // Individual fields are used as fallbacks when DATABASE_URL is absent.
  host:     process.env.PGHOST     || 'localhost',
  port:     parseInt(process.env.PGPORT || '5432', 10),
  database: process.env.PGDATABASE || 'app',
  user:     process.env.PGUSER,
  password: process.env.PGPASSWORD,

  // --- pool sizing ----------------------------------------------------------
  // Keep enough connections for typical API concurrency without exhausting
  // the database's max_connections limit.
  max:              parseInt(process.env.PG_POOL_MAX              || '10',   10),
  min:              parseInt(process.env.PG_POOL_MIN              || '2',    10),
  idleTimeoutMillis: parseInt(process.env.PG_IDLE_TIMEOUT_MS      || '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.PG_CONN_TIMEOUT_MS || '5000',  10),

  // --- security -------------------------------------------------------------
  // Enforce SSL in production; allow plain-text in local/test environments.
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers
// ---------------------------------------------------------------------------
pool.on('connect', (client) => {
  // pg fires this once per *new* physical connection, not per acquire().
  // We set a hard statement_timeout here so runaway queries can never block
  // the pool; individual queries may lower this further via SET LOCAL.
  client.query(
    `SET statement_timeout = ${parseInt(process.env.PG_STATEMENT_TIMEOUT_MS || '10000', 10)}`
  ).catch((err) => {
    console.error('[pool] Failed to set statement_timeout on new connection:', err.message);
  });
});

pool.on('error', (err) => {
  // Idle-client errors (e.g. server closed connection unexpectedly) are
  // surfaced here.  Log and continue — pg will remove the broken client
  // from the pool automatically.
  console.error('[pool] Unexpected error on idle client:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------
// Call pool.end() when the process exits so that in-flight transactions are
// not left dangling.  Callers (app.js, test teardown, etc.) should await
// this.
// ---------------------------------------------------------------------------
async function closePool() {
  await pool.end();
  console.log('[pool] All connections released.');
}

module.exports = { pool, closePool };

// db/queries.js
// ---------------------------------------------------------------------------
// Parameterised query functions for the /users endpoint.
//
// Security guarantees
// -------------------
// * ALL user-supplied values are passed as positional parameters ($1, $2, …)
//   and never interpolated into the SQL string.  This is the standard defence
//   against SQL injection when using node-postgres (pg).
// * Input validation is performed before the query reaches the database so
//   that type errors are caught early and never reach the query planner.
// * LIKE/ILIKE pattern characters (%, _) and the backslash escape character
//   inside the `searchUsers` query are escaped before being bound, preventing
//   pattern-injection attacks.
// * No raw SQL is ever constructed by concatenating user input.
//
// Performance
// -----------
// * All functions share the module-level pool (imported from pool.js) so
//   connections are reused across requests.
// * Every query is wrapped in a timing helper that logs duration, the query
//   name, and key parameters (never sensitive values).
// ---------------------------------------------------------------------------

'use strict';

const { pool } = require('./pool');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Wraps a pg query in performance timing and structured logging.
 *
 * @param {string}   queryName  - Human-readable label for logs.
 * @param {Function} queryFn    - Async function that performs the actual query.
 *                                Receives a pg.PoolClient already checked out.
 * @returns {Promise<pg.QueryResult>}
 */
async function timedQuery(queryName, queryFn) {
  const client = await pool.connect();
  const startNs = process.hrtime.bigint();

  try {
    const result = await queryFn(client);
    const durationMs = Number(process.hrtime.bigint() - startNs) / 1_000_000;
    console.log(
      `[query] name=${queryName} status=ok rows=${result.rowCount} duration=${durationMs.toFixed(3)}ms`
    );
    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - startNs) / 1_000_000;
    console.error(
      `[query] name=${queryName} status=error duration=${durationMs.toFixed(3)}ms message=${err.message}`
    );
    throw err;
  } finally {
    // Always release the client back to the pool, even on error.
    client.release();
  }
}

/**
 * Validates that a value is a safe positive integer.
 *
 * @param {*}      value   - The value to validate.
 * @param {string} label   - Field name used in error messages.
 * @param {number} [max]   - Optional upper bound (inclusive).
 * @returns {number} The coerced integer.
 * @throws {TypeError} If validation fails.
 */
function validatePositiveInt(value, label, max) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1) {
    throw new TypeError(`${label} must be a positive integer, got: ${value}`);
  }
  if (max !== undefined && n > max) {
    throw new TypeError(`${label} must be ≤ ${max}, got: ${n}`);
  }
  return n;
}

/**
 * Validates that a value is a safe non-negative integer (0 allowed).
 *
 * @param {*}      value - The value to validate.
 * @param {string} label - Field name used in error messages.
 * @returns {number} The coerced integer.
 * @throws {TypeError} If validation fails.
 */
function validateNonNegativeInt(value, label) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new TypeError(`${label} must be a non-negative integer, got: ${value}`);
  }
  return n;
}

/**
 * Validates and sanitises a search string.
 *
 * Rules:
 *   - Must be a non-empty string after trimming.
 *   - Maximum length of MAX_SEARCH_LENGTH characters (prevent oversized queries).
 *   - Only printable Unicode characters are permitted (control chars blocked).
 *
 * @param {*} value - The value to validate.
 * @returns {string} The trimmed, validated string.
 * @throws {TypeError} If validation fails.
 */
const MAX_SEARCH_LENGTH = 100;

function validateSearchQuery(value) {
  if (typeof value !== 'string') {
    throw new TypeError(`search query must be a string, got: ${typeof value}`);
  }
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    throw new TypeError('search query must not be empty');
  }
  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new TypeError(
      `search query must be ≤ ${MAX_SEARCH_LENGTH} characters, got: ${trimmed.length}`
    );
  }
  // Block ASCII control characters (0x00–0x1F, 0x7F).
  // eslint-disable-next-line no-control-regex
  if (/[\x00-\x1F\x7F]/.test(trimmed)) {
    throw new TypeError('search query contains invalid control characters');
  }
  return trimmed;
}

/**
 * Escapes LIKE/ILIKE special characters in a search term so the pattern
 * matches the literal string and cannot be used to leak data via wildcard
 * injection.
 *
 * Characters escaped: % _ \
 *
 * The resulting string is then wrapped in leading/trailing % wildcards for a
 * "contains" search.  Because the value is still passed as a parameterised
 * argument, no SQL injection is possible; the escaping is purely to preserve
 * the intended semantics of the LIKE expression.
 *
 * @param {string} raw - Already-validated search term.
 * @returns {string} Pattern safe for use as a LIKE/ILIKE argument.
 */
function escapeLikePattern(raw) {
  return '%' + raw.replace(/[\\%_]/g, '\\$&') + '%';
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetches a single user by their primary-key ID.
 *
 * @param {number|string} id - The user's numeric ID.
 * @returns {Promise<object|null>} The user row, or null if not found.
 * @throws {TypeError}  On invalid input.
 * @throws {Error}      On database errors.
 *
 * @example
 *   const user = await getUserById(42);
 *   // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: Date }
 */
async function getUserById(id) {
  // Validate: must be a positive integer (no floats, no strings like "1 OR 1=1")
  const safeId = validatePositiveInt(id, 'id');

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await timedQuery('getUserById', (client) =>
    client.query(sql, [safeId])
  );

  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users, ordered by ID ascending.
 *
 * @param {number} limit  - Maximum number of rows to return (1–100).
 * @param {number} offset - Number of rows to skip (≥ 0, for pagination).
 * @returns {Promise<{ users: object[], total: number }>}
 *   `users`  – the page of user rows.
 *   `total`  – the total number of users in the table (for building page counts).
 * @throws {TypeError}  On invalid input.
 * @throws {Error}      On database errors.
 *
 * @example
 *   const { users, total } = await getAllUsers(10, 0);
 */
async function getAllUsers(limit, offset) {
  // Validate: limit 1–100, offset ≥ 0
  const safeLimit  = validatePositiveInt(limit,  'limit',  100);
  const safeOffset = validateNonNegativeInt(offset, 'offset');

  // A single round-trip returns both the page and the total count via a
  // window function, avoiding a separate COUNT(*) query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await timedQuery('getAllUsers', (client) =>
    client.query(sql, [safeLimit, safeOffset])
  );

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  // Strip the synthetic total_count column from the returned user objects.
  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total };
}

/**
 * Full-text–style search across user name and email using a case-insensitive
 * ILIKE pattern.
 *
 * SQL injection prevention details
 * ---------------------------------
 * 1. `validateSearchQuery` rejects non-strings, empty strings, over-length
 *    strings, and strings containing control characters.
 * 2. `escapeLikePattern` escapes %, _, and \ so the value cannot widen the
 *    LIKE pattern beyond what the caller intended.
 * 3. The final escaped pattern string is still bound as a parameterised
 *    argument ($1), so the database driver handles all further quoting.
 *
 * @param {string} query  - The search term entered by the user.
 * @param {number} [limit=20]  - Max results (1–100).
 * @param {number} [offset=0] - Pagination offset (≥ 0).
 * @returns {Promise<{ users: object[], total: number }>}
 * @throws {TypeError}  On invalid input.
 * @throws {Error}      On database errors.
 *
 * @example
 *   const { users, total } = await searchUsers('alice', 20, 0);
 */
async function searchUsers(query, limit = 20, offset = 0) {
  const safeQuery  = validateSearchQuery(query);
  const safeLimit  = validatePositiveInt(limit,  'limit',  100);
  const safeOffset = validateNonNegativeInt(offset, 'offset');

  // Escape LIKE wildcards *before* binding.  The result is still a parameter.
  const pattern = escapeLikePattern(safeQuery);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR
      email ILIKE $1 ESCAPE '\\'
    ORDER BY
      -- Exact prefix matches first, then broader contains matches.
      CASE WHEN name  ILIKE $2 ESCAPE '\\' THEN 0
           WHEN email ILIKE $2 ESCAPE '\\' THEN 1
           ELSE 2
      END,
      id ASC
    LIMIT  $3
    OFFSET $4
  `;

  // $2 is a "starts-with" pattern used only for ranking, not filtering.
  const prefixPattern = escapeLikePattern(safeQuery).replace(/^%/, '');

  const result = await timedQuery('searchUsers', (client) =>
    client.query(sql, [pattern, prefixPattern, safeLimit, safeOffset])
  );

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = { getUserById, getAllUsers, searchUsers };

// app.js
// ---------------------------------------------------------------------------
// Express application.
// The /users endpoint is now backed by parameterised database queries.
// ---------------------------------------------------------------------------

'use strict';

require('dotenv').config();
const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./db/queries');
const { closePool } = require('./db/pool');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Sends a structured, consistently shaped error response.
 *
 * @param {express.Response} res
 * @param {number}           statusCode
 * @param {string}           message     - Safe, user-facing message.
 * @param {string}           [detail]    - Extra context (omitted in production).
 */
function sendError(res, statusCode, message, detail) {
  const body = { error: { status: statusCode, message } };
  if (detail && process.env.NODE_ENV !== 'production') {
    body.error.detail = detail;
  }
  return res.status(statusCode).json(body);
}

/**
 * Parses and validates the pagination query parameters that appear on
 * both GET /users and GET /users/search.
 *
 * Returns `null` and writes an error response when validation fails so the
 * caller can do an early return.
 *
 * @param {express.Request}  req
 * @param {express.Response} res
 * @returns {{ limit: number, offset: number } | null}
 */
function parsePagination(req, res) {
  const rawLimit  = req.query.limit  ?? '20';
  const rawOffset = req.query.offset ?? '0';

  const limit  = Number(rawLimit);
  const offset = Number(rawOffset);

  if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
    sendError(res, 400, 'Invalid pagination parameters.',
      'limit must be an integer between 1 and 100.');
    return null;
  }
  if (!Number.isInteger(offset) || offset < 0) {
    sendError(res, 400, 'Invalid pagination parameters.',
      'offset must be a non-negative integer.');
    return null;
  }

  return { limit, offset };
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health — liveness probe (no DB dependency)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
// Query params:
//   limit  {number}  1–100, default 20
//   offset {number}  ≥ 0,   default 0
//
// Returns:
//   200 { users: [...], total: number, limit: number, offset: number }
// ---------------------------------------------------------------------------
app.get('/users', async (req, res) => {
  const pagination = parsePagination(req, res);
  if (!pagination) return;                         // error already sent

  const { limit, offset } = pagination;

  try {
    const { users, total } = await getAllUsers(limit, offset);
    return res.json({ users, total, limit, offset });
  } catch (err) {
    console.error('[route] GET /users error:', err.message);
    return sendError(res, 500, 'Failed to retrieve users.');
  }
});

// ---------------------------------------------------------------------------
// GET /users/search
// Query params:
//   q      {string}  search term (required)
//   limit  {number}  1–100, default 20
//   offset {number}  ≥ 0,   default 0
//
// Returns:
//   200 { users: [...], total: number, query: string, limit: number, offset: number }
// ---------------------------------------------------------------------------
app.get('/users/search', async (req, res) => {
  const rawQ = req.query.q;

  // Validate presence and rough type before handing off to searchUsers.
  if (typeof rawQ !== 'string' || rawQ.trim().length === 0) {
    return sendError(res, 400, "Missing required query parameter 'q'.");
  }

  const pagination = parsePagination(req, res);
  if (!pagination) return;

  const { limit, offset } = pagination;

  try {
    const { users, total } = await searchUsers(rawQ, limit, offset);
    return res.json({ users, total, query: rawQ.trim(), limit, offset });
  } catch (err) {
    // Distinguish between caller errors (400) and server errors (500).
    if (err instanceof TypeError) {
      return sendError(res, 400, err.message);
    }
    console.error('[route] GET /users/search error:', err.message);
    return sendError(res, 500, 'Search failed.');
  }
});

// ---------------------------------------------------------------------------
// GET /users/:id
// Path params:
//   id {number}  positive integer
//
// Returns:
//   200 { user: {...} }   — found
//   404 { error: {...} }  — not found
// ---------------------------------------------------------------------------
app.get('/users/:id', async (req, res) => {
  const rawId = req.params.id;

  // Reject non-numeric IDs immediately (e.g. "abc", "1; DROP TABLE users").
  if (!/^\d+$/.test(rawId)) {
    return sendError(res, 400, 'User ID must be a positive integer.');
  }

  const id = Number(rawId);

  if (!Number.isInteger(id) || id < 1 || id > Number.MAX_SAFE_INTEGER) {
    return sendError(res, 400, 'User ID is out of valid range.');
  }

  try {
    const user = await getUserById(id);
    if (!user) {
      return sendError(res, 404, `User with ID ${id} not found.`);
    }
    return res.json({ user });
  } catch (err) {
    if (err instanceof TypeError) {
      return sendError(res, 400, err.message);
    }
    console.error(`[route] GET /users/${id} error:`, err.message);
    return sendError(res, 500, 'Failed to retrieve user.');
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------
async function shutdown(signal) {
  console.log(`[app] Received ${signal}. Shutting down gracefully…`);
  await closePool();
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Start server (skipped when file is require()'d in tests)
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = parseInt(process.env.PORT || '3000', 10);
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT} (${process.env.NODE_ENV ?? 'development'})`);
  });
}

module.exports = app;

// tests/queries.test.js
// ---------------------------------------------------------------------------
// Unit tests for db/queries.js.
//
// The pg pool is mocked so no real database connection is needed.  Each test
// controls exactly what the mock client returns, letting us verify:
//
//   • correct SQL is built (parameterised, no string interpolation)
//   • bind parameters match validated/escaped values
//   • input validation rejects bad values before they reach the DB
//   • LIKE pattern escaping works correctly
//   • timing logs are emitted
//   • the pool client is always released (even on error)
// ---------------------------------------------------------------------------

'use strict';

// ---------------------------------------------------------------------------
// Mock pg pool BEFORE requiring anything that imports it.
// ---------------------------------------------------------------------------
const mockRelease = jest.fn();
const mockQuery   = jest.fn();
const mockConnect = jest.fn().mockResolvedValue({
  query:   mockQuery,
  release: mockRelease,
});

jest.mock('../db/pool', () => ({
  pool:      { connect: mockConnect, on: jest.fn() },
  closePool: jest.fn().mockResolvedValue(undefined),
}));

const { getUserById, getAllUsers, searchUsers } = require('../db/queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Build a fake pg QueryResult. */
function fakeResult(rows) {
  return { rows, rowCount: rows.length };
}

/** Build a fake user row (includes total_count as the window fn would add). */
function fakeUserRow(overrides = {}) {
  return {
    id:          1,
    name:        'Alice',
    email:       'alice@example.com',
    created_at:  new Date('2024-01-01'),
    total_count: '1',
    ...overrides,
  };
}

// ---------------------------------------------------------------------------
// Setup / teardown
// ---------------------------------------------------------------------------
beforeEach(() => {
  jest.clearAllMocks();
  // Spy on console.log / console.error to verify timing output without noise.
  jest.spyOn(console, 'log').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  console.log.mockRestore();
  console.error.mockRestore();
});

// ===========================================================================
// getUserById
// ===========================================================================
describe('getUserById', () => {
  test('returns the user row when found', async () => {
    const row = fakeUserRow();
    mockQuery.mockResolvedValueOnce(fakeResult([row]));

    const user = await getUserById(1);

    expect(user).toEqual(row);
  });

  test('returns null when no row is found', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const user = await getUserById(999);

    expect(user).toBeNull();
  });

  test('sends id as a parameterised argument — never interpolated', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([fakeUserRow()]));

    await getUserById(42);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([42]);
    // The raw number must not appear literally inside the SQL string.
    expect(sql).not.toContain('42');
    expect(sql).toContain('$1');
  });

  test('always releases the pool client on success', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([fakeUserRow()]));
    await getUserById(1);
    expect(mockRelease).toHaveBeenCalledTimes(1);
  });

  test('always releases the pool client on DB error', async () => {
    mockQuery.mockRejectedValueOnce(new Error('DB down'));
    await expect(getUserById(1)).rejects.toThrow('DB down');
    expect(mockRelease).toHaveBeenCalledTimes(1);
  });

  test('emits a timing log on success', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([fakeUserRow()]));
    await getUserById(1);
    const logCall = console.log.mock.calls.find(([msg]) =>
      msg.includes('getUserById')
    );
    expect(logCall).toBeDefined();
    expect(logCall[0]).toMatch(/status=ok/);
    expect(logCall[0]).toMatch(/duration=\d+\.\d+ms/);
  });

  test('emits an error timing log on failure', async () => {
    mockQuery.mockRejectedValueOnce(new Error('timeout'));
    await expect(getUserById(1)).rejects.toThrow();
    const logCall = console.error.mock.calls.find(([msg]) =>
      msg.includes('getUserById')
    );
    expect(logCall).toBeDefined();
    expect(logCall[0]).toMatch(/status=error/);
  });

  // --- input validation ---
  test.each([
    ['string "abc"',    'abc'],
    ['float 1.5',        1.5],
    ['zero',             0],
    ['negative',        -1],
    ['NaN',             NaN],
    ['object',          {}],
    ['SQL fragment',    '1 OR 1=1'],
  ])('throws TypeError for invalid id: %s', async (_, badId) => {
    await expect(getUserById(badId)).rejects.toThrow(TypeError);
    // Must not reach the DB.
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

// ===========================================================================
// getAllUsers
// ===========================================================================
describe('getAllUsers', () => {
  test('returns users array and total count', async () => {
    const rows = [
      fakeUserRow({ id: 1, total_count: '2' }),
      fakeUserRow({ id: 2, name: 'Bob', email: 'bob@example.com', total_count: '2' }),
    ];
    mockQuery.mockResolvedValueOnce(fakeResult(rows));

    const { users, total } = await getAllUsers(10, 0);

    expect(total).toBe(2);
    expect(users).toHaveLength(2);
    // total_count should be stripped from individual user objects.
    expect(users[0]).not.toHaveProperty('total_count');
  });

  test('returns empty page with total 0 when table is empty', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const { users, total } = await getAllUsers(10, 0);

    expect(users).toEqual([]);
    expect(total).toBe(0);
  });

  test('binds limit and offset as positional parameters', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await getAllUsers(25, 50);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([25, 50]);
    expect(sql).toContain('$1');
    expect(sql).toContain('$2');
    // Raw numbers must not appear inside the SQL string.
    expect(sql).not.toContain('25');
    expect(sql).not.toContain('50');
  });

  test('always releases pool client on success', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await getAllUsers(10, 0);
    expect(mockRelease).toHaveBeenCalledTimes(1);
  });

  test('always releases pool client on DB error', async () => {
    mockQuery.mockRejectedValueOnce(new Error('DB error'));
    await expect(getAllUsers(10, 0)).rejects.toThrow();
    expect(mockRelease).toHaveBeenCalledTimes(1);
  });

  test('emits timing log', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await getAllUsers(10, 0);
    const logCall = console.log.mock.calls.find(([m]) => m.includes('getAllUsers'));
    expect(logCall?.[0]).toMatch(/status=ok/);
  });

  // --- limit validation ---
  test.each([
    ['zero',          0,   0],
