/**
 * db/pool.js
 *
 * Creates and exports a single shared pg connection pool for the entire
 * application. Importing this module multiple times always returns the same
 * pool instance (Node's module cache guarantees this).
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials are ever hard-coded in source. Copy .env.example to .env and
 * fill in real values before starting the server.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate that the minimum required environment variables are present before
// attempting to create the pool. Failing fast here gives a clear error message
// rather than a cryptic connection-refused later.
// ---------------------------------------------------------------------------
const REQUIRED_ENV = ['DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_USER', 'DB_PASSWORD'];

const missing = REQUIRED_ENV.filter((key) => !process.env[key]);
if (missing.length > 0) {
  throw new Error(
    `Missing required database environment variables: ${missing.join(', ')}.\n` +
      'Copy .env.example to .env and supply the correct values.'
  );
}

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
const poolConfig = {
  host:     process.env.DB_HOST,
  port:     Number(process.env.DB_PORT) || 5432,
  database: process.env.DB_NAME,
  user:     process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Use SSL in non-test environments unless explicitly disabled.
  ssl:
    process.env.NODE_ENV === 'test' || process.env.DB_SSL === 'false'
      ? false
      : { rejectUnauthorized: process.env.DB_SSL_REJECT_UNAUTHORIZED !== 'false' },

  // Connection pool sizing — tune via env for different deployment targets.
  max:              Number(process.env.DB_POOL_MAX)      || 10,  // max open connections
  min:              Number(process.env.DB_POOL_MIN)      || 2,   // keep-alive floor
  idleTimeoutMillis: Number(process.env.DB_IDLE_TIMEOUT) || 30_000,
  connectionTimeoutMillis: Number(process.env.DB_CONNECT_TIMEOUT) || 5_000,

  // Surface the application name in pg_stat_activity for easier DBA triage.
  application_name: process.env.APP_NAME || 'express-app',
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers
// ---------------------------------------------------------------------------

// Unhandled errors on idle clients must be caught here or they will crash the
// process (pg fires these outside of any query promise chain).
pool.on('error', (err, client) => {
  console.error('[pool] Unexpected error on idle client', {
    message: err.message,
    // Intentionally omit err.stack in production to avoid leaking internals.
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
  // Do NOT call process.exit() — let the pool recover by creating a new client.
});

pool.on('connect', () => {
  if (process.env.NODE_ENV !== 'production') {
    console.debug('[pool] New client connected. Total pool size:', pool.totalCount);
  }
});

pool.on('remove', () => {
  if (process.env.NODE_ENV !== 'production') {
    console.debug('[pool] Client removed. Total pool size:', pool.totalCount);
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper — call this from your SIGTERM handler so that all
// in-flight queries finish before the process exits.
// ---------------------------------------------------------------------------
async function closePool() {
  console.log('[pool] Draining connection pool…');
  await pool.end();
  console.log('[pool] All connections closed.');
}

