    expect(text).toContain('$1');
  });

  test('returns null when no user is found', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const user = await getUserById(999);

    expect(user).toBeNull();
  });

  test('rejects a non-integer id with TypeError', async () => {
    await expect(getUserById('abc')).rejects.toThrow(TypeError);
    await expect(getUserById('abc')).rejects.toThrow("'id' must be an integer");
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a SQL-injection attempt in the id field', async () => {
    // "1; DROP TABLE users--" is not an integer → TypeError before DB is called.
    await expect(getUserById('1; DROP TABLE users--')).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects id = 0 (below minimum of 1)', async () => {
    await expect(getUserById(0)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a negative id', async () => {
    await expect(getUserById(-5)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('propagates database errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('connection refused'));
    await expect(getUserById(1)).rejects.toThrow('connection refused');
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// getAllUsers
// ═══════════════════════════════════════════════════════════════════════════

describe('getAllUsers', () => {
  const ROWS = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), updated_at: new Date() },
  ];

  test('returns users and total count', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(withTotal(ROWS, 50)));

    const { users, total } = await getAllUsers(10, 0);

