    users.forEach((u) => expect(u).not.toHaveProperty('total_count'));
  });

  test('passes limit and offset as bound parameters', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(withTotal(ROWS, 2)));

    await getAllUsers(10, 20);

    const { text, values } = mockQuery.mock.calls[0][0];
    expect(values).toEqual([10, 20]);
    expect(text).toContain('$1');
    expect(text).toContain('$2');
