    expect(text).not.toMatch(/\bLIMIT\s+10\b/);
    expect(text).not.toMatch(/\bOFFSET\s+20\b/);
  });

  test('uses default limit=20 and offset=0', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await getAllUsers();

    const { values } = mockQuery.mock.calls[0][0];
    expect(values).toEqual([20, 0]);
  });

  test('returns empty list and total=0 when no rows exist', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const { users, total } = await getAllUsers();

    expect(users).toEqual([]);
    expect(total).toBe(0);
  });

  test('rejects limit > MAX_LIMIT (200)', async () => {
    await expect(getAllUsers(201, 0)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects limit = 0', async () => {
    await expect(getAllUsers(0, 0)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a non-integer limit', async () => {
    await expect(getAllUsers('ten', 0)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a negative offset', async () => {
    await expect(getAllUsers(20, -1)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects SQL injection in limit', async () => {
    await expect(getAllUsers('10; DROP TABLE users--', 0)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
