// ═══════════════════════════════════════════════════════════════════════════
// searchUsers
// ═══════════════════════════════════════════════════════════════════════════

describe('searchUsers', () => {
  const ROWS = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
  ];

  test('returns matching users and total', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(withTotal(ROWS, 1)));

    const { users, total } = await searchUsers('alice');

    expect(users).toHaveLength(1);
    expect(total).toBe(1);
    users.forEach((u) => expect(u).not.toHaveProperty('total_count'));
  });

  test('passes the ILIKE pattern and pagination as bound parameters', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(withTotal(ROWS, 1)));

    await searchUsers('alice', 5, 10);

    const { text, values } = mockQuery.mock.calls[0][0];
    // $1 = '%alice%', $2 = 5, $3 = 10
    expect(values).toEqual(['%alice%', 5, 10]);
    expect(text).toContain('$1');
    expect(text).toContain('$2');
    expect(text).toContain('$3');
    // Literal search term must not appear in the SQL text.
    expect(text).not.toContain('alice');
  });

  test('SQL injection in query string is treated as a literal search term', async () => {
    // The injection payload is valid as a search string (≤200 chars, non-empty).
    // It must be forwarded as a parameter — never interpolated into SQL.
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const injection = "' OR '1'='1";
    await searchUsers(injection);

    const { text, values } = mockQuery.mock.calls[0][0];
    // The pattern should be wrapped in % wildcards and passed as $1.
    expect(values[0]).toBe(`%${injection}%`);
    // The raw string must not appear in the SQL text itself.
    expect(text).not.toContain(injection);
    expect(text).not.toContain("'1'='1");
  });

  test('SQL injection with semicolon is treated as a literal search term', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const injection = "alice'; DROP TABLE users; --";
    await searchUsers(injection);

    const { values } = mockQuery.mock.calls[0][0];
    expect(values[0]).toBe(`%${injection}%`);
  });

  test('rejects an empty query string', async () => {
    await expect(searchUsers('')).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a non-string query', async () => {
    await expect(searchUsers(123)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a query string longer than 200 characters', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('accepts a query string of exactly 200 characters', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await expect(searchUsers('a'.repeat(200))).resolves.toEqual({ users: [], total: 0 });
  });

  test('returns empty result when no matches found', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const { users, total } = await searchUsers('zzznomatch');

    expect(users).toEqual([]);
    expect(total).toBe(0);
  });

  test('propagates database errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('timeout'));
    await expect(searchUsers('alice')).rejects.toThrow('timeout');
  });
});

