/**
 * db/pool.js
 *
 * Creates and exports a single shared pg connection pool for the entire
 * application. Importing this module multiple times always returns the same
 * pool instance (Node's module cache guarantees this).
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials are ever hard-coded in source. Copy .env.example to .env and
 * fill in real values before starting the server.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate that the minimum required environment variables are present before
// attempting to create the pool. Failing fast here gives a clear error message
// rather than a cryptic connection-refused later.
// ---------------------------------------------------------------------------
const REQUIRED_ENV = ['DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_USER', 'DB_PASSWORD'];

const missing = REQUIRED_ENV.filter((key) => !process.env[key]);
if (missing.length > 0) {
  throw new Error(
    `Missing required database environment variables: ${missing.join(', ')}.\n` +
      'Copy .env.example to .env and supply the correct values.'
  );
}

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
const poolConfig = {
  host:     process.env.DB_HOST,
  port:     Number(process.env.DB_PORT) || 5432,
  database: process.env.DB_NAME,
  user:     process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Use SSL in non-test environments unless explicitly disabled.
  ssl:
    process.env.NODE_ENV === 'test' || process.env.DB_SSL === 'false'
      ? false
      : { rejectUnauthorized: process.env.DB_SSL_REJECT_UNAUTHORIZED !== 'false' },

  // Connection pool sizing — tune via env for different deployment targets.
  max:              Number(process.env.DB_POOL_MAX)      || 10,  // max open connections
  min:              Number(process.env.DB_POOL_MIN)      || 2,   // keep-alive floor
  idleTimeoutMillis: Number(process.env.DB_IDLE_TIMEOUT) || 30_000,
  connectionTimeoutMillis: Number(process.env.DB_CONNECT_TIMEOUT) || 5_000,

  // Surface the application name in pg_stat_activity for easier DBA triage.
  application_name: process.env.APP_NAME || 'express-app',
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers
// ---------------------------------------------------------------------------

// Unhandled errors on idle clients must be caught here or they will crash the
// process (pg fires these outside of any query promise chain).
pool.on('error', (err, client) => {
  console.error('[pool] Unexpected error on idle client', {
    message: err.message,
    // Intentionally omit err.stack in production to avoid leaking internals.
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
  // Do NOT call process.exit() — let the pool recover by creating a new client.
});

pool.on('connect', () => {
  if (process.env.NODE_ENV !== 'production') {
    console.debug('[pool] New client connected. Total pool size:', pool.totalCount);
  }
});

pool.on('remove', () => {
  if (process.env.NODE_ENV !== 'production') {
    console.debug('[pool] Client removed. Total pool size:', pool.totalCount);
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper — call this from your SIGTERM handler so that all
// in-flight queries finish before the process exits.
// ---------------------------------------------------------------------------
async function closePool() {
  console.log('[pool] Draining connection pool…');
  await pool.end();
  console.log('[pool] All connections closed.');
}

module.exports = { pool, closePool };

/**
 * db/queries.js
 *
 * Parameterised query functions for the /users resource.
 *
 * Security guarantees
 * ───────────────────
 * • Every external value is passed as a positional parameter ($1, $2, …) via
 *   pg's parameterised-query interface. The pg driver sends the query text and
 *   the parameter list to PostgreSQL in *separate protocol messages*, so the
 *   database server never interpolates user input into SQL text. This is the
 *   canonical defence against SQL injection and is enforced at the protocol
 *   level, not just by string escaping.
 *
 * • Integer parameters (id, limit, offset) are coerced and range-checked in
 *   JavaScript *before* being forwarded to the database. This prevents
 *   malformed inputs (e.g. "1; DROP TABLE users") from reaching the query at all.
 *
 * • The search query string is validated for maximum length to prevent
 *   resource-exhaustion via enormous ILIKE patterns.
 *
 * • No raw string concatenation is used anywhere in this file.
 *
 * Performance / observability
 * ───────────────────────────
 * • Every query is wrapped in queryWithTiming(), which records wall-clock
 *   duration and logs it with contextual metadata.
 *
 * • Slow queries (> SLOW_QUERY_THRESHOLD_MS) are logged at WARN level so they
 *   can be spotted without enabling full query logs in production.
 *
 * • Pool connections are acquired and released automatically via pool.query().
 *   Explicit client checkout (pool.connect()) is only used when a transaction
 *   spans multiple statements.
 */

'use strict';

const { pool } = require('./pool');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Queries slower than this value (ms) are logged as warnings. */
const SLOW_QUERY_THRESHOLD_MS = Number(process.env.SLOW_QUERY_THRESHOLD_MS) || 200;

/** Hard upper bound on LIMIT to prevent accidental full-table scans. */
const MAX_LIMIT = 200;

/** Hard upper bound on the length of a search term. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Executes a parameterised query via the shared pool, measures its duration,
 * and emits structured timing logs.
 *
 * @param {string}   queryName  - Human-readable label used in log output.
 * @param {string}   text       - SQL query text with $n placeholders.
 * @param {Array}    params     - Positional parameter values (never interpolated).
 * @returns {Promise<import('pg').QueryResult>}
 */
async function queryWithTiming(queryName, text, params = []) {
  const startTime = process.hrtime.bigint();  // nanosecond precision

  try {
    const result = await pool.query({ text, values: params });

    const durationMs = Number(process.hrtime.bigint() - startTime) / 1_000_000;
    const logLevel   = durationMs > SLOW_QUERY_THRESHOLD_MS ? 'warn' : 'info';

    console[logLevel](`[query:${logLevel === 'warn' ? 'SLOW' : 'ok'}] ${queryName}`, {
      durationMs:   durationMs.toFixed(3),
      rowCount:     result.rowCount,
      paramCount:   params.length,
      ...(logLevel === 'warn' && { threshold: SLOW_QUERY_THRESHOLD_MS }),
    });

    return result;

  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - startTime) / 1_000_000;

    console.error(`[query:error] ${queryName}`, {
      durationMs: durationMs.toFixed(3),
      // Expose full error detail in non-production only to avoid leaking schema info.
      ...(process.env.NODE_ENV !== 'production'
        ? { message: err.message, code: err.code }
        : { code: err.code }),
    });

    // Re-throw so callers (route handlers) can return the correct HTTP status.
    throw err;
  }
}

/**
 * Validates and coerces a value to a safe integer within [min, max].
 * Throws a TypeError with a descriptive message if validation fails.
 *
 * @param {*}      value   - Raw (potentially user-supplied) value.
 * @param {string} name    - Parameter name for error messages.
 * @param {number} min     - Inclusive lower bound.
 * @param {number} max     - Inclusive upper bound.
 * @returns {number}
 */
function toSafeInt(value, name, min, max) {
  const n = Number(value);

  if (!Number.isInteger(n)) {
    throw new TypeError(`'${name}' must be an integer, received: ${JSON.stringify(value)}`);
  }
  if (n < min || n > max) {
    throw new RangeError(`'${name}' must be between ${min} and ${max}, received: ${n}`);
  }

  return n;
}

/**
 * Validates a search query string.
 * Throws a TypeError if validation fails.
 *
 * @param {*} value - Raw (potentially user-supplied) value.
 * @returns {string}
 */
function toSafeSearchString(value) {
  if (typeof value !== 'string') {
    throw new TypeError(`'query' must be a string, received: ${typeof value}`);
  }
  if (value.length === 0) {
    throw new TypeError("'query' must not be empty.");
  }
  if (value.length > MAX_SEARCH_LENGTH) {
    throw new RangeError(
      `'query' must be ${MAX_SEARCH_LENGTH} characters or fewer, received: ${value.length}`
    );
  }

  return value;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Retrieves a single user by their primary-key ID.
 *
 * The id is cast to an integer before being passed as a parameter, so values
 * like "1; DROP TABLE users--" are rejected outright with a TypeError before
 * they ever reach the database.
 *
 * @param {number|string} id - The user's integer primary key.
 * @returns {Promise<Object|null>} The user row, or null if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   // => { id: 42, name: 'Alice', email: 'alice@example.com', created_at: … }
 */
async function getUserById(id) {
  // Validate: must be a positive integer.
  const safeId = toSafeInt(id, 'id', 1, Number.MAX_SAFE_INTEGER);

  const text = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  // $1 is bound to safeId — pg sends it as a separate parameter, never
  // interpolated into the SQL string.
  const result = await queryWithTiming('getUserById', text, [safeId]);

  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users ordered by ID.
 *
 * Both limit and offset are coerced to integers and clamped to safe ranges,
 * then passed as separate query parameters so they cannot be used to inject
 * arbitrary SQL.
 *
 * @param {number} [limit=20]   - Maximum rows to return (1–200).
 * @param {number} [offset=0]   - Number of rows to skip (≥ 0).
 * @returns {Promise<{ users: Object[], total: number }>}
 *          users — the current page of user rows
 *          total — the total number of users (for building pagination metadata)
 *
 * @example
 *   const { users, total } = await getAllUsers(10, 20);
 */
async function getAllUsers(limit = 20, offset = 0) {
  // Validate & coerce.
  const safeLimit  = toSafeInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // Fetch the current page and the total count in a single round-trip using a
  // window function.  This avoids issuing two separate queries and the TOCTOU
  // race that would come with them.
  const text = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  // $1 → safeLimit, $2 → safeOffset (both integers, bound as parameters).
  const result = await queryWithTiming('getAllUsers', text, [safeLimit, safeOffset]);

  const total = result.rows.length > 0 ? Number(result.rows[0].total_count) : 0;

  // Strip the synthetic total_count column from every row before returning.
  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total };
}

/**
 * Full-text search across user names and email addresses.
 *
 * The search term is wrapped in `%…%` wildcards for a case-insensitive ILIKE
 * match.  Critically, the wildcard wrapping is done *in JavaScript* before the
 * value is placed into the parameter array — it is never concatenated into the
 * SQL string — so the database still receives the search term as a bound
 * parameter.  A user who sends `%' OR '1'='1` will simply get an ILIKE match
 * against that literal string.
 *
 * @param {string} query         - The search term (1–200 characters).
 * @param {number} [limit=20]    - Maximum rows to return (1–200).
 * @param {number} [offset=0]    - Number of rows to skip (≥ 0).
 * @returns {Promise<{ users: Object[], total: number }>}
 *
 * @example
 *   const { users, total } = await searchUsers('alice', 5, 0);
 */
async function searchUsers(query, limit = 20, offset = 0) {
  // Validate all inputs before touching the database.
  const safeQuery  = toSafeSearchString(query);
  const safeLimit  = toSafeInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // Build the ILIKE pattern in JS — it is passed as a *parameter*, not
  // concatenated into the query string.
  const pattern = `%${safeQuery}%`;

  const text = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  // $1 → pattern (ILIKE), $2 → safeLimit, $3 → safeOffset.
  const result = await queryWithTiming('searchUsers', text, [pattern, safeLimit, safeOffset]);

  const total = result.rows.length > 0 ? Number(result.rows[0].total_count) : 0;

  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total };

/**
 * app.js
 *
 * Express application entry point.
 *
 * /users routes now delegate all data access to the parameterised query
 * functions in db/queries.js, which use connection pooling (db/pool.js) and
 * never interpolate user input into SQL strings.
 */

'use strict';

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./db/queries');
const { closePool } = require('./db/pool');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps a route handler so that any thrown error (including async rejections)
 * is forwarded to Express's error middleware via next().
 *
 * @param {Function} fn - async (req, res, next) => …
 */
const asyncHandler = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

/**
 * Parses and returns a safe integer query-string parameter, falling back to
 * `defaultValue` when the parameter is absent.  Returns NaN when the value is
 * present but cannot be parsed so the route handler can return 400.
 *
 * @param {string|undefined} raw          - req.query value (always a string or undefined).
 * @param {number}           defaultValue - Value to use when raw is undefined.
 * @returns {number}
 */
function parseIntParam(raw, defaultValue) {
  if (raw === undefined) return defaultValue;
  const n = Number(raw);
  return Number.isInteger(n) ? n : NaN;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/** GET /health — simple liveness probe */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── GET /users ──────────────────────────────────────────────────────────────
//
//   Returns a paginated list of all users.
//
//   Query parameters:
//     limit  (integer, 1–200, default 20)  — page size
//     offset (integer, ≥ 0,   default  0)  — number of rows to skip
//
//   Example:  GET /users?limit=10&offset=20
// ────────────────────────────────────────────────────────────────────────────
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    const limit  = parseIntParam(req.query.limit,  20);
    const offset = parseIntParam(req.query.offset,  0);

    if (isNaN(limit) || isNaN(offset)) {
      return res.status(400).json({
        error: 'Bad Request',
        message: "'limit' and 'offset' must be integers.",
      });
    }

    const { users, total } = await getAllUsers(limit, offset);

    res.json({
      data:       users,
      pagination: {
        total,
        limit,
        offset,
        hasMore: offset + users.length < total,
      },
    });
  })
);

// ── GET /users/search ────────────────────────────────────────────────────────
//
//   Case-insensitive search across user name and email.
//
//   Query parameters:
//     q      (string,  required)            — search term
//     limit  (integer, 1–200, default 20)   — page size
//     offset (integer, ≥ 0,   default  0)   — number of rows to skip
//
//   Example:  GET /users/search?q=alice&limit=5
//
//   IMPORTANT: this route must be defined BEFORE /users/:id so that the
//   literal path segment "search" is not mistakenly treated as an id.
// ────────────────────────────────────────────────────────────────────────────
app.get(
  '/users/search',
  asyncHandler(async (req, res) => {
    const { q } = req.query;

    if (!q || typeof q !== 'string' || q.trim().length === 0) {
      return res.status(400).json({
        error:   'Bad Request',
        message: "Query parameter 'q' is required and must be a non-empty string.",
      });
    }

    const limit  = parseIntParam(req.query.limit,  20);
    const offset = parseIntParam(req.query.offset,  0);

    if (isNaN(limit) || isNaN(offset)) {
      return res.status(400).json({
        error: 'Bad Request',
        message: "'limit' and 'offset' must be integers.",
      });
    }

    const { users, total } = await searchUsers(q.trim(), limit, offset);

    res.json({
      data:       users,
      query:      q.trim(),
      pagination: {
        total,
        limit,
        offset,
        hasMore: offset + users.length < total,
      },
    });
  })
);

// ── GET /users/:id ───────────────────────────────────────────────────────────
//
//   Returns a single user by integer primary key.
//
//   Example:  GET /users/42
// ────────────────────────────────────────────────────────────────────────────
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const rawId = req.params.id;

    // Reject non-integer id values before they reach the query layer.
    if (!/^\d+$/.test(rawId)) {
      return res.status(400).json({
        error:   'Bad Request',
        message: `'id' must be a positive integer, received: ${JSON.stringify(rawId)}`,
      });
    }

    const user = await getUserById(rawId);

    if (!user) {
      return res.status(404).json({
        error:   'Not Found',
        message: `No user found with id ${rawId}.`,
      });
    }

    res.json({ data: user });
  })
);

// ---------------------------------------------------------------------------
// Global error handler
// ---------------------------------------------------------------------------

// Catch validation errors thrown by the query layer and translate them to
// HTTP 400 responses so the client gets a clear message.  All other errors
// become 500.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  if (err instanceof TypeError || err instanceof RangeError) {
    return res.status(400).json({
      error:   'Bad Request',
      message: err.message,
    });
  }

  // Log unexpected errors but do NOT expose internal detail to the client.
  console.error('[app:error]', {
    method: req.method,
    path:   req.path,
    ...(process.env.NODE_ENV !== 'production'
      ? { message: err.message, stack: err.stack }
      : {}),
  });

  res.status(500).json({
    error:   'Internal Server Error',
    message: 'An unexpected error occurred. Please try again later.',
  });
});

// ---------------------------------------------------------------------------
// Server startup & graceful shutdown
// ---------------------------------------------------------------------------

const PORT = Number(process.env.PORT) || 3000;

// Only start listening when this file is run directly (not when it is
// require()'d by a test suite).
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} [${process.env.NODE_ENV ?? 'development'}]`);
  });

  // Graceful shutdown: finish in-flight requests, then drain the DB pool.
  const shutdown = async (signal) => {
    console.log(`\n[app] ${signal} received — shutting down gracefully…`);
    server.close(async () => {
      await closePool();
      process.exit(0);
    });
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT',  () => shutdown('SIGINT'));
}

module.exports = app;

/**
 * tests/queries.test.js
 *
 * Unit tests for db/queries.js.
 *
 * The PostgreSQL pool is fully mocked so these tests run without a real
 * database.  Every test exercises:
 *   1. The SQL that would be sent (text + params)
 *   2. Input validation / SQL-injection prevention
 *   3. Edge-case behaviour (not-found, empty result-set, …)
 *
 * Run with:  npx jest  (or: node --test  if you prefer the built-in runner)
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the pool BEFORE requiring queries.js, so the module gets the mock.
// ---------------------------------------------------------------------------
const mockQuery = jest.fn();

jest.mock('../db/pool', () => ({
  pool:      { query: mockQuery },
  closePool: jest.fn().mockResolvedValue(undefined),
}));

// Also stub env vars that pool.js validates at load time.
process.env.DB_HOST     = 'localhost';
process.env.DB_PORT     = '5432';
process.env.DB_NAME     = 'test_db';
process.env.DB_USER     = 'test_user';
process.env.DB_PASSWORD = 'test_pass';
process.env.NODE_ENV    = 'test';

const { getUserById, getAllUsers, searchUsers } = require('../db/queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Builds a fake pg QueryResult. */
function fakeResult(rows) {
  return {
    rows,
    rowCount: rows.length,
    // Mimic the window-function total_count field.
    ...(rows.length > 0 && rows[0].total_count === undefined
      ? {}
      : {}),
  };
}

/** Adds total_count to every row (mirrors the window-function column). */
function withTotal(rows, total) {
  return rows.map((r) => ({ ...r, total_count: String(total) }));
}

