// ═══════════════════════════════════════════════════════════════════════════
// getUserById
// ═══════════════════════════════════════════════════════════════════════════

describe('getUserById', () => {
  const ROW = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() };

  test('returns the user row when found', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([ROW]));

    const user = await getUserById(1);

    expect(user).toEqual(ROW);
  });

  test('passes id as a bound parameter ($1), not interpolated', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([ROW]));

    await getUserById(42);

    const { text, values } = mockQuery.mock.calls[0][0];
    expect(values).toEqual([42]);
    // The SQL text must not contain the literal "42".
    expect(text).not.toContain('42');
    expect(text).toContain('$1');
  });

  test('returns null when no user is found', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const user = await getUserById(999);

    expect(user).toBeNull();
  });

  test('rejects a non-integer id with TypeError', async () => {
    await expect(getUserById('abc')).rejects.toThrow(TypeError);
    await expect(getUserById('abc')).rejects.toThrow("'id' must be an integer");
    expect(mockQuery).not.toHaveBeenCalled();
  });

