'use strict';

/**
 * db.js — PostgreSQL connection pool
 *
 * A single Pool instance is created once and reused across the entire
 * process lifetime.  The pool is configured entirely from environment
 * variables so that no credentials ever appear in source code.
 *
 * Environment variables (set in .env or the host environment):
 *   DATABASE_URL  – full connection string  (preferred)
 *     OR individual variables:
 *   PGHOST, PGPORT, PGDATABASE, PGUSER, PGPASSWORD
 *
 * Optional tuning variables:
 *   DB_POOL_MAX          – maximum pool size          (default: 10)
 *   DB_POOL_IDLE_TIMEOUT – ms before idle client ends (default: 30000)
 *   DB_CONN_TIMEOUT      – ms to wait for connection  (default: 5000)
 *   DB_STATEMENT_TIMEOUT – ms before query is aborted (default: 10000)
 *   NODE_ENV             – set to "test" to suppress pool-event noise
 */

const { Pool } = require('pg');
require('dotenv').config();

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------

const poolConfig = {
  // Accept a full DATABASE_URL or individual PG* variables (node-postgres
  // also reads the standard PG* env vars automatically, but being explicit
  // makes the intent clear).
  connectionString: process.env.DATABASE_URL || undefined,

  // Tunable limits – all sourced from environment variables with safe defaults.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT ?? '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT ?? '5000', 10),

  // Enforce a per-query statement timeout at the server level so that a
  // runaway query cannot hold a connection indefinitely.
  statement_timeout: parseInt(process.env.DB_STATEMENT_TIMEOUT ?? '10000', 10),

  // Always use SSL in production; skip certificate validation only when
  // NODE_ENV is explicitly set to "development" or "test".
  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : process.env.DATABASE_URL
      ? { rejectUnauthorized: false }
      : undefined,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

const silent = process.env.NODE_ENV === 'test';

pool.on('connect', (client) => {
  if (!silent) {
    console.log(
      `[DB Pool] New client connected (pool size: ${pool.totalCount})`
    );
  }

  // Belt-and-suspenders: set statement_timeout for every new connection so
  // that even connections obtained outside our query helpers are protected.
  client.query(
    `SET statement_timeout = ${poolConfig.statement_timeout}`
  ).catch((err) => {
    console.error('[DB Pool] Failed to set statement_timeout on client:', err.message);
  });
});

pool.on('acquire', () => {
  if (!silent) {
    console.log(
      `[DB Pool] Client acquired ` +
      `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
    );
  }
});

pool.on('remove', () => {
  if (!silent) {
    console.log(
      `[DB Pool] Client removed (pool size: ${pool.totalCount})`
    );
  }
});

// Surface unexpected pool-level errors so they are never silently swallowed.
pool.on('error', (err) => {
  console.error('[DB Pool] Unexpected error on idle client:', err.message);
  // Do NOT call process.exit() here – let the application decide how to
  // handle persistent pool failures.
});

// ---------------------------------------------------------------------------
// Exported helpers
// ---------------------------------------------------------------------------

/**
 * Execute a parameterised query and return the full pg QueryResult.
 *
 * @param {string}  text   – SQL string with $1, $2 … placeholders
 * @param {Array}   params – Ordered parameter values (never interpolated)
 * @returns {Promise<import('pg').QueryResult>}
 */
async function query(text, params = []) {
  const client = await pool.connect();
  try {
    return await client.query(text, params);
  } finally {
    client.release();
  }
}

/**
 * Acquire a client from the pool for use in multi-statement transactions.
 * The caller is responsible for calling client.release() in a finally block.
 *
 * @returns {Promise<import('pg').PoolClient>}
 */
async function getClient() {
  return pool.connect();
}

/**
 * Gracefully drain and shut down the pool.
 * Call this during application shutdown (e.g. SIGTERM handler).
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  await pool.end();
  if (!silent) {
    console.log('[DB Pool] Pool closed.');
  }
}

module.exports = { query, getClient, closePool, pool };

'use strict';

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Security posture
 * ────────────────
 * • Every value that originates from user input is passed as a bound
 *   parameter ($1, $2, …) – never interpolated into the SQL string.
 *   node-postgres sends parameters to PostgreSQL over the wire separately
 *   from the query text, so the database driver itself prevents SQL injection
 *   at the protocol level.
 * • LIMIT and OFFSET are cast to integers and clamped to safe ranges before
 *   being forwarded, providing a second layer of defence for numeric inputs.
 * • Free-text search terms are passed as parameters to the ILIKE operator;
 *   the only characters that need escaping within an ILIKE pattern are the
 *   SQL wildcard metacharacters (%, _) and the escape character itself (\).
 *   These are escaped before the value is handed to the query.
 * • Column and table names are never derived from user input.
 *
 * Query timing
 * ────────────
 * Every function records a high-resolution start time with process.hrtime.bigint()
 * and emits a structured log line after each query regardless of success or
 * failure.  The log includes the function name, parameter arity (never the
 * parameter values), duration in milliseconds, and whether the query succeeded.
 */

const { query } = require('./db');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Emit a structured timing log for a completed query.
 *
 * @param {string}  fnName    – name of the calling query function
 * @param {bigint}  startNs   – nanosecond timestamp from process.hrtime.bigint()
 * @param {boolean} success   – true when the query returned without throwing
 * @param {object}  [meta={}] – optional additional context (row count, etc.)
 */
function logQueryTiming(fnName, startNs, success, meta = {}) {
  const durationMs = Number(process.hrtime.bigint() - startNs) / 1_000_000;
  const status = success ? 'OK' : 'ERROR';
  const metaStr = Object.keys(meta).length
    ? ' | ' + Object.entries(meta).map(([k, v]) => `${k}=${v}`).join(', ')
    : '';

  console.log(
    `[Query] fn=${fnName} status=${status} duration=${durationMs.toFixed(3)}ms${metaStr}`
  );
}

/**
 * Cast a value to a safe integer.
 *
 * @param {*}      value    – raw input value
 * @param {number} fallback – value to use when input is not a finite integer
 * @param {number} min      – inclusive lower bound
 * @param {number} max      – inclusive upper bound
 * @returns {number}
 */
function toSafeInt(value, fallback, min, max) {
  const n = parseInt(value, 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(Math.max(n, min), max);
}

/**
 * Escape SQL ILIKE wildcard metacharacters in a search string.
 *
 * Characters escaped: \ (escape char), % (match any sequence), _ (match one)
 * The escaped string is then wrapped with leading/trailing % wildcards so
 * that it becomes a "contains" pattern.
 *
 * @param {string} raw – the raw search term provided by the caller
 * @returns {string}   – a safe ILIKE pattern, e.g. "%foo\%bar%"
 */
function toLikePattern(raw) {
  const escaped = String(raw)
    .replace(/\\/g, '\\\\') // must be first: escape the escape character
    .replace(/%/g, '\\%')   // escape literal percent
    .replace(/_/g, '\\_');  // escape literal underscore
  return `%${escaped}%`;
}

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

/**
 * Throw a well-typed error for invalid inputs so that callers can
 * distinguish validation failures from database failures.
 *
 * @param {string} message
 */
function validationError(message) {
  const err = new Error(message);
  err.code = 'VALIDATION_ERROR';
  return err;
}

// ---------------------------------------------------------------------------
// Query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user row by primary key.
 *
 * SELECT columns are explicit (no SELECT *) to avoid inadvertently exposing
 * new columns added to the table in the future (e.g. password_hash).
 *
 * @param {number|string} id – the user's numeric primary key
 * @returns {Promise<object|null>} the user object, or null if not found
 *
 * @throws {Error} with code VALIDATION_ERROR when id is not a positive integer
 * @throws {Error} on database failure
 *
 * @example
 *   const user = await getUserById(42);
 *   // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: Date }
 */
async function getUserById(id) {
  // --- Input validation -------------------------------------------------------
  const safeId = parseInt(id, 10);
  if (!Number.isFinite(safeId) || safeId <= 0) {
    throw validationError(`getUserById: id must be a positive integer, got: ${id}`);
  }

  // --- Query ------------------------------------------------------------------
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const startNs = process.hrtime.bigint();
  let success = false;

  try {
    const result = await query(sql, [safeId]);
    success = true;
    logQueryTiming('getUserById', startNs, success, { rows: result.rowCount });
    return result.rows[0] ?? null;
  } catch (err) {
    logQueryTiming('getUserById', startNs, success, { error: err.message });
    throw err;
  }
}

/**
 * Fetch a paginated list of users, ordered by id ascending.
 *
 * @param {number} [limit=20]  – maximum number of rows to return (1 – 100)
 * @param {number} [offset=0]  – number of rows to skip (>= 0)
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number}>}
 *
 * @throws {Error} with code VALIDATION_ERROR when limit/offset fail range checks
 * @throws {Error} on database failure
 *
 * @example
 *   const page = await getAllUsers(10, 20);
 *   // { users: [...], total: 57, limit: 10, offset: 20 }
 */
async function getAllUsers(limit = 20, offset = 0) {
  // --- Input validation / clamping --------------------------------------------
  const safeLimit  = toSafeInt(limit,  20, 1, 100);
  const safeOffset = toSafeInt(offset,  0, 0, Number.MAX_SAFE_INTEGER);

  if (safeLimit !== parseInt(limit ?? 20, 10) && parseInt(limit, 10) > 100) {
    // Warn (but don't throw) when the caller requested more than the cap.
    console.warn(
      `[Query] getAllUsers: requested limit ${limit} exceeds maximum (100); clamped to 100`
    );
  }

  // --- Query ------------------------------------------------------------------
  // A single round-trip returns both the page of rows and the total row count
  // using a window function, avoiding a second COUNT(*) query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const startNs = process.hrtime.bigint();
  let success = false;

  try {
    const result = await query(sql, [safeLimit, safeOffset]);
    success = true;

    const total = result.rows.length > 0
      ? parseInt(result.rows[0].total_count, 10)
      : 0;

    // Strip the synthetic total_count column from each row before returning.
    const users = result.rows.map(({ total_count, ...rest }) => rest);

    logQueryTiming('getAllUsers', startNs, success, {
      rows: users.length,
      total,
      limit: safeLimit,
      offset: safeOffset,
    });

    return { users, total, limit: safeLimit, offset: safeOffset };
  } catch (err) {
    logQueryTiming('getAllUsers', startNs, success, { error: err.message });
    throw err;
  }
}

/**
 * Search users by matching a query string against name and email.
 *
 * The search is case-insensitive (ILIKE) and uses a "contains" strategy by
 * default.  SQL wildcard metacharacters in the search term are automatically
 * escaped so that user input cannot influence match semantics.
 *
 * @param {string} searchQuery – the text to search for
 * @param {number} [limit=20]  – maximum rows to return (1 – 100)
 * @param {number} [offset=0]  – rows to skip (>= 0)
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number, query: string}>}
 *
 * @throws {Error} with code VALIDATION_ERROR when searchQuery is empty/invalid
 * @throws {Error} on database failure
 *
 * @example
 *   const results = await searchUsers('alice', 5, 0);
 *   // { users: [{id:1, name:'Alice', ...}], total: 1, limit: 5, offset: 0, query: 'alice' }
 */
async function searchUsers(searchQuery, limit = 20, offset = 0) {
  // --- Input validation -------------------------------------------------------
  if (searchQuery === null || searchQuery === undefined) {
    throw validationError('searchUsers: searchQuery must not be null or undefined');
  }

  const rawQuery = String(searchQuery).trim();

  if (rawQuery.length === 0) {
    throw validationError('searchUsers: searchQuery must not be empty');
  }

  if (rawQuery.length > 200) {
    throw validationError(
      `searchUsers: searchQuery exceeds maximum length of 200 characters`
    );
  }

  const safeLimit  = toSafeInt(limit,  20, 1, 100);
  const safeOffset = toSafeInt(offset,  0, 0, Number.MAX_SAFE_INTEGER);

  // --- Build safe ILIKE pattern -----------------------------------------------
  // toLikePattern escapes \, %, _ and wraps with % wildcards.
  // The pattern is passed as a bound parameter ($1) — never interpolated.
  const likePattern = toLikePattern(rawQuery);

  // --- Query ------------------------------------------------------------------
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR email ILIKE $1 ESCAPE '\\'
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const startNs = process.hrtime.bigint();
  let success = false;

  try {
    const result = await query(sql, [likePattern, safeLimit, safeOffset]);
    success = true;

    const total = result.rows.length > 0
      ? parseInt(result.rows[0].total_count, 10)
      : 0;

    const users = result.rows.map(({ total_count, ...rest }) => rest);

    logQueryTiming('searchUsers', startNs, success, {
      rows: users.length,
      total,
      limit: safeLimit,
      offset: safeOffset,
      // Log the query length, not the content, to avoid leaking PII to logs.
      queryLen: rawQuery.length,
    });

    return {
      users,
      total,
      limit: safeLimit,
      offset: safeOffset,
      query: rawQuery,
    };
  } catch (err) {
    logQueryTiming('searchUsers', startNs, success, { error: err.message });
    throw err;
  }
}

