/**
 * app.js — Express application
 *
 * /users endpoint variants
 * ────────────────────────
 *   GET /users                        → paginated list  (getAllUsers)
 *   GET /users?limit=N&offset=N       → paginated list with explicit page params
 *   GET /users?search=term            → free-text search (searchUsers)
 *   GET /users/:id                    → single user     (getUserById)
 */

require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');
const { closePool } = require('./db');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Health check
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// /users  – list or search
// ---------------------------------------------------------------------------

/**
 * GET /users
 *
 * Query parameters:
 *   search  {string}  – if present, delegates to searchUsers()
 *   limit   {number}  – page size  (1-100, default 20)
 *   offset  {number}  – page start (>= 0, default 0)
 *
 * Response 200:
 *   {
 *     users:  Array<{id, name, email, created_at}>,
 *     total:  number,   // total matching rows (for pagination)
 *     limit:  number,
 *     offset: number,
 *     query?: string    // echoed back only for search requests
 *   }
 */
app.get('/users', async (req, res) => {
  const { search, limit, offset } = req.query;

  try {
    if (search !== undefined) {
      // Delegate to the full-text search query.
      const data = await searchUsers(search, limit, offset);
      return res.json(data);
    }

    // Default: paginated list.
    const data = await getAllUsers(limit, offset);
    return res.json(data);
  } catch (err) {
    return handleQueryError(err, res, 'GET /users');
  }
});

// ---------------------------------------------------------------------------
// /users/:id  – single user by primary key
// ---------------------------------------------------------------------------

/**
 * GET /users/:id
 *
 * Path parameter:
 *   id  {number}  – user's numeric primary key (positive integer)
 *
 * Response 200:  { id, name, email, created_at }
 * Response 404:  { error: 'User not found' }
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    return res.json(user);
  } catch (err) {
    return handleQueryError(err, res, 'GET /users/:id');
  }
});

// ---------------------------------------------------------------------------
// Shared error handler for query errors
// ---------------------------------------------------------------------------

/**
 * Map query-layer errors to appropriate HTTP responses.
 *
 * VALIDATION_ERROR  → 400 Bad Request  (safe to surface to the client)
 * Everything else   → 500 Internal Server Error (details logged, not exposed)
 *
 * @param {Error}                   err    – the caught error
 * @param {import('express').Response} res – Express response object
 * @param {string}                  route  – label for log context
 */
function handleQueryError(err, res, route) {
  if (err.code === 'VALIDATION_ERROR') {
    return res.status(400).json({ error: err.message });
  }

  // For all other errors, log the full detail server-side but return only a
  // generic message to the client to avoid leaking implementation details.
  console.error(`[${route}] Unhandled error:`, err.message);
  return res.status(500).json({ error: 'Internal server error' });
}

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------

async function shutdown(signal) {
  console.log(`[App] Received ${signal}. Shutting down gracefully…`);
  await closePool();
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Server startup (skipped when the module is required by tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = parseInt(process.env.PORT ?? '3000', 10);
  app.listen(PORT, () => {
    console.log(`[App] Server running on port ${PORT}`);
  });
}

module.exports = app;

