// Manual mock for ./db
// We replace the module cache entry BEFORE requiring ./queries so that
// queries.js picks up the mock automatically.
// ---------------------------------------------------------------------------

let mockQueryFn;          // reassigned per test
let logLines = [];        // captures console.log output

// Intercept console.log before anything else loads
const originalLog   = console.log;
const originalWarn  = console.warn;
const originalError = console.error;

function muteConsole() {
  console.log   = (...args) => logLines.push(args.join(' '));
  console.warn  = () => {};
  console.error = () => {};
}
function restoreConsole() {
  console.log   = originalLog;
  console.warn  = originalWarn;
  console.error = originalError;
}

// Inject a fake ./db module into the require cache.
const path = require('node:path');
const dbCacheKey = path.resolve(__dirname, 'db.js');

require.cache[dbCacheKey] = {
  id:       dbCacheKey,
  filename: dbCacheKey,
  loaded:   true,
  exports: {
    query:     async (sql, params) => mockQueryFn(sql, params),
    getClient: async () => { throw new Error('not mocked'); },
    closePool: async () => {},
    pool:      { totalCount: 0, idleCount: 0, waitingCount: 0 },
  },
};

// Now it is safe to require queries.js — it will see our mock.
const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

/** Build a fake pg QueryResult (adds synthetic total_count). */
function makeResult(rows = []) {
  const withCount = rows.map((r) => ({ ...r, total_count: String(rows.length) }));
  return { rows: withCount, rowCount: rows.length };
}

const aliceRow = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };
const bobRow   = { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date() };

// Reset state before each individual test.
function resetState() {
  logLines = [];
  mockQueryFn = async () => { throw new Error('mockQueryFn not set for this test'); };
}

// ---------------------------------------------------------------------------
// ── getUserById ─────────────────────────────────────────────────────────────
// ---------------------------------------------------------------------------

describe('getUserById', () => {

  beforeEach(resetState);
  before(muteConsole);
  // (console is restored once at the very end of the file)

  it('returns the user row when found', async () => {
    mockQueryFn = async () => makeResult([aliceRow]);
    const result = await getUserById(1);
    assert.equal(result.id, 1);
    assert.equal(result.name, 'Alice');
  });

  it('returns null when no row matches', async () => {
    mockQueryFn = async () => makeResult([]);
    const result = await getUserById(999);
    assert.equal(result, null);
  });

  it('passes id as a bound parameter, not interpolated into SQL', async () => {
    let capturedSql, capturedParams;
    mockQueryFn = async (sql, params) => {
      capturedSql    = sql;
      capturedParams = params;
      return makeResult([aliceRow]);
    };
    await getUserById(42);
    assert.ok(!capturedSql.includes('42'),            'value must not appear in SQL text');
    assert.deepEqual(capturedParams, [42],             'value must be in params array');
    assert.ok(capturedSql.includes('$1'),              'placeholder $1 must be in SQL');
  });

  it('selects explicit columns (no SELECT *)', async () => {
    let capturedSql;
    mockQueryFn = async (sql) => { capturedSql = sql; return makeResult([aliceRow]); };
    await getUserById(1);
    assert.ok(!/SELECT\s+\*/i.test(capturedSql), 'must not use SELECT *');
    assert.ok(/id/i.test(capturedSql));
    assert.ok(/email/i.test(capturedSql));
  });

  it('accepts a numeric string id', async () => {
    let capturedParams;
    mockQueryFn = async (sql, params) => { capturedParams = params; return makeResult([aliceRow]); };
    await getUserById('7');
    assert.deepEqual(capturedParams, [7]);
  });

  it('throws VALIDATION_ERROR for id = 0', async () => {
    await assert.rejects(() => getUserById(0), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR');
      return true;
    });
  });

  it('throws VALIDATION_ERROR for negative id', async () => {
    await assert.rejects(() => getUserById(-1), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR');
      return true;
    });
  });

  it('throws VALIDATION_ERROR for non-numeric string', async () => {
    await assert.rejects(() => getUserById('abc'), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR');
      return true;
    });
  });

  it('throws VALIDATION_ERROR for null', async () => {
    await assert.rejects(() => getUserById(null), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR');
      return true;
    });
  });

  it('throws VALIDATION_ERROR for empty string', async () => {
    await assert.rejects(() => getUserById(''), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR');
      return true;
    });
  });

  it('emits a timing log with status=OK on success', async () => {
    mockQueryFn = async () => makeResult([aliceRow]);
    await getUserById(1);
    const hit = logLines.find((l) => l.includes('getUserById') && l.includes('status=OK'));
    assert.ok(hit, 'expected a timing log line');
    assert.ok(/duration=\d+\.\d{3}ms/.test(hit), 'expected duration field');
  });

  it('emits a timing log with status=ERROR on db failure', async () => {
    mockQueryFn = async () => { throw new Error('DB down'); };
    await assert.rejects(() => getUserById(1), /DB down/);
    const hit = logLines.find((l) => l.includes('getUserById') && l.includes('status=ERROR'));
    assert.ok(hit, 'expected an error timing log');
  });

  it('re-throws database errors', async () => {
    mockQueryFn = async () => { throw new Error('connection timeout'); };
    await assert.rejects(() => getUserById(1), /connection timeout/);
  });
});

