describe('getAllUsers', () => {
  beforeEach(resetState);

  it('returns users array with pagination metadata', async () => {
    mockQueryFn = async () => makeResult([aliceRow, bobRow]);
    const result = await getAllUsers(10, 0);
    assert.equal(result.users.length, 2);
    assert.equal(result.total, 2);
    assert.equal(result.limit, 10);
    assert.equal(result.offset, 0);
  });

  it('strips total_count from each returned row', async () => {
    mockQueryFn = async () => makeResult([aliceRow]);
    const { users } = await getAllUsers();
    assert.ok(!('total_count' in users[0]), 'total_count must be stripped');
  });

  it('returns empty array and total=0 when no rows', async () => {
    mockQueryFn = async () => makeResult([]);
    const result = await getAllUsers();
    assert.deepEqual(result.users, []);
    assert.equal(result.total, 0);
  });

  it('passes limit and offset as bound parameters', async () => {
    let capturedSql, capturedParams;
    mockQueryFn = async (sql, params) => {
      capturedSql = sql; capturedParams = params;
      return makeResult([aliceRow]);
    };
    await getAllUsers(5, 15);
    assert.ok(capturedSql.includes('$1'));
    assert.ok(capturedSql.includes('$2'));
    assert.deepEqual(capturedParams, [5, 15]);
    assert.ok(!/LIMIT\s+5\b/i.test(capturedSql),  'value must not be baked into SQL');
    assert.ok(!/OFFSET\s+15\b/i.test(capturedSql), 'value must not be baked into SQL');
  });

  it('defaults to limit=20 and offset=0', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    await getAllUsers();
    assert.deepEqual(capturedParams, [20, 0]);
  });

  it('clamps limit to 100', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    const result = await getAllUsers(9999, 0);
    assert.equal(capturedParams[0], 100);
    assert.equal(result.limit, 100);
  });

  it('clamps limit to minimum of 1 when 0 is given', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    await getAllUsers(0, 0);
    assert.equal(capturedParams[0], 1);
  });

  it('clamps negative offset to 0', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    await getAllUsers(10, -5);
    assert.equal(capturedParams[1], 0);
  });

  it('falls back to defaults for non-numeric limit/offset', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    await getAllUsers('banana', 'peel');
    assert.deepEqual(capturedParams, [20, 0]);
  });

  it('emits a timing log on success', async () => {
    mockQueryFn = async () => makeResult([aliceRow]);
    await getAllUsers();
    const hit = logLines.find((l) => l.includes('getAllUsers') && l.includes('status=OK'));
    assert.ok(hit, 'expected timing log');
  });

  it('re-throws database errors', async () => {
    mockQueryFn = async () => { throw new Error('query timeout'); };
    await assert.rejects(() => getAllUsers(), /query timeout/);
  });
});

// ---------------------------------------------------------------------------
// ── searchUsers ─────────────────────────────────────────────────────────────
// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  beforeEach(resetState);

  it('returns matching users and metadata', async () => {
    mockQueryFn = async () => makeResult([aliceRow]);
    const result = await searchUsers('alice');
    assert.equal(result.users.length, 1);
    assert.equal(result.total, 1);
    assert.equal(result.query, 'alice');
    assert.equal(result.limit, 20);
    assert.equal(result.offset, 0);
  });

  it('strips total_count from returned rows', async () => {
    mockQueryFn = async () => makeResult([aliceRow]);
    const { users } = await searchUsers('alice');
    assert.ok(!('total_count' in users[0]));
  });

  it('passes pattern, limit, offset as bound parameters', async () => {
    let capturedSql, capturedParams;
    mockQueryFn = async (sql, params) => {
      capturedSql = sql; capturedParams = params;
      return makeResult([aliceRow]);
    };
    await searchUsers('alice', 5, 10);
    assert.equal(capturedParams.length, 3);
    assert.equal(capturedParams[0], '%alice%');
    assert.equal(capturedParams[1], 5);
    assert.equal(capturedParams[2], 10);
    assert.ok(capturedSql.includes('$1'));
    assert.ok(capturedSql.includes('$2'));
    assert.ok(capturedSql.includes('$3'));
  });

  it('uses ILIKE operator', async () => {
    let capturedSql;
    mockQueryFn = async (sql) => { capturedSql = sql; return makeResult([]); };
    await searchUsers('bob');
    assert.ok(/ILIKE/i.test(capturedSql));
  });

  // ── ILIKE metacharacter escaping ──

  it('escapes % so it is treated as a literal character', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    await searchUsers('100%');
    assert.equal(capturedParams[0], '%100\\%%');
  });

  it('escapes _ so it is treated as a literal character', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    await searchUsers('user_name');
    assert.equal(capturedParams[0], '%user\\_name%');
  });

  it('escapes backslash in search term', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    await searchUsers('C:\\path');
    assert.equal(capturedParams[0], '%C:\\\\path%');
  });

  it('escapes combined metacharacters correctly', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    await searchUsers('%_100\\%_');
    assert.equal(capturedParams[0], '%\\%\\_100\\\\\\%\\_%');
  });

  // ── SQL injection ──

  it('does not interpolate the search term into the SQL string', async () => {
    const injection = "'; DROP TABLE users; --";
    let capturedSql, capturedParams;
    mockQueryFn = async (sql, params) => {
      capturedSql = sql; capturedParams = params;
      return makeResult([]);
    };
    await searchUsers(injection);
    assert.ok(!capturedSql.includes(injection),    'injection string must not be in SQL');
    assert.ok(!capturedSql.includes('DROP'),        'DROP must not appear in SQL');
    assert.ok(capturedParams[0].includes('DROP TABLE users'), 'value still present in params');
  });

  // ── input validation ──

  it('throws VALIDATION_ERROR for empty string', async () => {
    await assert.rejects(() => searchUsers(''), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR'); return true;
    });
  });

  it('throws VALIDATION_ERROR for whitespace-only string', async () => {
    await assert.rejects(() => searchUsers('   '), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR'); return true;
    });
  });

  it('throws VALIDATION_ERROR for null', async () => {
    await assert.rejects(() => searchUsers(null), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR'); return true;
    });
  });

  it('throws VALIDATION_ERROR for undefined', async () => {
    await assert.rejects(() => searchUsers(undefined), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR'); return true;
    });
  });

  it('throws VALIDATION_ERROR when query exceeds 200 characters', async () => {
    await assert.rejects(() => searchUsers('a'.repeat(201)), (err) => {
      assert.equal(err.code, 'VALIDATION_ERROR'); return true;
    });
  });

  it('accepts a query of exactly 200 characters', async () => {
    mockQueryFn = async () => makeResult([]);
    await assert.doesNotReject(() => searchUsers('a'.repeat(200)));
  });

  it('trims whitespace and echoes the trimmed query', async () => {
    let capturedParams;
    mockQueryFn = async (_, params) => { capturedParams = params; return makeResult([]); };
    const result = await searchUsers('  alice  ');
    assert.equal(result.query, 'alice');
    assert.equal(capturedParams[0], '%alice%');
  });

  // ── timing log ──

  it('logs queryLen but NOT the query text', async () => {
    mockQueryFn = async () => makeResult([aliceRow]);
    await searchUsers('alice');
    const hit = logLines.find((l) => l.includes('searchUsers') && l.includes('status=OK'));
    assert.ok(hit, 'expected timing log');
    assert.ok(hit.includes('queryLen=5'), 'expected queryLen in log');
    assert.ok(!hit.includes('alice'),     'raw query term must not appear in log');
  });

  // ── error propagation ──

  it('re-throws database errors', async () => {
    mockQueryFn = async () => { throw new Error('deadlock detected'); };
    await assert.rejects(() => searchUsers('test'), /deadlock detected/);
  });
});

// ---------------------------------------------------------------------------
// ── Cross-cutting: timing log shape ─────────────────────────────────────────
// ---------------------------------------------------------------------------

describe('logQueryTiming — cross-cutting', () => {
  beforeEach(resetState);

  it('every successful query emits a duration field in ms', async () => {
    mockQueryFn = async () => makeResult([]);
    await getUserById(1);
    await getAllUsers();
    await searchUsers('x');

    const timingLogs = logLines.filter((l) => /\[Query\].*duration=\d+\.\d{3}ms/.test(l));
    assert.equal(timingLogs.length, 3, 'expected 3 timing log entries');
  });

  it('status=ERROR is logged for every failing query function', async () => {
    mockQueryFn = async () => { throw new Error('simulated'); };

    await assert.rejects(() => getUserById(1));
    await assert.rejects(() => getAllUsers());
    await assert.rejects(() => searchUsers('x'));

    const errorLogs = logLines.filter((l) => l.includes('status=ERROR'));
    assert.equal(errorLogs.length, 3, 'expected 3 error log entries');
  });
});

